import { noCacheJson } from '@/lib/utils';
import { db } from '@/lib/db';
import { EXCLUDED_STUDENT_IDS } from '@/lib/student-blocklist';

export const dynamic = 'force-dynamic';

/**
 * GET /api/app-version/data-integrity
 *
 * Returns live DB counts so the "Versi Aplikasi" menu can show whether the
 * sandbox/production data has been rolled back to an older snapshot.
 *
 * Expected steady-state values (13 November 2026):
 *   - studentCount:        135  (excludes the 2 blocklisted/deleted students)
 *   - holidayCount:        varies (manual holidays; must NOT include Oct 24/26-29)
 *   - attendanceCount:     76,395
 *   - excludedStudentCount: 2   (length of EXCLUDED_STUDENT_IDS in student-blocklist.ts)
 *
 * If any of these drop dramatically, a data rollback likely happened.
 */
export async function GET(_request: NextRequest) {
  try {
    const [studentCount, holidayCount, attendanceCount, classCount] = await Promise.all([
      db.student.count(),
      db.dateHoliday.count(),
      db.attendance.count(),
      db.class.count(),
    ]);

    // Sample the most recent attendance date — if it's stale (e.g., before
    // November 2026), the data snapshot is old.
    const lastAttendance = await db.attendance.findFirst({
      orderBy: { date: 'desc' },
      select: { date: true },
    });

    return noCacheJson({
      studentCount,
      holidayCount,
      attendanceCount,
      classCount,
      excludedStudentCount: EXCLUDED_STUDENT_IDS.length,
      lastAttendanceDate: lastAttendance?.date ?? null,
      checkedAt: new Date().toISOString(),
    });
  } catch (e) {
    return noCacheJson(
      {
        error: e instanceof Error ? e.message : 'Unknown error',
        checkedAt: new Date().toISOString(),
      },
      500,
    );
  }
}
