import { noCacheJson } from '@/lib/utils';
import { APP_VERSION, FEATURE_MARKERS } from '@/lib/app-version';
import fs from 'fs';
import path from 'path';

export const dynamic = 'force-dynamic';

/**
 * GET /api/app-version
 *
 * Returns the CURRENT app version (single entry — old versions are deleted,
 * per user request) plus a LIVE feature check: each FEATURE_MARKERS entry is
 * searched inside its source file. If a marker is missing from an existing
 * file, the deployed code has been ROLLED BACK to an older version —
 * rollbackDetected=true.
 *
 * Status values:
 *  - 'present'  : file exists AND contains the pattern
 *  - 'missing'  : file exists but pattern NOT found → rollback indicator
 *  - 'unknown'  : file cannot be read (e.g., production bundle without sources)
 */
export async function GET(_request: NextRequest) {
  const features = FEATURE_MARKERS.map((marker) => {
    let status: 'present' | 'missing' | 'unknown' = 'unknown';
    try {
      // Resolve relative to project root (works in dev + sandbox).
      const filePath = path.join(process.cwd(), marker.file);
      if (fs.existsSync(filePath)) {
        const content = fs.readFileSync(filePath, 'utf8');
        status = content.includes(marker.pattern) ? 'present' : 'missing';
      } else {
        status = 'unknown';
      }
    } catch {
      status = 'unknown';
    }
    return { id: marker.id, name: marker.name, status };
  });

  const checkable = features.filter(f => f.status !== 'unknown');
  const missing = checkable.filter(f => f.status === 'missing');
  const rollbackDetected = checkable.length > 0 && missing.length > 0;

  return noCacheJson({
    version: APP_VERSION.version,
    versionCode: APP_VERSION.versionCode,
    releasedAt: APP_VERSION.releasedAt,
    note: APP_VERSION.note,
    previousVersions: APP_VERSION.previousVersions,
    rollbackDetected,
    features,
    missingFeatures: missing.map(f => f.name),
    checkedAt: new Date().toISOString(),
  });
}
