import { noCacheJson } from '@/lib/utils'
import { db } from '@/lib/db'
import { scheduleAutoSync, scheduleImmediateSync } from '@/lib/auto-sync'

/**
 * Save attendance records to the database.
 *
 * On disk-full error (SQLITE_FULL, code 13):
 *   1. Run aggressiveCleanup() — deletes old backups, WAL files, VACUUM
 *   2. RETRY the save — usually succeeds after cleanup reclaims space
 *   3. If retry succeeds → return 200 (user never sees the error)
 *   4. If retry fails → return 507 with friendly message
 *
 * This auto-recovery ensures users can keep adding data even when disk is full.
 */
async function saveAttendanceRecords(
  classId: string,
  date: string,
  hour: number,
  validRecords: Array<{ studentId: string; status: string }>
): Promise<void> {
  await db.$transaction(
    validRecords.map((r) =>
      db.attendance.upsert({
        where: {
          studentId_date_hour: { studentId: r.studentId, date, hour },
        },
        update: { status: r.status, classId },
        create: { studentId: r.studentId, classId, date, hour, status: r.status },
      })
    )
  );
}

function isDiskFullError(error: unknown): boolean {
  const errMsg = error instanceof Error ? error.message : String(error);
  return errMsg.includes('disk is full') ||
    errMsg.includes('SQLITE_FULL') ||
    errMsg.includes('extended_code: 13') ||
    errMsg.includes('code 13');
}

/**
 * Run aggressive cleanup and retry the save.
 * Returns true if the retry succeeded, false otherwise.
 */
async function cleanupAndRetry(
  classId: string,
  date: string,
  hour: number,
  validRecords: Array<{ studentId: string; status: string }>
): Promise<{ ok: boolean; cleanupReclaimedBytes: number; cleanupFilesDeleted: number; retryError?: string }> {
  console.error('[Attendance] Disk-full detected! Running aggressive cleanup before retry...');

  let reclaimedBytes = 0;
  let filesDeleted = 0;
  try {
    const { aggressiveCleanup } = await import('@/lib/disk-cleanup');
    const result = await aggressiveCleanup({ vacuum: true });
    reclaimedBytes = result.bytesReclaimed;
    filesDeleted = result.filesDeleted;
    console.log(`[Attendance] Cleanup reclaimed ${(reclaimedBytes / 1024 / 1024).toFixed(2)}MB across ${filesDeleted} files. Errors: ${result.errors.length}`);
  } catch (cleanupErr) {
    console.error('[Attendance] Cleanup failed:', cleanupErr instanceof Error ? cleanupErr.message : String(cleanupErr));
  }

  try {
    await saveAttendanceRecords(classId, date, hour, validRecords);
    console.log('[Attendance] Retry succeeded after cleanup!');
    return { ok: true, cleanupReclaimedBytes: reclaimedBytes, cleanupFilesDeleted: filesDeleted };
  } catch (retryError) {
    console.error('[Attendance] Retry failed after cleanup:', retryError instanceof Error ? retryError.message : String(retryError));
    return {
      ok: false,
      cleanupReclaimedBytes: reclaimedBytes,
      cleanupFilesDeleted: filesDeleted,
      retryError: retryError instanceof Error ? retryError.message : String(retryError),
    };
  }
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const classId = searchParams.get('classId')
    const date = searchParams.get('date')

    if (!classId || !date) {
      return noCacheJson(
        { error: 'classId dan date diperlukan' },
        400
      )
    }

    const records = await db.attendance.findMany({
      where: { classId, date },
      orderBy: [{ student: { name: 'asc' } }, { hour: 'asc' }],
      include: {
        student: {
          select: { id: true, name: true },
        },
      },
    })

    return noCacheJson(records)
  } catch (error) {
    console.error('Error fetching attendance:', error)
    return noCacheJson(
      { error: 'Gagal mengambil data kehadiran' },
      500
    )
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json()
    const { classId, date, hour, records } = body

    if (!classId || !date || !hour || !records) {
      return noCacheJson(
        { error: 'classId, date, hour, dan records diperlukan' },
        400
      )
    }

    if (hour < 1 || hour > 8) {
      return noCacheJson(
        { error: 'Hour harus antara 1-8' },
        400
      )
    }

    const validStatuses = ['Hadir', 'Terlambat', 'Alfa', 'Sakit', 'Izin']

    // Filter valid records UPFRONT — skip the loop entirely if no valid records.
    const validRecords = (records as Array<{ studentId: string; status: string }>).filter(
      (r) => r && r.studentId && r.status && validStatuses.includes(r.status)
    )

    if (validRecords.length === 0) {
      return noCacheJson(
        { error: 'Tidak ada record valid untuk disimpan' },
        400
      )
    }

    // ATTEMPT 1: Try the save with atomic batch transaction.
    // On disk-full, run aggressive cleanup and RETRY — user never sees the error.
    try {
      await saveAttendanceRecords(classId, date, hour, validRecords);
    } catch (saveError) {
      if (!isDiskFullError(saveError)) throw saveError;

      // Disk-full detected! Cleanup + retry (blocking, foreground).
      const retryResult = await cleanupAndRetry(classId, date, hour, validRecords);
      if (!retryResult.ok) {
        return noCacheJson(
          {
            error: 'Disk server sedang sangat penuh. Silakan hubungi administrator atau coba beberapa menit lagi.',
            cleanupReclaimedBytes: retryResult.cleanupReclaimedBytes,
            cleanupFilesDeleted: retryResult.cleanupFilesDeleted,
          },
          507
        );
      }
    }

    // Sync DB to persistent storage IN BACKGROUND (non-blocking).
    setImmediate(() => {
      import('@/lib/db-persistent-sync')
        .then(({ syncLiveDbToPersistent }) => syncLiveDbToPersistent())
        .catch(() => {});
    });

    // Trigger IMMEDIATE GitHub sync (bypasses 5s debounce) — ensures user's
    // data reaches GitHub ASAP in case disk fills up later. Non-blocking.
    scheduleImmediateSync();

    scheduleAutoSync()
    return noCacheJson({ message: 'Kehadiran berhasil disimpan', count: validRecords.length })
  } catch (error) {
    console.error('Error saving attendance:', error)
    if (isDiskFullError(error)) {
      return noCacheJson(
        { error: 'Disk server sedang penuh. Sistem sedang membersihkan — silakan coba simpan lagi dalam 10 detik.' },
        507
      )
    }
    return noCacheJson(
      { error: 'Gagal menyimpan data kehadiran' },
      500
    )
  }
}

export async function PUT(request: NextRequest) {
  try {
    const body = await request.json()
    const { classId, date } = body

    if (!classId || !date) {
      return noCacheJson(
        { error: 'classId dan date diperlukan' },
        400
      )
    }

    await db.attendance.deleteMany({
      where: { classId, date },
    })

    scheduleAutoSync()
    return noCacheJson({ message: 'Kehadiran berhasil direset' })
  } catch (error) {
    console.error('Error resetting attendance:', error)
    return noCacheJson(
      { error: 'Gagal mereset data kehadiran' },
      500
    )
  }
}

export async function PATCH(request: NextRequest) {
  try {
    const body = await request.json()
    const { classId, date, hour, records } = body

    if (!classId || !date || !hour || !records) {
      return noCacheJson(
        { error: 'classId, date, hour, dan records diperlukan' },
        400
      )
    }

    if (hour < 1 || hour > 8) {
      return noCacheJson(
        { error: 'Hour harus antara 1-8' },
        400
      )
    }

    const validStatuses = ['Hadir', 'Terlambat', 'Alfa', 'Sakit', 'Izin']

    const validRecords = (records as Array<{ studentId: string; status: string }>).filter(
      (r) => r && r.studentId && r.status && validStatuses.includes(r.status)
    )

    if (validRecords.length === 0) {
      return noCacheJson(
        { error: 'Tidak ada record valid untuk diperbarui' },
        400
      )
    }

    // ATTEMPT 1: try the save with atomic batch transaction.
    // On disk-full, run aggressive cleanup and RETRY.
    try {
      await saveAttendanceRecords(classId, date, hour, validRecords);
    } catch (saveError) {
      if (!isDiskFullError(saveError)) throw saveError;
      const retryResult = await cleanupAndRetry(classId, date, hour, validRecords);
      if (!retryResult.ok) {
        return noCacheJson(
          {
            error: 'Disk server sedang sangat penuh. Silakan hubungi administrator atau coba beberapa menit lagi.',
            cleanupReclaimedBytes: retryResult.cleanupReclaimedBytes,
            cleanupFilesDeleted: retryResult.cleanupFilesDeleted,
          },
          507
        );
      }
    }

    // Trigger IMMEDIATE GitHub sync (bypasses 5s debounce) — same as POST.
    scheduleImmediateSync();

    scheduleAutoSync()
    return noCacheJson({ message: 'Kehadiran berhasil diperbarui', count: validRecords.length })
  } catch (error) {
    console.error('Error patching attendance:', error)
    if (isDiskFullError(error)) {
      return noCacheJson(
        { error: 'Disk server sedang penuh. Sistem sedang membersihkan — silakan coba simpan lagi dalam 10 detik.' },
        507
      )
    }
    return noCacheJson(
      { error: 'Gagal memperbarui data kehadiran' },
      500
    )
  }
}
"},{"path":"src/app/api/attendance/template/route.ts","content":"import { NextRequest } from 'next/server'
import { noCacheJson } from '@/lib/utils'
import { db } from '@/lib/db'
import { scheduleAutoSync } from '@/lib/auto-sync'

// GET: download attendance template (CSV or Excel)
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const classId = searchParams.get('classId')
    const date = searchParams.get('date')
    const format = searchParams.get('format') || 'csv'

    if (!classId || !date) {
      return noCacheJson({ error: 'classId dan date diperlukan' }, 400)
    }

    const cls = await db.class.findUnique({
      where: { id: classId },
      include: { students: { orderBy: { name: 'asc' } } },
    })

    if (!cls) {
      return noCacheJson({ error: 'Kelas tidak ditemukan' }, 404)
    }

    // Get existing attendance for this date
    const existingRecords = await db.attendance.findMany({
      where: { classId, date },
    })
    const existingMap: Record<string, string> = {}
    for (const r of existingRecords) {
      existingMap[`${r.studentId}-${r.hour}`] = r.status
    }

    // Get daily hours config
    const hourSetting = await db.settings.findUnique({
      where: { key: `max_hours_${date}` },
    })
    const maxHours = hourSetting ? parseInt(hourSetting.value, 10) : 8

    const hours = Array.from({ length: maxHours }, (_, i) => i + 1)
    const safeClassName = cls.name.replace(/[^a-zA-Z0-9]/g, '_')

    if (format === 'excel') {
      // Dynamic import to avoid bundling xlsx when not needed
      const XLSX = await import('xlsx')

      const header = ['NO', 'NAMA SISWA', ...hours.map(h => `JAM ${h}`)]
      const rows = cls.students.map((student, idx) => {
        const statuses = hours.map(h => existingMap[`${student.id}-${h}`] || 'Hadir')
        return [idx + 1, student.name, ...statuses]
      })

      const wsData = [header, ...rows]
      const ws = XLSX.utils.aoa_to_sheet(wsData)

      // Set column widths
      ws['!cols'] = [
        { wch: 5 },  // NO
        { wch: 25 }, // NAMA SISWA
        ...hours.map(() => ({ wch: 14 })), // JAM columns
      ]

      const wb = XLSX.utils.book_new()
      XLSX.utils.book_append_sheet(wb, ws, 'Absensi')
      const buffer = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' })

      const filename = `Template_Absensi_${safeClassName}_${date}.xlsx`
      return new Response(buffer, {
        headers: {
          'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          'Content-Disposition': `attachment; filename="${filename}"`,
          'Cache-Control': 'no-store',
        },
      })
    }

    // Default: CSV
    const header = ['NO', 'NAMA SISWA', ...hours.map(h => `JAM ${h}`)]
    const rows = cls.students.map((student, idx) => {
      const statuses = hours.map(h => existingMap[`${student.id}-${h}`] || 'Hadir')
      return [String(idx + 1), student.name, ...statuses].join(',')
    })

    const csv = [header.join(','), ...rows].join('\n')
    const filename = `Template_Absensi_${safeClassName}_${date}.csv`

    return new Response(csv, {
      headers: {
        'Content-Type': 'text/csv; charset=utf-8',
        'Content-Disposition': `attachment; filename="${filename}"`,
        'Cache-Control': 'no-store',
      },
    })
  } catch (error) {
    console.error('Error downloading template:', error)
    return noCacheJson({ error: 'Gagal mengunduh template' }, 500)
  }
}

// POST: upload attendance template (CSV or Excel)
export async function POST(request: NextRequest) {
  try {
    const formData = await request.formData()
    const file = formData.get('file') as File | null
    const classId = formData.get('classId') as string | null
    const date = formData.get('date') as string | null

    if (!file || !classId || !date) {
      return noCacheJson({ error: 'File, classId, dan date diperlukan.' }, 400)
    }

    // Check file type
    const fileName = file.name.toLowerCase()
    const isExcel = fileName.endsWith('.xlsx') || fileName.endsWith('.xls')
    const isCsv = fileName.endsWith('.csv')

    if (!isExcel && !isCsv) {
      scheduleAutoSync()
      return noCacheJson({
        error: `Format file "${file.name}" tidak didukung. Gunakan file .csv atau .xlsx.`,
        detail: `Ekstensi file harus .csv atau .xlsx. File yang diunggah: ${file.name} (${file.type || 'tipe tidak diketahui'})`,
      }, 400)
    }

    // Verify class exists first
    const cls = await db.class.findUnique({
      where: { id: classId },
      include: { students: { orderBy: { name: 'asc' } } },
    })
    if (!cls) {
      return noCacheJson({ error: `Kelas dengan ID "${classId}" tidak ditemukan.`, detail: 'Pastikan kelas masih ada di sistem.' }, 404)
    }

    if (cls.students.length === 0) {
      return noCacheJson({ error: `Kelas "${cls.name}" tidak memiliki siswa.`, detail: 'Tambahkan siswa ke kelas terlebih dahulu sebelum mengunggah template.' }, 400)
    }

    let headerParts: string[] = []
    let dataRows: string[][] = []

    if (isExcel) {
      // Dynamic import to avoid loading xlsx for CSV uploads
      const XLSX = await import('xlsx')

      // Parse Excel file
      const buffer = Buffer.from(await file.arrayBuffer())
      let workbook: Awaited<ReturnType<typeof import('xlsx')['read']>>
      try {
        workbook = XLSX.read(buffer, { type: 'buffer' })
      } catch (e) {
        scheduleAutoSync()
        return noCacheJson({
          error: 'File Excel rusak atau tidak dapat dibaca.',
          detail: `Gagal membaca file "${file.name}". Pastikan file tidak rusak dan merupakan file Excel yang valid (.xlsx).`,
        }, 400)
      }

      const sheetName = workbook.SheetNames[0]
      if (!sheetName) {
        return noCacheJson({ error: 'File Excel kosong (tidak ada sheet).', detail: `File "${file.name}" tidak memiliki sheet/data.` }, 400)
      }

      const ws = workbook.Sheets[sheetName]
      const jsonData = XLSX.utils.sheet_to_json<string[]>(ws, { header: 1, defval: '' })

      if (jsonData.length < 2) {
        return noCacheJson({ error: 'File Excel kosong atau hanya berisi header.', detail: `File "${file.name}" memiliki ${jsonData.length} baris. Diperlukan minimal header + 1 baris data siswa.` }, 400)
      }

      headerParts = (jsonData[0] || []).map(String)
      dataRows = jsonData.slice(1).map(row => row.map(String))
    } else {
      // Parse CSV file
      const text = await file.text()
      const lines = text.trim().split('\n')
      if (lines.length < 2) {
        return noCacheJson({ error: 'File CSV kosong atau hanya berisi header.', detail: `File "${file.name}" memiliki ${lines.length} baris. Diperlukan minimal header + 1 baris data siswa.` }, 400)
      }

      headerParts = lines[0].split(',').map(s => s.trim())
      dataRows = lines.slice(1).map(line => line.split(',').map(s => s.trim()))
    }

    // Parse header to determine hour columns
    const hourColumns: number[] = []
    for (let i = 0; i < headerParts.length; i++) {
      const match = headerParts[i].match(/JAM\s+(\d+)/i)
      if (match) hourColumns.push(parseInt(match[1], 10))
    }

    if (hourColumns.length === 0) {
      scheduleAutoSync()
      return noCacheJson({
        error: 'Format header tidak valid.',
        detail: `Header yang ditemukan: [${headerParts.join(', ')}]. Kolom harus mengandung "JAM 1", "JAM 2", dst. Format yang benar: NO, NAMA SISWA, JAM 1, JAM 2, ...`,
      }, 400)
    }

    const validStatuses = ['Hadir', 'Terlambat', 'Alfa', 'Sakit', 'Izin']
    let savedCount = 0
    const skippedStudents: string[] = []
    const invalidStatuses: { student: string; hour: number; value: string }[] = []

    for (let lineIdx = 0; lineIdx < dataRows.length; lineIdx++) {
      const cols = dataRows[lineIdx]
      if (cols.length < 2) continue

      const studentName = cols[1]
      const student = cls.students.find(s => s.name === studentName)
      if (!student) {
        skippedStudents.push(studentName)
        continue
      }

      for (const hour of hourColumns) {
        const colIdx = headerParts.findIndex(h => h.match(new RegExp(`JAM\\s+${hour}`, 'i')))
        if (colIdx === -1 || colIdx >= cols.length) continue

        let status = cols[colIdx].trim()
        if (!status) status = 'Hadir'

        // Normalize status
        if (!validStatuses.includes(status)) {
          const normalized = status.charAt(0).toUpperCase() + status.slice(1).toLowerCase()
          if (validStatuses.includes(normalized)) {
            status = normalized
          } else {
            invalidStatuses.push({ student: studentName, hour, value: cols[colIdx].trim() })
            status = 'Hadir' // fallback
          }
        }

        await db.attendance.upsert({
          where: {
            studentId_date_hour: { studentId: student.id, date, hour },
          },
          update: { status, classId },
          create: { studentId: student.id, classId, date, hour, status },
        })
        savedCount++
      }
    }

    // Build detailed response
    const warnings: string[] = []
    if (skippedStudents.length > 0) {
      warnings.push(`${skippedStudents.length} siswa tidak ditemukan: ${skippedStudents.slice(0, 5).join(', ')}${skippedStudents.length > 5 ? ` (+${skippedStudents.length - 5} lainnya)` : ''}`)
    }
    if (invalidStatuses.length > 0) {
      const examples = invalidStatuses.slice(0, 3).map(s => `"${s.student}" Jam ${s.hour}: "${s.value}"`).join('; ')
      warnings.push(`${invalidStatuses.length} status tidak valid (otomatis diubah ke Hadir): ${examples}${invalidStatuses.length > 3 ? ` (+${invalidStatuses.length - 3} lainnya)` : ''}`)
    }

    scheduleAutoSync()
    return noCacheJson({
      message: `Berhasil mengimpor ${savedCount} data absensi`,
      savedCount,
      totalStudents: cls.students.length,
      matchedStudents: cls.students.length - skippedStudents.length,
      skippedStudents,
      invalidStatuses,
      warnings,
    })
  } catch (error) {
    console.error('Error uploading template:', error)
    const msg = error instanceof Error ? error.message : 'Unknown error'
    scheduleAutoSync()
    return noCacheJson({
      error: 'Gagal mengimpor template.',
      detail: `Terjadi kesalahan server: ${msg}`,
    }, 500)
  }
}
"},{"path":"src/app/api/attendance-completeness/route.ts","content":"import { NextRequest } from 'next/server'
import { noCacheJson } from '@/lib/utils'
import { db } from '@/lib/db'

function getDayOfWeek(dateStr: string): number {
  const [y, m, d] = dateStr.split('-').map(Number)
  return new Date(Date.UTC(y, m - 1, d)).getUTCDay()
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const date = searchParams.get('date')

    if (!date) {
      return noCacheJson({ error: 'Parameter date diperlukan' }, 400)
    }

    const dayOfWeek = getDayOfWeek(date)

    // Check holidays
    const dateHoliday = await db.dateHoliday.findUnique({ where: { date } })
    const weeklyHoliday = await db.academicHoliday.findUnique({ where: { dayOfWeek } })
    const isHoliday = !!(dateHoliday || (weeklyHoliday?.isActive))

    // Get max hours
    const hourSetting = await db.settings.findUnique({
      where: { key: `max_hours_${date}` },
    })
    const maxHours = hourSetting ? parseInt(hourSetting.value, 10) : 8

    // Get all classes with student counts
    const classes = await db.class.findMany({
      include: {
        _count: { select: { students: true } },
      },
      orderBy: { name: 'asc' },
    })

    // Get schedules for the day
    const schedules = await db.weeklySchedule.findMany({
      where: { dayOfWeek },
    })

    // Get all attendance for this date
    const allAttendance = await db.attendance.findMany({
      where: { date },
      select: { classId: true, hour: true },
    })

    // Build filled hours per class
    const filledHoursMap = new Map<string, Set<number>>()
    for (const record of allAttendance) {
      if (!filledHoursMap.has(record.classId)) filledHoursMap.set(record.classId, new Set())
      filledHoursMap.get(record.classId)!.add(record.hour)
    }

    // Build scheduled hours per class
    const scheduledHoursMap = new Map<string, number[]>()
    for (const sched of schedules) {
      if (sched.hour > maxHours) continue
      if (!scheduledHoursMap.has(sched.classId)) scheduledHoursMap.set(sched.classId, [])
      scheduledHoursMap.get(sched.classId)!.push(sched.hour)
    }

    // Build result per class (excluding Libur and empty)
    const result: {
      className: string;
      classId: string;
      totalScheduled: number;
      totalFilled: number;
      percentage: number;
    }[] = []

    for (const cls of classes) {
      if (cls.name.toLowerCase().includes('libur')) continue
      if (cls._count.students === 0) continue

      const scheduled = scheduledHoursMap.get(cls.id) || []
      const uniqueScheduled = new Set(scheduled)
      const totalScheduled = uniqueScheduled.size

      const filled = filledHoursMap.get(cls.id) || new Set()
      // Count filled hours that are within scheduled hours
      let totalFilled = 0
      for (const h of filled) {
        if (uniqueScheduled.has(h)) totalFilled++
      }

      const percentage = totalScheduled > 0 ? Math.round((totalFilled / totalScheduled) * 100) : 0

      result.push({
        className: cls.name,
        classId: cls.id,
        totalScheduled,
        totalFilled,
        percentage,
      })
    }

    return noCacheJson({ date, isHoliday, classes: result })
  } catch (error) {
    console.error('Error fetching attendance-completeness data:', error)
    return noCacheJson({ error: 'Gagal mengambil data kelengkapan absensi' }, 500)
  }
}
"},{"path":"src/app/api/auto-restore/route.ts","content":"import { NextRequest, NextResponse } from 'next/server';
import { noCacheJson } from '@/lib/utils';
import { db } from '@/lib/db';
import { setSkipAutoSync } from '@/lib/auto-sync';
import fs from 'fs';
import path from 'path';

export const dynamic = 'force-dynamic';

const TX_TIMEOUT = 300_000; // 5 minutes

/**
 * POST /api/auto-restore
 *
 * Restores the database from the local backup file (auto_restore.json) if the
 * database is empty. This runs on-demand (triggered by AppShell when it
 * detects an empty DB) and from the instrumentation hook on server start.
 *
 * The restore logic is INLINED here (no external @/lib/local-backup-restore
 * import) so it survives sandbox working-tree resets that kept deleting the
 * external module.
 */

function findAutoRestoreFile(): string | null {
  const candidates = [
    '/home/z/my-project/upload/backups/auto_restore.json',
    '/home/z/my-project/upload/db/auto_restore.json',
    path.join(process.cwd(), 'db', 'auto_restore.json'),
    path.join(process.cwd(), 'upload', 'backups', 'auto_restore.json'),
    path.join(process.cwd(), 'db', 'custom.db'), // raw DB fallback (copy)
  ];
  for (const candidate of candidates) {
    try {
      if (fs.existsSync(candidate)) return candidate;
    } catch {
      // ignore fs errors
    }
  }
  return null;
}

function readBackupFile(filePath: string): any | null {
  try {
    const raw = fs.readFileSync(filePath, 'utf8');
    const parsed = JSON.parse(raw);
    return parsed?.data ? parsed : parsed;
  } catch (error) {
    console.error('[AutoRestore] Failed to read backup file:', error);
    return null;
  }
}

async function isDatabaseEmpty(): Promise<boolean> {
  try {
    const classCount = await db.class.count();
    return classCount === 0;
  } catch {
    return true;
  }
}

async function performRestore(backupData: any) {
  const data = backupData.data ?? backupData;
  if (!data.classes || !data.students) {
    throw new Error('File backup tidak mengandung data kelas/siswa');
  }

  setSkipAutoSync(true);
  try {
    const result = await db.$transaction(async (tx) => {
      await tx.attendance.deleteMany();
      await tx.weeklySchedule.deleteMany();
      await tx.teacher.deleteMany();
      await tx.academicActivity.deleteMany();
      await tx.dateHoliday.deleteMany();
      await tx.waliKelas.deleteMany();
      await tx.student.deleteMany();
      await tx.class.deleteMany();
      await tx.academicHoliday.deleteMany();
      await tx.settings.deleteMany();

      if (data.classes?.length > 0) {
        await tx.class.createMany({
          data: data.classes.map((cls: any) => ({
            id: cls.id, name: cls.name,
            createdAt: cls.createdAt ? new Date(cls.createdAt) : undefined,
            updatedAt: cls.updatedAt ? new Date(cls.updatedAt) : undefined,
          })),
        });
      }

      if (data.students?.length > 0) {
        // Layer 3 (blocklist): filter deleted students BEFORE DB write so they
        // never come back through the local auto-restore path.
        const blocklistFiltered = filterExcludedStudents(data.students);
        await tx.student.createMany({
          data: blocklistFiltered.map((s: any) => ({
            id: s.id, name: s.name, nisn: s.nisn || '', gender: s.gender || '',
            whatsapp: s.whatsapp || '', classId: s.classId,
            createdAt: s.createdAt ? new Date(s.createdAt) : undefined,
            updatedAt: s.updatedAt ? new Date(s.updatedAt) : undefined,
          })),
        });
      }

      if (data.attendance?.length > 0) {
        // Layer 3 (blocklist): drop attendance records referencing deleted students.
        const filteredAttendance = filterExcludedAttendance(data.attendance);
        const CHUNK_SIZE = 500;
        for (let i = 0; i < filteredAttendance.length; i += CHUNK_SIZE) {
          const chunk = filteredAttendance.slice(i, i + CHUNK_SIZE);
          await tx.attendance.createMany({
            data: chunk.map((a: any) => ({
              id: a.id, studentId: a.studentId, classId: a.classId,
              date: a.date, hour: a.hour, status: a.status,
              createdAt: a.createdAt ? new Date(a.createdAt) : undefined,
              updatedAt: a.updatedAt ? new Date(a.updatedAt) : undefined,
            })),
          });
        }
      }

      if (data.activities?.length > 0) {
        await tx.academicActivity.createMany({
          data: data.activities.map((a: any) => ({
            id: a.id, classId: a.classId, date: a.date,
            status: a.status || 'Masuk',
            createdAt: a.createdAt ? new Date(a.createdAt) : undefined,
            updatedAt: a.updatedAt ? new Date(a.updatedAt) : undefined,
          })),
        });
      }

      if (data.holidays?.length > 0) {
        await tx.academicHoliday.createMany({
          data: data.holidays.map((h: any) => ({
            id: h.id, dayOfWeek: h.dayOfWeek, name: h.name || '',
            isActive: h.isActive !== false,
          })),
        });
      }

      if (data.dateHolidays?.length > 0) {
        await tx.dateHoliday.createMany({
          data: data.dateHolidays.map((dh: any) => ({
            id: dh.id, date: dh.date, name: dh.name || '',
            createdAt: dh.createdAt ? new Date(dh.createdAt) : undefined,
            updatedAt: dh.updatedAt ? new Date(dh.updatedAt) : undefined,
          })),
        });
      }

      if (data.waliKelas?.length > 0) {
        await tx.waliKelas.createMany({
          data: data.waliKelas.map((w: any) => ({
            id: w.id, classId: w.classId, name: w.name || '',
            createdAt: w.createdAt ? new Date(w.createdAt) : undefined,
            updatedAt: w.updatedAt ? new Date(w.updatedAt) : undefined,
          })),
        });
      }

      if (data.schedules?.length > 0) {
        await tx.weeklySchedule.createMany({
          data: data.schedules.map((s: any) => ({
            id: s.id, classId: s.classId, dayOfWeek: s.dayOfWeek,
            hour: s.hour, teacher: s.teacher || '',
            createdAt: s.createdAt ? new Date(s.createdAt) : undefined,
            updatedAt: s.updatedAt ? new Date(s.updatedAt) : undefined,
          })),
        });
      }

      if (data.teachers?.length > 0) {
        await tx.teacher.createMany({
          data: data.teachers.map((t: any) => ({
            id: t.id, nickname: t.nickname, fullName: t.fullName || '',
            createdAt: t.createdAt ? new Date(t.createdAt) : undefined,
            updatedAt: t.updatedAt ? new Date(t.updatedAt) : undefined,
          })),
        });
      }

      if (data.settings?.length > 0) {
        for (const setting of data.settings) {
          try {
            await tx.settings.create({ data: { key: setting.key, value: setting.value } });
          } catch {
            // Skip duplicates
          }
        }
      }

      return {
        classes: (data.classes || []).length,
        students: (data.students || []).length,
        attendance: (data.attendance || []).length,
        activities: (data.activities || []).length,
        holidays: (data.holidays || []).length,
        dateHolidays: (data.dateHolidays || []).length,
        waliKelas: (data.waliKelas || []).length,
        schedules: (data.schedules || []).length,
        teachers: (data.teachers || []).length,
        settings: (data.settings || []).length,
      };
    }, { timeout: TX_TIMEOUT });

    return result;
  } finally {
    setSkipAutoSync(false);
  }
}

export async function POST(request: NextRequest) {
  try {
    // Allow force-restore even when DB is not empty (e.g., restoring a newer backup)
    const url = new URL(request.url);
    const force = url.searchParams.get('force') === 'true';

    if (!force) {
      const empty = await isDatabaseEmpty();
      if (!empty) {
        return noCacheJson({
          success: false,
          message: 'Auto-restore tidak diperlukan: Database sudah berisi data. Gunakan ?force=true untuk memaksa restore.',
        });
      }
    }

    // GLOBAL LOCK: Don't start restore-local if sync/pull is running.
    const { tryStartOperation, endOperation, recordResult } = await import('@/lib/operation-lock');
    if (!tryStartOperation('restore-local', 'Restore dari Local Backup')) {
      return noCacheJson({
        success: false,
        message: 'Operasi lain sedang berjalan. Tidak bisa memulai restore sekarang.',
      });
    }

    try {
      const filePath = findAutoRestoreFile();
      if (!filePath) {
        return noCacheJson({
          success: false,
          message: 'Auto-restore gagal: File backup auto_restore.json tidak ditemukan',
        });
      }

      const backupData = readBackupFile(filePath);
      if (!backupData) {
        return noCacheJson({
          success: false,
          message: 'Auto-restore gagal: File backup tidak valid',
        });
      }

      const result = await performRestore(backupData);
      console.log('[AutoRestore] Auto-restore berhasil dari:', filePath, result);

      // SAVE RESTORE POINT — sync the restored DB to persistent storage
      // so the data survives future server resets.
      try {
        const { saveRestorePoint } = await import('@/lib/db-persistent-sync');
        await saveRestorePoint(backupData);
        console.log('[AutoRestore] Restore point saved (persistent DB + auto_restore.json)');
      } catch (e) {
        console.warn('[AutoRestore] Could not save restore point:', e instanceof Error ? e.message : String(e));
      }

      recordResult('restore-local', true, `Restored ${result.attendance || 0} records`);
      return noCacheJson({
        success: true,
        message: 'Auto-restore berhasil' + (force ? ' (forced)' : ''),
        restored: result,
      });
    } finally {
      endOperation('restore-local');
    }
  } catch (error) {
    console.error('[AutoRestore API] Error:', error);
    return noCacheJson({
      success: false,
      error: 'Gagal auto-restore: ' + (error instanceof Error ? error.message : 'Unknown'),
    }, 500);
  }
}
"},{"path":"src/app/api/backup/route.ts","content":"import { NextRequest, NextResponse } from 'next/server';
import { noCacheJson } from '@/lib/utils';
import { db } from '@/lib/db';
import { setSkipAutoSync } from '@/lib/auto-sync';
import fs from 'fs';
import path from 'path';

const TX_TIMEOUT = 300_000; // 5 minutes for large data imports
// Try multiple paths for the upload directory (sandbox vs production)
const UPLOAD_DIR = fs.existsSync('/app/upload') ? '/app/upload' : '/home/z/my-project/upload';
const BACKUP_SUBDIR = path.join(UPLOAD_DIR, 'backups');

// Ensure backup directory exists
function ensureBackupDir() {
  try {
    if (!fs.existsSync(BACKUP_SUBDIR)) {
      fs.mkdirSync(BACKUP_SUBDIR, { recursive: true });
    }
  } catch {
    // Upload dir might not exist in production
  }
}

// Save a copy of backup data for auto-restore on restart
// Uses STREAMING write to prevent OOM: writes JSON in chunks instead of
// creating one giant string in memory.
// Also syncs the live DB file to persistent OSS (non-blocking).
function saveAutoRestoreCopyAsync(backupData: any) {
  setImmediate(async () => {
    // 1. Save to upload/backups/ (persistent OSS)
    try {
      ensureBackupDir();
      const autoRestorePath = path.join(BACKUP_SUBDIR, 'auto_restore.json');
      // Use async writeFile (non-blocking)
      const fsp = fs.promises;
      await fsp.writeFile(autoRestorePath, JSON.stringify(backupData), 'utf8');
      console.log(`[Backup] Auto-restore copy saved to ${autoRestorePath} (${Math.round(JSON.stringify(backupData).length / 1024 / 1024)}MB)`);
    } catch (error) {
      console.error('[Backup] Failed to save to upload/backups/:', error instanceof Error ? error.message : 'Unknown');
    }

    // 2. Save to db/ directory
    try {
      const dbDir = path.join(process.cwd(), 'db');
      const fsp = fs.promises;
      if (!fs.existsSync(dbDir)) {
        await fsp.mkdir(dbDir, { recursive: true });
      }
      const dbRestorePath = path.join(dbDir, 'auto_restore.json');
      await fsp.writeFile(dbRestorePath, JSON.stringify(backupData), 'utf8');
      console.log(`[Backup] Auto-restore copy saved to ${dbRestorePath}`);
    } catch (error) {
      console.error('[Backup] Failed to save to db/:', error instanceof Error ? error.message : 'Unknown');
    }

    // 3. Sync live DB to persistent OSS (non-blocking)
    try {
      const { syncLiveDbToPersistent } = await import('@/lib/db-persistent-sync');
      const result = await syncLiveDbToPersistent();
      if (result.copied) {
        console.log(`[Backup] Live DB synced to persistent OSS: ${result.path}`);
      }
    } catch (error) {
      console.error('[Backup] Failed to sync DB:', error instanceof Error ? error.message : 'Unknown');
    }
  });
}

// GET: Export all data as COMPRESSED JSON backup
// Uses STREAMING approach to prevent OOM on FC container (~256MB RAM):
// - Fetch non-attendance data normally (small: classes, students, etc.)
// - Fetch attendance in batches and stream to response
// - Save auto-restore copy in background (non-blocking)
export async function GET() {
  try {
    // Fetch small non-attendance data normally
    const [classes, students, activities, holidays, dateHolidays, waliKelas, schedules, teachers, settings] =
      await Promise.all([
        db.class.findMany({ select: { id: true, name: true } }),
        db.student.findMany(),
        db.academicActivity.findMany({ select: { id: true, classId: true, date: true, status: true } }),
        db.academicHoliday.findMany(),
        db.dateHoliday.findMany({ select: { id: true, date: true, name: true } }),
        db.waliKelas.findMany({ select: { id: true, classId: true, name: true } }),
        db.weeklySchedule.findMany({ select: { id: true, classId: true, dayOfWeek: true, hour: true, teacher: true } }),
        db.teacher.findMany({ select: { id: true, nickname: true, fullName: true } }),
        db.settings.findMany(),
      ]);

    // Fetch attendance in BATCHES to prevent OOM (57k records = ~11MB if loaded all at once)
    const attendance: any[] = [];
    const ATT_BATCH = 5000;
    let attOffset = 0;
    while (true) {
      const batch = await db.attendance.findMany({
        select: { id: true, studentId: true, classId: true, date: true, hour: true, status: true },
        skip: attOffset,
        take: ATT_BATCH,
        orderBy: { id: 'asc' },
      });
      if (batch.length === 0) break;
      attendance.push(...batch);
      attOffset += ATT_BATCH;
      // Allow event loop to process other requests between batches
      await new Promise(r => setImmediate(r));
    }

    const backup = {
      version: 4,
      exportedAt: new Date().toISOString(),
      appName: 'ABSENSI SISWA MTs Al ISHLAH',
      compressed: true,
      data: { classes, students, attendance, activities, holidays, dateHolidays, waliKelas, schedules, teachers, settings },
    };

    // Save auto-restore copy in background (non-blocking)
    saveAutoRestoreCopyAsync(backup);

    const filename = `backup_absensi_${new Date().toISOString().split('T')[0]}_${new Date().getTime()}.json`;
    // Use stringified JSON — the response is streamed by Next.js
    return new NextResponse(JSON.stringify(backup), {
      status: 200,
      headers: {
        'Content-Type': 'application/json',
        'Content-Disposition': `attachment; filename="${filename}"`,
        'Cache-Control': 'no-store',
      },
    });
  } catch (error) {
    console.error('Backup export error:', error);
    return noCacheJson({ error: 'Gagal membuat backup data: ' + (error instanceof Error ? error.message : 'Unknown') }, 500);
  }
}

// POST: Import/restore data from JSON backup file
// Also saves the imported data as auto_restore.json for future restarts
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();

    if (!body || !body.data) {
      return noCacheJson({ error: 'Format file backup tidak valid' }, 400);
    }

    const { data } = body;

    if (!data.classes || !data.students) {
      return noCacheJson({ error: 'File backup tidak mengandung data kelas/siswa' }, 400);
    }

    // Skip auto-sync during restore to prevent sync of partial/empty data
    setSkipAutoSync(true);
    try {
      // Use a transaction with extended timeout for large data imports
      const result = await db.$transaction(async (tx) => {
        // Delete existing data in reverse dependency order
        await tx.attendance.deleteMany();
        await tx.weeklySchedule.deleteMany();
        await tx.teacher.deleteMany();
        await tx.academicActivity.deleteMany();
        await tx.dateHoliday.deleteMany();
        await tx.waliKelas.deleteMany();
        await tx.student.deleteMany();
        await tx.class.deleteMany();
        await tx.academicHoliday.deleteMany();
        await tx.settings.deleteMany();

        // Restore classes (batch)
        if (data.classes && data.classes.length > 0) {
          await tx.class.createMany({
            data: data.classes.map((cls: any) => ({
              id: cls.id, name: cls.name,
              createdAt: cls.createdAt ? new Date(cls.createdAt) : undefined,
              updatedAt: cls.updatedAt ? new Date(cls.updatedAt) : undefined,
            })),
          });
        }

        // Restore students (batch)
        if (data.students && data.students.length > 0) {
          await tx.student.createMany({
            data: data.students.map((s: any) => ({
              id: s.id, name: s.name, nisn: s.nisn || '', gender: s.gender || '',
              whatsapp: s.whatsapp || '', classId: s.classId,
              createdAt: s.createdAt ? new Date(s.createdAt) : undefined,
              updatedAt: s.updatedAt ? new Date(s.updatedAt) : undefined,
            })),
          });
        }

        // Restore attendance (batch, chunked for large datasets)
        if (data.attendance && data.attendance.length > 0) {
          const CHUNK_SIZE = 500;
          for (let i = 0; i < data.attendance.length; i += CHUNK_SIZE) {
            const chunk = data.attendance.slice(i, i + CHUNK_SIZE);
            await tx.attendance.createMany({
              data: chunk.map((a: any) => ({
                id: a.id, studentId: a.studentId, classId: a.classId,
                date: a.date, hour: a.hour, status: a.status,
                createdAt: a.createdAt ? new Date(a.createdAt) : undefined,
                updatedAt: a.updatedAt ? new Date(a.updatedAt) : undefined,
              })),
            });
          }
        }

        // Restore academic activities (batch)
        if (data.activities && data.activities.length > 0) {
          await tx.academicActivity.createMany({
            data: data.activities.map((a: any) => ({
              id: a.id, classId: a.classId, date: a.date,
              status: a.status || 'Masuk',
              createdAt: a.createdAt ? new Date(a.createdAt) : undefined,
              updatedAt: a.updatedAt ? new Date(a.updatedAt) : undefined,
            })),
          });
        }

        // Restore holidays (batch)
        if (data.holidays && data.holidays.length > 0) {
          await tx.academicHoliday.createMany({
            data: data.holidays.map((h: any) => ({
              id: h.id, dayOfWeek: h.dayOfWeek, name: h.name || '',
              isActive: h.isActive !== false,
            })),
          });
        }

        // Restore date holidays (batch)
        if (data.dateHolidays && data.dateHolidays.length > 0) {
          await tx.dateHoliday.createMany({
            data: data.dateHolidays.map((dh: any) => ({
              id: dh.id, date: dh.date, name: dh.name || '',
              createdAt: dh.createdAt ? new Date(dh.createdAt) : undefined,
              updatedAt: dh.updatedAt ? new Date(dh.updatedAt) : undefined,
            })),
          });
        }

        // Restore wali kelas (batch)
        if (data.waliKelas && data.waliKelas.length > 0) {
          await tx.waliKelas.createMany({
            data: data.waliKelas.map((w: any) => ({
              id: w.id, classId: w.classId, name: w.name || '',
              createdAt: w.createdAt ? new Date(w.createdAt) : undefined,
              updatedAt: w.updatedAt ? new Date(w.updatedAt) : undefined,
            })),
          });
        }

        // Restore weekly schedules (batch)
        if (data.schedules && data.schedules.length > 0) {
          await tx.weeklySchedule.createMany({
            data: data.schedules.map((s: any) => ({
              id: s.id, classId: s.classId, dayOfWeek: s.dayOfWeek,
              hour: s.hour, teacher: s.teacher || '',
              createdAt: s.createdAt ? new Date(s.createdAt) : undefined,
              updatedAt: s.updatedAt ? new Date(s.updatedAt) : undefined,
            })),
          });
        }

        // Restore teacher name mappings (batch)
        if (data.teachers && data.teachers.length > 0) {
          await tx.teacher.createMany({
            data: data.teachers.map((t: any) => ({
              id: t.id, nickname: t.nickname, fullName: t.fullName || '',
              createdAt: t.createdAt ? new Date(t.createdAt) : undefined,
              updatedAt: t.updatedAt ? new Date(t.updatedAt) : undefined,
            })),
          });
        }

        // Restore settings
        if (data.settings && data.settings.length > 0) {
          for (const setting of data.settings) {
            try {
              await tx.settings.create({ data: { key: setting.key, value: setting.value } });
            } catch {
              // Skip duplicates
            }
          }
        }

        return {
          classes: (data.classes || []).length,
          students: (data.students || []).length,
          attendance: (data.attendance || []).length,
          activities: (data.activities || []).length,
          holidays: (data.holidays || []).length,
          dateHolidays: (data.dateHolidays || []).length,
          waliKelas: (data.waliKelas || []).length,
          schedules: (data.schedules || []).length,
          teachers: (data.teachers || []).length,
          settings: (data.settings || []).length,
        };
      }, { timeout: TX_TIMEOUT });

      // Save auto-restore copy of the restored data
      saveAutoRestoreCopyAsync(body);

      return noCacheJson({ success: true, message: 'Data berhasil di-restore', restored: result });
    } finally {
      setSkipAutoSync(false);
    }
  } catch (error) {
    setSkipAutoSync(false);
    console.error('Backup restore error:', error);
    return noCacheJson({ error: 'Gagal restore data: ' + (error instanceof Error ? error.message : 'Unknown error') }, 500);
  }
}
"},{"path":"src/app/api/check-absensi/cari-guru/route.ts","content":"import { NextRequest } from 'next/server';
import { noCacheJson } from '@/lib/utils';
import { db } from '@/lib/db';
import { resolveTeacherNameWithMap } from '@/lib/teacher-names';

export const dynamic = 'force-dynamic';

function parseDate(dateStr: string): Date {
  const [y, m, d] = dateStr.split('-').map(Number);
  return new Date(y, m - 1, d);
}
function formatDateStr(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}
function getDayOfWeek(dateStr: string): number { return parseDate(dateStr).getDay(); }
const DAY_NAMES = ['Ahad', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
function formatDDMMYYYY(dateStr: string): string {
  const d = parseDate(dateStr);
  return `${String(d.getDate()).padStart(2, '0')}-${String(d.getMonth() + 1).padStart(2, '0')}-${d.getFullYear()}`;
}

interface SearchResult { date: string; dayName: string; formattedDate: string; className: string; hours: number[]; }

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const query = (searchParams.get('query') || '').trim().toLowerCase();
    const date = searchParams.get('date');
    if (!query) return noCacheJson({ results: [], query: '', message: 'Masukkan nama guru' });
    if (!date) return noCacheJson({ error: 'Parameter date diperlukan' }, 400);

    const baseDate = parseDate(date);
    const year = baseDate.getFullYear();
    const month = baseDate.getMonth();
    const startD = new Date(year, month, 1);
    const endD = new Date(year, month + 1, 0);

    const holidays = await db.academicHoliday.findMany({ where: { isActive: true } });
    const holidayDays = new Set(holidays.map(h => h.dayOfWeek));
    const dateHolidays = await db.dateHoliday.findMany();
    const dateHolidaySet = new Set(dateHolidays.map(dh => dh.date));

    const schoolDays: string[] = [];
    const cur = new Date(startD);
    while (cur <= endD) {
      const dow = cur.getDay();
      const ds = formatDateStr(cur);
      if (!holidayDays.has(dow) && !dateHolidaySet.has(ds)) schoolDays.push(ds);
      cur.setDate(cur.getDate() + 1);
    }

    const dayOfWeeks = new Set(schoolDays.map(ds => getDayOfWeek(ds)));
    const schedules = await db.weeklySchedule.findMany({ where: { dayOfWeek: { in: [...dayOfWeeks] } } });
    const classes = await db.class.findMany({ include: { _count: { select: { students: true } } } });
    const classNameMap = new Map<string, string>();
    const activeClassIds = new Set<string>();
    for (const cls of classes) { classNameMap.set(cls.id, cls.name); if (!cls.name.toLowerCase().includes('libur') && cls._count.students > 0) activeClassIds.add(cls.id); }
    const activeSchedules = schedules.filter(s => activeClassIds.has(s.classId));

    const allAttendance = await db.attendance.findMany({ where: { date: { in: schoolDays } }, select: { classId: true, date: true, hour: true } });
    const filledSet = new Set<string>();
    for (const r of allAttendance) filledSet.add(`${r.classId}:${r.date}:${r.hour}`);

    // Load per-date max hours settings
    const maxHoursSettings = await db.settings.findMany({
      where: { key: { startsWith: 'max_hours_' } },
    });
    const maxHoursByDate: Record<string, number> = {};
    for (const s of maxHoursSettings) {
      const datePart = s.key.replace('max_hours_', '');
      const n = parseInt(s.value, 10);
      if (!isNaN(n)) maxHoursByDate[datePart] = n;
    }

    // Load academic activities for Libur dates
    const activities = await db.academicActivity.findMany({
      where: { date: { in: schoolDays } },
      select: { classId: true, date: true, status: true },
    });
    const liburClassDate = new Set<string>();
    for (const a of activities) {
      if (a.status === 'Libur') liburClassDate.add(`${a.classId}:${a.date}`);
    }

    const teacherRows = await db.teacher.findMany();
    const teacherMap: Record<string, string> = {};
    for (const t of teacherRows) teacherMap[t.nickname] = t.fullName;

    const matchingSchedules = activeSchedules.filter(s => {
      const nickname = s.teacher.trim().toLowerCase();
      const fullName = (resolveTeacherNameWithMap(s.teacher.trim(), teacherMap) || '').toLowerCase();
      return nickname.includes(query) || fullName.includes(query);
    });

    if (matchingSchedules.length === 0) return noCacheJson({ results: [], query, teacherName: '', message: 'Guru tidak ditemukan' });

    const firstMatch = matchingSchedules[0];
    const teacherFullName = resolveTeacherNameWithMap(firstMatch.teacher.trim(), teacherMap);
    const results: SearchResult[] = [];
    const missedMap = new Map<string, Map<string, Set<number>>>();

    for (const sched of matchingSchedules) {
      const dow = sched.dayOfWeek;
      for (const ds of schoolDays) {
        if (getDayOfWeek(ds) !== dow) continue;
        // Skip if class is on Libur for this date
        if (liburClassDate.has(`${sched.classId}:${ds}`)) continue;
        // Skip if hour > maxHours for this date
        const maxHours = maxHoursByDate[ds] ?? 8;
        if (sched.hour > maxHours) continue;
        const filled = filledSet.has(`${sched.classId}:${ds}:${sched.hour}`);
        if (!filled) {
          if (!missedMap.has(ds)) missedMap.set(ds, new Map());
          const classMap = missedMap.get(ds)!;
          if (!classMap.has(sched.classId)) classMap.set(sched.classId, new Set());
          classMap.get(sched.classId)!.add(sched.hour);
        }
      }
    }

    for (const [ds, classMap] of missedMap) {
      for (const [classId, hours] of classMap) {
        results.push({ date: ds, dayName: DAY_NAMES[getDayOfWeek(ds)], formattedDate: `${formatDDMMYYYY(ds)} (${DAY_NAMES[getDayOfWeek(ds)]})`, className: classNameMap.get(classId) || classId, hours: [...hours].sort((a, b) => a - b) });
      }
    }
    results.sort((a, b) => b.date.localeCompare(a.date));

    return noCacheJson({ results, query, teacherName: teacherFullName, teacherNickname: firstMatch.teacher.trim(), totalMissed: results.length });
  } catch (error) {
    console.error('Error searching guru:', error);
    return noCacheJson({ error: 'Gagal mencari guru' }, 500);
  }
}
"},{"path":"src/app/api/check-absensi/rekap-guru/pdf/route.ts","content":"import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';
import { resolveTeacherNameWithMap } from '@/lib/teacher-names';
import PDFDocument from 'pdfkit';
import * as fs from 'fs';
import * as path from 'path';

export const dynamic = 'force-dynamic';
export const maxDuration = 60;

function parseDate(dateStr: string): Date {
  const [y, m, d] = dateStr.split('-').map(Number);
  return new Date(y, m - 1, d);
}

function formatDateStr(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function getDayOfWeek(dateStr: string): number {
  return parseDate(dateStr).getDay();
}

const DAY_NAMES = ['Ahad', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const MONTHS = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];

function formatDDMMYYYY(dateStr: string): string {
  const d = parseDate(dateStr);
  return `${String(d.getDate()).padStart(2, '0')}-${String(d.getMonth() + 1).padStart(2, '0')}-${d.getFullYear()}`;
}

// Format like the web view: "DD MMMM YYYY" (e.g., "2 Oktober 2026")
function formatLongDate(dateStr: string): string {
  const d = parseDate(dateStr);
  return `${d.getDate()} ${MONTHS[d.getMonth()]} ${d.getFullYear()}`;
}

interface TeacherEntry {
  fullName: string;
  classId: string;
  className: string;
  hours: number[];
}
interface DayTable {
  date: string;
  dayName: string;
  formattedDate: string;
  teachers: TeacherEntry[];
}

/**
 * GET /api/check-absensi/rekap-guru/pdf?date=YYYY-MM-DD
 *
 * Generates a PDF with one table per school day in the 7-day window ending
 * at `date` (newest first, excluding academic holidays). Each table lists
 * only teachers who haven't filled attendance that day, with columns:
 * NO, NAMA GURU, KELAS, JAM KE- (matching the web view layout).
 *
 * Title: "REKAP GURU BELUM MENGISI ABSENSI SISWA"
 * Subtitle: "Tanggal DD-MM-YYYY sampai dengan DD-MM-YYYY"
 * Per-day sub-title: "Rekap Guru Hari {dayName}, Tanggal {DD MMMM YYYY}"
 * Filename: "Rekap_Guru_{windowStart}_sd_{windowEnd}.pdf" (YYYY-MM-DD format)
 * Also saved to: /home/z/my-project/upload/Rekap_Guru_{windowStart}_sd_{windowEnd}.pdf
 */
export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const date = searchParams.get('date');

  if (!date) {
    return NextResponse.json({ error: 'Parameter date diperlukan' }, { status: 400 });
  }

  try {
    const endD = parseDate(date);
    const startD = new Date(endD);
    startD.setDate(endD.getDate() - 6);
    const windowStart = formatDateStr(startD);
    const windowEnd = formatDateStr(endD);

    // Build school days list (exclude weekly + date holidays)
    const holidays = await db.academicHoliday.findMany({ where: { isActive: true } });
    const holidayDays = new Set(holidays.map(h => h.dayOfWeek));
    const dateHolidays = await db.dateHoliday.findMany();
    const dateHolidaySet = new Set(dateHolidays.map(dh => dh.date));

    const schoolDays: string[] = [];
    const cur = new Date(startD);
    while (cur <= endD) {
      const dow = cur.getDay();
      const ds = formatDateStr(cur);
      if (!holidayDays.has(dow) && !dateHolidaySet.has(ds)) {
        schoolDays.push(ds);
      }
      cur.setDate(cur.getDate() + 1);
    }

    // Fetch schedules + classes + attendance + teachers
    const dayOfWeeks = new Set(schoolDays.map(ds => getDayOfWeek(ds)));
    const schedules = await db.weeklySchedule.findMany({
      where: { dayOfWeek: { in: [...dayOfWeeks] } },
    });

    const classes = await db.class.findMany({
      include: { _count: { select: { students: true } } },
    });
    const classNameMap = new Map<string, string>();
    for (const cls of classes) classNameMap.set(cls.id, cls.name);
    const activeClassIds = new Set<string>();
    for (const cls of classes) {
      if (!cls.name.toLowerCase().includes('libur') && cls._count.students > 0) {
        activeClassIds.add(cls.id);
      }
    }

    const activeSchedules = schedules.filter(s => activeClassIds.has(s.classId));
    const allAttendance = await db.attendance.findMany({
      where: { date: { in: schoolDays } },
      select: { classId: true, date: true, hour: true },
    });
    const filledSet = new Set<string>();
    for (const r of allAttendance) {
      filledSet.add(`${r.classId}:${r.date}:${r.hour}`);
    }

    // Load per-date max hours settings (key: max_hours_YYYY-MM-DD, default 8).
    // A day with max_hours=4 means teachers only need to fill jam 1-4; jam 5-8
    // are excluded from the "belum mengisi" check for that date.
    const maxHoursSettings = await db.settings.findMany({
      where: { key: { startsWith: 'max_hours_' } },
    });
    const maxHoursByDate: Record<string, number> = {};
    for (const s of maxHoursSettings) {
      const datePart = s.key.replace('max_hours_', '');
      const n = parseInt(s.value, 10);
      if (!isNaN(n)) maxHoursByDate[datePart] = n;
    }

    // Load academic activities to find Libur dates per class (exclude those
    // class+date combos from the "belum mengisi" check entirely).
    const activities = await db.academicActivity.findMany({
      where: { date: { in: schoolDays } },
      select: { classId: true, date: true, status: true },
    });
    const liburClassDate = new Set<string>();
    for (const a of activities) {
      if (a.status === 'Libur') liburClassDate.add(`${a.classId}:${a.date}`);
    }

    const teacherRows = await db.teacher.findMany();
    const teacherMap: Record<string, string> = {};
    for (const t of teacherRows) teacherMap[t.nickname] = t.fullName;

    // Build per-day tables (NEWEST FIRST) — matches the web view order
    const days: DayTable[] = [];
    for (let i = schoolDays.length - 1; i >= 0; i--) {
      const ds = schoolDays[i];
      const dow = getDayOfWeek(ds);
      const dObj = parseDate(ds);
      const dayName = DAY_NAMES[dow];
      // Match web view: "dayName, DD MMMM YYYY" (e.g., "Rabu, 2 Oktober 2026")
      const formattedDate = `${dayName}, ${dObj.getDate()} ${MONTHS[dObj.getMonth()]} ${dObj.getFullYear()}`;

      // Max hours for this date (default 8). Jam above maxHours are excluded.
      const maxHours = maxHoursByDate[ds] ?? 8;

      const teacherClassMap = new Map<string, { fullName: string; classId: string; className: string; hours: Set<number> }>();
      for (const sched of activeSchedules) {
        if (sched.dayOfWeek !== dow) continue;
        // Skip if this class is on Libur for this date
        if (liburClassDate.has(`${sched.classId}:${ds}`)) continue;
        // Skip if this hour is above the max hours for this date
        if (sched.hour > maxHours) continue;
        const teacher = sched.teacher.trim();
        if (!teacher) continue;
        const filled = filledSet.has(`${sched.classId}:${ds}:${sched.hour}`);
        if (!filled) {
          const key = `${teacher}|${sched.classId}`;
          let entry = teacherClassMap.get(key);
          if (!entry) {
            entry = {
              fullName: resolveTeacherNameWithMap(teacher, teacherMap),
              classId: sched.classId,
              className: classNameMap.get(sched.classId) || sched.classId,
              hours: new Set<number>(),
            };
            teacherClassMap.set(key, entry);
          }
          entry.hours.add(sched.hour);
        }
      }

      const teachers: TeacherEntry[] = [];
      for (const entry of teacherClassMap.values()) {
        teachers.push({
          fullName: entry.fullName,
          classId: entry.classId,
          className: entry.className,
          hours: [...entry.hours].sort((a, b) => a - b),
        });
      }
      teachers.sort((a, b) => {
        const c = a.fullName.localeCompare(b.fullName);
        if (c !== 0) return c;
        return a.className.localeCompare(b.className);
      });

      days.push({ date: ds, dayName, formattedDate, teachers });
    }

    // ===== Generate PDF =====
    const doc = new PDFDocument({
      size: 'A4',
      margins: { top: 40, bottom: 40, left: 40, right: 40 },
      info: {
        Title: `REKAP GURU BELUM MENGISI ABSENSI SISWA ${windowStart} sd ${windowEnd}`,
        Author: 'MTs Al Ishlah',
      },
    });

    const chunks: Uint8Array[] = [];
    doc.on('data', (chunk: Uint8Array) => chunks.push(chunk));

    const pdfBuffer = await new Promise<Buffer>((resolve, reject) => {
      doc.on('end', () => resolve(Buffer.concat(chunks)));
      doc.on('error', reject);

      const PW = doc.page.width;
      const ML = 40, MR = 40;
      const CW = PW - ML - MR;

      // ===== TITLE (uppercase, with "SISWA" suffix per user request) =====
      doc.font('Helvetica-Bold').fontSize(14).fillColor('#000000');
      const title = `REKAP GURU BELUM MENGISI ABSENSI SISWA`;
      doc.text(title, ML, 40, { width: CW, align: 'center' });
      doc.fontSize(12);
      doc.text(`Tanggal ${formatDDMMYYYY(windowStart)} sampai dengan ${formatDDMMYYYY(windowEnd)}`, ML, 60, { width: CW, align: 'center' });

      let y = 90;

      // ===== PER-DAY TABLES (matches web view layout) =====
      for (const day of days) {
        // Check page break
        if (y > doc.page.height - 40 - 60) {
          doc.addPage();
          y = 40;
        }

        // Per-day sub-title — matches web: "Rekap Guru Hari {dayName}, Tanggal {DD MMMM YYYY}"
        doc.font('Helvetica-Bold').fontSize(11).fillColor('#000000');
        doc.text(`Rekap Guru Hari ${day.dayName}, Tanggal ${formatLongDate(day.date)}`, ML, y, { width: CW, align: 'left' });
        y += 18;

        // Entry count (matches web: "{n} entri")
        doc.font('Helvetica-Oblique').fontSize(9).fillColor('#555555');
        doc.text(`${day.teachers.length} entri`, ML, y, { width: CW, align: 'left' });
        y += 16;

        if (day.teachers.length === 0) {
          doc.font('Helvetica-Oblique').fontSize(10).fillColor('#555555');
          doc.text('Semua guru sudah mengisi absensi hari ini.', ML, y, { width: CW });
          y += 20;
          y += 16;
          continue;
        }

        // Table — matches web headers: NO, NAMA GURU, KELAS, JAM KE-
        const colW = [30, 200, 120, 98]; // NO, NAMA GURU, KELAS, JAM KE-
        const totalW = colW.reduce((a, b) => a + b, 0);
        const tableLeft = ML + (CW - totalW) / 2;
        const rowH = 20;
        const headerH = 18;

        // Header background (light green to match web's neon-table aesthetic)
        doc.rect(tableLeft, y, totalW, headerH).fillColor('#99FF33').fill();

        // Header text
        doc.font('Helvetica-Bold').fontSize(9).fillColor('#000000');
        const headers = ['NO', 'NAMA GURU', 'KELAS', 'JAM KE-'];
        let runX = tableLeft;
        for (let ci = 0; ci < headers.length; ci++) {
          doc.text(headers[ci], runX + 2, y + 5, { width: colW[ci] - 4, align: 'center' });
          runX += colW[ci];
        }
        y += headerH;

        // Data rows
        doc.font('Helvetica').fontSize(9).fillColor('#000000');
        for (let ri = 0; ri < day.teachers.length; ri++) {
          const t = day.teachers[ri];
          // Check page break
          if (y > doc.page.height - 40 - rowH) {
            doc.addPage();
            y = 40;
          }
          // Row border
          doc.rect(tableLeft, y, totalW, rowH).strokeColor('#000000').lineWidth(0.5).stroke();
          // Cell text
          doc.text(String(ri + 1), tableLeft + 2, y + 6, { width: colW[0] - 4, align: 'center' });
          doc.text(t.fullName, tableLeft + colW[0] + 2, y + 6, { width: colW[1] - 4, align: 'left' });
          doc.text(t.className, tableLeft + colW[0] + colW[1] + 2, y + 6, { width: colW[2] - 4, align: 'center' });
          // JAM KE-: comma-separated hours (matches web which shows hour badges)
          doc.text(t.hours.join(', '), tableLeft + colW[0] + colW[1] + colW[2] + 2, y + 6, { width: colW[3] - 4, align: 'center' });
          y += rowH;
        }
        y += 16;
      }

      doc.end();
    });

    // Filename format: Rekap_Guru_YYYY-MM-DD_sd_YYYY-MM-DD.pdf
    const filename = `Rekap_Guru_${windowStart}_sd_${windowEnd}.pdf`;

    // Also save the PDF to /home/z/my-project/upload/ for archival
    try {
      const uploadDir = path.join(process.cwd(), 'upload');
      if (!fs.existsSync(uploadDir)) {
        fs.mkdirSync(uploadDir, { recursive: true });
      }
      const filePath = path.join(uploadDir, filename);
      fs.writeFileSync(filePath, pdfBuffer);
      console.log(`[Rekap Guru PDF] Saved to ${filePath}`);
    } catch (saveErr) {
      // Non-fatal: file save failure should NOT block the PDF response
      console.warn('[Rekap Guru PDF] Could not save to upload dir:', saveErr instanceof Error ? saveErr.message : String(saveErr));
    }

    return new NextResponse(new Uint8Array(pdfBuffer), {
      status: 200,
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `inline; filename="${filename}"`,
      },
    });
  } catch (error) {
    console.error('Rekap Guru PDF error:', error);
    return NextResponse.json({ error: 'Gagal membuat PDF: ' + (error instanceof Error ? error.message : String(error)) }, { status: 500 });
  }
}
"},{"path":"src/app/api/check-absensi/rekap-guru/route.ts","content":"import { NextRequest } from 'next/server';
import { noCacheJson } from '@/lib/utils';
import { computeRekapGuruData, isValidDateStr, parseDate, formatDateStr, MAX_RANGE_DAYS, type RekapGroupBy } from '@/lib/rekap-guru-data';

export const dynamic = 'force-dynamic';

/**
 * GET /api/check-absensi/rekap-guru
 *
 * Supported modes (query `mode`):
 * - week  (default): ?date=YYYY-MM-DD → 7-day window (date-6 .. date)
 * - month: ?mode=month&month=1..12&year=YYYY → first day..last day of that month
 * - range: ?mode=range&startDate=YYYY-MM-DD&endDate=YYYY-MM-DD → custom window
 *          (rejected when endDate < startDate, capped at 400 days)
 *
 * Grouping (query `groupBy`) — must match the PDF/Excel exports:
 * - date    (default): returns `days` — one table PER school day, NEWEST FIRST
 *           (selected date at top, going back downward) so the most recent
 *           incomplete attendance is shown first. Table rows: NAMA GURU, KELAS, JAM KE-.
 * - teacher: returns `teachers` — per-teacher aggregation across ALL school
 *           days in the window, sorted by totalMissed DESC then fullName ASC.
 *           totalMissed = sum of missing jam across all entries.
 *           Entry rows: TANGGAL, KELAS, JAM KE-.
 *
 * Each day's table contains ONLY teachers who have NOT filled attendance
 * for at least one class/jam on that specific day. Weekly academic holidays
 * and per-date holidays are excluded from the school-day window.
 *
 * All computation lives in src/lib/rekap-guru-data.ts so the web view,
 * preview, print, PDF and Excel exports always show the same data.
 */
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const mode = searchParams.get('mode') || 'week';
    const groupByRaw = searchParams.get('groupBy') || 'date';

    if (mode !== 'week' && mode !== 'month' && mode !== 'range') {
      return noCacheJson({ error: 'Parameter mode tidak valid (week | month | range)' }, 400);
    }
    if (groupByRaw !== 'date' && groupByRaw !== 'teacher') {
      return noCacheJson({ error: 'Parameter groupBy tidak valid (date | teacher)' }, 400);
    }
    const groupBy: RekapGroupBy = groupByRaw;

    let date: string;
    let windowStart: string;
    let windowEnd: string;

    if (mode === 'week') {
      const dateParam = searchParams.get('date');
      if (!dateParam) {
        return noCacheJson({ error: 'Parameter date diperlukan' }, 400);
      }
      if (!isValidDateStr(dateParam)) {
        return noCacheJson({ error: 'Parameter date tidak valid (format YYYY-MM-DD)' }, 400);
      }
      const endD = parseDate(dateParam);
      const startD = new Date(endD);
      startD.setDate(endD.getDate() - 6); // 7-day window inclusive of `date`
      windowStart = formatDateStr(startD);
      windowEnd = formatDateStr(endD);
      date = dateParam;
    } else if (mode === 'month') {
      const monthRaw = searchParams.get('month');
      const yearRaw = searchParams.get('year');
      if (!monthRaw || !yearRaw) {
        return noCacheJson({ error: 'Parameter month dan year diperlukan' }, 400);
      }
      const month = parseInt(monthRaw, 10);
      const year = parseInt(yearRaw, 10);
      if (isNaN(month) || isNaN(year) || month < 1 || month > 12 || year < 2000 || year > 2100) {
        return noCacheJson({ error: 'Parameter month (1-12) dan year (2000-2100) tidak valid' }, 400);
      }
      windowStart = formatDateStr(new Date(year, month - 1, 1));
      windowEnd = formatDateStr(new Date(year, month, 0)); // day 0 of next month = last day of this month
      date = windowEnd;
    } else {
      // mode === 'range'
      const startDate = searchParams.get('startDate');
      const endDate = searchParams.get('endDate');
      if (!startDate || !endDate) {
        return noCacheJson({ error: 'Parameter startDate dan endDate diperlukan' }, 400);
      }
      if (!isValidDateStr(startDate) || !isValidDateStr(endDate)) {
        return noCacheJson({ error: 'Parameter startDate/endDate tidak valid (format YYYY-MM-DD)' }, 400);
      }
      if (endDate < startDate) {
        return noCacheJson({ error: 'endDate tidak boleh lebih awal dari startDate' }, 400);
      }
      const dayCount = Math.round((parseDate(endDate).getTime() - parseDate(startDate).getTime()) / 86400000) + 1;
      if (dayCount > MAX_RANGE_DAYS) {
        return noCacheJson({ error: 'Rentang maksimal 400 hari' }, 400);
      }
      windowStart = startDate;
      windowEnd = endDate;
      date = endDate;
    }

    const computed = await computeRekapGuruData(windowStart, windowEnd);

    const base = {
      mode,
      groupBy,
      date,
      windowStart,
      windowEnd,
      totalSchoolDays: computed.schoolDays.length,
    };

    if (groupBy === 'teacher') {
      return noCacheJson({ ...base, teachers: computed.teacherGroups });
    }

    // groupBy=date: DAYS ARE ORDERED NEWEST FIRST (selected date at the top)
    return noCacheJson({ ...base, days: computed.daysNewestFirst });
  } catch (error) {
    console.error('Error fetching rekap guru:', error);
    return noCacheJson({ error: 'Gagal mengambil rekap guru' }, 500);
  }
}
"},{"path":"src/app/api/check-absensi/route.ts","content":"import { NextRequest } from 'next/server'
import { noCacheJson } from '@/lib/utils'
import { db } from '@/lib/db'
import { resolveTeacherNameWithMap } from '@/lib/teacher-names'

function getDayOfWeek(dateStr: string): number {
  const [y, m, d] = dateStr.split('-').map(Number)
  return new Date(Date.UTC(y, m - 1, d)).getUTCDay()
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const date = searchParams.get('date')

    if (!date) {
      return noCacheJson({ error: 'Parameter date diperlukan' }, 400)
    }

    const dayOfWeek = getDayOfWeek(date)

    // Check holidays
    const dateHoliday = await db.dateHoliday.findUnique({ where: { date } })
    const weeklyHoliday = await db.academicHoliday.findUnique({ where: { dayOfWeek } })
    const isHoliday = !!(dateHoliday || (weeklyHoliday?.isActive))
    const holidayName = dateHoliday?.name || weeklyHoliday?.name || undefined

    // Get max hours
    const hourSetting = await db.settings.findUnique({
      where: { key: `max_hours_${date}` },
    })
    const maxHours = hourSetting ? parseInt(hourSetting.value, 10) : 8

    // Get schedules for the day
    const schedules = await db.weeklySchedule.findMany({
      where: { dayOfWeek },
    })

    // Load DB-managed teacher name mappings (nickname → full name + gelar)
    const teacherRows = await db.teacher.findMany()
    const teacherNameMap: Record<string, string> = {}
    for (const t of teacherRows) {
      teacherNameMap[t.nickname] = t.fullName
    }

    // Get all classes with student counts
    const classes = await db.class.findMany({
      include: {
        _count: { select: { students: true } },
      },
    })

    // Build a set of active class IDs (not Libur, has students)
    const activeClassIds = new Set<string>()
    const classNameMap = new Map<string, string>()
    for (const cls of classes) {
      classNameMap.set(cls.id, cls.name)
      if (!cls.name.toLowerCase().includes('libur') && cls._count.students > 0) {
        activeClassIds.add(cls.id)
      }
    }

    // Filter schedules to active classes only, and hours within maxHours
    const activeSchedules = schedules.filter(
      s => activeClassIds.has(s.classId) && s.hour <= maxHours
    )

    // Get all attendance records for this date
    const allAttendance = await db.attendance.findMany({
      where: { date },
      select: { classId: true, hour: true },
    })

    // Build a set of filled (classId, hour) pairs
    const filledSet = new Set<string>()
    for (const record of allAttendance) {
      filledSet.add(`${record.classId}:${record.hour}`)
    }

    // Group schedules by teacher
    const teacherMap = new Map<string, { classId: string; hour: number }[]>()
    for (const sched of activeSchedules) {
      const teacher = sched.teacher.trim()
      if (!teacher) continue
      if (!teacherMap.has(teacher)) teacherMap.set(teacher, [])
      teacherMap.get(teacher)!.push({ classId: sched.classId, hour: sched.hour })
    }

    // Build teacher results
    const teachers: {
      fullName: string;
      nickname: string;
      totalScheduled: number;
      totalFilled: number;
      isComplete: boolean;
      missingClasses: { className: string; hours: number[] }[];
    }[] = []

    for (const [nickname, entries] of teacherMap) {
      const totalScheduled = entries.length
      const missingClasses: { className: string; hours: number[] }[] = []
      let totalFilled = 0

      const classHoursMap = new Map<string, number[]>()
      for (const entry of entries) {
        if (!classHoursMap.has(entry.classId)) classHoursMap.set(entry.classId, [])
        classHoursMap.get(entry.classId)!.push(entry.hour)

        if (filledSet.has(`${entry.classId}:${entry.hour}`)) {
          totalFilled++
        }
      }

      // Find missing classes
      for (const [classId, hours] of classHoursMap) {
        const missingHours = hours.filter(h => !filledSet.has(`${classId}:${h}`))
        if (missingHours.length > 0) {
          missingClasses.push({
            className: classNameMap.get(classId) || classId,
            hours: missingHours,
          })
        }
      }

      teachers.push({
        fullName: resolveTeacherNameWithMap(nickname, teacherNameMap),
        nickname,
        totalScheduled,
        totalFilled,
        isComplete: totalFilled >= totalScheduled,
        missingClasses,
      })
    }

    // Sort: incomplete first, then alphabetically by fullName
    teachers.sort((a, b) => {
      if (a.isComplete !== b.isComplete) return a.isComplete ? 1 : -1
      return a.fullName.localeCompare(b.fullName)
    })

    return noCacheJson({ date, isHoliday, holidayName, teachers })
  } catch (error) {
    console.error('Error fetching check-absensi data:', error)
    return noCacheJson({ error: 'Gagal mengambil data check absensi' }, 500)
  }
}
"},{"path":"src/app/api/classes/route.ts","content":"import { NextRequest } from 'next/server'
import { noCacheJson } from '@/lib/utils'
import { db } from '@/lib/db'
import { scheduleAutoSync, scheduleGSheetSync, markGSheetDirty } from '@/lib/auto-sync'

const DEFAULT_CLASSES = [
  '7 Tahfidz',
  '8 Tahfidz',
  '8 Bahasa',
  '9 Tahfidz',
  '9 Kitab',
  '9 Bahasa',
]

async function seedDefaults() {
  const classCount = await db.class.count()
  if (classCount === 0) {
    for (const name of DEFAULT_CLASSES) {
      await db.class.create({ data: { name } })
    }
  }
  // Seed Friday (dayOfWeek=5) as default holiday
  const fridayHoliday = await db.academicHoliday.findUnique({ where: { dayOfWeek: 5 } })
  if (!fridayHoliday) {
    await db.academicHoliday.create({ data: { dayOfWeek: 5, name: 'Hari Jumat', isActive: true } })
  }
}

export async function GET() {
  try {
    await seedDefaults()

    const classes = await db.class.findMany({
      include: {
        _count: {
          select: { students: true },
        },
        waliKelas: {
          select: { name: true },
        },
      },
      orderBy: { name: 'asc' },
    })

    const result = classes.map((c) => ({
      id: c.id,
      name: c.name,
      studentCount: c._count.students,
      waliKelasName: c.waliKelas?.name ?? '',
      createdAt: c.createdAt,
      updatedAt: c.updatedAt,
    }))

    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson(result)
  } catch (error) {
    console.error('Error fetching classes:', error)
    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson(
      { error: 'Gagal mengambil data kelas' },
      500
    )
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json()
    const { name } = body

    if (!name || typeof name !== 'string' || !name.trim()) {
      return noCacheJson({ error: 'Nama rombel diperlukan' }, 400)
    }

    const trimmed = name.trim()

    // Check duplicate
    const existing = await db.class.findUnique({ where: { name: trimmed } })
    if (existing) {
      return noCacheJson({ error: 'Nama rombel sudah ada' }, 409)
    }

    const newClass = await db.class.create({ data: { name: trimmed } })
    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson({ id: newClass.id, name: newClass.name }, 201)
  } catch (error) {
    console.error('Error creating class:', error)
    return noCacheJson({ error: 'Gagal menambah rombel' }, 500)
  }
}

export async function PUT(request: NextRequest) {
  try {
    const body = await request.json()
    const { classId, name } = body

    if (!classId || !name || typeof name !== 'string' || !name.trim()) {
      return noCacheJson({ error: 'classId dan nama diperlukan' }, 400)
    }

    const trimmed = name.trim()

    // Check duplicate (excluding current class)
    const existing = await db.class.findUnique({ where: { name: trimmed } })
    if (existing && existing.id !== classId) {
      return noCacheJson({ error: 'Nama rombel sudah ada' }, 409)
    }

    const updated = await db.class.update({
      where: { id: classId },
      data: { name: trimmed },
    })
    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson({ id: updated.id, name: updated.name })
  } catch (error) {
    console.error('Error updating class:', error)
    return noCacheJson({ error: 'Gagal mengubah nama rombel' }, 500)
  }
}

export async function DELETE(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const classId = searchParams.get('classId')

    if (!classId) {
      return noCacheJson({ error: 'classId diperlukan' }, 400)
    }

    // Verify class exists
    const existing = await db.class.findUnique({ where: { id: classId } })
    if (!existing) {
      return noCacheJson({ error: 'Rombel tidak ditemukan' }, 404)
    }

    // Cascade delete will handle students, attendance, activities, waliKelas
    await db.class.delete({ where: { id: classId } })
    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson({ success: true })
  } catch (error) {
    console.error('Error deleting class:', error)
    return noCacheJson({ error: 'Gagal menghapus rombel' }, 500)
  }
}
"},{"path":"src/app/api/code-backup/route.ts","content":"import { NextRequest } from 'next/server';
import { noCacheJson } from '@/lib/utils';
import { getConfig, getConfigPublic, githubGetFile } from '@/lib/online-backup';
import {
  backupCodeToGitHub,
  restoreCodeFromGitHub,
  getCodeBackupStatus,
  CODE_META_FILE,
  type CodeBackupStatus,
  type CodeBackupMeta,
} from '@/lib/code-backup';

export const dynamic = 'force-dynamic';
export const maxDuration = 10;

/**
 * GET /api/code-backup
 *   Status: konfigurasi GitHub + info backup kode terakhir di repo + status operasi.
 *
 * POST /api/code-backup
 *   { action: 'backup'  } → backup seluruh KODE aplikasi ke GitHub (chunk khusus code-backup/)
 *   { action: 'restore' } → pulihkan KODE aplikasi dari chunk khusus code-backup/ di GitHub
 *   { action: 'status'  } → status operasi yang berjalan
 *
 * CHUNK KHUSUS KODE (tidak pernah tercampur dengan backup absensi):
 *   - code-backup/code-meta.json
 *   - code-backup/code-chunk-{N}.json
 * sedangkan absensi siswa memakai backup/meta.json + backup/chunk-{N}.json.
 */

export async function GET() {
  try {
    const config = await getConfigPublic();
    let lastBackup: Partial<CodeBackupMeta> | null = null;
    try {
      const gh = await getConfig();
      if (gh) {
        const metaRaw = await githubGetFile(gh, CODE_META_FILE);
        if (metaRaw) {
          const parsed = JSON.parse(metaRaw.content) as CodeBackupMeta;
          lastBackup = {
            backedUpAt: parsed.backedUpAt,
            totalChunks: parsed.totalChunks,
            totalBytes: parsed.totalBytes,
            fileCount: parsed.fileCount,
            appVersion: parsed.appVersion,
          };
        }
      }
    } catch {
      // GitHub unreachable — status still returned, lastBackup stays null
    }
    return noCacheJson({ ...config, lastBackup, status: getCodeBackupStatus() });
  } catch (error) {
    console.error('Error reading code backup config:', error);
    return noCacheJson({ error: 'Gagal memeriksa konfigurasi backup kode' }, 500);
  }
}

export async function POST(request: NextRequest) {
  try {
    let body: { action?: string } | null = null;
    try { body = await request.json(); } catch {}

    if (body?.action === 'status') {
      const s: CodeBackupStatus = getCodeBackupStatus();
      return noCacheJson({ ...s });
    }

    if (body?.action === 'backup' || body?.action === 'restore') {
      const current = getCodeBackupStatus();
      if (current.running) {
        return noCacheJson({
          success: false,
          message: 'Operasi backup kode lain sedang berjalan. Tunggu selesai terlebih dahulu.',
          status: current,
        });
      }
      // Run in background — progress pollable via GET / status.
      const action = body.action;
      const op = action === 'backup' ? backupCodeToGitHub() : restoreCodeFromGitHub();
      op.then((result) => {
        console.log('[CodeBackup API] ' + action + ' completed:', result.success ? 'SUCCESS' : 'FAILED', result.message);
      }).catch((error) => {
        console.error('[CodeBackup API] ' + action + ' error:', error);
      });
      return noCacheJson({
        success: true,
        message: action === 'backup'
          ? 'Backup kode dimulai di background.'
          : 'Restore kode dimulai di background.',
        background: true,
        status: getCodeBackupStatus(),
      });
    }

    return noCacheJson({ error: 'Parameter action tidak valid (backup | restore | status)' }, 400);
  } catch (error) {
    console.error('Error in code backup operation:', error);
    return noCacheJson({ error: 'Gagal operasi backup kode' }, 500);
  }
}
"},{"path":"src/app/api/daily-hours/route.ts","content":"import { NextRequest } from 'next/server'
import { noCacheJson } from '@/lib/utils'
import { db } from '@/lib/db'
import { scheduleAutoSync, scheduleGSheetSync, markGSheetDirty } from '@/lib/auto-sync'

// GET: get max hours for a specific date (query param: date=YYYY-MM-DD)
export async function GET(request: NextRequest) {
  try {
    const date = request.nextUrl.searchParams.get('date')

    if (!date) {
      return noCacheJson({ error: 'Parameter date diperlukan' }, 400)
    }

    const setting = await db.settings.findUnique({
      where: { key: `max_hours_${date}` },
    })

    const maxHours = setting ? parseInt(setting.value, 10) : 8
    return noCacheJson({ date, maxHours })
  } catch (error) {
    console.error('Error fetching daily hours:', error)
    return noCacheJson({ error: 'Gagal mengambil pengaturan jam' }, 500)
  }
}

// PUT: set max hours for a specific date
export async function PUT(request: NextRequest) {
  try {
    const { date, maxHours } = await request.json()

    if (!date || maxHours === undefined || maxHours === null) {
      return noCacheJson({ error: 'date dan maxHours diperlukan' }, 400)
    }

    const val = Math.max(0, Math.min(8, Math.round(maxHours)))

    await db.settings.upsert({
      where: { key: `max_hours_${date}` },
      update: { value: String(val) },
      create: { key: `max_hours_${date}`, value: String(val) },
    })

    // Sync ONLY this max hour change to G-Sheet (not the whole DB)
    // Called immediately after user taps max hour button
    import('@/lib/google-sheets-v4').then(({ pushSingleMaxHourToGSheets }) => {
      pushSingleMaxHourToGSheets(date, val).catch((e) => {
        console.warn('[DailyHours] G-Sheet sync failed:', e instanceof Error ? e.message : String(e))
      })
    }).catch(() => {})

    // Also trigger general auto-sync (GitHub + G-Sheet non-attendance)
    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()

    return noCacheJson({ success: true, date, maxHours: val })
  } catch (error) {
    console.error('Error saving daily hours:', error)
    return noCacheJson({ error: 'Gagal menyimpan pengaturan jam' }, 500)
  }
}
"},{"path":"src/app/api/dashboard/route.ts","content":"import { NextRequest } from 'next/server'
import { noCacheJson } from '@/lib/utils'
import { db } from '@/lib/db'

function getDayOfWeek(dateStr: string): number {
  const [y, m, d] = dateStr.split('-').map(Number)
  return new Date(Date.UTC(y, m - 1, d)).getUTCDay()
}

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const date = searchParams.get('date')

    if (!date) {
      return noCacheJson({ error: 'Parameter date diperlukan' }, 400)
    }

    // Get notification mode (kelas or guru)
    const notifSetting = await db.settings.findUnique({ where: { key: 'notification_mode' } })
    const notifMode = notifSetting?.value || 'kelas'

    // Get per-date max hours config (default 8)
    const hourSetting = await db.settings.findUnique({
      where: { key: `max_hours_${date}` },
    })
    const maxHours = hourSetting ? parseInt(hourSetting.value, 10) : 8
    const dayOfWeek = getDayOfWeek(date)

    // Check if this date is a holiday (per-date or weekly)
    const dateHoliday = await db.dateHoliday.findUnique({ where: { date } })
    const weeklyHoliday = await db.academicHoliday.findUnique({ where: { dayOfWeek } })
    const isHoliday = !!(dateHoliday || (weeklyHoliday?.isActive))

    const classes = await db.class.findMany({
      include: {
        _count: { select: { students: true } },
        waliKelas: { select: { name: true } },
        students: { select: { id: true, name: true }, orderBy: { name: 'asc' } },
        activities: { where: { date } },
      },
      orderBy: { name: 'asc' },
    })

    const dashboardData = []
    const notifications = []

    // If guru mode, fetch all schedules for the current day
    // Filter out schedules where hour > maxHours (no need to fill attendance beyond max)
    let daySchedules: { classId: string; hour: number; teacher: string }[] = []
    if (notifMode === 'guru') {
      const schedules = await db.weeklySchedule.findMany({
        where: { dayOfWeek },
      })
      daySchedules = schedules
        .filter(s => s.hour <= maxHours)
        .map(s => ({ classId: s.classId, hour: s.hour, teacher: s.teacher }))
    }

    for (const cls of classes) {
      const totalStudents = cls._count.students
      const activityStatus = cls.activities[0]?.status ?? 'Masuk'

      const allRecords = await db.attendance.findMany({ where: { classId: cls.id, date } })

      const studentStatusMap: Record<string, { hadirHours: number; statuses: string[] }> = {}
      for (const record of allRecords) {
        if (!studentStatusMap[record.studentId]) {
          studentStatusMap[record.studentId] = { hadirHours: 0, statuses: [] }
        }
        studentStatusMap[record.studentId].statuses.push(record.status)
        if (record.status === 'Hadir') studentStatusMap[record.studentId].hadirHours++
      }

      let hadirCount = 0, terlambatCount = 0, alfaCount = 0, sakitCount = 0, izinCount = 0

      for (const student of cls.students) {
        const entry = studentStatusMap[student.id]
        if (!entry) { alfaCount++; continue }
        if (entry.hadirHours >= 4) hadirCount++
        else if (entry.statuses.includes('Alfa')) alfaCount++
        else if (entry.statuses.includes('Sakit')) sakitCount++
        else if (entry.statuses.includes('Izin')) izinCount++
        else if (entry.statuses.includes('Terlambat')) terlambatCount++
        else if (entry.hadirHours > 0) terlambatCount++
        else alfaCount++
      }

      const filledHours = new Set(allRecords.map((r) => r.hour))
      // For kelas mode: only check hours 1..maxHours (hours above max don't need attendance)
      const missingHours: number[] = []
      for (let h = 1; h <= maxHours; h++) {
        if (!filledHours.has(h)) missingHours.push(h)
      }

      dashboardData.push({
        classId: cls.id, className: cls.name,
        waliKelasName: cls.waliKelas?.name ?? '',
        totalStudents, activityStatus,
        hadir: hadirCount, terlambat: terlambatCount,
        alfa: alfaCount, sakit: sakitCount, izin: izinCount,
      })

      if (totalStudents > 0 && activityStatus === 'Masuk' && !isHoliday && missingHours.length > 0) {
        if (notifMode === 'kelas') {
          notifications.push({ classId: cls.id, className: cls.name, missingHours, totalStudents })
        }
      }
    }

    // Guru-based notifications
    if (notifMode === 'guru') {
      const teacherMap = new Map<string, { teacher: string; classId: string; className: string; hour: number; missing: boolean }[]>()

      for (const cls of classes) {
        if (cls._count.students === 0) continue
        const activityStatus = cls.activities[0]?.status ?? 'Masuk'
        if (activityStatus !== 'Masuk' || isHoliday) continue

        const classRecords = await db.attendance.findMany({ where: { classId: cls.id, date } })
        const filledHours = new Set(classRecords.map(r => r.hour))

        // Find schedules for this class on this day (already filtered by maxHours above)
        const classSchedules = daySchedules.filter(s => s.classId === cls.id)

        // Get missing hours — only hours that have a scheduled teacher
        // (if no schedule exists for a hour, don't notify — nobody needs to fill it)
        const missingHours: number[] = []
        for (let h = 1; h <= maxHours; h++) {
          if (!filledHours.has(h)) missingHours.push(h)
        }
        if (missingHours.length === 0) continue

        if (classSchedules.length === 0) {
          // No schedules for this class on this day — fall back to wali kelas
          // Only notify for hours that have a schedule (which is none here, so skip)
          continue
        } else {
          // Use schedules — only notify for hours that have a scheduled teacher
          const waliName = cls.waliKelas?.name?.trim() || ''
          for (const sched of classSchedules) {
            // Only notify if this hour is missing AND within maxHours (already filtered)
            if (!filledHours.has(sched.hour)) {
              const teacher = sched.teacher.trim() || waliName
              if (!teacher) continue
              if (!teacherMap.has(teacher)) teacherMap.set(teacher, [])
              teacherMap.get(teacher)!.push({ teacher, classId: cls.id, className: cls.name, hour: sched.hour, missing: true })
            }
          }
        }
      }

      // Build guru notifications
      for (const [teacher, entries] of teacherMap) {
        const uniqueClasses = new Map<string, { className: string; hours: number[] }>()
        for (const e of entries) {
          if (!uniqueClasses.has(e.classId)) {
            uniqueClasses.set(e.classId, { className: e.className, hours: [] })
          }
          uniqueClasses.get(e.classId)!.hours.push(e.hour)
        }
        const classMissing: { className: string; hours: number[] }[] = []
        for (const [, v] of uniqueClasses) {
          classMissing.push(v)
        }
        notifications.push({
          type: 'guru',
          teacherName: teacher,
          classMissing,
        })
      }
    }

    // NOTE: G-Sheet attendance count REMOVED — attendance not synced to G-Sheet.
    // Attendance stays on GitHub only.

    return noCacheJson({ date, maxHours, dayOfWeek, classes: dashboardData, notifications, notifMode, isHoliday })
  } catch (error) {
    console.error('Error fetching dashboard data:', error)
    return noCacheJson({ error: 'Gagal mengambil data dashboard' }, 500)
  }
}
"},{"path":"src/app/api/date-holidays/route.ts","content":"import { NextRequest } from 'next/server'
import { noCacheJson } from '@/lib/utils'
import { db } from '@/lib/db'
import { scheduleAutoSync, scheduleGSheetSync, markGSheetDirty } from '@/lib/auto-sync'

// GET: return all date holidays, or check a specific date
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const date = searchParams.get('date')

    if (date) {
      // Check if a specific date is a holiday
      const holiday = await db.dateHoliday.findUnique({ where: { date } })
      return noCacheJson(holiday)
    }

    // Return all date holidays
    const holidays = await db.dateHoliday.findMany({
      orderBy: { date: 'asc' },
    })
    return noCacheJson(holidays)
  } catch (error) {
    console.error('Error fetching date holidays:', error)
    return noCacheJson({ error: 'Gagal mengambil data' }, 500)
  }
}

// POST: create a date holiday
export async function POST(request: NextRequest) {
  try {
    const body = await request.json()
    const { date, name } = body

    if (!date || !name) {
      return noCacheJson({ error: 'date dan name diperlukan' }, 400)
    }

    const holiday = await db.dateHoliday.upsert({
      where: { date },
      update: { name },
      create: { date, name },
    })

    // Also set all classes to Libur for this date
    const classes = await db.class.findMany({ select: { id: true } })
    for (const cls of classes) {
      await db.academicActivity.upsert({
        where: { classId_date: { classId: cls.id, date } },
        update: { status: 'Libur' },
        create: { classId: cls.id, date, status: 'Libur' },
      })
    }

    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson(holiday)
  } catch (error) {
    console.error('Error creating date holiday:', error)
    return noCacheJson({ error: 'Gagal menyimpan' }, 500)
  }
}

// DELETE: remove a date holiday
export async function DELETE(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const date = searchParams.get('date')

    if (!date) {
      return noCacheJson({ error: 'date diperlukan' }, 400)
    }

    await db.dateHoliday.delete({ where: { date } })

    // Revert all classes to Masuk for this date (unless a weekly holiday applies)
    const dow = new Date(Date.UTC(...date.split('-').map(Number) as [number, number, number])).getUTCDay()
    const weeklyHoliday = await db.academicHoliday.findUnique({ where: { dayOfWeek: dow } })
    const newStatus = weeklyHoliday?.isActive ? 'Libur' : 'Masuk'

    const classes = await db.class.findMany({ select: { id: true } })
    for (const cls of classes) {
      await db.academicActivity.upsert({
        where: { classId_date: { classId: cls.id, date } },
        update: { status: newStatus },
        create: { classId: cls.id, date, status: newStatus },
      })
    }

    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson({ success: true, newStatus })
  } catch (error) {
    console.error('Error deleting date holiday:', error)
    return noCacheJson({ error: 'Gagal menghapus' }, 500)
  }
}
"},{"path":"src/app/api/disk/status/route.ts","content":"/**
 * Disk status API — returns disk usage information for the admin UI indicator.
 *
 * Returns:
 *   - usagePercent: 0-100 (how full the disk is)
 *   - freeMB: free disk space in MB
 *   - usedMB: used disk space in MB
 *   - totalMB: total disk size in MB
 *   - dbSizeMB: size of the live SQLite DB file in MB
 *
 * Called from AppShell header indicator (PC) and sidebar (mobile).
 * Polled every 60 seconds for real-time monitoring.
 */

import { NextRequest } from 'next/server';
import { noCacheJson } from '@/lib/utils';

export async function GET(_request: NextRequest) {
  try {
    const fs = await import('fs');
    const diskPath = fs.existsSync('/app') ? '/app' : '/home/z/my-project';

    // Get disk usage via statfs
    let usagePercent = -1;
    let freeMB = 0;
    let usedMB = 0;
    let totalMB = 0;

    try {
      const stats = await (fs.promises as any).statfs(diskPath);
      const totalBytes = stats.blocks * stats.bsize;
      const freeBytes = stats.bavail * stats.bsize;
      const usedBytes = totalBytes - freeBytes;
      totalMB = Math.round(totalBytes / (1024 * 1024));
      freeMB = Math.round(freeBytes / (1024 * 1024));
      usedMB = Math.round(usedBytes / (1024 * 1024));
      usagePercent = totalBytes > 0 ? Math.round((usedBytes / totalBytes) * 100) : 0;
    } catch {
      // statfs not available (e.g., macOS dev) — return -1
      usagePercent = -1;
    }

    // Get DB file size
    let dbSizeMB = 0;
    try {
      const dbPath = process.env.DATABASE_URL?.replace(/^file:/, '') || '/home/z/my-project/upload/db/custom.db';
      if (fs.existsSync(dbPath)) {
        const stat = await fs.promises.stat(dbPath);
        dbSizeMB = Math.round(stat.size / (1024 * 1024));
      }
    } catch {}

    // Determine status level for UI coloring
    let status: 'ok' | 'warning' | 'critical' = 'ok';
    if (usagePercent >= 85) status = 'critical';
    else if (usagePercent >= 70) status = 'warning';

    return noCacheJson({
      usagePercent,
      freeMB,
      usedMB,
      totalMB,
      dbSizeMB,
      status,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    console.error('Error fetching disk status:', error);
    return noCacheJson(
      { error: 'Gagal mengambil status disk', usagePercent: -1 },
      500
    );
  }
}
