"},{"path":"src/app/api/google-sheets/config/route.ts","content":"import { NextRequest } from 'next/server';
import { noCacheJson } from '@/lib/utils';
import {
  getScriptUrl,
  setScriptUrl,
  getSpreadsheetId,
  getSpreadsheetUrl,
} from '@/lib/google-sheets';

// Inline validation for Apps Script URL
const APPS_SCRIPT_URL_PATTERN = /^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/;

function validateAppsScriptUrl(url: string): { valid: boolean; error?: string } {
  if (!url || url.trim().length === 0) {
    return { valid: false, error: 'URL tidak boleh kosong' };
  }
  if (!url.startsWith('https://script.google.com/macros/s/')) {
    return { valid: false, error: 'URL harus dimulai dengan https://script.google.com/macros/s/' };
  }
  if (!url.endsWith('/exec')) {
    return { valid: false, error: 'URL harus diakhungi dengan /exec' };
  }
  if (!APPS_SCRIPT_URL_PATTERN.test(url)) {
    return { valid: false, error: 'Format URL tidak valid. Contoh: https://script.google.com/macros/s/XXXXX/exec' };
  }
  return { valid: true };
}

async function testAppsScriptConnection(url: string): Promise<{
  success: boolean;
  message: string;
}> {
  try {
    const validation = validateAppsScriptUrl(url);
    if (!validation.valid) {
      return { success: false, message: validation.error || 'URL tidak valid' };
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 15000);

    const response = await fetch(url, {
      method: 'GET',
      signal: controller.signal,
      redirect: 'follow',
    });
    clearTimeout(timeout);

    if (!response.ok) {
      if (response.status === 404) {
        return {
          success: false,
          message: 'URL Apps Script tidak ditemukan (404). Pastikan deployment web app sudah dibuat dan belum dihapus.',
        };
      }
      return {
        success: false,
        message: `Gagal menghubungi Apps Script (HTTP ${response.status}). Pastikan web app sudah di-deploy dengan akses "Anyone".`,
      };
    }

    const result = await response.json().catch(() => null);
    if (result && result.status === 'ready') {
      return { success: true, message: 'Koneksi berhasil! Apps Script siap menerima data.' };
    }
    return { success: true, message: 'Koneksi berhasil. Apps Script merespon.' };
  } catch (error) {
    if (error instanceof DOMException && error.name === 'AbortError') {
      return { success: false, message: 'Timeout: Apps Script tidak merespon dalam 15 detik.' };
    }
    const message = error instanceof Error ? error.message : 'Unknown error';
    return { success: false, message: `Gagal menghubungi Apps Script: ${message}` };
  }
}

export async function GET(request: NextRequest) {
  try {
    const scriptUrl = await getScriptUrl();
    const { searchParams } = new URL(request.url);
    const testParam = searchParams.get('test');

    // If ?test=true, test the current saved URL
    if (testParam === 'true' && scriptUrl) {
      const testResult = await testAppsScriptConnection(scriptUrl);
      return noCacheJson({
        scriptUrl,
        spreadsheetUrl: getSpreadsheetUrl(),
        spreadsheetId: getSpreadsheetId(),
        testConnection: testResult,
      });
    }

    // If ?test=URL, test a specific URL without saving
    if (testParam && testParam !== 'true' && testParam.startsWith('https://')) {
      const testResult = await testAppsScriptConnection(testParam);
      return noCacheJson({
        testConnection: testResult,
      });
    }

    return noCacheJson({
      scriptUrl,
      spreadsheetUrl: getSpreadsheetUrl(),
      spreadsheetId: getSpreadsheetId(),
    });
  } catch (error) {
    console.error('Error getting Google Sheets config:', error);
    return noCacheJson(
      { error: 'Gagal mengambil konfigurasi' },
      500
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { scriptUrl } = body;

    if (!scriptUrl || typeof scriptUrl !== 'string') {
      return noCacheJson(
        { error: 'URL Apps Script wajib diisi' },
        400
      );
    }

    // Validate URL format
    const validation = validateAppsScriptUrl(scriptUrl.trim());
    if (!validation.valid) {
      return noCacheJson(
        { error: validation.error },
        400
      );
    }

    await setScriptUrl(scriptUrl.trim());
    return noCacheJson({ success: true });
  } catch (error) {
    console.error('Error saving Google Sheets config:', error);
    return noCacheJson(
      { error: 'Gagal menyimpan konfigurasi' },
      500
    );
  }
}
"},{"path":"src/app/api/google-sheets/export/route.ts","content":"import { NextRequest, NextResponse } from 'next/server';
import { noCacheJson } from '@/lib/utils';
import { generateClassCSV, generateAllCSV } from '@/lib/google-sheets';

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const className = searchParams.get('class');

    if (className) {
      // Export single class
      const csv = await generateClassCSV(className);
      const filename = `absensi_${className.replace(/\s+/g, '_')}.csv`;
      return new NextResponse(csv, {
        headers: {
          'Content-Type': 'text/csv; charset=utf-8',
          'Content-Disposition': `attachment; filename="${filename}"`,
        },
      });
    } else {
      // Export all classes combined
      const allCsv = await generateAllCSV();
      const classNames = Object.keys(allCsv).sort();
      const combinedLines: string[] = [];

      for (const name of classNames) {
        if (combinedLines.length > 0) {
          combinedLines.push('');
        }
        combinedLines.push(`=== KELAS: ${name} ===`);
        combinedLines.push(allCsv[name]);
      }

      const combined = combinedLines.join('\n');
      return new NextResponse(combined, {
        headers: {
          'Content-Type': 'text/csv; charset=utf-8',
          'Content-Disposition': 'attachment; filename="absensi_semua_kelas.csv"',
        },
      });
    }
  } catch (error) {
    console.error('Error exporting CSV:', error);
    const message = error instanceof Error ? error.message : 'Gagal mengekspor data';
    return noCacheJson({ error: message }, 500);
  }
}
"},{"path":"src/app/api/google-sheets/route.ts","content":"import { NextRequest } from 'next/server';
import { noCacheJson } from '@/lib/utils';
import {
  getScriptUrl,
  getSpreadsheetUrl,
  syncToGoogleSheets,
  restoreFromGoogleSheets,
  setSyncProgressCallback,
  pauseSync,
  cancelSync,
} from '@/lib/google-sheets';

export const dynamic = 'force-dynamic';
export const maxDuration = 10; // Short — sync runs in background

// Track sync status so frontend can poll for progress
interface SyncProgress {
  current: number;   // current chunk index
  total: number;     // total chunks
  percentage: number; // 0-100
  label: string;     // e.g. "Meta chunk" or "Attendance chunk 3/15"
}
interface SyncStatus {
  running: boolean;
  lastResult: { success: boolean; message: string } | null;
  startedAt: string | null;
  progress: SyncProgress | null;
}

let syncStatus: SyncStatus = {
  running: false,
  lastResult: null,
  startedAt: null,
  progress: null,
};

/** Allow google-sheets.ts to update progress during sync */
export function updateSyncProgress(current: number, total: number, label: string) {
  const percentage = total > 0 ? Math.round((current / total) * 100) : 0;
  syncStatus = {
    ...syncStatus,
    progress: { current, total, percentage, label },
  };
}

export async function GET() {
  try {
    const scriptUrl = await getScriptUrl();
    const looksValid = scriptUrl?.startsWith('https://script.google.com/macros/s/');
    return noCacheJson({
      configured: !!scriptUrl && looksValid,
      spreadsheetUrl: getSpreadsheetUrl(),
      scriptUrl,
      syncStatus,
    });
  } catch (error) {
    console.error('Error checking Google Sheets config:', error);
    return noCacheJson(
      { error: 'Gagal memeriksa konfigurasi Google Sheets' },
      500
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    let body: { action?: string } | null = null;
    try {
      body = await request.json();
    } catch {
      // No body or invalid JSON — treat as regular sync
    }

    // Pull/restore — run in BACKGROUND (like sync) to avoid 504 timeout
    if (body?.action === 'restore') {
      if (syncStatus.running) {
        return noCacheJson({
          success: false,
          message: 'Operasi sedang berjalan. Tunggu sebentar.',
          syncStatus,
        });
      }

      // Start pull in background
      syncStatus = { running: true, lastResult: null, startedAt: new Date().toISOString(), progress: null };
      console.log('[Pull API] Starting background pull from G-Sheet...');

      // Set progress callback
      setSyncProgressCallback((current, total, label) => {
        syncStatus = {
          ...syncStatus,
          progress: { current, total, percentage: total > 0 ? Math.round((current / total) * 100) : 0, label },
        };
      });

      // Don't await — let it run in the background
      restoreFromGoogleSheets()
        .then((result) => {
          setSyncProgressCallback(null);
          syncStatus = {
            running: false,
            lastResult: result,
            startedAt: syncStatus.startedAt,
            progress: { current: 0, total: 0, percentage: 100, label: 'Selesai' },
          };
          console.log('[Pull API] Background pull completed:', result.success ? 'SUCCESS' : 'FAILED', result.message);
        })
        .catch((error) => {
          setSyncProgressCallback(null);
          syncStatus = {
            running: false,
            lastResult: { success: false, message: 'Error: ' + (error instanceof Error ? error.message : 'Unknown') },
            startedAt: syncStatus.startedAt,
            progress: null,
          };
          console.error('[Pull API] Background pull error:', error);
        });

      // Return immediately — pull continues in background
      return noCacheJson({
        success: true,
        message: 'Pull dimulai di background. Cek status dengan GET /api/google-sheets.',
        background: true,
        syncStatus,
      });
    }

    // Check sync status
    if (body?.action === 'status') {
      return noCacheJson(syncStatus);
    }

    // Stop/cancel ongoing sync or pull
    if (body?.action === 'stop') {
      if (syncStatus.running) {
        console.log('[API] Stopping ongoing operation...');
        // Signal the running sync/pull loop to abort after the current chunk
        cancelSync();
        // Also clear the pause flag so sync can resume after stop
        pauseSync(false);
        setSyncProgressCallback(null);
        syncStatus = {
          running: false,
          lastResult: { success: false, message: 'Operasi dihentikan oleh user' },
          startedAt: syncStatus.startedAt,
          progress: { current: 0, total: 0, percentage: 0, label: 'Dihentikan' },
        };
        return noCacheJson({ success: true, message: 'Operasi dihentikan. Sync dapat dilanjutkan kembali.' });
      }
      // Even if not running, clear the pause flag in case it was stuck
      pauseSync(false);
      return noCacheJson({ success: false, message: 'Tidak ada operasi yang berjalan.' });
    }

    // Sync (push) — run in BACKGROUND, return immediately to avoid 502 timeout
    if (syncStatus.running) {
      return noCacheJson({
        success: false,
        message: 'Operasi sedang berjalan. Klik STOP untuk membatalkan.',
        syncStatus,
      });
    }

    // Start sync in background (fire-and-forget)
    syncStatus = { running: true, lastResult: null, startedAt: new Date().toISOString(), progress: null };
    console.log('[Sync API] Starting background sync...');

    // Set progress callback so syncToGoogleSheets can update syncStatus
    setSyncProgressCallback((current, total, label) => {
      syncStatus = {
        ...syncStatus,
        progress: {
          current,
          total,
          percentage: total > 0 ? Math.round((current / total) * 100) : 0,
          label,
        },
      };
    });

    // Don't await — let it run in the background
    syncToGoogleSheets()
      .then((result) => {
        setSyncProgressCallback(null);
        syncStatus = {
          running: false,
          lastResult: result,
          startedAt: syncStatus.startedAt,
          progress: { current: 0, total: 0, percentage: 100, label: 'Selesai' },
        };
        console.log('[Sync API] Background sync completed:', result.success ? 'SUCCESS' : 'FAILED', result.message);
      })
      .catch((error) => {
        setSyncProgressCallback(null);
        syncStatus = {
          running: false,
          lastResult: { success: false, message: 'Error: ' + (error instanceof Error ? error.message : 'Unknown') },
          startedAt: syncStatus.startedAt,
          progress: null,
        };
        console.error('[Sync API] Background sync error:', error);
      });

    // Return immediately — sync continues in background
    return noCacheJson({
      success: true,
      message: 'Sync dimulai di background. Cek status dengan GET /api/google-sheets.',
      background: true,
      syncStatus,
    });
  } catch (error) {
    console.error('Error in Google Sheets operation:', error);
    return noCacheJson(
      { success: false, message: 'Gagal operasi Google Sheets' },
      500
    );
  }
}
"},{"path":"src/app/api/gsheets/route.ts","content":"import { NextRequest } from 'next/server';
import { noCacheJson } from '@/lib/utils';
import {
  getGSheetsConfigPublic,
  setGSheetsConfig,
  testGSheetsConnection,
  pushToGSheets,
  pullFromGSheets,
  getGSheetsHealth,
  APPS_SCRIPT_CODE,
  replaceDateHolidaysAndMaxHours,
} from '@/lib/google-sheets-v4';
import { db } from '@/lib/db';

export const dynamic = 'force-dynamic';
export const maxDuration = 60;

export async function GET() {
  try {
    const config = await getGSheetsConfigPublic();
    const health = await getGSheetsHealth();
    return noCacheJson({ ...config, health, appsScriptCode: APPS_SCRIPT_CODE });
  } catch (error) {
    console.error('Error getting gsheets config:', error);
    return noCacheJson({ error: 'Gagal mendapatkan konfigurasi' }, 500);
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { action } = body;

    // Test connection
    if (action === 'test') {
      const result = await testGSheetsConnection();
      return noCacheJson(result);
    }

    // Push (sync to Google Sheets) — works in ALL environments (production + sandbox)
    if (action === 'sync' || action === 'push') {
      const result = await pushToGSheets();
      return noCacheJson(result);
    }

    // Pull (fetch from Google Sheets) — works in ALL environments
    if (action === 'pull') {
      const result = await pullFromGSheets();
      // After pull, if students were deleted, clean up GitHub chunks
      if (result.success && result.restored?.deletedStudents > 0) {
        try {
          const { cleanDeletedStudentsFromGitHub } = await import('@/lib/google-sheets-v4');
          const cleanup = await cleanDeletedStudentsFromGitHub();
          result.message += ` | GitHub cleanup: ${cleanup.success ? 'berhasil' : 'gagal'}`;
        } catch (e) {
          console.warn('[GSheets API] GitHub cleanup after pull failed:', e);
        }
      }
      return noCacheJson(result);
    }

    // Cleanup GitHub (delete orphaned attendance from deleted students)
    // ALLOWED in BOTH sandbox and production — user can manually trigger this
    // from the UI in any environment.
    if (action === 'cleanup') {
      const { cleanDeletedStudentsFromGitHub } = await import('@/lib/google-sheets-v4');
      const result = await cleanDeletedStudentsFromGitHub();
      return noCacheJson(result);
    }

    // REPLACE date holidays and max hours on G-Sheet with current DB data.
    // Unlike "push" (which merges), this CLEARS old entries and writes ONLY
    // new data. Requires the deployed Apps Script webhook to support the
    // "replaceDateHolidaysAndMaxHours" action.
    // Works in BOTH sandbox and production.
    if (action === 'replaceDateHolidaysAndMaxHours') {
      try {
        // Get all date holidays from DB
        const dateHolidays = await db.dateHoliday.findMany({ orderBy: { date: 'asc' } });
        // Get all max_hours settings from DB
        const maxHourSettings = await db.settings.findMany({
          where: { key: { startsWith: 'max_hours_' } },
          orderBy: { key: 'asc' },
        });
        const maxHours = maxHourSettings.map(s => ({
          date: s.key.replace('max_hours_', ''),
          maxHour: parseInt(s.value, 10),
        }));
        const result = await replaceDateHolidaysAndMaxHours(dateHolidays, maxHours);
        return noCacheJson(result);
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        return noCacheJson({ success: false, message: `Gagal replace: ${msg}` }, 500);
      }
    }

    // NOTE: Attendance sync/pull/count actions REMOVED.
    // Attendance stays on GitHub only — NOT synced to G-Sheet.
    // G-Sheet integration remains for: max hour, holidays, teachers,
    // wali kelas, schedules, students (via push/pull actions above).

    // Save config
    const { webhookUrl, spreadsheetUrl } = body;
    if (!webhookUrl) {
      return noCacheJson({ success: false, message: 'Webhook URL wajib diisi' }, 400);
    }
    await setGSheetsConfig({ webhookUrl, spreadsheetUrl });
    return noCacheJson({ success: true, message: 'Konfigurasi Google Sheets disimpan!' });
  } catch (error) {
    console.error('Error in gsheets POST:', error);
    return noCacheJson({ success: false, message: 'Gagal operasi Google Sheets' }, 500);
  }
}
