import { noCacheJson } from '@/lib/utils';
import { db } from '@/lib/db';
import { scheduleAutoSync, scheduleGSheetSync, markGSheetDirty } from '@/lib/auto-sync'

// GET: return all active holidays
export async function GET() {
  try {
    const holidays = await db.academicHoliday.findMany({
      where: { isActive: true },
      orderBy: { dayOfWeek: 'asc' },
    });
    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson(holidays);
  } catch (error) {
    console.error('Error fetching holidays:', error);
    return noCacheJson({ error: 'Gagal mengambil data libur' }, 500);
  }
}

// POST: create or update a holiday (upsert by dayOfWeek)
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { dayOfWeek, name, isActive } = body;

    if (dayOfWeek === undefined || dayOfWeek < 0 || dayOfWeek > 6) {
      return noCacheJson({ error: 'dayOfWeek harus 0-6' }, 400);
    }
    if (!name || typeof name !== 'string') {
      return noCacheJson({ error: 'name wajib diisi' }, 400);
    }

    const holiday = await db.academicHoliday.upsert({
      where: { dayOfWeek },
      update: { name, isActive: isActive !== undefined ? isActive : true },
      create: { dayOfWeek, name, isActive: isActive !== undefined ? isActive : true },
    });

    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson(holiday);
  } catch (error) {
    console.error('Error upserting holiday:', error);
    return noCacheJson({ error: 'Gagal menyimpan data libur' }, 500);
  }
}
