import { noCacheJson } from '@/lib/utils';
import { setConfig, getConfigPublic } from '@/lib/online-backup';

export const dynamic = 'force-dynamic';
export const maxDuration = 10;

export async function GET() {
  try {
    const config = await getConfigPublic();
    return noCacheJson(config);
  } catch (error) {
    console.error('Error getting online backup config:', error);
    return noCacheJson({ error: 'Gagal mendapatkan konfigurasi' }, 500);
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { token, owner, repo, branch } = body;

    if (!token || !owner || !repo) {
      return noCacheJson({ success: false, error: 'Token, owner, dan repo wajib diisi' }, 400);
    }

    // Test the token by trying to access the repo
    const testRes = await fetch(`https://api.github.com/repos/${owner}/${repo}`, {
      headers: {
        'Authorization': `Bearer ${token}`,
        'Accept': 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28',
      },
      signal: AbortSignal.timeout(15000),
    });

    if (!testRes.ok) {
      const testData = await testRes.json().catch(() => ({}));
      if (testRes.status === 404) {
        return noCacheJson({ success: false, error: `Repo tidak ditemukan atau token tidak punya akses: ${owner}/${repo}` }, 400);
      }
      return noCacheJson({ success: false, error: `Token tidak valid: ${testData.message || testRes.statusText}` }, 400);
    }

    await setConfig(token, owner, repo, branch || 'main');
    const config = await getConfigPublic();

    return noCacheJson({
      success: true,
      message: 'Konfigurasi tersimpan!',
      config,
    });
  } catch (error) {
    console.error('Error saving online backup config:', error);
    return noCacheJson({ success: false, error: 'Gagal menyimpan konfigurasi' }, 500);
  }
}
"},{"path":"src/app/api/online-backup/route.ts","content":"import { NextRequest } from 'next/server';
import { noCacheJson } from '@/lib/utils';
import {
  syncToOnlineBackup,
  restoreFromOnlineBackup,
  restoreMissingFromOnlineBackup,
  setOnlineSyncProgressCallback,
  pauseOnlineSync,
  cancelOnlineSync,
  getConfigPublic,
  getConfig,
  checkOnlineBackup,
  repairMetaFile,
  deduplicateAndRepairMeta,
  getSyncHealth,
  clearHealthCache,
} from '@/lib/online-backup';

export const dynamic = 'force-dynamic';
export const maxDuration = 10;

interface SyncProgress {
  current: number;
  total: number;
  percentage: number;
  label: string;
}
interface SyncStatus {
  running: boolean;
  lastResult: { success: boolean; message: string } | null;
  startedAt: string | null;
  progress: SyncProgress | null;
}

let syncStatus: SyncStatus = {
  running: false,
  lastResult: null,
  startedAt: null,
  progress: null,
};

export function updateSyncProgress(current: number, total: number, label: string) {
  syncStatus = {
    ...syncStatus,
    progress: { current, total, percentage: total > 0 ? Math.round((current / total) * 100) : 0, label },
  };
}

export async function GET() {
  try {
    const config = await getConfigPublic();
    // Return config + syncStatus WITHOUT calling GitHub API
    // GitHub API calls in this endpoint cause ERR_INVALID_RESPONSE
    // Connection status is only checked when user opens the "JSON Backup Online" panel
    return noCacheJson({ ...config, syncStatus });
  } catch (error) {
    console.error('Error checking online backup config:', error);
    return noCacheJson({ error: 'Gagal memeriksa konfigurasi' }, 500);
  }
}

export async function POST(request: NextRequest) {
  try {
    let body: { action?: string } | null = null;
    try { body = await request.json(); } catch {}

    // Manual sync/pull operations are ALLOWED in BOTH sandbox and production.
    // User can manually trigger sync/pull-diff/deduplicate from the UI in any
    // environment. Automatic sync (auto-sync/pull-diff on startup) is still
    // production-only — gated by isProductionEnv() in instrumentation/auto-sync.
    // This block previously blocked ALL sandbox sync/pull operations; it has
    // been removed so users can test sync/pull manually in sandbox.
    // Status/health/config/debug/stop actions are also still allowed in sandbox.

    // Restore (pull from GitHub) — full restore (DELETE ALL + CREATE ALL)
    if (body?.action === 'restore') {
      // GLOBAL LOCK: Check if another operation is running
      const { tryStartOperation, endOperation, updateProgress: updateOpProgress, recordResult } = await import('@/lib/operation-lock');
      if (!tryStartOperation('pull-full', 'Pull Full dari GitHub')) {
        return noCacheJson({ success: false, message: 'Operasi lain sedang berjalan. Tidak bisa memulai pull full sekarang. Hentikan operasi yang sedang berjalan terlebih dahulu.' });
      }
      if (syncStatus.running) {
        endOperation('pull-full');
        return noCacheJson({ success: false, message: 'Operasi sedang berjalan. Klik STOP untuk membatalkan.', syncStatus });
      }
      syncStatus = { running: true, lastResult: null, startedAt: new Date().toISOString(), progress: null };
      console.log('[OnlineBackup API] Starting background restore (full)...');

      setOnlineSyncProgressCallback((current, total, label) => {
        syncStatus = {
          ...syncStatus,
          progress: { current, total, percentage: total > 0 ? Math.round((current / total) * 100) : 0, label },
        };
        updateOpProgress(current, total, label);
      });

      restoreFromOnlineBackup()
        .then(async (result) => {
          setOnlineSyncProgressCallback(null);
          clearHealthCache();
          syncStatus = { running: false, lastResult: result, startedAt: syncStatus.startedAt, progress: { current: 0, total: 0, percentage: 100, label: 'Selesai' } };
          console.log('[OnlineBackup API] Restore completed:', result.success ? 'SUCCESS' : 'FAILED', result.message);
          recordResult('pull-full', result.success, result.message);
          // Save restore point after successful full restore
          // Only sync DB file (not load all attendance into memory — prevents OOM)
          if (result.success) {
            try {
              const { syncLiveDbToPersistent } = await import('@/lib/db-persistent-sync');
              const dbSync = await syncLiveDbToPersistent();
              if (dbSync.copied) {
                console.log('[OnlineBackup API] Persistent DB synced after full restore:', dbSync.path);
              }
            } catch (e) { console.warn('[OnlineBackup API] Could not sync persistent DB:', e); }
          }
          endOperation('pull-full');
        })
        .catch((error) => {
          setOnlineSyncProgressCallback(null);
          syncStatus = { running: false, lastResult: { success: false, message: 'Error: ' + (error instanceof Error ? error.message : 'Unknown') }, startedAt: syncStatus.startedAt, progress: null };
          console.error('[OnlineBackup API] Restore error:', error);
          recordResult('pull-full', false, error instanceof Error ? error.message : 'Unknown');
          endOperation('pull-full');
        });

      return noCacheJson({ success: true, message: 'Restore dimulai di background.', background: true, syncStatus });
    }

    // Restore diff (pull only missing records from GitHub — much faster)
    if (body?.action === 'restore-diff') {
      if (syncStatus.running) {
        return noCacheJson({ success: false, message: 'Operasi sedang berjalan. Klik STOP untuk membatalkan.', syncStatus });
      }
      syncStatus = { running: true, lastResult: null, startedAt: new Date().toISOString(), progress: null };
      console.log('[OnlineBackup API] Starting background restore-diff (only missing)...');

      const { updateProgress: updateOpProgress } = await import('@/lib/operation-lock');
      setOnlineSyncProgressCallback((current, total, label) => {
        syncStatus = {
          ...syncStatus,
          progress: { current, total, percentage: total > 0 ? Math.round((current / total) * 100) : 0, label },
        };
        updateOpProgress(current, total, label);
      });

      restoreMissingFromOnlineBackup()
        .then((result) => {
          setOnlineSyncProgressCallback(null);
          clearHealthCache();
          syncStatus = { running: false, lastResult: result, startedAt: syncStatus.startedAt, progress: { current: 0, total: 0, percentage: 100, label: 'Selesai' } };
          console.log('[OnlineBackup API] Restore-diff completed:', result.success ? 'SUCCESS' : 'FAILED', result.message);
        })
        .catch((error) => {
          setOnlineSyncProgressCallback(null);
          syncStatus = { running: false, lastResult: { success: false, message: 'Error: ' + (error instanceof Error ? error.message : 'Unknown') }, startedAt: syncStatus.startedAt, progress: null };
          console.error('[OnlineBackup API] Restore-diff error:', error);
        });

      return noCacheJson({ success: true, message: 'Restore diff dimulai di background.', background: true, syncStatus });
    }

    // Status check
    if (body?.action === 'status') {
      return noCacheJson(syncStatus);
    }

    // Health check — returns sync health for dashboard display
    if (body?.action === 'health') {
      const health = await getSyncHealth();
      return noCacheJson(health);
    }

    // Check backup info
    if (body?.action === 'check') {
      const result = await checkOnlineBackup();
      return noCacheJson(result);
    }

    // Repair meta.json (when chunks exist but meta.json is missing)
    if (body?.action === 'repair') {
      const result = await repairMetaFile();
      return noCacheJson(result);
    }

    // Deduplicate chunks: fetch all chunks, remove duplicate records, delete duplicate chunks, fix meta.json
    // ALLOWED in BOTH sandbox and production — user can manually trigger this
    // from the UI in any environment.
    if (body?.action === 'deduplicate') {
      if (syncStatus.running) {
        return noCacheJson({ success: false, message: 'Operasi sedang berjalan. Klik STOP untuk membatalkan.', syncStatus });
      }
      syncStatus = { running: true, lastResult: null, startedAt: new Date().toISOString(), progress: null };
      console.log('[OnlineBackup API] Starting background deduplication...');

      const { updateProgress: updateOpProgress, recordResult, tryStartOperation, endOperation } = await import('@/lib/operation-lock');
      if (!tryStartOperation('sync', 'Deduplication Chunk GitHub')) {
        syncStatus = { running: false, lastResult: null, startedAt: null, progress: null };
        return noCacheJson({ success: false, message: 'Operasi lain sedang berjalan. Tidak bisa memulai deduplication sekarang.' });
      }

      setOnlineSyncProgressCallback((current, total, label) => {
        syncStatus = {
          ...syncStatus,
          progress: { current, total, percentage: total > 0 ? Math.round((current / total) * 100) : 0, label },
        };
        updateOpProgress(current, total, label);
      });

      deduplicateAndRepairMeta()
        .then((result) => {
          setOnlineSyncProgressCallback(null);
          clearHealthCache();
          syncStatus = { running: false, lastResult: result, startedAt: syncStatus.startedAt, progress: { current: 0, total: 0, percentage: 100, label: 'Selesai' } };
          console.log('[OnlineBackup API] Deduplication completed:', result.success ? 'SUCCESS' : 'FAILED', result.message);
          recordResult('sync', result.success, result.message);
          endOperation('sync');
        })
        .catch((error) => {
          setOnlineSyncProgressCallback(null);
          syncStatus = { running: false, lastResult: { success: false, message: 'Error: ' + (error instanceof Error ? error.message : 'Unknown') }, startedAt: syncStatus.startedAt, progress: null };
          console.error('[OnlineBackup API] Deduplication error:', error);
          recordResult('sync', false, error instanceof Error ? error.message : 'Unknown');
          endOperation('sync');
        });

      return noCacheJson({ success: true, message: 'Deduplication dimulai di background.', background: true, syncStatus });
    }

    // Debug: list all files in the repo and test meta.json fetch
    if (body?.action === 'debug') {
      const config = await getConfig();
      if (!config) {
        return noCacheJson({ success: false, message: 'Not configured' });
      }
      const GITHUB_API = 'https://api.github.com';
      const debug: any = { config: { owner: config.owner, repo: config.repo, branch: config.branch } };

      // 1. List repo contents (root)
      try {
        const rootRes = await fetch(`${GITHUB_API}/repos/${config.owner}/${config.repo}/contents?ref=${encodeURIComponent(config.branch)}`, {
          headers: { 'Authorization': `Bearer ${config.token}`, 'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' },
          signal: AbortSignal.timeout(15000),
        });
        debug.rootStatus = rootRes.status;
        if (rootRes.ok) {
          const rootData = await rootRes.json();
          debug.rootFiles = Array.isArray(rootData) ? rootData.map((f: any) => ({ name: f.name, type: f.type, path: f.path })) : [];
        } else {
          debug.rootError = await rootRes.json().catch(() => ({}));
        }
      } catch (e) {
        debug.rootError = e instanceof Error ? e.message : String(e);
      }

      // 2. List backup/ folder
      try {
        const backupRes = await fetch(`${GITHUB_API}/repos/${config.owner}/${config.repo}/contents/backup?ref=${encodeURIComponent(config.branch)}`, {
          headers: { 'Authorization': `Bearer ${config.token}`, 'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' },
          signal: AbortSignal.timeout(15000),
        });
        debug.backupStatus = backupRes.status;
        if (backupRes.ok) {
          const backupData = await backupRes.json();
          debug.backupFiles = Array.isArray(backupData) ? backupData.map((f: any) => ({ name: f.name, path: f.path, size: f.size })) : [];
        } else {
          debug.backupError = await backupRes.json().catch(() => ({}));
        }
      } catch (e) {
        debug.backupError = e instanceof Error ? e.message : String(e);
      }

      // 3. Try to fetch meta.json directly
      try {
        const metaRes = await fetch(`${GITHUB_API}/repos/${config.owner}/${config.repo}/contents/backup/meta.json?ref=${encodeURIComponent(config.branch)}`, {
          headers: { 'Authorization': `Bearer ${config.token}`, 'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' },
          signal: AbortSignal.timeout(15000),
        });
        debug.metaStatus = metaRes.status;
        if (metaRes.ok) {
          const metaData = await metaRes.json();
          debug.metaExists = true;
          debug.metaSize = metaData.size;
          debug.metaSha = metaData.sha?.substring(0, 8);
        } else {
          debug.metaExists = false;
          debug.metaError = await metaRes.json().catch(() => ({}));
        }
      } catch (e) {
        debug.metaError = e instanceof Error ? e.message : String(e);
      }

      return noCacheJson({ success: true, debug });
    }

    // Stop
    if (body?.action === 'stop') {
      if (syncStatus.running) {
        console.log('[OnlineBackup API] Stopping...');
        cancelOnlineSync();
        pauseOnlineSync(false);
        setOnlineSyncProgressCallback(null);
        syncStatus = { running: false, lastResult: { success: false, message: 'Operasi dihentikan oleh user' }, startedAt: syncStatus.startedAt, progress: { current: 0, total: 0, percentage: 0, label: 'Dihentikan' } };
        return noCacheJson({ success: true, message: 'Operasi dihentikan.' });
      }
      pauseOnlineSync(false);
      return noCacheJson({ success: false, message: 'Tidak ada operasi yang berjalan.' });
    }

    // Sync (push to GitHub)
    // GLOBAL LOCK: Check if another operation is running
    {
      const { tryStartOperation, endOperation, updateProgress: updateOpProgress, recordResult } = await import('@/lib/operation-lock');
      if (!tryStartOperation('sync', 'Sync ke GitHub')) {
        return noCacheJson({ success: false, message: 'Operasi lain sedang berjalan. Tidak bisa memulai sync sekarang. Hentikan operasi yang sedang berjalan terlebih dahulu.' });
      }
      if (syncStatus.running) {
        endOperation('sync');
        return noCacheJson({ success: false, message: 'Operasi sedang berjalan. Klik STOP untuk membatalkan.', syncStatus });
      }
      syncStatus = { running: true, lastResult: null, startedAt: new Date().toISOString(), progress: null };
      console.log('[OnlineBackup API] Starting background sync...');

      setOnlineSyncProgressCallback((current, total, label) => {
        syncStatus = {
          ...syncStatus,
          progress: { current, total, percentage: total > 0 ? Math.round((current / total) * 100) : 0, label },
        };
        updateOpProgress(current, total, label);
      });

      syncToOnlineBackup()
        .then((result) => {
          setOnlineSyncProgressCallback(null);
          syncStatus = { running: false, lastResult: result, startedAt: syncStatus.startedAt, progress: { current: 0, total: 0, percentage: 100, label: 'Selesai' } };
          console.log('[OnlineBackup API] Sync completed:', result.success ? 'SUCCESS' : 'FAILED', result.message);
          recordResult('sync', result.success, result.message);
          endOperation('sync');
        })
        .catch((error) => {
          setOnlineSyncProgressCallback(null);
          syncStatus = { running: false, lastResult: { success: false, message: 'Error: ' + (error instanceof Error ? error.message : 'Unknown') }, startedAt: syncStatus.startedAt, progress: null };
          console.error('[OnlineBackup API] Sync error:', error);
          recordResult('sync', false, error instanceof Error ? error.message : 'Unknown');
          endOperation('sync');
        });
    }

    return noCacheJson({ success: true, message: 'Sync dimulai di background.', background: true, syncStatus });
  } catch (error) {
    console.error('Error in online backup operation:', error);
    return noCacheJson({ success: false, message: 'Gagal operasi online backup' }, 500);
  }
}
"},{"path":"src/app/api/recap/excel/route.ts","content":"import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';

export const dynamic = 'force-dynamic';
export const maxDuration = 60;

function parseDate(dateStr: string): Date {
  const [y, m, d] = dateStr.split('-').map(Number);
  return new Date(y, m - 1, d);
}

function formatDateStr(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

const DAY_NAMES = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const MONTHS = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];

/**
 * GET /api/recap/excel?type=harian|mingguan|bulanan&classId=...&...
 * Exports a recap as an .xlsx file with neat column widths.
 *
 * - harian: per-student per-hour attendance for the selected date (matches
 *   the RekapHarianContent table: NO, NAMA, NISN, JK, JAM 1-8 with status per
 *   hour, HADIR, %).
 * - mingguan/bulanan: per-student totals (Masuk, Sakit, Izin, Alfa, Terlambat,
 *   Total, %) with a totals row.
 */
export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const type = searchParams.get('type') || 'harian';
  const classId = searchParams.get('classId');
  const startDate = searchParams.get('startDate');
  const endDate = searchParams.get('endDate');
  const month = searchParams.get('month');
  const year = searchParams.get('year');

  if (!classId) {
    return NextResponse.json({ error: 'classId wajib' }, { status: 400 });
  }

  try {
    const classData = await db.class.findUnique({ where: { id: classId } });
    if (!classData) {
      return NextResponse.json({ error: 'Kelas tidak ditemukan' }, { status: 404 });
    }

    const holidays = await db.academicHoliday.findMany({ where: { isActive: true } });
    const holidayDays = new Set(holidays.map(h => h.dayOfWeek));
    // PER-DATE HOLIDAYS: libur per tanggal juga dikecualikan agar tidak menghasilkan Alfa.
    const dateHolidays = await db.dateHoliday.findMany({ select: { date: true } });
    const dateHolidaySet = new Set(dateHolidays.map(dh => dh.date));
    const students = await db.student.findMany({ where: { classId }, orderBy: { name: 'asc' } });

    let start: Date;
    let end: Date;

