      const typeLabel = type === 'bulanan' ? 'BULANAN' : 'MINGGUAN';
      wsData = [];
      wsData.push([`REKAP ABSENSI ${typeLabel}`]);
      wsData.push([`Kelas: ${classData.name}`]);
      wsData.push([`Periode: ${periodLabel}`]);
      wsData.push([`Hari efektif: ${effectiveDays.length}`]);
