      wsData.push(['NO', 'NAMA SISWA', 'NISN', 'JENIS KELAMIN', 'MASUK', 'SAKIT', 'IZIN', 'ALFA', 'TERLAMBAT', 'TOTAL HARI', 'PERSENTASE (%)']);

      const recap = students.map(student => {
        const s = { name: student.name, nisn: student.nisn, gender: student.gender, hMasuk: 0, hSakit: 0, hIzin: 0, hAlfa: 0, terlambat: 0, totalHari: effectiveDays.length };
        const sm = attendanceMap[student.id];
        // Transfer student: get start date (YYYY-MM-DD). Days before this date
        // are counted as "Hadir" (present), not "Alfa".
        const transferDate = transferStartDates.get(student.id);
