      });

      for (let i = 0; i < recap.length; i++) {
        const s = recap[i];
        const pct = s.totalHari === 0 ? 0 : Math.round((s.hMasuk / s.totalHari) * 1000) / 10;
        wsData.push([i + 1, s.name, s.nisn || '-', s.gender || '-', s.hMasuk, s.hSakit, s.hIzin, s.hAlfa, s.terlambat, s.totalHari, pct]);
