        hMasuk: recap.reduce((a, r) => a + r.hMasuk, 0),
        hSakit: recap.reduce((a, r) => a + r.hSakit, 0),
        hIzin: recap.reduce((a, r) => a + r.hIzin, 0),
        hAlfa: recap.reduce((a, r) => a + r.hAlfa, 0),
        terlambat: recap.reduce((a, r) => a + r.terlambat, 0),
      };
      const totalHariAll = effectiveDays.length * recap.length;
      const totPct = totalHariAll === 0 ? 0 : Math.round((tot.hMasuk / totalHariAll) * 1000) / 10;
      wsData.push(['', 'TOTAL', '', '', tot.hMasuk, tot.hSakit, tot.hIzin, tot.hAlfa, tot.terlambat, totalHariAll, totPct]);

      colWidths = [5, 28, 14, 14, 8, 8, 8, 8, 11, 11, 13];
