    const activities = dateList.length > 0
      ? await db.academicActivity.findMany({ where: { classId, date: { in: dateList } } })
      : [];
    const liburDates = new Set(activities.filter(a => a.status === 'Libur').map(a => a.date));

    const effectiveDays = schoolDays.filter(d => !liburDates.has(d.date));

    // Build attendance map: date -> hour -> status
    const attendanceMap: Record<string, Record<number, string>> = {};
