    // TRANSFER STUDENT SUPPORT: read transfer_start_{studentId} setting.
    // Days BEFORE this date are classified as "Masuk" (present), not "Alfa".
    // Used for transfer students (e.g., Moh. Alpian Reydani joined 2026-10-01).
    const transferSetting = await db.settings.findUnique({
      where: { key: `transfer_start_${studentId}` },
    });
    const transferDate = transferSetting?.value || null;

    const dayResults: { day: typeof effectiveDays[0]; status: DayStatus }[] = [];
    for (const day of effectiveDays) {
      // Transfer student: before start date, classify as "Masuk"
      if (transferDate && day.date < transferDate) {
        dayResults.push({ day, status: 'Masuk' });
        continue;
      }
      const status = classifyDay(attendanceMap[day.date]);
      dayResults.push({ day, status });
    }

    // Compute totals
    const totals: Record<DayStatus, number> = { Masuk: 0, Terlambat: 0, Alfa: 0, Sakit: 0, Izin: 0 };
    for (const r of dayResults) {
      totals[r.status]++;
    }

    // Load logo and QR code images from filesystem
    let logoImg: Image | null = null;
    let qrImg: Image | null = null;
    try {
      logoImg = new Image();
      logoImg.src = fs.readFileSync(path.join(process.cwd(), 'upload', 'LOGO MTS.png'));
    } catch { /* logo not found, skip */ }
    try {
      qrImg = new Image();
      qrImg.src = fs.readFileSync(path.join(process.cwd(), 'upload', 'QR CODE NEW.png'));
    } catch { /* qr not found, skip */ }

    // ===== LAYOUT CONSTANTS =====
    const W = 800;
