      { w: 170 },  // 2: Tanggal
      { w: 88 },   // 3: Masuk
      { w: 88 },   // 4: Terlambat
      { w: 88 },   // 5: Alfa
      { w: 88 },   // 6: Sakit
      { w: 88 },   // 7: Izin
    ];
    // Total: 45+85+170+88*5 = 740 ✓

    // Compute column X positions
    const colX: number[] = [];
    let runningX = ML;
    for (const c of COLS) {
      colX.push(runningX);
      runningX += c.w;
    }
    const tableRight = colX[colX.length - 1] + COLS[COLS.length - 1].w; // 770

