    const thRow2H = 22;
    const thH = thRow1H + thRow2H; // 44
    const rowH = 26;
    const totalRowH = 28;
    const numDataRows = dayResults.length;
    const tableBodyH = numDataRows * rowH;
    const tableBottom = tableTop + thH + tableBodyH + totalRowH;
