    ctx.fillStyle = '#000000';
    ctx.font = '10px sans-serif';
    ctx.fillText('YAYASAN LEMBAGA PENDIDIKAN', textCenter, headerTop + 12);

    // Line 2: MADRASAH TSANAWIYAH AL ISHLAH (bold, 14pt)
    ctx.font = 'bold 14px sans-serif';
    ctx.fillText('MADRASAH TSANAWIYAH AL ISHLAH', textCenter, headerTop + 30);

    // Line 3: NSM / NPSN / AHU (8pt, gray)
    ctx.font = '8px sans-serif';
    ctx.fillStyle = '#666666';
    ctx.fillText(
      'NSM : 121235060089  NPSN : 20581159  Nomor AHU-0013757.AH.01.04.Tahun2019',
      textCenter, headerTop + 44,
    );

    // Line 4: Akta Notaris (8pt, gray)
    ctx.fillText(
      'Akta Notaris : Fibrianto Bimo Setiawan S.H., M.Kn. No. 08-20-2019',
      textCenter, headerTop + 55,
    );

    // Line 5: Email / Web (8pt, gray)
    ctx.fillText(
