    ctx.lineTo(tableRight, lineY);
    ctx.stroke();

    // ===== TITLE =====
    ctx.textAlign = 'center';
    ctx.fillStyle = '#000000';
    ctx.font = 'bold 14px sans-serif';
    ctx.fillText('REKAPITULASI ABSENSI SISWA', W / 2, titleY);

    // ===== STUDENT INFO =====
    const infoLine1Y = infoTop + 16;
    const infoLine2Y = infoTop + 33;

    ctx.font = '11px sans-serif';
    ctx.fillStyle = '#000000';

    // Left side
    ctx.textAlign = 'left';
    ctx.fillText(`Nama : ${student.name}`, ML, infoLine1Y);
    ctx.fillText(`NISN : ${student.nisn || '-'}`, ML, infoLine2Y);

    // Right side
    ctx.textAlign = 'right';
    ctx.fillText(`Kelas : ${classData.name}`, tableRight, infoLine1Y);
    ctx.fillText(`Jenis Kelamin : ${student.gender || '-'}`, tableRight, infoLine2Y);

    // ===== TABLE =====

    // --- Draw alternating row backgrounds first ---
    const dataStartY = tableTop + thH;
    for (let i = 0; i < numDataRows; i++) {
      if (i % 2 === 1) {
        const rowY = dataStartY + i * rowH;
        ctx.fillStyle = '#f5f5f5';
        ctx.fillRect(ML, rowY, CW, rowH);
      }
    }

    // --- Draw all horizontal lines ---
    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 1;

    // Top border of table
    ctx.beginPath();
    ctx.moveTo(ML, tableTop);
    ctx.lineTo(tableRight, tableTop);
    ctx.stroke();

    // Line between header row 1 and row 2
    const hRow2Y = tableTop + thRow1H;
    ctx.beginPath();
    ctx.moveTo(ML, hRow2Y);
    ctx.lineTo(tableRight, hRow2Y);
    ctx.stroke();

    // Line below header (top of data area)
    ctx.beginPath();
    ctx.moveTo(ML, dataStartY);
    ctx.lineTo(tableRight, dataStartY);
    ctx.stroke();

    // Lines between data rows
    for (let i = 0; i < numDataRows; i++) {
      const y = dataStartY + (i + 1) * rowH;
      ctx.beginPath();
      ctx.moveTo(ML, y);
      ctx.lineTo(tableRight, y);
      ctx.stroke();
    }

    // Line above total row (thicker)
    const totalRowY = dataStartY + numDataRows * rowH;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(ML, totalRowY);
    ctx.lineTo(tableRight, totalRowY);
    ctx.stroke();
    ctx.lineWidth = 1;

    // Bottom border of table (thicker)
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(ML, totalRowY + totalRowH);
    ctx.lineTo(tableRight, totalRowY + totalRowH);
