      ctx.lineTo(x, totalRowY + totalRowH);
      ctx.stroke();
    }

    // --- Header text ---
    // Row 1: No. | Hari | Tanggal | Keterangan (spanning cols 3-7)
    const hRow1CenterY = tableTop + 15;
    ctx.textAlign = 'center';
    ctx.font = 'bold 10px sans-serif';
    ctx.fillStyle = '#000000';

    ctx.fillText('No.', colX[0] + COLS[0].w / 2, hRow1CenterY);
    ctx.fillText('Hari', colX[1] + COLS[1].w / 2, hRow1CenterY);
    ctx.fillText('Tanggal', colX[2] + COLS[2].w / 2, hRow1CenterY);

    // "Keterangan" centered across cols 3-7
    const ketCenter = (colX[3] + tableRight) / 2;
    ctx.fillText('Keterangan', ketCenter, hRow1CenterY);

    // Row 2: sub-column names
    const hRow2CenterY = hRow2Y + 15;
    ctx.font = '9px sans-serif';
    const subLabels = ['Masuk', 'Terlambat', 'Alfa', 'Sakit', 'Izin'];
    for (let j = 0; j < 5; j++) {
      const ci = j + 3;
      ctx.fillText(subLabels[j], colX[ci] + COLS[ci].w / 2, hRow2CenterY);
    }

    // --- Data rows ---
    for (let i = 0; i < numDataRows; i++) {
      const { day, status } = dayResults[i];
      const rowY = dataStartY + i * rowH;
      const centerY = rowY + rowH / 2 + 4; // baseline offset

      // No.
      ctx.textAlign = 'center';
      ctx.font = '10px sans-serif';
      ctx.fillStyle = '#000000';
      ctx.fillText(String(i + 1), colX[0] + COLS[0].w / 2, centerY);

      // Hari
      ctx.fillText(day.dayName, colX[1] + COLS[1].w / 2, centerY);

      // Tanggal
      ctx.fillText(formatDateIndo(day.date), colX[2] + COLS[2].w / 2, centerY);

      // Keterangan columns: show ✓ for active status, - for others
      for (let j = 0; j < KETERANGAN_ORDER.length; j++) {
        const kStatus = KETERANGAN_ORDER[j];
        const ci = j + 3;
        const cx = colX[ci] + COLS[ci].w / 2;

        if (kStatus === status) {
          ctx.fillStyle = STATUS_COLORS[kStatus];
          ctx.font = 'bold 13px sans-serif';
          ctx.fillText('✓', cx, centerY);
        } else {
          ctx.fillStyle = '#cccccc';
          ctx.font = '10px sans-serif';
          ctx.fillText('-', cx, centerY);
        }
      }
    }

    // --- Total row ---
    const totalCenterY = totalRowY + totalRowH / 2 + 4;

    // "Total" label centered across cols 0-2
    ctx.textAlign = 'center';
    ctx.font = 'bold 11px sans-serif';
    ctx.fillStyle = '#000000';
    const totalLabelCenter = (colX[0] + colX[2] + COLS[2].w) / 2;
    ctx.fillText('Total', totalLabelCenter, totalCenterY);

    // Totals for each keterangan column
    for (let j = 0; j < KETERANGAN_ORDER.length; j++) {
      const kStatus = KETERANGAN_ORDER[j];
      const ci = j + 3;
      const cx = colX[ci] + COLS[ci].w / 2;
      const val = totals[kStatus];

      ctx.fillStyle = val > 0 ? STATUS_COLORS[kStatus] : '#cccccc';
      ctx.font = 'bold 11px sans-serif';
      ctx.fillText(String(val), cx, totalCenterY);
    }

    // ===== SIGNATURE SECTION =====
    ctx.textAlign = 'right';
    ctx.font = '11px sans-serif';
    ctx.fillStyle = '#000000';

    const signX = tableRight - 20;
    ctx.fillText('Mengetahui,', signX, signTop + 5);
    ctx.fillText('Kepala Madrasah,', signX, signTop + 20);

    // Space for signature (empty)
    ctx.font = '11px sans-serif';
    ctx.fillText('Rohmat Agung W., S.Pd.I', signX, signTop + 62);

    // ===== OUTPUT =====
    const buffer = canvas.toBuffer('image/jpeg', { quality: 0.92 });

    return new NextResponse(buffer, {
      status: 200,
      headers: {
        'Content-Type': 'image/jpeg',
        'Content-Disposition': `inline; filename="rekap_${student.name.replace(/\s+/g, '_')}_${startDate}_${endDate}.jpg"`,
      },
    });
  } catch (error) {
    console.error('Recap image error:', error);
    return noCacheJson({ error: 'Gagal membuat gambar rekap' }, 500);
  }
}
"},{"path":"src/app/api/recap/pdf/route.ts","content":"import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';
import PDFDocument from 'pdfkit';
import fs from 'fs';
import path from 'path';
import { ensurePdfFonts } from '@/lib/pdf-fonts';

const DAY_NAMES = ['Ahad', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const MONTH_NAMES = [
  'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
  'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember',
];

function parseDate(dateStr: string): Date {
  const [y, m, d] = dateStr.split('-').map(Number);
  return new Date(y, m - 1, d);
}

function formatDateStr(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function formatDateIndo(dateStr: string): string {
  const d = parseDate(dateStr);
  return `${d.getDate()} ${MONTH_NAMES[d.getMonth()]} ${d.getFullYear()}`;
}

type DayStatus = 'Masuk' | 'Terlambat' | 'Alfa' | 'Sakit' | 'Izin';
const KETERANGAN_ORDER: DayStatus[] = ['Masuk', 'Terlambat', 'Alfa', 'Sakit', 'Izin'];

const STATUS_SYMBOLS: Record<DayStatus, string> = {
  Masuk: '\u2714',      // heavy checkmark
  Terlambat: '\u23F0',  // alarm clock
  Alfa: '\u274C',       // cross mark
  Sakit: '\u2709',      // envelope (mail)
  Izin: '\u2709',       // envelope (mail)
};

const STATUS_COLORS: Record<DayStatus, [number, number, number]> = {
  Masuk: [5, 150, 105],
  Terlambat: [234, 88, 12],
  Alfa: [220, 38, 38],
  Sakit: [8, 145, 178],
  Izin: [202, 138, 4],
};

/** Classify a single day into one status based on majority of jam statuses */
function classifyDay(hourMap: Record<number, string> | undefined): DayStatus {
  let hadir = 0, terlambat = 0, sakit = 0, izin = 0, alfa = 0;

  if (hourMap && Object.keys(hourMap).length > 0) {
    for (let h = 1; h <= 8; h++) {
      const s = hourMap[h];
      if (!s) { alfa++; continue; }
      if (s === 'Hadir') hadir++;
      else if (s === 'Terlambat') terlambat++;
      else if (s === 'Sakit') sakit++;
      else if (s === 'Izin') izin++;
      else alfa++;
    }
  } else {
    alfa = 8;
  }

  if (hadir >= 4) return 'Masuk';
  if (hadir + terlambat >= 4) return 'Terlambat';
  if (sakit > izin && sakit > 0) return 'Sakit';
  if (izin > sakit && izin > 0) return 'Izin';
  return 'Alfa';
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const studentId = searchParams.get('studentId');
  const classId = searchParams.get('classId');
  const startDate = searchParams.get('startDate');
  const endDate = searchParams.get('endDate');

  if (!studentId || !classId || !startDate || !endDate) {
    return NextResponse.json({ error: 'studentId, classId, startDate, endDate wajib' }, { status: 400 });
  }

  try {
    ensurePdfFonts();
    const student = await db.student.findUnique({ where: { id: studentId } });
    if (!student) {
      return NextResponse.json({ error: 'Siswa tidak ditemukan' }, { status: 404 });
    }

    const classData = await db.class.findUnique({ where: { id: classId } });
    if (!classData) {
      return NextResponse.json({ error: 'Kelas tidak ditemukan' }, { status: 404 });
    }

    // Fetch holidays
    const holidays = await db.academicHoliday.findMany({ where: { isActive: true } });
    const holidayDays = new Set(holidays.map(h => h.dayOfWeek));

    const dateHolidays = await db.dateHoliday.findMany();
    const dateHolidaySet = new Set(dateHolidays.map(dh => dh.date));

    // Build school days list (Senin-Ahad, excluding weekly holidays and per-date holidays)
    const start = parseDate(startDate);
    const end = parseDate(endDate);
    const schoolDays: { date: string; dayName: string }[] = [];
    const current = new Date(start);
    while (current <= end) {
      const dayOfWeek = current.getDay();
      const ds = formatDateStr(current);
      if (!holidayDays.has(dayOfWeek) && !dateHolidaySet.has(ds)) {
        schoolDays.push({ date: ds, dayName: DAY_NAMES[dayOfWeek] });
      }
      current.setDate(current.getDate() + 1);
    }

    const dateList = schoolDays.map(d => d.date);

    // Fetch attendance records
    const records = dateList.length > 0
      ? await db.attendance.findMany({ where: { studentId, classId, date: { in: dateList } } })
      : [];

    // Fetch academic activities (to exclude Libur days)
    const activities = dateList.length > 0
      ? await db.academicActivity.findMany({ where: { classId, date: { in: dateList } } })
      : [];
    const liburDates = new Set(activities.filter(a => a.status === 'Libur').map(a => a.date));
    const effectiveDays = schoolDays.filter(d => !liburDates.has(d.date));

    // Build attendance map
    const attendanceMap: Record<string, Record<number, string>> = {};
    for (const r of records) {
      if (!attendanceMap[r.date]) attendanceMap[r.date] = {};
      attendanceMap[r.date][r.hour] = r.status;
    }

    // Classify each effective day
    // TRANSFER STUDENT SUPPORT: read transfer_start_{studentId} setting.
    // Days BEFORE this date are classified as "Masuk" (present), not "Alfa".
    // Used for transfer students (e.g., Moh. Alpian Reydani joined 2026-10-01).
    const transferSetting = await db.settings.findUnique({
      where: { key: `transfer_start_${studentId}` },
    });
    const transferDate = transferSetting?.value || null;

    const dayResults: { day: typeof effectiveDays[0]; status: DayStatus }[] = [];
    for (const day of effectiveDays) {
      // Transfer student: before start date, classify as "Masuk"
      if (transferDate && day.date < transferDate) {
        dayResults.push({ day, status: 'Masuk' });
        continue;
      }
      const status = classifyDay(attendanceMap[day.date]);
      dayResults.push({ day, status });
    }

    // Compute totals
    const totals: Record<DayStatus, number> = { Masuk: 0, Terlambat: 0, Alfa: 0, Sakit: 0, Izin: 0 };
    for (const r of dayResults) {
      totals[r.status]++;
    }

    // ===== Generate PDF =====
    const doc = new PDFDocument({
      size: 'A4',
      margins: { top: 20, bottom: 20, left: 40, right: 40 },
      info: {
        Title: `Rekap Absensi - ${student.name}`,
        Author: 'MTs Al Ishlah',
      },
    });

    const chunks: Uint8Array[] = [];
    doc.on('data', (chunk) => chunks.push(chunk));

    const PW = doc.page.width;
    const ML = 40;
    const MR = 40;
    const CW = PW - ML - MR;

    // Load logo image
    let logoBuf: Buffer | null = null;
    try {
      logoBuf = fs.readFileSync(path.join(process.cwd(), 'upload', 'LOGO MTS.png'));
    } catch { /* skip */ }

    // Load QR code image
    let qrBuf: Buffer | null = null;
    try {
      qrBuf = fs.readFileSync(path.join(process.cwd(), 'upload', 'QR CODE NEW.png'));
    } catch { /* skip */ }

    // ===== HEADER SECTION =====
    const headerTop = 25;

    // Logo (left)
    if (logoBuf) {
      doc.image(logoBuf, ML, headerTop, { width: 55, height: 55 });
    }

    // QR Code (right, above signature area later, but in header per template)
    if (qrBuf) {
      doc.image(qrBuf, PW - MR - 55, headerTop, { width: 55, height: 55 });
    }

    // Center text block
    const textCenter = PW / 2;
    const textLeft = ML + 65; // after logo
    const textRight = PW - MR - 65; // before QR

    // YAYASAN LEMBAGA PENDIDIKAN
    doc.font('Helvetica').fontSize(9).fillColor('#000000');
    doc.text('YAYASAN LEMBAGA PENDIDIKAN', textLeft, headerTop + 8, {
      width: textRight - textLeft,
      align: 'center',
    });

    // MADRASAH TSANAWIYAH AL ISHLAH (bold, bigger)
    doc.font('Helvetica-Bold').fontSize(14);
    doc.text('MADRASAH TSANAWIYAH AL ISHLAH', textLeft, headerTop + 22, {
      width: textRight - textLeft,
      align: 'center',
    });

    // NSM / NPSN / AHU
    doc.font('Helvetica').fontSize(7).fillColor('#555555');
    doc.text(
      'NSM : 121235060089     NPSN : 20581159     Nomor AHU-0013757.AH.01.04.Tahun2019',
      textLeft, headerTop + 40,
      { width: textRight - textLeft, align: 'center' },
    );

    // Akta Notaris
    doc.text(
      'Akta Notaris : Fibrianto Bimo Setiawan S.H., M.Kn. No. 08-20-2019',
      textLeft, headerTop + 50,
      { width: textRight - textLeft, align: 'center' },
    );

    // Email / Web
    doc.text(
      'Email : mtsalishlah89@gmail.com     Web : http://mtsalishlah.sch.id',
      textLeft, headerTop + 60,
      { width: textRight - textLeft, align: 'center' },
    );

    // Alamat
    doc.text(
      'Alamat : Rt.012/Rw.002 Dsn. Dlopo \u2013 Ds. Karangrejo \u2013 Kec. Ngasem \u2013 Kab. Kediri \u2013 Jawa Timur',
      textLeft, headerTop + 70,
      { width: textRight - textLeft, align: 'center' },
    );

    // Horizontal line
    const lineY = headerTop + 83;
    doc.moveTo(ML, lineY).lineTo(PW - MR, lineY).strokeColor('#000000').lineWidth(1).stroke();

    // ===== TITLE =====
    doc.font('Helvetica-Bold').fontSize(13).fillColor('#000000');
    doc.text('REKAPITULASI ABSENSI SISWA', ML, lineY + 12, {
      width: CW,
      align: 'center',
    });

    // ===== STUDENT INFO =====
    const infoY = lineY + 32;
    doc.font('Helvetica').fontSize(10).fillColor('#000000');

    // Left: Nama, NISN
    doc.text(`Nama\t\t: ${student.name}`, ML, infoY, { continued: false });
    doc.text(`NISN\t\t: ${student.nisn || '-'}`, ML, infoY + 16, { continued: false });

    // Right: Kelas, Jenis Kelamin
    doc.text(`Kelas\t\t: ${classData.name}`, PW / 2, infoY, { align: 'left', width: PW / 2 - MR });
    doc.text(`Jenis Kelamin\t: ${student.gender || '-'}`, PW / 2, infoY + 16, { align: 'left', width: PW / 2 - MR });

    // ===== TABLE =====
    const tableTop = infoY + 42;
    const colWidths = [30, 70, 140, 68, 68, 58, 58, 58]; // No, Hari, Tanggal, Masuk, Terlambat, Alfa, Sakit, Izin
    const totalColW = colWidths.reduce((a, b) => a + b, 0);
    const colX: number[] = [];
    let runX = ML;
    for (const w of colWidths) {
      colX.push(runX);
      runX += w;
    }

    const thH1 = 18;
    const thH2 = 18;
    const rowH = 22;
    const totalRowH = 24;
    const numDataRows = dayResults.length;

    // Check if we need page break for many rows (A4 usable height ~700px)
    const maxRowsPerPage = 18;
    const pages: number[][] = [];
    for (let i = 0; i < numDataRows; i += maxRowsPerPage) {
      pages.push(Array.from({ length: Math.min(maxRowsPerPage, numDataRows - i) }, (_, j) => i + j));
    }

    for (let pi = 0; pi < pages.length; pi++) {
      if (pi > 0) {
        doc.addPage();
      }

      const pRows = pages[pi];
      const cTableTop = pi === 0 ? tableTop : 40;
      const cDataStartY = cTableTop + thH1 + thH2;
      const cTableBottom = cDataStartY + pRows.length * rowH + (pi === pages.length - 1 ? totalRowH : 0);

      // Table border helper
      const drawTableBorders = (top: number, bottom: number) => {
        // Outer border
        doc.rect(ML, top, totalColW, bottom - top).strokeColor('#000000').lineWidth(1).stroke();
        // Horizontal lines: between th rows, between th and data, between data rows
        doc.moveTo(ML, top + thH1).lineTo(ML + totalColW, top + thH1).stroke();
        doc.moveTo(ML, cDataStartY).lineTo(ML + totalColW, cDataStartY).stroke();
        // Vertical lines
        for (let ci = 1; ci < colWidths.length; ci++) {
          doc.moveTo(colX[ci], top).lineTo(colX[ci], bottom).stroke();
        }
        // Data row horizontal lines
        for (let r = 0; r < pRows.length; r++) {
          const ry = cDataStartY + (r + 1) * rowH;
          doc.moveTo(ML, ry).lineTo(ML + totalColW, ry).stroke();
        }
        // Total row separator (if last page)
        if (pi === pages.length - 1) {
          const totalRY = cDataStartY + pRows.length * rowH;
          doc.moveTo(ML, totalRY).lineTo(ML + totalColW, totalRY).lineWidth(1.5).stroke();
          doc.lineWidth(1);
          doc.moveTo(ML, totalRY + totalRowH).lineTo(ML + totalColW, totalRY + totalRowH).lineWidth(1.5).stroke();
          doc.lineWidth(1);
        }
      };

      drawTableBorders(cTableTop, cTableBottom);

      // Header row 1: No. | Hari | Tanggal | Keterangan (merged cols 3-7)
      doc.font('Helvetica-Bold').fontSize(9).fillColor('#000000');
      const h1Y = cTableTop + 12;

      doc.text('No.', colX[0] + 2, h1Y, { width: colWidths[0] - 4, align: 'center' });
      doc.text('Hari', colX[1] + 2, h1Y, { width: colWidths[1] - 4, align: 'center' });
      doc.text('Tanggal', colX[2] + 2, h1Y, { width: colWidths[2] - 4, align: 'center' });

      // 'Keterangan' centered across cols 3-7
      const ketLeft = colX[3];
      const ketWidth = colX[7] + colWidths[7] - colX[3];
      doc.text('Keterangan', ketLeft + 2, h1Y, { width: ketWidth - 4, align: 'center' });

      // Remove vertical lines inside merged Keterangan header for row 1
      // Redraw row1 verticals only for cols 0-3 and col 7 boundary
      doc.strokeColor('#FFFFFF').lineWidth(2);
      for (let ci = 4; ci <= 6; ci++) {
        doc.moveTo(colX[ci], cTableTop).lineTo(colX[ci], cTableTop + thH1).stroke();
      }
      doc.strokeColor('#000000').lineWidth(1);

      // Header row 2: sub-columns
      doc.font('Helvetica').fontSize(8);
      const h2Y = cTableTop + thH1 + 12;
      const subLabels = ['Masuk', 'Terlambat', 'Alfa', 'Sakit', 'Izin'];
      for (let j = 0; j < 5; j++) {
        const ci = j + 3;
        doc.text(subLabels[j], colX[ci] + 2, h2Y, { width: colWidths[ci] - 4, align: 'center' });
      }

      // Data rows
      for (let r = 0; r < pRows.length; r++) {
        const di = pRows[r];
        const { day, status } = dayResults[di];
        const ry = cDataStartY + r * rowH;
        const centerY = ry + 14;

        // Alternating row background
        if (r % 2 === 1) {
          doc.rect(ML + 0.5, ry + 0.5, totalColW - 1, rowH - 1).fillColor('#f7f7f7').fill();
        }

        // No.
        doc.font('Helvetica').fontSize(9).fillColor('#000000');
        doc.text(String(di + 1), colX[0] + 2, centerY, { width: colWidths[0] - 4, align: 'center' });

        // Hari
        doc.text(day.dayName, colX[1] + 2, centerY, { width: colWidths[1] - 4, align: 'center' });

        // Tanggal
        doc.text(formatDateIndo(day.date), colX[2] + 2, centerY, { width: colWidths[2] - 4, align: 'center' });

        // Keterangan columns
        for (let j = 0; j < KETERANGAN_ORDER.length; j++) {
          const kStatus = KETERANGAN_ORDER[j];
          const ci = j + 3;

          if (kStatus === status) {
            const rgb = STATUS_COLORS[kStatus];
            doc.font('Helvetica-Bold').fontSize(11).fillColor(`rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`);
            doc.text(STATUS_SYMBOLS[kStatus], colX[ci] + 2, centerY, { width: colWidths[ci] - 4, align: 'center' });
          } else {
            doc.font('Helvetica').fontSize(9).fillColor('#cccccc');
            doc.text('-', colX[ci] + 2, centerY, { width: colWidths[ci] - 4, align: 'center' });
          }
        }
      }

      // Total row (last page only)
      if (pi === pages.length - 1) {
        const totalRY = cDataStartY + pRows.length * rowH;
        const totalCY = totalRY + 15;

        // Light gray background for total row
        doc.rect(ML + 0.5, totalRY + 0.5, totalColW - 1, totalRowH - 1).fillColor('#eeeeee').fill();

        doc.font('Helvetica-Bold').fontSize(9).fillColor('#000000');
        // 'Total' label across No, Hari, Tanggal
        const totalLabelW = colX[2] + colWidths[2] - colX[0];
        doc.text('Total', colX[0] + 2, totalCY, { width: totalLabelW - 4, align: 'center' });

        for (let j = 0; j < KETERANGAN_ORDER.length; j++) {
          const kStatus = KETERANGAN_ORDER[j];
          const ci = j + 3;
          const val = totals[kStatus];

          if (val > 0) {
            const rgb = STATUS_COLORS[kStatus];
            doc.font('Helvetica-Bold').fontSize(10).fillColor(`rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`);
          } else {
            doc.font('Helvetica').fontSize(9).fillColor('#cccccc');
          }
          doc.text(String(val), colX[ci] + 2, totalCY, { width: colWidths[ci] - 4, align: 'center' });
        }
      }
    }

    // ===== SIGNATURE SECTION (always on last page) =====
    const signX = PW - MR - 10;
    const signTop = doc.y + 25;

    doc.font('Helvetica').fontSize(10).fillColor('#000000');
    doc.text('Mengetahui,', signX, signTop, { width: 160, align: 'right' });
    doc.text('Kepala Madrasah,', signX, signTop + 15, { width: 160, align: 'right' });

    // Signature space
    doc.text('', signX, signTop + 30, { width: 160, align: 'right' });
    doc.text('', signX, signTop + 45, { width: 160, align: 'right' });

    doc.font('Helvetica-Bold').fontSize(10);
    doc.text('Rohmat Agung W., S.Pd.I', signX, signTop + 55, { width: 160, align: 'right' });

    doc.end();

    // Wait for PDF to finish
    const pdfBuffer = await new Promise<Buffer>((resolve) => {
      doc.on('end', () => resolve(Buffer.concat(chunks)));
    });

    const safeName = student.name.replace(/[^a-zA-Z0-9 ]/g, '').replace(/\s+/g, '_');

    return new NextResponse(new Uint8Array(pdfBuffer), {
      status: 200,
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `inline; filename="Rekap_${classData.name}_${safeName}_${startDate}_sd_${endDate}.pdf"`,
      },
    });
  } catch (error) {
    console.error('Recap PDF error:', error);
    return NextResponse.json({ error: 'Gagal membuat PDF rekap: ' + (error instanceof Error ? error.message : String(error)) }, { status: 500 });
  }
}
"},{"path":"src/app/api/recap/rekap-guru-excel/route.ts","content":"import { NextRequest, NextResponse } from 'next/server';
import * as XLSX from 'xlsx';
import {
  computeRekapGuruData,
  isValidDateStr,
  parseDate,
  formatDateStr,
  formatDateIndo,
  formatDDMMYYYY,
  MAX_RANGE_DAYS,
  type RekapGroupBy,
} from '@/lib/rekap-guru-data';

export const dynamic = 'force-dynamic';
export const maxDuration = 60;

interface WindowParams {
  mode: 'week' | 'month' | 'range';
  windowStart: string;
  windowEnd: string;
}

type ResolvedWindow =
  | { ok: true; params: WindowParams }
  | { ok: false; error: string; status: number };

/**
 * Shared window computation for all modes — mirrors the JSON API at
 * /api/check-absensi/rekap-guru so both endpoints always agree on the period.
 */
function resolveWindowParams(searchParams: URLSearchParams): ResolvedWindow {
  const mode = searchParams.get('mode') || 'week';

  if (mode === 'week') {
    const date = searchParams.get('date');
    if (!date) {
      return { ok: false, error: 'Parameter date diperlukan', status: 400 };
    }
    if (!isValidDateStr(date)) {
      return { ok: false, error: 'Parameter date tidak valid (format YYYY-MM-DD)', status: 400 };
    }
    const endD = parseDate(date);
    const startD = new Date(endD);
    startD.setDate(endD.getDate() - 6); // 7-day window inclusive of `date`
    return {
      ok: true,
      params: { mode: 'week', windowStart: formatDateStr(startD), windowEnd: formatDateStr(endD) },
    };
  }

  if (mode === 'month') {
    const monthRaw = searchParams.get('month');
    const yearRaw = searchParams.get('year');
    if (!monthRaw || !yearRaw) {
      return { ok: false, error: 'Parameter month dan year diperlukan', status: 400 };
    }
    const month = parseInt(monthRaw, 10);
    const year = parseInt(yearRaw, 10);
    if (isNaN(month) || isNaN(year) || month < 1 || month > 12 || year < 2000 || year > 2100) {
      return { ok: false, error: 'Parameter month (1-12) dan year (2000-2100) tidak valid', status: 400 };
    }
    const windowStart = formatDateStr(new Date(year, month - 1, 1));
    const windowEnd = formatDateStr(new Date(year, month, 0)); // last day of month
    return { ok: true, params: { mode: 'month', windowStart, windowEnd } };
  }

  if (mode === 'range') {
    const startDate = searchParams.get('startDate');
    const endDate = searchParams.get('endDate');
    if (!startDate || !endDate) {
      return { ok: false, error: 'Parameter startDate dan endDate diperlukan', status: 400 };
    }
    if (!isValidDateStr(startDate) || !isValidDateStr(endDate)) {
      return { ok: false, error: 'Parameter startDate/endDate tidak valid (format YYYY-MM-DD)', status: 400 };
    }
    if (endDate < startDate) {
      return { ok: false, error: 'endDate tidak boleh lebih awal dari startDate', status: 400 };
    }
    const dayCount = Math.round((parseDate(endDate).getTime() - parseDate(startDate).getTime()) / 86400000) + 1;
    if (dayCount > MAX_RANGE_DAYS) {
      return { ok: false, error: 'Rentang maksimal 400 hari', status: 400 };
    }
    return { ok: true, params: { mode: 'range', windowStart: startDate, windowEnd: endDate } };
  }

  return { ok: false, error: 'Parameter mode tidak valid (week | month | range)', status: 400 };
}

/**
 * GET /api/recap/rekap-guru-excel
 *
 * Excel export for REKAP GURU — grouping follows the `groupBy` query param so
 * the downloaded file ALWAYS matches the web view's Kelompok selector:
 *
 * - groupBy=date (default) → KELOMPOK PER TANGGAL:
 *     one neat table per school day (newest first):
 *     NO | NAMA GURU | KELAS | JAM BELUM DIISI
 *
 * - groupBy=teacher → KELOMPOK PER GURU:
 *     grouped by teacher name; under each teacher a neat table:
 *     NO | TANGGAL | KELAS | JAM BELUM DIISI
 */
export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);

  const resolved = resolveWindowParams(searchParams);
  if (!resolved.ok) {
    return NextResponse.json({ error: resolved.error }, { status: resolved.status });
  }
  const { mode, windowStart, windowEnd } = resolved.params;

  const groupByRaw = (searchParams.get('groupBy') || 'date').toLowerCase();
  if (groupByRaw !== 'date' && groupByRaw !== 'teacher') {
    return NextResponse.json({ error: 'Parameter groupBy tidak valid (date | teacher)' }, { status: 400 });
  }
  const groupBy: RekapGroupBy = groupByRaw;

  try {
    const computed = await computeRekapGuruData(windowStart, windowEnd);
    const periodLabel = `Tanggal ${formatDDMMYYYY(windowStart)} sampai dengan ${formatDDMMYYYY(windowEnd)}`;
    const groupLabel = groupBy === 'teacher' ? 'PER GURU' : 'PER TANGGAL';

    // Build the sheet as an array-of-arrays (rows). Sections mirror the PDF
    // layout: group title row → column header row → data rows → blank row.
    const rows: (string | number)[][] = [
      ['REKAP GURU BELUM MENGISI ABSENSI SISWA'],
      [`Kelompok: ${groupLabel}`],
      [periodLabel],
      [],
    ];

    let hasData = false;

    if (groupBy === 'teacher') {
      rows.push([`KELOMPOK ${groupLabel}`, '', '', '']);
      rows.push([]);
      for (const group of computed.teacherGroups) {
        if (group.entries.length === 0) continue;
        hasData = true;
        rows.push([`Nama Guru: ${group.fullName} (Total ${group.totalMissed} jam belum diisi)`]);
        rows.push(['NO', 'TANGGAL', 'KELAS', 'JAM BELUM DIISI']);
        group.entries.forEach((e, idx) => {
          rows.push([idx + 1, e.formattedDate, e.className, e.hours.map(h => `Jam ${h}`).join(', ')]);
        });
        rows.push([]);
      }
    } else {
      rows.push([`KELOMPOK ${groupLabel}`, '', '', '']);
      rows.push([]);
      // Newest first — matches the web view order.
      for (const day of computed.daysNewestFirst) {
        if (day.teachers.length === 0) continue;
        hasData = true;
        rows.push([`Rekap Guru Hari ${day.dayName}, Tanggal ${formatDateIndo(day.date)} (${day.teachers.length} entri)`]);
        rows.push(['NO', 'NAMA GURU', 'KELAS', 'JAM BELUM DIISI']);
        day.teachers.forEach((t, idx) => {
          rows.push([idx + 1, t.fullName, t.className, t.hours.map(h => `Jam ${h}`).join(', ')]);
        });
        rows.push([]);
      }
    }

    if (!hasData) {
      rows.push(['Semua guru sudah mengisi absensi pada periode ini.']);
      rows.push([]);
    }

    if (computed.holidays.length > 0) {
      rows.push(['Keterangan Hari Libur:']);
      for (const h of computed.holidays) {
        rows.push([`${h.dayName}, ${formatDateIndo(h.date)} = ${h.name}`]);
      }
      rows.push([]);
    }
    rows.push([`Dicetak: ${new Date().toLocaleString('id-ID', { dateStyle: 'full', timeStyle: 'short' })}`]);

    const ws = XLSX.utils.aoa_to_sheet(rows);
    // Reasonable column widths so the table is readable straight away.
    ws['!cols'] = [
      { wch: 5 },   // NO
      { wch: 34 },  // NAMA GURU / TANGGAL
      { wch: 14 },  // KELAS
      { wch: 26 },  // JAM
    ];

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, groupBy === 'teacher' ? 'Per Guru' : 'Per Tanggal');

    const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' }) as Buffer;

    // Filename mirrors the PDF convention (group suffix keeps files apart).
    const groupSuffix = groupBy === 'teacher' ? '_Per_Guru' : '';
    const filename = mode === 'month'
      ? `Rekap_Guru${groupSuffix}_${windowStart.slice(0, 7)}.xlsx`
      : `Rekap_Guru${groupSuffix}_${windowStart}_sd_${windowEnd}.xlsx`;

    return new NextResponse(new Uint8Array(buf), {
      status: 200,
      headers: {
        'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'Content-Disposition': `attachment; filename="${filename}"`,
        'Cache-Control': 'no-store',
      },
    });
  } catch (error) {
    console.error('Rekap Guru Excel error:', error);
    return NextResponse.json({ error: 'Gagal membuat Excel: ' + (error instanceof Error ? error.message : String(error)) }, { status: 500 });
  }
}
