/**
 * GET /api/recap/rekap-guru-pdf
 *
 * PDF export for REKAP GURU — grouping follows the `groupBy` query param so
 * the printed filter ALWAYS matches the web view's Kelompok selector:
 *
 * - groupBy=date (default) → KELOMPOK PER TANGGAL:
 *     one table per school day (newest first):
 *     NO | NAMA GURU | KELAS | JAM KE-
 *
 * - groupBy=teacher → KELOMPOK PER GURU:
 *     grouped by teacher name; under each teacher a neat table:
 *     NO | TANGGAL | KELAS | JAM KE-
 *     containing every (date, class, jam) combination the teacher has not
 *     filled attendance for.
 */
export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);

  const resolved = resolveWindowParams(searchParams);
  if (!resolved.ok) {
    return NextResponse.json({ error: resolved.error }, { status: resolved.status });
  }
  const { mode, windowStart, windowEnd } = resolved.params;

  const groupByRaw = (searchParams.get('groupBy') || 'date').toLowerCase();
  if (groupByRaw !== 'date' && groupByRaw !== 'teacher') {
    return NextResponse.json({ error: 'Parameter groupBy tidak valid (date | teacher)' }, { status: 400 });
  }
  const groupBy: RekapGroupBy = groupByRaw;

  try {
    ensurePdfFonts();
    const computed = await computeRekapGuruData(windowStart, windowEnd);

    // Generate PDF
    const doc = new PDFDocument({ size: 'A4', margins: { top: 40, bottom: 40, left: 40, right: 40 }, bufferPages: true });
    const chunks: Uint8Array[] = [];
    doc.on('data', (chunk: Uint8Array) => chunks.push(chunk));
    const endPromise = new Promise<Buffer>((resolve) => {
      doc.on('end', () => resolve(Buffer.concat(chunks)));
    });

    const PW = doc.page.width;
    const ML = 40, MR = 40;
    const CW = PW - ML - MR;

    // ===== TITLE (uppercase, with "SISWA" suffix per user request) =====
    doc.font('Helvetica-Bold').fontSize(14).fillColor('#000000');
    doc.text('REKAP GURU BELUM MENGISI ABSENSI SISWA', ML, 40, { width: CW, align: 'center' });
    doc.font('Helvetica').fontSize(10).fillColor('#000000');
    doc.text(`Tanggal ${formatDDMMYYYY(windowStart)} sampai dengan ${formatDDMMYYYY(windowEnd)}`, ML, 60, { width: CW, align: 'center' });
    doc.font('Helvetica-Bold').fontSize(10).fillColor('#000000');
    doc.text(`Kelompok: ${groupBy === 'teacher' ? 'PER GURU' : 'PER TANGGAL'}`, ML, doc.y + 4, { width: CW, align: 'center' });
    doc.moveDown(0.8);

    let hasData = false;

    // Draw a table with the given column layout. Shared by both grouping
    // modes so borders, header color and row spacing stay identical.
    const drawTable = (
      headers: string[],
      colW: number[],
      aligns: ('left' | 'center')[],
      rows: string[][],
    ) => {
      if (doc.y > 700) {
        doc.addPage();
      }
      const totalW = colW.reduce((a, b) => a + b, 0);
      const tableLeft = ML + (CW - totalW) / 2;
      const cx: number[] = [];
      let acc = tableLeft;
      for (const w of colW) {
        cx.push(acc);
        acc += w;
      }

      const rowH = 18;
      const headerH = 18;

      // Header background (light green to match web's neon-table aesthetic)
      doc.rect(tableLeft, doc.y, totalW, headerH).fillColor('#99FF33').fill();
      doc.font('Helvetica-Bold').fontSize(9).fillColor('#000000');
      const headerY = doc.y + 5;
      headers.forEach((h, i) => {
        doc.text(h, cx[i] + 2, headerY, { width: colW[i] - 4, align: 'center' });
      });
      doc.y += headerH;

      // Data rows
      doc.font('Helvetica').fontSize(9).fillColor('#000000');
      let rowY = doc.y;
      rows.forEach((row) => {
        if (rowY > 750) { doc.addPage(); rowY = 40; }
        doc.rect(tableLeft, rowY, totalW, rowH).strokeColor('#000000').lineWidth(0.5).stroke();
        row.forEach((cell, i) => {
          doc.text(cell, cx[i] + 2, rowY + 5, { width: colW[i] - 4, align: aligns[i] });
        });
        rowY += rowH;
      });
      doc.y = rowY + 10;
    };

    if (groupBy === 'teacher') {
      // ===== KELOMPOK PER GURU =====
      // Groups: one block per teacher name (sorted by total jam DESC then name).
      // Under each teacher: NO | TANGGAL | KELAS | JAM KE-.
      for (const group of computed.teacherGroups) {
        if (group.entries.length === 0) continue;
        hasData = true;

        if (doc.y > 690) {
          doc.addPage();
        }

        // Teacher group header — dikelompokkan berdasarkan nama guru
        doc.font('Helvetica-Bold').fontSize(11).fillColor('#000000');
        doc.text(`Nama Guru: ${group.fullName}`, ML, doc.y, { width: CW, align: 'left' });
        doc.font('Helvetica-Oblique').fontSize(9).fillColor('#555555');
        doc.text(`Total ${group.totalMissed} jam belum diisi`, ML, doc.y + 2, { width: CW, align: 'left' });
        doc.moveDown(0.3);

        drawTable(
          ['NO', 'TANGGAL', 'KELAS', 'JAM KE-'],
          [40, 170, 120, 110],
          ['center', 'left', 'center', 'center'],
          group.entries.map((e, idx) => [
            String(idx + 1),
            e.formattedDate,
            e.className,
            e.hours.map(h => String(h)).join(', '),
          ]),
        );
      }
    } else {
      // ===== KELOMPOK PER TANGGAL =====
      // One table per school day (newest first) — NO | NAMA GURU | KELAS | JAM KE-.
      // For long windows (month/range mode), keep the PDF bounded: when there are
      // more than 62 school days, only include days that have at least one
      // missing teacher (empty-day tables would add pages without value).
      const includeEmptyDays = computed.schoolDays.length <= 62;
      for (const day of computed.daysNewestFirst) {
        if (day.teachers.length === 0) {
          if (!includeEmptyDays) continue;
          // Empty day blocks are skipped in rendering even when collected —
          // an empty table adds no value in the PDF.
          continue;
        }
        hasData = true;

        if (doc.y > 690) {
          doc.addPage();
        }

        // Per-day sub-title — matches web: "Rekap Guru Hari {dayName}, Tanggal {DD MMMM YYYY}"
        doc.font('Helvetica-Bold').fontSize(11).fillColor('#000000');
        doc.text(`Rekap Guru Hari ${day.dayName}, Tanggal ${formatDateIndo(day.date)}`, ML, doc.y, { width: CW, align: 'left' });
        doc.font('Helvetica-Oblique').fontSize(9).fillColor('#555555');
        doc.text(`${day.teachers.length} entri`, ML, doc.y + 2, { width: CW, align: 'left' });
        doc.moveDown(0.3);

        drawTable(
          ['NO', 'NAMA GURU', 'KELAS', 'JAM KE-'],
          [40, 240, 100, 98],
          ['center', 'left', 'center', 'center'],
          day.teachers.map((t, idx) => [
            String(idx + 1),
            t.fullName,
            t.className,
            t.hours.map(h => String(h)).join(', '),
          ]),
        );
      }
    }

    if (!hasData) {
      doc.font('Helvetica').fontSize(10).fillColor('#555555').text('Semua guru sudah mengisi absensi pada periode ini.', ML, doc.y, { width: CW, align: 'center' });
    }

    // Holiday notes at the end
    if (computed.holidays.length > 0) {
      if (doc.y > 700) doc.addPage();
      doc.moveDown(1);
      doc.font('Helvetica-Bold').fontSize(9).fillColor('#000000').text('Keterangan Hari Libur:', ML, doc.y, { width: CW, align: 'left' });
      doc.font('Helvetica').fontSize(8).fillColor('#000000');
      for (const h of computed.holidays) {
        doc.text(`${h.dayName}, ${formatDateIndo(h.date)} = ${h.name}`, ML, doc.y, { width: CW, align: 'left' });
      }
    }

    doc.end();
    const pdfBuffer = await endPromise;

    // Filename format (includes the grouping so files from different
    // Kelompok filters never overwrite each other):
    // week/range + date    → Rekap_Guru_YYYY-MM-DD_sd_YYYY-MM-DD.pdf
    // week/range + teacher → Rekap_Guru_Per_Guru_YYYY-MM-DD_sd_YYYY-MM-DD.pdf
    // month      + date    → Rekap_Guru_YYYY-MM.pdf
    // month      + teacher → Rekap_Guru_Per_Guru_YYYY-MM.pdf
    const groupSuffix = groupBy === 'teacher' ? '_Per_Guru' : '';
    const filename = mode === 'month'
      ? `Rekap_Guru${groupSuffix}_${windowStart.slice(0, 7)}.pdf`
      : `Rekap_Guru${groupSuffix}_${windowStart}_sd_${windowEnd}.pdf`;

    // Also save the PDF to /home/z/my-project/upload/ for archival
    try {
      const uploadDir = path.join(process.cwd(), 'upload');
      if (!fs.existsSync(uploadDir)) {
        fs.mkdirSync(uploadDir, { recursive: true });
      }
      const filePath = path.join(uploadDir, filename);
      fs.writeFileSync(filePath, pdfBuffer);
      console.log(`[Rekap Guru PDF] Saved to ${filePath}`);
    } catch (saveErr) {
      // Non-fatal: file save failure should NOT block the PDF response
      console.warn('[Rekap Guru PDF] Could not save to upload dir:', saveErr instanceof Error ? saveErr.message : String(saveErr));
    }

    return new NextResponse(new Uint8Array(pdfBuffer), {
      status: 200,
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `inline; filename="${filename}"`,
      },
    });
  } catch (error) {
    console.error('Rekap Guru PDF error:', error);
    return NextResponse.json({ error: 'Gagal membuat PDF: ' + (error instanceof Error ? error.message : String(error)) }, { status: 500 });
  }
}
