import { noCacheJson } from '@/lib/utils';
import { db } from '@/lib/db';

function parseDate(dateStr: string): Date {
  const [y, m, d] = dateStr.split('-').map(Number);
  return new Date(y, m - 1, d);
}

function formatDateStr(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const type = searchParams.get('type') || 'weekly';
  const classId = searchParams.get('classId');
  const startDate = searchParams.get('startDate');
  const endDate = searchParams.get('endDate');
  const month = searchParams.get('month');
  const year = searchParams.get('year');

  if (!classId) {
    return noCacheJson({ error: 'classId wajib' }, 400);
  }

  try {
    const holidays = await db.academicHoliday.findMany({ where: { isActive: true } });
    const holidayDays = new Set(holidays.map(h => h.dayOfWeek));
    // PER-DATE HOLIDAYS: libur pada tanggal spesifik (mis. Hari Santri Nasional,
    // Penyisihan Aksioma) juga harus dikecualikan dari hari sekolah — jika tidak,
    // siswa tanpa record pada tanggal libur dihitung Alfa pada rekap bulanan.
    const dateHolidays = await db.dateHoliday.findMany({ select: { date: true } });
    const dateHolidaySet = new Set(dateHolidays.map(dh => dh.date));
    const students = await db.student.findMany({ where: { classId }, orderBy: { name: 'asc' } });

    let start: Date;
    let end: Date;

    if (type === 'monthly' && month && year) {
      const m = parseInt(month);
      const y = parseInt(year);
      start = new Date(y, m - 1, 1);
      end = new Date(y, m, 0);
      const startDateSetting = await db.settings.findUnique({ where: { key: 'attendance_start_date' } });
      if (startDateSetting?.value) {
        const recordStart = parseDate(startDateSetting.value);
        if (recordStart > start) start = recordStart;
      }
    } else {
      if (!startDate || !endDate) {
        return noCacheJson({ error: 'startDate dan endDate wajib' }, 400);
      }
      start = parseDate(startDate);
      end = parseDate(endDate);
    }

    const schoolDays: string[] = [];
    const current = new Date(start);
    while (current <= end) {
      const dayOfWeek = current.getDay();
      const ds = formatDateStr(current);
      // AHAD = HARI EFEKTIF: hari libur mingguan diatur manual di menu Libur
      // (AcademicHoliday — mis. Jumat). Ahad TIDAK dikecualikan otomatis.
      if (!holidayDays.has(dayOfWeek) && !dateHolidaySet.has(ds)) {
        schoolDays.push(ds);
      }
      current.setDate(current.getDate() + 1);
    }

    const attendanceRecords = await db.attendance.findMany({ where: { classId, date: { in: schoolDays } } });
    const activities = await db.academicActivity.findMany({ where: { classId, date: { in: schoolDays } } });
    const settings = await db.settings.findMany();
    const liburDates = new Set(activities.filter(a => a.status === 'Libur').map(a => a.date));
    const effectiveDays = schoolDays.filter(d => !liburDates.has(d));

    const attendanceMap: Record<string, Record<string, Record<number, string>>> = {};
    for (const r of attendanceRecords) {
      if (!attendanceMap[r.studentId]) attendanceMap[r.studentId] = {};
      if (!attendanceMap[r.studentId][r.date]) attendanceMap[r.studentId][r.date] = {};
      attendanceMap[r.studentId][r.date][r.hour] = r.status;
    }

    // TRANSFER STUDENT SUPPORT: Read transfer start dates from Settings
    // Format: key = "transfer_start_{studentId}", value = "YYYY-MM-DD"
    // Before this date, the student is counted as "Hadir" (present) in recap.
    // Example: Moh. Alpian Reydani (transfer_start_cmuoxgv610001v1ud2ab3zmf2 = "2026-10-01")
    const transferStartDates = new Map<string, string>();
    for (const setting of settings) {
      if (setting.key?.startsWith('transfer_start_')) {
        const studentId = setting.key.replace('transfer_start_', '');
        transferStartDates.set(studentId, setting.value);
      }
    }

    const recap = students.map(student => {
      const s = { studentId: student.id, name: student.name, nisn: student.nisn, gender: student.gender, hMasuk: 0, hSakit: 0, hIzin: 0, hAlfa: 0, terlambat: 0, totalHari: effectiveDays.length };
      const sm = attendanceMap[student.id];

      if (!sm) {
        // No attendance records at all for this student
        // Check if this is a transfer student (started mid-semester)
        const transferDate = transferStartDates.get(student.id);
        if (transferDate) {
          // Transfer student: count days BEFORE transfer start as "Hadir"
          for (const date of effectiveDays) {
            if (date < transferDate) { s.hMasuk++; } // Before transfer = Hadir
            else { s.hAlfa++; } // After transfer but no records = Alfa
          }
        } else {
          s.hAlfa = effectiveDays.length;
        }
        return s;
      }
      for (const date of effectiveDays) {
        const dr = sm[date];
        // Transfer student: before start date, count as "Hadir"
        const transferDate = transferStartDates.get(student.id);
        if (transferDate && date < transferDate) {
          s.hMasuk++; // Transfer student before start date = Hadir
          continue;
        }
        if (!dr || Object.keys(dr).length === 0) { s.hAlfa++; continue; }
        const vals = Object.values(dr);
        const hadir = vals.filter(v => v === 'Hadir').length;
        const terlambat = vals.filter(v => v === 'Terlambat').length;
        const sakit = vals.filter(v => v === 'Sakit').length;
        const izin = vals.filter(v => v === 'Izin').length;
        if (hadir >= 4) { s.hMasuk++; }
        else if (hadir + terlambat >= 4) { s.terlambat++; }
        else if (sakit > 0 && sakit >= hadir + terlambat) { s.hSakit++; }
        else if (izin > 0 && izin >= hadir + terlambat) { s.hIzin++; }
        else { s.hAlfa++; }
      }
      return s;
    });

    const totals = { hMasuk: recap.reduce((a, r) => a + r.hMasuk, 0), hSakit: recap.reduce((a, r) => a + r.hSakit, 0), hIzin: recap.reduce((a, r) => a + r.hIzin, 0), hAlfa: recap.reduce((a, r) => a + r.hAlfa, 0), terlambat: recap.reduce((a, r) => a + r.terlambat, 0) };

    return noCacheJson({ students: recap, totals, effectiveDays: effectiveDays.length, schoolDays: effectiveDays, startDate: formatDateStr(start), endDate: formatDateStr(end) });
  } catch (error) {
    console.error('Recap error:', error);
    return noCacheJson({ error: 'Gagal mengambil rekap' }, 500);
  }
}
"},{"path":"src/app/api/recap/student/route.ts","content":"import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';

const DAY_NAMES = ['Ahad', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const studentId = searchParams.get('studentId');
  const classId = searchParams.get('classId');
  const startDate = searchParams.get('startDate');
  const endDate = searchParams.get('endDate');

  if (!studentId || !classId || !startDate || !endDate) {
    return NextResponse.json({ error: 'Parameter tidak lengkap' }, { status: 400 });
  }

  try {
    // Fetch holidays
    const holidays = await db.academicHoliday.findMany({ where: { isActive: true } });
    const holidayDays = new Set(holidays.map((h: any) => h.dayOfWeek));

    const dateHolidays = await db.dateHoliday.findMany();
    const dateHolidaySet = new Set(dateHolidays.map((dh: any) => dh.date));

    // Build school days list
    const start = new Date(startDate + 'T00:00:00');
    const end = new Date(endDate + 'T00:00:00');
    const schoolDays: { date: string; dayName: string; dayOfWeek: number }[] = [];
    const current = new Date(start);
    while (current <= end) {
      const dayOfWeek = current.getDay();
      const ds = `${current.getFullYear()}-${String(current.getMonth() + 1).padStart(2, '0')}-${String(current.getDate()).padStart(2, '0')}`;
      if (!holidayDays.has(dayOfWeek) && !dateHolidaySet.has(ds)) {
        schoolDays.push({ date: ds, dayName: DAY_NAMES[dayOfWeek], dayOfWeek });
      }
      current.setDate(current.getDate() + 1);
    }

    const dateList = schoolDays.map((d: any) => d.date);

    // Fetch attendance records
    const records = dateList.length > 0
      ? await db.attendance.findMany({ where: { studentId, classId, date: { in: dateList } } })
      : [];

    // Fetch academic activities
    const activities = dateList.length > 0
      ? await db.academicActivity.findMany({ where: { classId, date: { in: dateList } } })
      : [];
    const liburDates = new Set(activities.filter((a: any) => a.status === 'Libur').map((a: any) => a.date));

    // Build attendance map: date -> hour -> status
    const attendanceMap: Record<string, Record<number, string>> = {};
    for (const r of records) {
      if (!attendanceMap[r.date]) attendanceMap[r.date] = {};
      attendanceMap[r.date][r.hour] = r.status;
    }

    // TRANSFER STUDENT SUPPORT: read transfer_start_{studentId} setting.
    // Days BEFORE this date are classified as "Hadir" (present), not "Alfa".
    // Used for transfer students (e.g., Moh. Alpian Reydani joined 2026-10-01).
    const transferSetting = await db.settings.findUnique({
      where: { key: `transfer_start_${studentId}` },
    });
    const transferDate = transferSetting?.value || null;

    // Classify each school day
    const days = schoolDays
      .filter((d: any) => !liburDates.has(d.date))
      .map((d: any) => {
        const hourMap = attendanceMap[d.date];
        // Transfer student: before start date, classify as "Hadir"
        if (transferDate && d.date < transferDate) {
          return {
            date: d.date,
            dayName: d.dayName,
            dayOfWeek: d.dayOfWeek,
            status: 'Hadir',
            hourDetails: hourMap || {},
          };
        }
        const status = classifyDay(hourMap);
        return {
          date: d.date,
          dayName: d.dayName,
          dayOfWeek: d.dayOfWeek,
          status,
          hourDetails: hourMap || {},
        };
      });

    return NextResponse.json({ days });
  } catch (error) {
    console.error('Student recap error:', error);
    return NextResponse.json({ error: 'Gagal mengambil data rekap' }, { status: 500 });
  }
}

function classifyDay(hourMap: Record<number, string> | undefined): string | null {
  if (!hourMap || Object.keys(hourMap).length === 0) return null;

  let hadir = 0, terlambat = 0, sakit = 0, izin = 0, alfa = 0;
  for (let h = 1; h <= 8; h++) {
    const s = hourMap[h];
    if (!s) { alfa++; continue; }
    if (s === 'Hadir') hadir++;
    else if (s === 'Terlambat') terlambat++;
    else if (s === 'Sakit') sakit++;
    else if (s === 'Izin') izin++;
    else alfa++;
  }

  if (hadir >= 4) return 'Hadir';
  if (hadir + terlambat >= 4) return 'Terlambat';
  if (sakit > izin && sakit > 0) return 'Sakit';
  if (izin > sakit && izin > 0) return 'Izin';
  return 'Alfa';
}
