import { db } from '@/lib/db';
import { noCacheJson } from '@/lib/utils';

export const dynamic = 'force-dynamic';
export const maxDuration = 30;

function parseDate(dateStr: string): Date {
  const [y, m, d] = dateStr.split('-').map(Number);
  return new Date(y, m - 1, d);
}

function formatDateStr(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

/**
 * GET /api/recap/student-bulk?classId=...&startDate=...&endDate=...
 *
 * Returns per-student attendance summary for a date range.
 * Columns: name, nisn, gender, masuk, terlambat, alfa, sakit, izin
 */
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const classId = searchParams.get('classId');
    const startDate = searchParams.get('startDate');
    const endDate = searchParams.get('endDate');

    if (!classId || !startDate || !endDate) {
      return noCacheJson({ error: 'classId, startDate, dan endDate wajib diisi' }, 400);
    }

    const classData = await db.class.findUnique({ where: { id: classId } });
    if (!classData) {
      return noCacheJson({ error: 'Kelas tidak ditemukan' }, 404);
    }

    // Get holidays (weekly + per-date) to skip those days
    const holidays = await db.academicHoliday.findMany({ where: { isActive: true } });
    const holidayDays = new Set(holidays.map(h => h.dayOfWeek));
    // PER-DATE HOLIDAYS: libur per tanggal juga dikecualikan agar tidak menghasilkan Alfa.
    const dateHolidays = await db.dateHoliday.findMany({ select: { date: true } });
    const dateHolidaySet = new Set(dateHolidays.map(dh => dh.date));

    // Build list of school days in range
    const start = parseDate(startDate);
    const end = parseDate(endDate);
    const schoolDays: string[] = [];
    const current = new Date(start);
    while (current <= end) {
      const dayOfWeek = current.getDay();
      const ds = formatDateStr(current);
      // AHAD = HARI EFEKTIF: hari libur mingguan diatur manual di menu Libur
      // (AcademicHoliday — mis. Jumat). Ahad TIDAK dikecualikan otomatis.
      if (!holidayDays.has(dayOfWeek) && !dateHolidaySet.has(ds)) {
        schoolDays.push(ds);
      }
      current.setDate(current.getDate() + 1);
    }

    // Get all attendance records for this class in the date range
    const students = await db.student.findMany({ where: { classId }, orderBy: { name: 'asc' } });
    const attendanceRecords = await db.attendance.findMany({
      where: { classId, date: { in: schoolDays } },
      select: { studentId: true, date: true, hour: true, status: true },
    });

    // Get activities (to check for "Libur" days)
    const activities = await db.academicActivity.findMany({
      where: { classId, date: { in: schoolDays } },
      select: { date: true, status: true },
    });
    const liburDates = new Set(activities.filter(a => a.status === 'Libur').map(a => a.date));
    const effectiveDays = schoolDays.filter(d => !liburDates.has(d));

    // Build attendance map: studentId -> date -> { hour: status }
    const attendanceMap: Record<string, Record<string, Record<number, string>>> = {};
    for (const r of attendanceRecords) {
      if (!attendanceMap[r.studentId]) attendanceMap[r.studentId] = {};
      if (!attendanceMap[r.studentId][r.date]) attendanceMap[r.studentId][r.date] = {};
      attendanceMap[r.studentId][r.date][r.hour] = r.status;
    }

    // TRANSFER STUDENT SUPPORT: Read transfer start dates from Settings.
    // Format: key = "transfer_start_{studentId}", value = "YYYY-MM-DD"
    // Before this date, the student is counted as "Hadir" (present) in recap,
    // NOT "Alfa". This is for transfer students like Moh. Alpian Reydani who
    // joined mid-semester (e.g., 2026-10-01).
    const allSettings = await db.settings.findMany();
    const transferStartDates = new Map<string, string>();
    for (const setting of allSettings) {
      if (setting.key?.startsWith('transfer_start_')) {
        const studentId = setting.key.replace('transfer_start_', '');
        transferStartDates.set(studentId, setting.value);
      }
    }

    // Build summary per student
    const studentsOut = students.map(student => {
      const sm = attendanceMap[student.id];
      let hMasuk = 0, hSakit = 0, hIzin = 0, hAlfa = 0, terlambat = 0;

      // Transfer student: get start date (YYYY-MM-DD). Days before this date
      // are counted as "Hadir" (present), not "Alfa".
      const transferDate = transferStartDates.get(student.id);

      if (!sm) {
        // No attendance records at all for this student
        if (transferDate) {
          // Transfer student: count days BEFORE transfer start as "Hadir"
          for (const date of effectiveDays) {
            if (date < transferDate) { hMasuk++; } // Before transfer = Hadir
            else { hAlfa++; } // After transfer but no records = Alfa
          }
        } else {
          hAlfa = effectiveDays.length;
        }
      } else {
        for (const date of effectiveDays) {
          // Transfer student: before start date, count as "Hadir"
          if (transferDate && date < transferDate) {
            hMasuk++; // Transfer student before start date = Hadir
            continue;
          }
          const dr = sm[date];
          if (!dr || Object.keys(dr).length === 0) {
            hAlfa++;
            continue;
          }
          const vals = Object.values(dr);
          const hadir = vals.filter(v => v === 'Hadir').length;
          const terl = vals.filter(v => v === 'Terlambat').length;
          const sakit = vals.filter(v => v === 'Sakit').length;
          const izin = vals.filter(v => v === 'Izin').length;
          if (hadir >= 4) { hMasuk++; }
          else if (hadir + terl >= 4) { terlambat++; }
          else if (sakit > 0 && sakit >= hadir + terl) { hSakit++; }
          else if (izin > 0 && izin >= hadir + terl) { hIzin++; }
          else { hAlfa++; }
        }
      }

      return {
        name: student.name,
        nisn: student.nisn || '-',
        gender: student.gender || '-',
        masuk: hMasuk,
        terlambat: terlambat,
        alfa: hAlfa,
        sakit: hSakit,
        izin: hIzin,
        totalHari: effectiveDays.length,
      };
    });

    return noCacheJson({
      className: classData.name,
      startDate,
      endDate,
      effectiveDays: effectiveDays.length,
      students: studentsOut,
    });
  } catch (error) {
    console.error('Recap student-bulk error:', error);
    return noCacheJson({ error: 'Gagal membuat rekap: ' + (error instanceof Error ? error.message : String(error)) }, 500);
  }
}
"},{"path":"src/app/api/recap/student-bulk-zip/route.ts","content":"import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';
import JSZip from 'jszip';
import fs from 'fs';
import path from 'path';
import { ensurePdfFonts } from '@/lib/pdf-fonts';
import { generateRekapPdf, DayResultData, HolidayInfo } from '@/lib/generate-rekap-pdf';

const DAY_NAMES = ['Ahad', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];

type DayStatus = 'Hadir' | 'Terlambat' | 'Alfa' | 'Sakit' | 'Izin';

function classifyDay(hourMap: Record<number, string> | undefined): DayStatus | null {
  if (!hourMap || Object.keys(hourMap).length === 0) return null;
  let hadir = 0, terlambat = 0, sakit = 0, izin = 0, alfa = 0;
  for (let h = 1; h <= 8; h++) {
    const s = hourMap[h];
    if (!s) { alfa++; continue; }
    if (s === 'Hadir') hadir++;
    else if (s === 'Terlambat') terlambat++;
    else if (s === 'Sakit') sakit++;
    else if (s === 'Izin') izin++;
    else alfa++;
  }
  if (hadir >= 4) return 'Hadir';
  if (hadir + terlambat >= 4) return 'Terlambat';
  if (sakit > izin && sakit > 0) return 'Sakit';
  if (izin > sakit && izin > 0) return 'Izin';
  return 'Alfa';
}

export const maxDuration = 180;

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const classId = searchParams.get('classId');
  const startDate = searchParams.get('startDate');
  const endDate = searchParams.get('endDate');

  if (!classId || !startDate || !endDate) {
    return NextResponse.json({ error: 'Parameter tidak lengkap' }, { status: 400 });
  }

  try {
    ensurePdfFonts();
    const classData = await db.class.findUnique({ where: { id: classId } });
    if (!classData) return NextResponse.json({ error: 'Kelas tidak ditemukan' }, { status: 404 });

    const students = await db.student.findMany({ where: { classId }, orderBy: { name: 'asc' } });
    if (students.length === 0) return NextResponse.json({ error: 'Tidak ada siswa' }, { status: 404 });

    // Load QR code and school logo
    let qrBuf: Buffer | null = null;
    try { qrBuf = fs.readFileSync(path.join(process.cwd(), 'upload', 'QR CODE NEW.png')); } catch { /* skip */ }
    let logoBuf: Buffer | null = null;
    try { logoBuf = fs.readFileSync(path.join(process.cwd(), 'upload', 'LOGO MTS.png')); } catch { /* skip */ }

    const holidays = await db.academicHoliday.findMany({ where: { isActive: true } });
    const holidayDays = new Set(holidays.map((h: any) => h.dayOfWeek));
    const dateHolidays = await db.dateHoliday.findMany();
    const dateHolidaySet = new Set(dateHolidays.map((dh: any) => dh.date));

    const start = new Date(startDate + 'T00:00:00');
    const end = new Date(endDate + 'T00:00:00');
    const dateList: string[] = [];
    const cur = new Date(start);
    while (cur <= end) {
      const dow = cur.getDay();
      const ds = `${cur.getFullYear()}-${String(cur.getMonth() + 1).padStart(2, '0')}-${String(cur.getDate()).padStart(2, '0')}`;
      if (!holidayDays.has(dow) && !dateHolidaySet.has(ds)) dateList.push(ds);
      cur.setDate(cur.getDate() + 1);
    }

    // Fetch all attendance and activities for this class in the date range
    const allRecords = dateList.length > 0
      ? await db.attendance.findMany({ where: { classId, date: { in: dateList } } })
      : [];
    const activities = dateList.length > 0
      ? await db.academicActivity.findMany({ where: { classId, date: { in: dateList } } })
      : [];
    const liburDates = new Set(activities.filter((a: any) => a.status === 'Libur').map((a: any) => a.date));

    // Group attendance by student -> date -> hour
    const studentAttendance: Record<string, Record<string, Record<number, string>>> = {};
    for (const r of allRecords) {
      if (!studentAttendance[r.studentId]) studentAttendance[r.studentId] = {};
      if (!studentAttendance[r.studentId][r.date]) studentAttendance[r.studentId][r.date] = {};
      studentAttendance[r.studentId][r.date][r.hour] = r.status;
    }

    // Build school day info
    const schoolDayInfo = dateList.map(ds => {
      const d = new Date(ds + 'T00:00:00');
      return { date: ds, dayName: DAY_NAMES[d.getDay()] };
    }).filter(d => !liburDates.has(d.date));

    // TRANSFER STUDENT SUPPORT: read all transfer_start_{studentId} settings.
    // Days BEFORE this date are classified as "Hadir" (present), not "Alfa".
    // Used for transfer students (e.g., Moh. Alpian Reydani joined 2026-10-01).
    const allSettings = await db.settings.findMany();
    const transferStartDates = new Map<string, string>();
    for (const setting of allSettings) {
      if (setting.key?.startsWith('transfer_start_')) {
        const sid = setting.key.replace('transfer_start_', '');
        transferStartDates.set(sid, setting.value);
      }
    }

    // Collect manual date holidays within the date range for display in PDF
    const pdfHolidays: HolidayInfo[] = [];
    for (const dh of dateHolidays) {
      if (dh.date >= startDate && dh.date <= endDate) {
        const date = new Date(dh.date + 'T00:00:00');
        const dow = date.getDay();
        pdfHolidays.push({
          date: dh.date,
          dayName: DAY_NAMES[dow],
          name: dh.name,
        });
      }
    }
    pdfHolidays.sort((a, b) => a.date.localeCompare(b.date));

    const zip = new JSZip();
    const folderName = `Rekap_${classData.name}_${startDate}_sd_${endDate}`;

    for (const student of students) {
      const studentHourMap = studentAttendance[student.id] || {};
      // Transfer student: get start date for this student
      const transferDate = transferStartDates.get(student.id);
      const dayResults: DayResultData[] = schoolDayInfo.map(d => {
        // Transfer student: before start date, classify as "Hadir"
        if (transferDate && d.date < transferDate) {
          return { date: d.date, dayName: d.dayName, status: 'Hadir' as DayStatus };
        }
        return {
          date: d.date,
          dayName: d.dayName,
          status: classifyDay(studentHourMap[d.date]),
        };
      });

      if (dayResults.length === 0) continue;

      const pdfBuffer = await generateRekapPdf(
        { name: student.name, nisn: student.nisn || '', gender: student.gender || '' },
        { name: classData.name },
        dayResults,
        logoBuf,
        qrBuf,
        pdfHolidays,
      );
      const safeName = student.name.replace(/[^a-zA-Z0-9 ]/g, '').replace(/\s+/g, '_');
      zip.file(`Rekap_${classData.name}_${safeName}.pdf`, pdfBuffer);
    }

    const zipBuffer = await zip.generateAsync({ type: 'nodebuffer' });

    return new NextResponse(new Uint8Array(zipBuffer), {
      status: 200,
      headers: {
        'Content-Type': 'application/zip',
        'Content-Disposition': `attachment; filename="${folderName}.zip"`,
      },
    });
  } catch (error) {
    console.error('Bulk ZIP error:', error);
    return NextResponse.json({ error: 'Gagal membuat ZIP: ' + (error instanceof Error ? error.message : String(error)) }, { status: 500 });
  }
}
