}"},{"path":"src/app/api/schedules/download/route.ts","content":"import { NextRequest } from 'next/server';
import { db } from '@/lib/db';

const ALL_DAYS = ['Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu', 'Ahad'];
const DAY_MAP: Record<string, number> = {
  Ahad: 0, Senin: 1, Selasa: 2, Rabu: 3, Kamis: 4, Jumat: 5, Sabtu: 6,
};
const HOURS = [1, 2, 3, 4, 5, 6, 7, 8];

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const classId = searchParams.get('classId');

    if (!classId) {
      return new Response('Parameter classId diperlukan', { status: 400 });
    }

    // Get class name
    const cls = await db.class.findUnique({ where: { id: classId } });
    if (!cls) {
      return new Response('Kelas tidak ditemukan', { status: 404 });
    }

    // Get academic holidays (weekly)
    const holidays = await db.academicHoliday.findMany({ where: { isActive: true } });
    const holidayDays = new Set(holidays.map(h => h.dayOfWeek));

    // Filter active days (non-holiday)
    const activeDays = ALL_DAYS.filter(d => !holidayDays.has(DAY_MAP[d]));

    // Get existing schedules for this class — these are the ACTUAL schedules
    // saved by the user, NOT dummy data. We fill the Excel with whatever
    // schedules exist for this class. Empty cells mean no schedule has been
    // saved for that day/hour combination.
    const [existingSchedules, waliKelas] = await Promise.all([
      db.weeklySchedule.findMany({ where: { classId } }),
      db.waliKelas.findUnique({ where: { classId } }),
    ]);
    const scheduleMap = new Map<string, string>();
    for (const s of existingSchedules) {
      scheduleMap.set(`${s.dayOfWeek}-${s.hour}`, s.teacher);
    }

    const hasSchedules = existingSchedules.length > 0;

    // Build Excel using xlsx library
    const XLSX = await import('xlsx');
    const wb = XLSX.utils.book_new();

    // Row 1: Title — "JADWAL MINGGUAN KELAS <NAME>"
    // Merge cells across all columns for the title row
    const titleText = `JADWAL MINGGUAN KELAS ${cls.name.toUpperCase()}`;
    // Row 2: Wali Kelas name (if available)
    const waliText = waliKelas?.name ? `Wali Kelas: ${waliKelas.name}` : '';
    // Row 3: empty (spacer)
    // Row 4: Header row (Jam, day1, day2, ...)
    // Row 5+: Data rows (1..8 with actual teacher names filled)
    const headers = ['Jam', ...activeDays];
    const dataRows: (string | number)[][] = [];
    for (const hour of HOURS) {
      const row: (string | number)[] = [hour];
      for (const day of activeDays) {
        const dayNum = DAY_MAP[day];
        const key = `${dayNum}-${hour}`;
        // Fill ACTUAL teacher name if schedule exists; empty string otherwise
        row.push(scheduleMap.get(key) || '');
      }
      dataRows.push(row);
    }

    // Build the full sheet data with title rows
    // Row layout:
    //   Row 0: Title "JADWAL MINGGUAN KELAS <NAME>" (merged across all columns)
    //   Row 1: Wali Kelas name (only if exists; merged across all columns)
    //   Row 2: Empty spacer row
    //   Row 3: Header row (Jam, day1, day2, ...)
    //   Row 4+: Data rows (1..8 with actual teacher names filled)
    const wsData: (string | number)[][] = [];
    wsData.push([titleText, ...activeDays.map(() => '')]);
    if (waliText) {
      wsData.push([waliText, ...activeDays.map(() => '')]);
    }
    wsData.push([]); // spacer
    wsData.push(headers);
    for (const row of dataRows) {
      wsData.push(row);
    }

    const ws = XLSX.utils.aoa_to_sheet(wsData);

    // Merge title (and wali) row across all columns
    const numCols = 1 + activeDays.length;
    const merges: { s: { r: number; c: number }; e: { r: number; c: number } }[] = [
      { s: { r: 0, c: 0 }, e: { r: 0, c: numCols - 1 } }, // title row
    ];
    if (waliText) {
      merges.push({ s: { r: 1, c: 0 }, e: { r: 1, c: numCols - 1 } }); // wali row
    }
    ws['!merges'] = merges;

    // Style: make title row bold (via cell property — xlsx community build supports `s`)
    const titleCellRef = XLSX.utils.encode_cell({ r: 0, c: 0 });
    if (ws[titleCellRef]) {
      ws[titleCellRef].s = { font: { bold: true, sz: 14 }, alignment: { horizontal: 'center' } };
    }

    // Set column widths
    ws['!cols'] = [
      { wch: 6 },   // Jam column
      ...activeDays.map(() => ({ wch: 25 })), // Day columns
    ];

    XLSX.utils.book_append_sheet(wb, ws, 'Jadwal Mingguan');
    const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });

    // File name reflects that this contains ACTUAL schedule data (not a template)
    // when the class has schedules. If the class has no schedules yet, it's a
    // blank template the user can fill in and re-upload.
    const fileName = hasSchedules
      ? `Jadwal_Mingguan_${cls.name.replace(/\s+/g, '_')}.xlsx`
      : `Template_Jadwal_${cls.name.replace(/\s+/g, '_')}.xlsx`;
    return new Response(buf, {
      headers: {
        'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'Content-Disposition': `attachment; filename="${encodeURIComponent(fileName)}"`,
      },
    });
  } catch (error) {
    console.error('Error downloading schedule template:', error);
    return new Response('Gagal mengunduh template', { status: 500 });
  }
}
