import { db } from '@/lib/db';
import { noCacheJson } from '@/lib/utils';
import { scheduleAutoSync, scheduleGSheetSync, markGSheetDirty } from '@/lib/auto-sync'

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const classId = searchParams.get('classId');

    if (!classId) {
      return noCacheJson({ error: 'Parameter classId diperlukan' }, 400);
    }

    const schedules = await db.weeklySchedule.findMany({
      where: { classId },
      orderBy: [{ dayOfWeek: 'asc' }, { hour: 'asc' }],
    });

    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson({ schedules });
  } catch (error) {
    console.error('Error fetching schedules:', error);
    return noCacheJson({ error: 'Gagal mengambil jadwal' }, 500);
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { classId, schedules } = body as {
      classId: string;
      schedules: { dayOfWeek: number; hour: number; teacher: string }[];
    };

    if (!classId || !Array.isArray(schedules)) {
      return noCacheJson({ error: 'Data tidak valid' }, 400);
    }

    // Verify class exists
    const cls = await db.class.findUnique({ where: { id: classId } });
    if (!cls) {
      return noCacheJson({ error: 'Kelas tidak ditemukan' }, 404);
    }

    // Delete existing schedules for this class and recreate
    await db.weeklySchedule.deleteMany({ where: { classId } });

    if (schedules.length > 0) {
      await db.weeklySchedule.createMany({
        data: schedules.map(s => ({
          classId,
          dayOfWeek: s.dayOfWeek,
          hour: s.hour,
          teacher: s.teacher || '',
        })),
      });
    }

    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson({ success: true, message: 'Jadwal berhasil disimpan' });
  } catch (error) {
    console.error('Error saving schedules:', error);
    return noCacheJson({ error: 'Gagal menyimpan jadwal' }, 500);
  }
}
