import { noCacheJson } from '@/lib/utils';
import { db } from '@/lib/db';
import { scheduleAutoSync, scheduleGSheetSync, markGSheetDirty } from '@/lib/auto-sync'

export const dynamic = 'force-dynamic';

const KEY = 'reset_schedule_hour';
const DEFAULT_HOUR = 0; // midnight Jakarta time (00:00 WIB)

/**
 * GET /api/settings/reset-schedule
 * Returns the configured reset hour (0-23, Jakarta time).
 * Default: 0 (midnight).
 */
export async function GET() {
  try {
    const setting = await db.settings.findUnique({ where: { key: KEY } });
    const hour = setting ? parseInt(setting.value, 10) : DEFAULT_HOUR;
    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson({ hour: isNaN(hour) ? DEFAULT_HOUR : hour });
  } catch (error) {
    console.error('Error fetching reset schedule:', error);
    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson({ hour: DEFAULT_HOUR });
  }
}

/**
 * POST /api/settings/reset-schedule
 * Body: { hour: number } — 0-23 (Jakarta time)
 * Saves the reset schedule hour.
 */
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const hour = parseInt(body.hour, 10);
    if (isNaN(hour) || hour < 0 || hour > 23) {
      return noCacheJson({ error: 'Hour harus antara 0-23' }, 400);
    }
    await db.settings.upsert({
      where: { key: KEY },
      update: { value: String(hour) },
      create: { key: KEY, value: String(hour) },
    });
    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson({ success: true, hour });
  } catch (error) {
    console.error('Error saving reset schedule:', error);
    return noCacheJson({ error: 'Gagal menyimpan jadwal reset' }, 500);
  }
}
