import { noCacheJson } from '@/lib/utils'
import { db } from '@/lib/db'
import { scheduleAutoSync, scheduleGSheetSync, markGSheetDirty } from '@/lib/auto-sync'
import { filterExcludedStudents, isStudentExcluded } from '@/lib/student-blocklist'

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const classId = searchParams.get('classId')

    if (!classId) {
      scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
      return noCacheJson(
        { error: 'classId diperlukan' },
        400
      )
    }

    const students = await db.student.findMany({
      where: { classId },
      orderBy: { name: 'asc' },
    })

    // Layer 1 (blocklist): deleted students must never appear in class rosters,
    // even if a restore path re-inserted them into the DB.
    const visibleStudents = filterExcludedStudents(students)

    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson(visibleStudents)
  } catch (error) {
    console.error('Error fetching students:', error)
    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson(
      { error: 'Gagal mengambil data siswa' },
      500
    )
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json()
    const { name, nisn, gender, whatsapp, classId } = body

    // Layer 2 (blocklist): reject creation attempts that reuse a blocklisted ID.
    if (isStudentExcluded(body?.id)) {
      scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
      return noCacheJson({ error: 'ID siswa ini telah diblokir (siswa telah dihapus permanen)' }, 403)
    }

    if (!name || !classId) {
      scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
      return noCacheJson(
        { error: 'Nama dan classId diperlukan' },
        400
      )
    }

    const student = await db.student.create({
      data: {
        name,
        nisn: nisn || '',
        gender: gender || '',
        whatsapp: whatsapp || '',
        classId,
      },
    })

    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson(student, 201)
  } catch (error) {
    console.error('Error creating student:', error)
    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson(
      { error: 'Gagal menambah siswa' },
      500
    )
  }
}
"},{"path":"src/app/api/sync-status/route.ts","content":"import { NextResponse } from 'next/server';
import { getOperationState, getLastResults, isAnyOperationRunning } from '@/lib/operation-lock';
import { noCacheJson } from '@/lib/utils';
import { db } from '@/lib/db';

export const dynamic = 'force-dynamic';
export const maxDuration = 10;

/**
 * GET /api/sync-status
 *
 * Returns the current sync/restore operation state for frontend polling.
 * The frontend uses this to:
 *   1. Show toast notifications when operations start/complete
 *   2. Show conflict warnings when an operation is blocked
 *   3. Disable buttons when an operation is running
 *   4. Detect server reset condition (local count < GitHub count) and
 *      block new attendance saves until pull-diff completes
 *
 * Response:
 * {
 *   "currentOperation": "pull-diff" | "sync" | "auto-sync" | "restore-local" | null,
 *   "startedAt": "2026-...",
 *   "label": "Pull Diff dari GitHub",
 *   "progress": { "current": 50, "total": 100, "percentage": 50, "label": "..." },
 *   "isRunning": true/false,
 *   "lastResults": { ... },
 *   "serverReset": true/false,         // true if local count < GitHub count
 *   "localCount": 55441,              // local DB attendance count
 *   "ghCount": 61582,                 // GitHub attendance count (cached)
 *   "pullDiffRunning": true/false     // true if pull-diff is currently running
 * }
 */
export async function GET() {
  try {
    const state = getOperationState();
    const lastResults = getLastResults();

    // Server reset detection: compare local count vs cached GitHub count.
    // If local < GitHub, the server is in reset recovery state — pull-diff
    // should be running (or about to run) to restore missing records.
    // The frontend uses this to block new attendance saves until pull-diff
    // completes, preventing data loss.
    let serverReset = false;
    let localCount = 0;
    let ghCount = 0;
    let pullDiffRunning = false;
    try {
      localCount = await db.attendance.count();
      const ghCountSetting = await db.settings.findUnique({ where: { key: 'online_attendance_count' } });
      ghCount = ghCountSetting ? (parseInt(ghCountSetting.value, 10) || 0) : 0;
      serverReset = ghCount > 0 && localCount < ghCount;
      pullDiffRunning = state.current === 'pull-diff';
    } catch (e) {
      // If DB query fails, don't block — assume no server reset
      console.warn('[sync-status] Could not compute serverReset:', e instanceof Error ? e.message : String(e));
    }

    return noCacheJson({
      currentOperation: state.current,
      startedAt: state.startedAt,
      label: state.label,
      progress: state.progress,
      isRunning: isAnyOperationRunning(),
      lastResults,
      // Server reset detection — used by IsiAbsensiTab to block saves during recovery
      serverReset,
      localCount,
      ghCount,
      pullDiffRunning,
    });
  } catch (error) {
    console.error('Error in sync-status:', error);
    return noCacheJson({ error: 'Gagal mengambil status sync' }, 500);
  }
}
