import { noCacheJson } from '@/lib/utils';
import { db } from '@/lib/db';
import { scheduleAutoSync, scheduleGSheetSync, markGSheetDirty } from '@/lib/auto-sync'

export const dynamic = 'force-dynamic';

function decodeNicknameParam(param: string): string {
  // Next.js dynamic route params are URL-encoded. decodeURIComponent handles
  // spaces (%20) and other reserved characters in nicknames like "Bu Anis".
  try {
    return decodeURIComponent(param);
  } catch {
    return param;
  }
}

/**
 * DELETE /api/teachers/[nickname]
 * Removes the Teacher mapping AND all WeeklySchedule entries that reference
 * this nickname (so the teacher no longer appears anywhere in the system).
 */
export async function DELETE(
  _request: NextRequest,
  { params }: { params: Promise<{ nickname: string }> },
) {
  try {
    const { nickname: raw } = await params;
    const nickname = decodeNicknameParam(raw).trim();

    if (!nickname) {
      return noCacheJson({ error: 'Nickname guru tidak valid' }, 400);
    }

    // Remove all schedule rows that use this teacher nickname
    const deletedSchedules = await db.weeklySchedule.deleteMany({
      where: { teacher: nickname },
    });

    // Remove the Teacher mapping itself
    const deletedTeacher = await db.teacher.deleteMany({
      where: { nickname },
    });

    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson({
      success: true,
      message: `Guru "${nickname}" berhasil dihapus`,
      deletedSchedules: deletedSchedules.count,
      deletedTeacher: deletedTeacher.count,
    });
  } catch (error) {
    console.error('Error deleting teacher:', error);
    return noCacheJson({ error: 'Gagal menghapus data guru' }, 500);
  }
}
