import { noCacheJson } from '@/lib/utils';
import { db } from '@/lib/db';
import { TEACHER_NAME_MAP } from '@/lib/teacher-names';
import { scheduleAutoSync, scheduleGSheetSync, markGSheetDirty } from '@/lib/auto-sync'

export const dynamic = 'force-dynamic';

/**
 * GET /api/teachers
 * Returns all teacher nickname→fullName mappings.
 * Merges:
 *   1. Teacher table (DB-managed, edited via Rombel > Guru tab)
 *   2. Any nicknames found in WeeklySchedule that are not yet in the Teacher
 *      table (auto-created as pending rows so the user can fill the full name)
 *   3. Static fallback map values used to pre-fill new Teacher rows
 */
export async function GET() {
  try {
    // 1. Existing Teacher rows
    const [dbTeachers, schedules] = await Promise.all([
      db.teacher.findMany({ orderBy: { nickname: 'asc' } }),
      db.weeklySchedule.findMany({ select: { teacher: true } }),
    ]);

    // 2. Unique non-empty nicknames currently used in schedules
    const usedNicknames = new Set<string>();
    for (const s of schedules) {
      const t = (s.teacher || '').trim();
      if (t) usedNicknames.add(t);
    }

    // 3. Auto-create Teacher rows for nicknames that are used in schedules but
    //    not yet in the Teacher table (pre-fill with static map when available)
    const existingNicknames = new Set(dbTeachers.map(t => t.nickname));
    const missing = [...usedNicknames].filter(n => !existingNicknames.has(n));
    if (missing.length > 0) {
      await db.teacher.createMany({
        data: missing.map(nickname => ({
          nickname,
          fullName: TEACHER_NAME_MAP[nickname] || '',
        })),
      });
    }

    // Re-fetch after auto-create so the response is always fresh
    const teachers = missing.length > 0
      ? await db.teacher.findMany({ orderBy: { nickname: 'asc' } })
      : dbTeachers;

    // Sort: non-empty fullName first, then alphabetical by nickname
    teachers.sort((a, b) => {
      const aEmpty = !a.fullName.trim();
      const bEmpty = !b.fullName.trim();
      if (aEmpty !== bEmpty) return aEmpty ? 1 : -1;
      return a.nickname.localeCompare(b.nickname);
    });

    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson({ teachers });
  } catch (error) {
    console.error('Error fetching teachers:', error);
    return noCacheJson({ error: 'Gagal mengambil data guru' }, 500);
  }
}

/**
 * POST /api/teachers
 * Bulk upsert teacher nickname→fullName mappings.
 * Body: { teachers: [{ nickname: string, fullName: string }] }
 */
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const incoming = Array.isArray(body?.teachers) ? body.teachers : [];

    if (incoming.length === 0) {
      scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
      return noCacheJson({ success: true, saved: 0, message: 'Tidak ada data untuk disimpan' });
    }

    let saved = 0;
    for (const item of incoming) {
      const nickname = String(item.nickname || '').trim();
      const fullName = String(item.fullName || '').trim();
      if (!nickname) continue;
      await db.teacher.upsert({
        where: { nickname },
        update: { fullName },
        create: { nickname, fullName },
      });
      saved++;
    }

    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson({ success: true, saved, message: `${saved} data guru berhasil disimpan` });
  } catch (error) {
    console.error('Error saving teachers:', error);
    return noCacheJson({ error: 'Gagal menyimpan data guru' }, 500);
  }
}
