import { noCacheJson } from '@/lib/utils'
import { db } from '@/lib/db'
import { scheduleAutoSync, scheduleGSheetSync, markGSheetDirty } from '@/lib/auto-sync'

export async function GET() {
  try {
    const waliKelasList = await db.waliKelas.findMany({
      include: {
        class: {
          select: { id: true, name: true },
        },
      },
      orderBy: { class: { name: 'asc' } },
    })

    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson(waliKelasList)
  } catch (error) {
    console.error('Error fetching wali kelas:', error)
    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson(
      { error: 'Gagal mengambil data wali kelas' },
      500
    )
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json()
    const { classId, name } = body

    if (!classId) {
      scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
      return noCacheJson(
        { error: 'classId diperlukan' },
        400
      )
    }

    const waliKelas = await db.waliKelas.upsert({
      where: { classId },
      update: { name: name || '' },
      create: { classId, name: name || '' },
    })

    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson(waliKelas, 201)
  } catch (error) {
    console.error('Error saving wali kelas:', error)
    scheduleAutoSync(); markGSheetDirty(); scheduleGSheetSync()
    return noCacheJson(
      { error: 'Gagal menyimpan data wali kelas' },
      500
    )
  }
}
