/* ============================================
   Animations
   ============================================ */
@keyframes neon-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.85; }
}
@keyframes neon-flicker {
  0%, 19%, 21%, 23%, 25%, 54%, 56%, 100% { opacity: 1; }
  20%, 24%, 55% { opacity: 0.7; }
}
@keyframes glow-rotate {
  0% { filter: hue-rotate(0deg); }
  100% { filter: hue-rotate(360deg); }
}
@keyframes scanline {
  0% { transform: translateY(-100%); }
  100% { transform: translateY(100vh); }
}
@keyframes border-glow {
  0%, 100% { border-color: #3b82f6; box-shadow: 0 0 2px rgba(59, 130, 246, 0.15); }
  33% { border-color: #7c3aed; box-shadow: 0 0 2px rgba(124, 58, 237, 0.15); }
  66% { border-color: #34d399; box-shadow: 0 0 2px rgba(52, 211, 153, 0.15); }
}
@keyframes sl-border-pulse {
  0%, 100% { border-color: var(--sl-border-glow); }
  50% { border-color: var(--sl-glow-strong); }
}

.animate-neon-pulse { animation: neon-pulse 2s ease-in-out infinite; }

/* Animation off toggle */
.anim-off .c-flow { animation: none !important; stroke-dashoffset: 0; }
.anim-off .animate-neon-pulse { animation: none !important; }
.anim-off .c-glow { display: none; }
.animate-neon-flicker { animation: neon-flicker 3s infinite; }
.animate-glow-rotate { animation: glow-rotate 4s linear infinite; }
.animate-border-glow { animation: border-glow 6s linear infinite; }

/* ============================================
   CIRCUIT BOARD BACKGROUND
   ============================================ */
.circuit-bg {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}
.circuit-bg-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

/* Static circuit traces */
.c-traces path {
  fill: none;
  stroke-width: 1;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.dark .c-traces path {
  stroke: rgba(59, 130, 246, 0.18);
}
.light .c-traces path {
  stroke: rgba(30, 41, 59, 0.12);
}

/* Node pads (hollow) */
.c-nodes circle {
  fill: none;
  stroke-width: 1;
}
.dark .c-nodes circle {
  stroke: rgba(59, 130, 246, 0.25);
}
.light .c-nodes circle {
  stroke: rgba(30, 41, 59, 0.18);
}

/* Via holes (filled) */
.c-via {
  fill: none !important;
}
.dark .c-via {
  stroke: rgba(59, 130, 246, 0.3);
}
.light .c-via {
  stroke: rgba(30, 41, 59, 0.2);
}

/* IC chip footprints */
.c-chips rect,
.c-chips line {
  fill: none;
  stroke-width: 1;
}
.dark .c-chips rect {
  stroke: rgba(59, 130, 246, 0.25);
}
.dark .c-chips line {
  stroke: rgba(59, 130, 246, 0.18);
}
.light .c-chips rect {
  stroke: rgba(30, 41, 59, 0.18);
}
.light .c-chips line {
  stroke: rgba(30, 41, 59, 0.12);
}

/* Animated glow flow — theme-aware colors */
.c-flow {
  fill: none;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 40 600;
  animation: circuit-travel linear infinite;
 will-change: stroke-dashoffset;
}
.dark .c-flow {
  stroke: rgba(147, 197, 253, 0.65);
}
.light .c-flow {
  stroke: rgba(15, 23, 42, 0.5);
}

@keyframes circuit-travel {
  from { stroke-dashoffset: 640; }
  to { stroke-dashoffset: -640; }
}

/* ============================================
   Header SL styling
   ============================================ */
.sl-header {
  backdrop-filter: blur(12px);
  position: relative;
}
.dark .sl-header {
  background: rgba(15, 23, 42, 0.8);
  border-bottom: 1px solid rgba(59, 130, 246, 0.2);
}
.light .sl-header {
  background: rgba(255, 255, 255, 0.85);
  border-bottom: 1px solid rgba(59, 130, 246, 0.15);
}
.sl-header::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--sl-accent-blue), var(--sl-accent-purple), transparent);
  opacity: 0.4;
}

/* ============================================
   SL icon button (header icons)
   ============================================ */
.sl-icon-btn {
  position: relative;
  padding: 6px;
  border-radius: 4px;
  border: 1px solid;
  cursor: pointer;
  transition: all 0.25s ease;
  display: flex;
  align-items: center;
  justify-content: center;
}
@media (min-width: 640px) {
  .sl-icon-btn {
    padding: 8px;
  }
}
.sl-icon-btn:hover {
  box-shadow: 0 0 6px var(--sl-glow-strong);
}
.sl-icon-btn.active {
  box-shadow: 0 0 6px var(--sl-glow-strong);
}

/* ============================================
   Role Selection — SL landing
   ============================================ */
.sl-landing-card {
  position: relative;
  overflow: hidden;
}
.sl-landing-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  z-index: 10;
}
.sl-landing-card:hover {
  transform: translateY(-4px);
  transition: all 0.3s ease;
}

/* ============================================
