   ============================================ */

/* Glossy overlay on SL windows */
.sl-window::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.05) 0%,
    rgba(255, 255, 255, 0.02) 25%,
    transparent 45%
  );
