/* ============================================
   REKAP STATUS TOOLTIP — High contrast
   ============================================ */
.status-tooltip {
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%);
  margin-bottom: 6px;
  padding: 5px 10px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
  font-family: 'Rajdhani', sans-serif;
  white-space: nowrap;
  z-index: 50;
  pointer-events: none;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}
.dark .status-tooltip {
  background: rgba(10, 10, 18, 0.95);
  border: 1px solid rgba(59, 130, 246, 0.3);
  box-shadow: 0 4px 16px rgba(0,0,0,0.5), 0 0 8px rgba(59, 130, 246, 0.1);
  backdrop-filter: blur(8px);
}
.light .status-tooltip {
  background: rgba(255, 255, 255, 0.97);
  border: 1px solid rgba(30, 41, 59, 0.2);
  box-shadow: 0 4px 16px rgba(0,0,0,0.12);
  backdrop-filter: blur(8px);
}
.status-tooltip::after {
  content: '';
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  border: 5px solid transparent;
}
.dark .status-tooltip::after {
  border-top-color: rgba(10, 10, 18, 0.95);
}
.light .status-tooltip::after {
  border-top-color: rgba(255, 255, 255, 0.97);
}
/* ============================================
   LIGHT THEME — IMPROVED CONTRAST
   Fix: text-cyan-300, text-green-400, etc. are
   designed for dark bg. In light theme they're
   too pale. Override with darker, readable colors.
   ============================================ */
.light .text-cyan-300 { color: #0369a1 !important; }
.light .text-cyan-400 { color: #0891b2 !important; }
.light .text-green-300 { color: #047857 !important; }
.light .text-green-400 { color: #059669 !important; }
.light .text-orange-300 { color: #c2410c !important; }
.light .text-orange-400 { color: #ea580c !important; }
.light .text-red-300 { color: #b91c1c !important; }
.light .text-red-400 { color: #dc2626 !important; }
.light .text-fuchsia-300 { color: #86198f !important; }
.light .text-fuchsia-400 { color: #a21caf !important; }
.light .text-yellow-300 { color: #a16207 !important; }
.light .text-yellow-400 { color: #ca8a04 !important; }
.light .text-muted-foreground { color: #475569 !important; }
.light .text-foreground { color: #0f172a !important; }

/* === Additional overrides — comprehensive coverage === */
/* Blue */
.light .text-blue-400 { color: #1d4ed8 !important; }
.light .text-blue-600 { color: #1e40af !important; }
/* Gray — make them darker on light bg so they're readable */
.light .text-gray-400 { color: #64748b !important; }
.light .text-gray-500 { color: #475569 !important; }
.light .text-gray-600 { color: #334155 !important; }
/* Fuchsia */
.light .text-fuchsia-200 { color: #86198f !important; }
/* Orange */
.light .text-orange-200 { color: #c2410c !important; }
/* Red */
.light .text-red-50 { color: #b91c1c !important; }
/* Yellow */
.light .text-yellow-500 { color: #a16207 !important; }

/* Opacity-modified text colors — Tailwind generates separate classes
   for `text-X-300/80` etc., so we need to override them explicitly. */
.light .text-cyan-300\/80 { color: #0369a1 !important; }
.light .text-cyan-400\/60 { color: #0891b2 !important; }
.light .text-cyan-400\/0 { color: transparent !important; }
.light .text-green-300\/80 { color: #047857 !important; }
.light .text-green-400\/60 { color: #059669 !important; }
.light .text-fuchsia-400\/60 { color: #a21caf !important; }
.light .text-fuchsia-400\/70 { color: #a21caf !important; }
.light .text-red-300\/70 { color: #b91c1c !important; }

/* Hover text colors */
.light .hover\:text-cyan-300:hover { color: #0369a1 !important; }
.light .hover\:text-cyan-400:hover { color: #0891b2 !important; }
.light .hover\:text-green-400:hover { color: #059669 !important; }
.light .hover\:text-red-300:hover { color: #b91c1c !important; }
.light .hover\:text-red-50:hover { color: #b91c1c !important; }

/* === Dark backgrounds that clash with light theme ===
   bg-gray-700/50 is the progress bar track;
   bg-gray-800/40-60 are inactive/disabled tab buttons.
   Override with light gray for proper light-theme appearance. */
.light .bg-gray-700\/50 { background-color: rgba(203, 213, 225, 0.6) !important; }
.light .bg-gray-800\/40 { background-color: rgba(241, 245, 249, 0.7) !important; }
.light .bg-gray-800\/50 { background-color: rgba(241, 245, 249, 0.8) !important; }
.light .bg-gray-800\/60 { background-color: rgba(226, 232, 240, 0.9) !important; }
.light .bg-gray-500 { background-color: #94a3b8 !important; }
.light .bg-gray-600 { background-color: #64748b !important; }
.light .border-gray-600\/20 { border-color: rgba(148, 163, 184, 0.4) !important; }
.light .border-gray-600\/30 { border-color: rgba(148, 163, 184, 0.5) !important; }
.light .hover\:bg-gray-800\/60:hover { background-color: rgba(226, 232, 240, 0.9) !important; }

/* Neon card content text in light theme */
.light .neon-card { color: #1e293b; }
.light .neon-card .cyber-body { color: #1e293b; }
.light .neon-card .cyber-heading { color: #0f172a; }
.light .neon-card .cyber-mono { color: #334155; }
.light .neon-card .cyber-subheading { color: #1e293b; }

/* Status tooltip in light theme */
.light .status-tooltip { color: #1e293b !important; background: #ffffff; border: 1px solid #cbd5e1; }

/* Dropdown/popover content in light theme */
.light .neon-popup { color: #1e293b; }
.light .neon-popup .cyber-body { color: #1e293b; }
.light .neon-popup .cyber-mono { color: #334155; }

/* Window title text in light theme */
.light .sl-window-title { color: #1e40af; }
.light .sl-window-status { color: #475569; }

/* Sl-notification text in light theme */
.light .sl-notification { color: #1e293b; }
.light .sl-notification .cyber-body { color: #1e293b; }
.light .sl-notification .cyber-mono { color: #334155; }

/* Sl-dialog text in light theme */
.light .sl-dialog { color: #1e293b; }
.light .sl-dialog .cyber-body { color: #1e293b; }
.light .sl-dialog .cyber-heading { color: #0f172a; }
.light .sl-dialog .cyber-subheading { color: #1e293b; }

/* Window title — use a more visible accent color on light bg */
.light .sl-window-title { color: #1e40af; font-weight: 700; }
.light .sl-text-label { color: #475569 !important; }
.light .sl-text-sub { color: #475569 !important; }

/* Inputs — make placeholder darker on light theme */
.light .sl-input::placeholder { color: #64748b; opacity: 0.9; }
.light .neon-input::placeholder { color: #64748b; opacity: 0.9; }

/* Sl-table on light theme — darker text for readability */
.light .sl-table th { color: #1e40af; }
.light .sl-table td { color: #1e293b; }
.light .sl-tab { color: #475569; }
.light .sl-tab:hover { color: #1e40af; }
.light .sl-tab-active { color: #1e40af; }
.light .sl-sidebar-item { color: #475569; }
.light .sl-sidebar-item:hover { color: #1e293b; }
.light .sl-sidebar-item.active { color: #1e40af; }

/* Progress bar track on light theme — soft gray */
.light .bg-gray-700\/50,
.light .bg-gray-800\/50 {
  background-color: rgba(203, 213, 225, 0.6) !important;
}

/* Tables on light theme — make td text darker for better readability */
.light .neon-table td { color: #1e293b; }
.light .neon-table th { color: #1e40af; }
"},{"path":"src/app/layout.tsx","content":"import type { Metadata } from "next";
import "./globals.css";
import { Toaster } from "@/components/ui/toaster";
import { ThemeProvider } from "next-themes";
import { CircuitBackground } from "@/components/app/CircuitBackground";

export const metadata: Metadata = {
  title: "ABSENSI SISWA MTs Al ISHLAH",
  description: "Sistem Rekap Kehadiran Siswa MTs Al ISHLAH",
};

// Inline script: applies saved card opacity + animation-off BEFORE first paint
// so there's no flash. Background stays at 100% opacity; only card/dialog
// background-colors become transparent per the user's slider preference.
const bgPrefScript = `
(function(){
  try {
    var op = localStorage.getItem('sl-bg-opacity');
    var anim = localStorage.getItem('sl-bg-animation');
    if (anim === 'off') {
      document.documentElement.classList.add('anim-off');
    }
    var val = (op === null) ? 85 : Math.max(0, Math.min(100, parseInt(op, 10) || 85));
    var alpha = (val / 100).toFixed(2);
    var style = document.createElement('style');
    style.id = 'bg-opacity-style';
    style.textContent =
      '.circuit-bg{opacity:1 !important;}' +
      '.dark .neon-card{background-color:rgba(15,23,42,' + alpha + ') !important;}' +
      '.light .neon-card{background-color:rgba(255,255,255,' + alpha + ') !important;}' +
      '.dark .sl-dialog{background-color:rgba(15,23,42,' + alpha + ') !important;}' +
      '.light .sl-dialog{background-color:rgba(255,255,255,' + alpha + ') !important;}' +
      '.dark .sl-notification{background-color:rgba(15,23,42,' + alpha + ') !important;}' +
      '.light .sl-notification{background-color:rgba(255,255,255,' + alpha + ') !important;}';
    document.head.appendChild(style);
  } catch(e){}
})();
`;

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="id" suppressHydrationWarning>
      <head>
        <link rel="preconnect" href="https://fonts.googleapis.com" />
        <link rel="preconnect" href="https://fonts.gstatic.com" crossOrigin="anonymous" />
        <link
          href="https://fonts.googleapis.com/css2?family=Orbitron:wght@400;500;600;700;800;900&family=Share+Tech+Mono&family=Rajdhani:wght@300;400;500;600;700&family=Inter:wght@300;400;500;600;700;800;900&display=swap"
          rel="stylesheet"
        />
        <script dangerouslySetInnerHTML={{ __html: bgPrefScript }} />
      </head>
      <body className="antialiased bg-cyber-bg text-foreground min-h-screen">
        <ThemeProvider attribute="class" defaultTheme="dark" enableSystem={false}>
          <CircuitBackground />
          <div className="relative z-10">
            {children}
          </div>
          <Toaster />
        </ThemeProvider>
      </body>
    </html>
  );
}
"},{"path":"src/app/page.tsx","content":"'use client';

import { useState, useEffect, useCallback, useSyncExternalStore } from 'react';
import { RoleSelection } from '@/components/app/RoleSelection';
import { AppShell } from '@/components/app/AppShell';
import { safeFetchJson } from '@/lib/fetch';

const ROLE_KEY = 'absensi_role';

function getStoredRole(): string | null {
  if (typeof window === 'undefined') return null;
  return localStorage.getItem(ROLE_KEY);
}
function subscribeRole(cb: () => void) {
  window.addEventListener('storage', cb);
  return () => window.removeEventListener('storage', cb);
}

export default function Home() {
  const role = useSyncExternalStore(subscribeRole, getStoredRole, () => null) as 'admin' | 'guru' | null;

  useEffect(() => {
    // Seed classes on mount
    safeFetchJson('/api/classes');
  }, []);

  const handleSelectRole = useCallback((r: 'admin' | 'guru') => {
    localStorage.setItem(ROLE_KEY, r);
    window.dispatchEvent(new Event('storage'));
  }, []);

  const handleLogout = useCallback(() => {
    localStorage.removeItem(ROLE_KEY);
    window.dispatchEvent(new Event('storage'));
  }, []);

  if (!role) {
    return <RoleSelection onSelect={handleSelectRole} />;
  }

  return <AppShell role={role} onLogout={handleLogout} />;
}
"},{"path":"src/components/app/AppShell.tsx","content":"'use client';

import { useState, useEffect, useCallback, useRef, useMemo, useSyncExternalStore } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Home, BookOpen, Globe, ScrollText, Bell, LogOut,
  Menu, X, ChevronRight, CalendarOff, Database, Users,
  Settings, Sun, Moon, Zap, ZapOff, Clock, FileCheck, Droplet, Cloud, Sheet, FileSpreadsheet,
  GitBranch, AlertTriangle
} from 'lucide-react';
import { useTheme } from 'next-themes';
import { ClassData } from './types';
import { safeFetchJson } from '@/lib/fetch';
import { getJakartaToday } from '@/lib/utils';
import { DashboardView } from './DashboardView';
import { RombelView } from './RombelView';
import { ClassView } from './ClassView';
import { CheckAbsensiView } from './CheckAbsensiView';
import { RekapAbsensiGuruView } from './RekapAbsensiGuruView';
import { OnlineBackupSync } from './OnlineBackupSync';
import { HolidayManager } from './HolidayManager';
import { BackupManager } from './BackupManager';
import { PopupShell } from './PopupShell';
import { SyncNotification } from './SyncNotification';
import { GSheetsIntegration } from './GSheetsIntegration';
import { VersiAplikasiView } from './VersiAplikasiView';

const ANIM_KEY = 'sl-bg-animation';
const OPACITY_KEY = 'sl-bg-opacity';

function getAnimPref(): boolean {
  if (typeof window === 'undefined') return true;
  return localStorage.getItem(ANIM_KEY) !== 'off';
}
function subscribeAnimPref(cb: () => void) {
  window.addEventListener('storage', cb);
  return () => window.removeEventListener('storage', cb);
}

/**
 * Card/dialog transparency preference (0-100%). Default 100% (fully opaque
 * cards). The slider lowers the background-color alpha of content surfaces
 * (neon-card, sl-dialog, sl-notification) so the circuit background shows
 * through them. Background (.circuit-bg) always stays at opacity:1.
 */
function getOpacityPref(): number {
  if (typeof window === 'undefined') return 85;
  const raw = localStorage.getItem(OPACITY_KEY);
  if (raw === null) return 85;
  const n = parseInt(raw, 10);
  if (isNaN(n)) return 85;
  return Math.max(0, Math.min(100, n));
}

function applyOpacity(value: number) {
  // Apply alpha to card/dialog background-colors only. Background stays full opacity.
  let style = document.getElementById('bg-opacity-style') as HTMLStyleElement | null;
  if (!style) {
    style = document.createElement('style');
    style.id = 'bg-opacity-style';
    document.head.appendChild(style);
  }
  const alpha = (value / 100).toFixed(2);
  style.textContent =
    '.circuit-bg{opacity:1 !important;}' +
    '.dark .neon-card{background-color:rgba(15,23,42,' + alpha + ') !important;}' +
    '.light .neon-card{background-color:rgba(255,255,255,' + alpha + ') !important;}' +
    '.dark .sl-dialog{background-color:rgba(15,23,42,' + alpha + ') !important;}' +
    '.light .sl-dialog{background-color:rgba(255,255,255,' + alpha + ') !important;}' +
    '.dark .sl-notification{background-color:rgba(15,23,42,' + alpha + ') !important;}' +
    '.light .sl-notification{background-color:rgba(255,255,255,' + alpha + ') !important;}';
}

interface AppShellProps {
  role: 'admin' | 'guru';
  onLogout: () => void;
}

function classIcon(name: string) {
  const n = name.toLowerCase();
  if (n.includes('bahasa')) return Globe;
  if (n.includes('kitab')) return ScrollText;
  return BookOpen;
}

export function AppShell({ role, onLogout }: AppShellProps) {
  const { setTheme, resolvedTheme } = useTheme();
  const isDark = resolvedTheme !== 'light';
  const animOn = useSyncExternalStore(subscribeAnimPref, getAnimPref);
  const [opacity, setOpacityState] = useState<number>(85);

  // Load saved opacity on mount and apply it.
  useEffect(() => {
    const saved = getOpacityPref();
    setOpacityState(saved);
    applyOpacity(saved);
  }, []);

  // Digital clock (Jakarta GMT+7)
  const [clockTime, setClockTime] = useState('');
  useEffect(() => {
    const updateClock = () => {
      const now = new Date();
      const utc = now.getTime() + now.getTimezoneOffset() * 60000;
      const jakarta = new Date(utc + 7 * 3600000);
      const h = String(jakarta.getHours()).padStart(2, '0');
      const m = String(jakarta.getMinutes()).padStart(2, '0');
      const s = String(jakarta.getSeconds()).padStart(2, '0');
      setClockTime(`${h}:${m}:${s}`);
    };
    updateClock();
    const iv = setInterval(updateClock, 1000);
    return () => clearInterval(iv);
  }, []);

  const [currentView, setCurrentView] = useState<string>('dashboard');
  const [pendingTab, setPendingTab] = useState<string | null>(null);
  const [classes, setClasses] = useState<ClassData[]>([]);
  // Shared selectedDate — used by DashboardView AND for fetching notifications
  // so notifications always reflect the date the user is viewing.
  const [selectedDate, setSelectedDate] = useState<string>(() => getJakartaToday());
  const [notificationCount, setNotificationCount] = useState(0);
  const [isRestoring, setIsRestoring] = useState(false);
  const hasFetchedOnce = useRef(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [showMobileMenu, setShowMobileMenu] = useState(false);
  const [showOnlineBackup, setShowOnlineBackup] = useState(false);
  const [showGSheets, setShowGSheets] = useState(false);
  const [showHolidays, setShowHolidays] = useState(false);
  const [showBackup, setShowBackup] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  // Version/rollback status — fetched once on mount so the sidebar can show a
  // tiny status dot next to the "Versi Aplikasi" menu item, and a compact red
  // alert strip can appear at the top of every page if a rollback is detected.
  // (The full banner lives inside the Versi Aplikasi menu, per user request.)
  const [versionStatus, setVersionStatus] = useState<{ rollbackDetected: boolean; version: string; missingFeatures: string[] } | null>(null);
  const [notifications, setNotifications] = useState<{ classId?: string; className?: string; missingHours?: number[]; type?: string; teacherName?: string; classMissing?: { className: string; hours: number[] }[] }[]>([]);

  const notifRef = useRef<HTMLDivElement>(null);
  const notifBtnRef = useRef<HTMLButtonElement>(null);
  const onlineBackupRef = useRef<HTMLDivElement>(null);
  const onlineBackupBtnRef = useRef<HTMLButtonElement>(null);
  const settingsRef = useRef<HTMLDivElement>(null);
  const settingsBtnRef = useRef<HTMLButtonElement>(null);

  // Body scroll lock for mobile menu
  useEffect(() => {
    if (showMobileMenu) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => { document.body.style.overflow = ''; };
  }, [showMobileMenu]);

  // Outside click handlers
  useEffect(() => {
    if (!showNotifications) return;
    const handler = (e: MouseEvent | TouchEvent) => {
      if (notifRef.current && !notifRef.current.contains(e.target as Node) && notifBtnRef.current && !notifBtnRef.current.contains(e.target as Node)) {
        setShowNotifications(false);
      }
    };
    document.addEventListener('mousedown', handler);
    document.addEventListener('touchstart', handler);
    return () => { document.removeEventListener('mousedown', handler); document.removeEventListener('touchstart', handler); };
  }, [showNotifications]);

  useEffect(() => {
    if (!showOnlineBackup) return;
    const handler = (e: MouseEvent | TouchEvent) => {
      if (onlineBackupRef.current && !onlineBackupRef.current.contains(e.target as Node) && onlineBackupBtnRef.current && !onlineBackupBtnRef.current.contains(e.target as Node)) {
        setShowOnlineBackup(false);
      }
    };
    document.addEventListener('mousedown', handler);
    document.addEventListener('touchstart', handler);
    return () => { document.removeEventListener('mousedown', handler); document.removeEventListener('touchstart', handler); };
  }, [showOnlineBackup]);

  useEffect(() => {
    if (!showSettings) return;
    const handler = (e: MouseEvent | TouchEvent) => {
      if (settingsRef.current && !settingsRef.current.contains(e.target as Node) && settingsBtnRef.current && !settingsBtnRef.current.contains(e.target as Node)) {
        setShowSettings(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => { document.removeEventListener('mousedown', handler); };
  }, [showSettings]);

  // ======================== DATA SYNC ========================
  const fetchClassesRef = useRef<() => Promise<void>>();
  const fetchNotificationsRef = useRef<() => Promise<void>>();

  // Fetch classes from DB
  const fetchClasses = useCallback(async () => {
    const data = await safeFetchJson('/api/classes');
    if (data) {
      setClasses(data);
      if (!hasFetchedOnce.current && data.length === 0) {
        hasFetchedOnce.current = true;
        setTimeout(() => triggerAutoRestore(), 500);
      }
      if (data.length > 0) hasFetchedOnce.current = true;
    }
  }, []);

  const fetchNotifications = useCallback(async () => {
    // Use the user-selected date so notifications reflect what they're viewing,
    // not always "today".
    const dateForNotif = selectedDate || getJakartaToday();
    const data = await safeFetchJson(`/api/dashboard?date=${dateForNotif}`, { timeoutMs: 60000 });
    if (data) {
      // Disable notifications on holidays
      if (data.isHoliday) {
        setNotifications([]);
        setNotificationCount(0);
      } else {
        setNotifications(data.notifications || []);
        setNotificationCount(data.notifications?.length || 0);
      }
    }
  }, [selectedDate]);

  // Keep refs updated
  useEffect(() => { fetchClassesRef.current = fetchClasses; }, [fetchClasses]);
  useEffect(() => { fetchNotificationsRef.current = fetchNotifications; }, [fetchNotifications]);

  // ======================== AUTO-RESTORE ========================
  const triggerAutoRestore = useCallback(async () => {
    if (isRestoring) return;
    setIsRestoring(true);
    try {
      console.log('[AppShell] Database kosong, memulai auto-restore...');
      const res = await fetch('/api/auto-restore', { method: 'POST' });
      const result = await res.json();
      if (result.success) {
        console.log('[AppShell] Auto-restore berhasil:', result.message);
        fetchClassesRef.current?.();
        fetchNotificationsRef.current?.();
      } else {
        console.warn('[AppShell] Auto-restore skip:', result.message);
      }
    } catch (e) {
      console.error('[AppShell] Auto-restore error:', e);
    } finally {
      setIsRestoring(false);
    }
  }, [isRestoring]);

  const [notifMode, setNotifMode] = useState<'kelas' | 'guru'>('kelas');
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const data = await safeFetchJson('/api/settings/notification-mode');
      if (!cancelled && data?.mode) setNotifMode(data.mode as 'kelas' | 'guru');
    })();
    return () => { cancelled = true; };
  }, []);

  // Initial load + polling every 15s for classes
  useEffect(() => {
    const poll = () => fetchClasses();
    poll();
    const iv = setInterval(poll, 15000);
    return () => clearInterval(iv);
  }, [fetchClasses]);

  // Poll notifications every 30s
  useEffect(() => {
    const poll = () => fetchNotifications();
    poll();
    const iv = setInterval(poll, 30000);
    return () => clearInterval(iv);
  }, [fetchNotifications]);

  // Fetch version/rollback status once on mount (cheap file-read check).
  // Drives the sidebar status dot + the compact rollback alert strip.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const res = await fetch('/api/app-version', { cache: 'no-store' });
        if (res.ok) {
          const data = await res.json();
          if (!cancelled) setVersionStatus({
            rollbackDetected: !!data.rollbackDetected,
            version: data.version ?? '',
            missingFeatures: data.missingFeatures ?? [],
          });
        }
      } catch {
        // ignore — sidebar dot stays neutral
      }
    })();
    return () => { cancelled = true; };
  }, []);

  // Re-fetch data when switching views (ensures fresh data)
  useEffect(() => {
    const refresh = () => { fetchClasses(); fetchNotifications(); };
    refresh();
  }, [currentView, fetchClasses, fetchNotifications]);

  // ======================== MENU (dynamic from DB) ========================
  const menuItems = useMemo(() => {
    const items: { name: string; icon: typeof Home; view: string }[] = [
      { name: 'Dashboard', icon: Home, view: 'dashboard' },
      { name: 'Check Absensi', icon: FileCheck, view: 'check-absensi' },
      { name: 'Rekap Absensi', icon: FileSpreadsheet, view: 'rekap-absensi' },
    ];
    if (role === 'admin') {
      items.push({ name: 'Rombel', icon: Users, view: 'rombel' });
    }
    for (const cls of classes) {
      items.push({ name: cls.name, icon: classIcon(cls.name), view: cls.name });
    }
    // Always-visible "Versi Aplikasi" menu — the version banner has been moved
    // here per user request so it lives in a dedicated page rather than on
    // every view. Visible to both admin and guru.
    items.push({ name: 'Versi Aplikasi', icon: GitBranch, view: 'versi-aplikasi' });
    return items;
  }, [classes, role]);

  const handleNavigateToClass = useCallback((className: string) => {
    setPendingTab('isi-absensi');
    setCurrentView(className);
  }, []);

  const renderContent = () => {
    if (currentView === 'dashboard') return <DashboardView role={role} classes={classes} onRefreshClasses={fetchClasses} onNavigateToClass={handleNavigateToClass} selectedDate={selectedDate} onSelectedDateChange={setSelectedDate} />;
    if (currentView === 'check-absensi') return <CheckAbsensiView />;
    if (currentView === 'rekap-absensi') return <RekapAbsensiGuruView classes={classes} />;
    if (currentView === 'versi-aplikasi') return <VersiAplikasiView />;
    if (currentView === 'rombel' && role === 'admin') return <RombelView classes={classes} onRefresh={fetchClasses} />;
    const cls = classes.find(c => c.name === currentView);
    if (cls) return <ClassView classData={cls} role={role} onRefreshClasses={fetchClasses} initialTab={pendingTab} />;
    return <DashboardView role={role} classes={classes} onRefreshClasses={fetchClasses} onNavigateToClass={handleNavigateToClass} selectedDate={selectedDate} onSelectedDateChange={setSelectedDate} />;
  };

  const handleNav = (view: string) => {
    setPendingTab(null);
    setCurrentView(view);
    setShowMobileMenu(false);
  };
  const closeAllPanels = () => { setShowNotifications(false); setShowHolidays(false); setShowBackup(false); setShowSettings(false); setShowGSheets(false); };

  const toggleAnim = useCallback(() => {
    const next = !animOn;
    localStorage.setItem(ANIM_KEY, next ? 'on' : 'off');
    document.documentElement.classList.toggle('anim-off', !next);
    window.dispatchEvent(new Event('storage'));
  }, [animOn]);

  const handleOpacityChange = useCallback((value: number) => {
    setOpacityState(value);
    localStorage.setItem(OPACITY_KEY, String(value));
    applyOpacity(value);
  }, []);

  const sidebarNav = (skipViews: string[] = []) => (
    <nav className="p-2 space-y-0.5">
      {menuItems.filter(item => !skipViews.includes(item.view)).map((item) => {
        const Icon = item.icon;
        const active = currentView === item.view;
        const isVersionItem = item.view === 'versi-aplikasi';
        const rollback = versionStatus?.rollbackDetected;
        return (
          <button
            key={item.view}
            onClick={() => handleNav(item.view)}
            className={`sl-sidebar-item w-full flex items-center gap-2.5 px-3 py-2.5 text-sm cyber-body font-medium ${active ? 'active' : ''}`}
          >
            <Icon className={`w-5 h-5 flex-shrink-0 ${active ? 'neon-text-cyan' : ''}`} />
            <span className="flex-1 text-left truncate">{item.name}</span>
            {isVersionItem && (
              <span
                className={`w-2 h-2 rounded-full flex-shrink-0 ${rollback ? 'bg-red-500 animate-pulse' : 'bg-green-400'}`}
                title={rollback ? 'Rollback terdeteksi — klik untuk detail' : 'Versi terbaru aktif'}
                aria-label={rollback ? 'Rollback terdeteksi' : 'Versi terbaru aktif'}
              />
            )}
            {active && <ChevronRight className="w-4 h-4 flex-shrink-0" />}
          </button>
        );
      })}
    </nav>
  );

  const userBadge = () => (
    <div className="p-3 border-t border-[var(--sl-border)]">
      <div className="flex items-center gap-2 p-2 rounded-lg bg-[var(--sl-surface)] border border-[var(--sl-border)]">
        <div className="w-7 h-7 rounded-full flex items-center justify-center text-[10px] font-bold flex-shrink-0" style={{ background: 'linear-gradient(135deg, var(--sl-accent-blue), var(--sl-accent-purple))', color: '#fff' }}>
          {role === 'admin' ? 'A' : 'G'}
        </div>
        <div className="flex-1 min-w-0">
