import { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Database, Download, Upload, X, AlertTriangle, CheckCircle, Loader } from 'lucide-react';

interface BackupManagerProps {
  isOpen: boolean;
  onClose: () => void;
}

interface RestoreResult {
  success: boolean;
  message: string;
  restored?: {
    classes: number;
    students: number;
    attendance: number;
    activities: number;
    holidays: number;
    dateHolidays: number;
    waliKelas: number;
    schedules: number;
    teachers: number;
    settings: number;
  };
}

export function BackupManager({ isOpen, onClose }: BackupManagerProps) {
  const [backupStatus, setBackupStatus] = useState<'idle' | 'backing' | 'done' | 'error'>('idle');
  const [restoreStatus, setRestoreStatus] = useState<'idle' | 'confirming' | 'restoring' | 'done' | 'error'>('idle');
  const [message, setMessage] = useState('');
  const [restoreResult, setRestoreResult] = useState<RestoreResult | null>(null);
  const [lastBackupInfo, setLastBackupInfo] = useState<{ filename: string; size: string; date: string } | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const pendingFileRef = useRef<File | null>(null);

  const handleBackup = async () => {
    setBackupStatus('backing');
    setMessage('');
    try {
      const res = await fetch('/api/backup');
      if (!res.ok) {
        setBackupStatus('error');
        setMessage('Gagal membuat backup');
        return;
      }
      const blob = await res.blob();
      const contentDisposition = res.headers.get('Content-Disposition') || '';
      const filenameMatch = contentDisposition.match(/filename="([^"]+)"/);
      const filename = filenameMatch ? filenameMatch[1] : `backup_${Date.now()}.json`;
      const size = (blob.size / 1024).toFixed(1) + ' KB';
      const date = new Date().toLocaleString('id-ID');

      // Trigger download
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      setBackupStatus('done');
      setLastBackupInfo({ filename, size, date });
      setMessage('Backup berhasil dibuat dan diunduh');
    } catch (e) {
      setBackupStatus('error');
      setMessage('Terjadi kesalahan saat backup');
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.name.endsWith('.json')) {
      setMessage('File harus berformat .json');
      return;
    }
    pendingFileRef.current = file;
    setRestoreStatus('confirming');
    setMessage(`File "${file.name}" dipilih. Klik "Restore" untuk melanjutkan.`);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleRestore = async () => {
    if (!pendingFileRef.current) return;
    setRestoreStatus('restoring');
    setMessage('');

    try {
      const file = pendingFileRef.current;
      const text = await file.text();
      const json = JSON.parse(text);

      if (!json.data || !json.data.classes) {
        setRestoreStatus('error');
        setMessage('Format file backup tidak valid. File harus mengandung data kelas dan siswa.');
        return;
      }

      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 200_000);
      const res = await fetch('/api/backup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(json),
        signal: controller.signal,
      });
      clearTimeout(timeoutId);

      const data = await res.json();

      if (res.ok && data.success) {
