import { useState, useRef, useCallback, useEffect } from 'react';
import {
  Database, Download, Upload, CloudUpload, CloudDownload, Loader2,
  CheckCircle2, XCircle, AlertTriangle, Github, RefreshCw, Trash2, FileCode2,
} from 'lucide-react';
import { safeFetchJson } from '@/lib/fetch';
import { useToast } from '@/hooks/use-toast';

/**
 * BACKUP & PEMULIHAN PANEL (fitur "tombol backup" di menu Versi Aplikasi)
 *
 * Tiga kelompok aksi untuk pencegahan rollback data/versi:
 *
 * 1. BACKUP JSON LOKAL
 *    - Backup/Download JSON  → GET /api/backup  (seluruh isi DB → file .json)
 *    - Restore dari JSON     → POST /api/backup (isi ulang DB dari file .json)
 *
 * 2. SYNC GITHUB (online — pemulihan jika terjadi rollback)
 *    - Sync ke GitHub          → POST /api/online-backup (push chunk backup)
 *    - Pulihkan (diff)         → POST {action:'restore-diff'} — hanya record yang hilang
 *    - Pulihkan penuh          → POST {action:'restore'}    — hapus semua + buat ulang
 *    Konfigurasi repo/token dibaca server-side dari DB settings / upload/github-config.json.
 *
 * 3. BACKUP KODE APLIKASI (versi terakhir — semua kode + konfigurasi)
 *    - Backup Kode ke GitHub   → POST /api/code-backup {action:'backup'}
 *      chunk khusus: code-backup/code-chunk-{N}.json + code-backup/code-meta.json
 *    - Pulihkan Kode dari GitHub → POST /api/code-backup {action:'restore'}
 *      restore HANYA membaca chunk code-backup/* — tidak pernah salah ambil
 *      chunk absensi (backup/chunk-*).
 */

interface SyncProgressInfo {
  current: number;
  total: number;
  percentage: number;
  label: string;
}

interface SyncStatusInfo {
  running: boolean;
  lastResult: { success: boolean; message: string } | null;
  startedAt: string | null;
  progress: SyncProgressInfo | null;
}

interface RestoreResultCounts {
  classes?: number;
  students?: number;
  attendance?: number;
  activities?: number;
  holidays?: number;
  dateHolidays?: number;
  waliKelas?: number;
  schedules?: number;
  teachers?: number;
  settings?: number;
}

interface CodeBackupInfo {
  backedUpAt: string;
  totalChunks: number;
  totalBytes: number;
  fileCount: number;
  appVersion: string;
}

const POLL_INTERVAL_MS = 2000;
const POLL_MAX_MS = 30 * 60 * 1000; // stop polling after 30 minutes (full sync ~326 chunks can take 20+ min)

export function BackupPemulihanPanel({ onDataRestored }: { onDataRestored?: () => void }) {
  const { toast } = useToast();

  // ===== Backup JSON lokal =====
  const [backing, setBacking] = useState(false);
  const [lastBackup, setLastBackup] = useState<{ filename: string; size: string } | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const pendingFileRef = useRef<File | null>(null);
  const [restorePhase, setRestorePhase] = useState<'idle' | 'confirm' | 'busy'>('idle');
  const [restoreMsg, setRestoreMsg] = useState<{ ok: boolean; text: string; counts?: RestoreResultCounts } | null>(null);

  // ===== Sync GitHub =====
  const [ghChecking, setGhChecking] = useState(true);
  const [ghConfigured, setGhConfigured] = useState<boolean | null>(null);
  const [ghRepoLabel, setGhRepoLabel] = useState<string | null>(null);
  const [ghTokenMasked, setGhTokenMasked] = useState<string | null>(null);
  const [ghSyncing, setGhSyncing] = useState(false);
  const [ghPulling, setGhPulling] = useState(false);
  const [ghProgress, setGhProgress] = useState<SyncProgressInfo | null>(null);
  const [ghLastResult, setGhLastResult] = useState<{ success: boolean; message: string } | null>(null);
  const [confirmFullRestore, setConfirmFullRestore] = useState(false);
  const pollTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const pollDeadlineRef = useRef<number>(0);

  // ===== Backup Kode Aplikasi =====
  const [codeChecking, setCodeChecking] = useState(true);
  const [codeInfo, setCodeInfo] = useState<CodeBackupInfo | null>(null);
  const [codeBusy, setCodeBusy] = useState(false);
  const [codeProgress, setCodeProgress] = useState<SyncProgressInfo | null>(null);
  const [codeLastResult, setCodeLastResult] = useState<{ success: boolean; message: string } | null>(null);
  const [confirmCodeRestore, setConfirmCodeRestore] = useState(false);
  const codePollTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const codePollDeadlineRef = useRef<number>(0);

  /** Fetch GitHub config + sync status (no synchronous setState in effect body). */
  const fetchGhStatus = useCallback(async (): Promise<SyncStatusInfo | null> => {
    const data = await safeFetchJson('/api/online-backup', { timeoutMs: 20000 });
    return data ?? null;
  }, []);

  /** Poll sync status while an operation is running (background ops on server). */
  const startPolling = useCallback(() => {
    pollDeadlineRef.current = Date.now() + POLL_MAX_MS;
    const tick = async () => {
      if (Date.now() > pollDeadlineRef.current) {
        setGhSyncing(false);
        setGhPulling(false);
        setGhProgress(null);
        return;
      }
      const st = await fetchGhStatus();
      const info = (st?.syncStatus as SyncStatusInfo | undefined) ?? null;
      if (info?.running) {
        setGhProgress(info.progress ?? null);
        pollTimerRef.current = setTimeout(tick, POLL_INTERVAL_MS);
        return;
      }
      // Operation finished
      setGhSyncing(false);
      setGhPulling(false);
      setGhProgress(null);
      if (info?.lastResult) {
        setGhLastResult(info.lastResult);
        toast({
          title: info.lastResult.success ? 'Operasi GitHub selesai' : 'Operasi GitHub gagal',
          description: info.lastResult.message,
        });
        if (info.lastResult.success && onDataRestored) onDataRestored();
      }
    };
    pollTimerRef.current = setTimeout(tick, POLL_INTERVAL_MS);
  }, [fetchGhStatus, toast, onDataRestored]);

  // Initial load — setState happens in async continuation (React Compiler safe).
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const data = await fetchGhStatus();
        if (cancelled) return;
        if (data) {
          setGhConfigured(!!data.configured);
          if (data.configured) {
            setGhRepoLabel(`${data.owner}/${data.repo} (${data.branch})`);
            setGhTokenMasked(data.tokenMasked || null);
          }
          const st = data.syncStatus as SyncStatusInfo | undefined;
          if (st?.lastResult) setGhLastResult(st.lastResult);
          if (st?.running) {
            setGhProgress(st.progress ?? null);
            setGhSyncing(true); // refined by poll result shortly
            startPolling();
          }
        }
      } catch {
        // ignore — status shows "tidak terbaca"
      }
      if (!cancelled) setGhChecking(false);
    })();
    return () => {
      cancelled = true;
      if (pollTimerRef.current) clearTimeout(pollTimerRef.current);
    };
  }, [fetchGhStatus, startPolling]);

  /** POST an operation to /api/online-backup. Default body = push sync. */
  const ghOperation = useCallback(async (body?: Record<string, unknown>, kind: 'sync' | 'pull' = 'sync') => {
    const data = await safeFetchJson('/api/online-backup', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body ?? {}),
      timeoutMs: 30000,
    });
    if (!data) {
      toast({ title: 'Gagal', description: 'Tidak dapat menghubungi server backup online.', variant: 'destructive' });
      return;
    }
    if (data.success === false && !data.background) {
      setGhLastResult({ success: false, message: data.message || 'Operasi ditolak server.' });
      toast({ title: 'Gagal', description: data.message || 'Operasi gagal dimulai.', variant: 'destructive' });
      return;
    }
    if (kind === 'sync') setGhSyncing(true); else setGhPulling(true);
    setGhProgress(null);
    startPolling();
  }, [startPolling, toast]);

  const handleGhSync = useCallback(() => {
    setGhLastResult(null);
    ghOperation({}, 'sync');
  }, [ghOperation]);

  const handleGhPullDiff = useCallback(() => {
    setGhLastResult(null);
    ghOperation({ action: 'restore-diff' }, 'pull');
  }, [ghOperation]);

  const handleGhPullFull = useCallback(async () => {
    setConfirmFullRestore(false);
    setGhLastResult(null);
    await ghOperation({ action: 'restore' }, 'pull');
  }, [ghOperation]);

  // ===== Backup Kode Aplikasi (chunk khusus code-backup/) =====
  const fetchCodeStatus = useCallback(async (): Promise<{ lastBackup: CodeBackupInfo | null; status: SyncStatusInfo & { operation?: string | null } } | null> => {
    const data = await safeFetchJson('/api/code-backup', { timeoutMs: 20000 });
    return data ?? null;
  }, []);

  const startCodePolling = useCallback(() => {
    codePollDeadlineRef.current = Date.now() + POLL_MAX_MS;
    const tick = async () => {
      if (Date.now() > codePollDeadlineRef.current) {
        setCodeBusy(false);
        setCodeProgress(null);
        return;
      }
      const st = await fetchCodeStatus();
      const info = (st?.status as SyncStatusInfo | undefined) ?? null;
      if (info?.running) {
        setCodeProgress(info.progress ?? null);
        codePollTimerRef.current = setTimeout(tick, POLL_INTERVAL_MS);
        return;
      }
      setCodeBusy(false);
      setCodeProgress(null);
      if (info?.lastResult) {
        setCodeLastResult(info.lastResult);
        toast({
          title: info.lastResult.success ? 'Operasi kode selesai' : 'Operasi kode gagal',
          description: info.lastResult.message,
        });
        // Refresh last-backup info after a successful code backup.
        if (info.lastResult.success) {
          const fresh = await fetchCodeStatus();
          if (fresh?.lastBackup) setCodeInfo(fresh.lastBackup);
        }
      }
    };
    codePollTimerRef.current = setTimeout(tick, POLL_INTERVAL_MS);
  }, [fetchCodeStatus, toast]);

  // Initial code-backup load — setState in async continuation only.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const data = await fetchCodeStatus();
        if (cancelled) return;
        if (data) {
          if (data.lastBackup) setCodeInfo(data.lastBackup);
          const st = data.status as SyncStatusInfo | undefined;
          if (st?.lastResult) setCodeLastResult(st.lastResult);
          if (st?.running) {
            setCodeBusy(true);
            setCodeProgress(st.progress ?? null);
            startCodePolling();
          }
        }
      } catch {
        // ignore
      }
      if (!cancelled) setCodeChecking(false);
    })();
    return () => {
      cancelled = true;
      if (codePollTimerRef.current) clearTimeout(codePollTimerRef.current);
    };
  }, [fetchCodeStatus, startCodePolling]);

  const codeOperation = useCallback(async (action: 'backup' | 'restore') => {
    const data = await safeFetchJson('/api/code-backup', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action }),
      timeoutMs: 30000,
    });
    if (!data) {
      toast({ title: 'Gagal', description: 'Tidak dapat menghubungi server backup kode.', variant: 'destructive' });
      return;
    }
    if (data.success === false && !data.background) {
      setCodeLastResult({ success: false, message: data.message || 'Operasi ditolak server.' });
      toast({ title: 'Gagal', description: data.message || 'Operasi gagal dimulai.', variant: 'destructive' });
      return;
    }
    setCodeBusy(true);
    setCodeProgress(null);
    setCodeLastResult(null);
    startCodePolling();
  }, [startCodePolling, toast]);

  const handleCodeBackup = useCallback(async () => {
    setCodeLastResult(null);
    await codeOperation('backup');
  }, [codeOperation]);

  const handleCodeRestore = useCallback(async () => {
    setConfirmCodeRestore(false);
    setCodeLastResult(null);
    await codeOperation('restore');
  }, [codeOperation]);

  // ===== Backup JSON handlers =====
  const handleBackupDownload = useCallback(async () => {
    setBacking(true);
    try {
      const res = await fetch('/api/backup', { cache: 'no-store' });
      if (!res.ok) throw new Error('HTTP ' + res.status);
      const blob = await res.blob();
      const contentDisposition = res.headers.get('Content-Disposition') || '';
      const filenameMatch = contentDisposition.match(/filename="([^"]+)"/);
      const filename = filenameMatch ? filenameMatch[1] : `backup_absensi_${new Date().toISOString().split('T')[0]}.json`;
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      setLastBackup({ filename, size: (blob.size / 1024 / 1024).toFixed(2) + ' MB' });
      toast({ title: 'Backup berhasil', description: `${filename} (${(blob.size / 1024 / 1024).toFixed(2)} MB) tersimpan.` });
    } catch (e) {
      toast({
        title: 'Backup gagal',
        description: e instanceof Error ? e.message : 'Terjadi kesalahan saat membuat backup.',
        variant: 'destructive',
      });
    }
    setBacking(false);
  }, [toast]);

  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.name.toLowerCase().endsWith('.json')) {
      setRestorePhase('idle');
      setRestoreMsg({ ok: false, text: 'File harus berformat .json' });
      toast({ title: 'File tidak valid', description: 'File harus berformat .json', variant: 'destructive' });
      return;
    }
    pendingFileRef.current = file;
    setRestorePhase('confirm');
    setRestoreMsg({ ok: true, text: `File "${file.name}" siap di-restore. Klik "Ya, Restore" — data saat ini akan DIGANTI dengan isi file.` });
    if (fileInputRef.current) fileInputRef.current.value = '';
  }, [toast]);

  const handleRestoreJson = useCallback(async () => {
    const file = pendingFileRef.current;
    if (!file) return;
    setRestorePhase('busy');
    setRestoreMsg(null);
    try {
      const text = await file.text();
      const json = JSON.parse(text);
      if (!json?.data?.classes || !json?.data?.students) {
        setRestorePhase('idle');
        setRestoreMsg({ ok: false, text: 'Format file backup tidak valid (harus mengandung data kelas & siswa).' });
        return;
      }
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 200_000);
      const res = await fetch('/api/backup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(json),
        signal: controller.signal,
      });
      clearTimeout(timeoutId);
      const data = await res.json().catch(() => null);
      if (res.ok && data?.success) {
        const c: RestoreResultCounts = data.restored || {};
        setRestorePhase('idle');
        setRestoreMsg({
          ok: true,
          text: `Restore berhasil: ${c.classes || 0} kelas, ${c.students || 0} siswa, ${c.attendance || 0} absensi, ${c.teachers || 0} guru, ${c.dateHolidays || 0} libur tanggal.`,
          counts: c,
        });
        pendingFileRef.current = null;
        toast({ title: 'Restore JSON berhasil', description: 'Data di database telah diganti sesuai file backup.' });
        if (onDataRestored) onDataRestored();
      } else {
        setRestorePhase('idle');
        setRestoreMsg({ ok: false, text: data?.error || 'Restore gagal di server.' });
        toast({ title: 'Restore gagal', description: data?.error || 'Periksa format file.', variant: 'destructive' });
      }
    } catch (e) {
      setRestorePhase('idle');
      const msg = e instanceof DOMException && e.name === 'AbortError'
        ? 'Waktu restore habis (file terlalu besar). Coba file backup yang lebih kecil.'
        : 'Terjadi kesalahan saat membaca/mengirim file.';
      setRestoreMsg({ ok: false, text: msg });
      toast({ title: 'Restore gagal', description: msg, variant: 'destructive' });
    }
  }, [toast, onDataRestored]);

  const ghBusy = ghSyncing || ghPulling || ghChecking;
  const anyBusy = ghBusy || codeBusy || codeChecking || backing || restorePhase === 'busy';

  return (
    <div className="neon-card rounded-xl p-4 sm:p-5 space-y-5">
      {/* ===== HEADER ===== */}
      <div className="flex items-center gap-2">
        <Database className="w-4 h-4 text-fuchsia-400 flex-shrink-0" />
        <h3 className="cyber-subheading text-xs sm:text-sm neon-text-cyan">BACKUP &amp; PEMULIHAN</h3>
      </div>
      <p className="cyber-mono text-[10px] sm:text-xs text-muted-foreground leading-relaxed -mt-3">
        Pencegahan rollback: simpan salinan seluruh data (JSON) secara lokal/online, dan pulihkan kembali kapan saja jika data hilang atau tertimpa versi lama.
      </p>

      {/* ===== 1. BACKUP JSON LOKAL ===== */}
      <div className="rounded-lg border border-[var(--sl-border)] bg-[var(--sl-surface)] p-3 sm:p-4 space-y-3">
        <div className="flex items-center gap-1.5">
          <Database className="w-3.5 h-3.5 text-cyan-400 flex-shrink-0" />
          <p className="cyber-subheading text-[11px] sm:text-xs text-cyan-300">BACKUP JSON LOKAL</p>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
          <button
            onClick={() => handleBackupDownload()}
            disabled={backing || restorePhase === 'busy'}
            className="sl-icon-btn min-h-[40px] border-cyan-400/40 bg-cyan-400/5 text-cyan-300 hover:bg-cyan-400/15 flex items-center justify-center gap-2 rounded-lg px-3 py-2 text-[11px] cyber-mono transition-colors disabled:opacity-50 w-full"
            aria-label="Backup dan download JSON"
          >
            {backing ? <Loader2 className="w-3.5 h-3.5 animate-spin flex-shrink-0" /> : <Download className="w-3.5 h-3.5 flex-shrink-0" />}
            <span>{backing ? 'Membuat backup...' : 'Backup / Download JSON'}</span>
          </button>
          <button
            onClick={() => fileInputRef.current?.click()}
            disabled={backing || restorePhase === 'busy'}
            className="sl-icon-btn min-h-[40px] border-amber-400/40 bg-amber-400/5 text-amber-300 hover:bg-amber-400/15 flex items-center justify-center gap-2 rounded-lg px-3 py-2 text-[11px] cyber-mono transition-colors disabled:opacity-50 w-full"
            aria-label="Restore dari file JSON"
          >
            {restorePhase === 'busy' ? <Loader2 className="w-3.5 h-3.5 animate-spin flex-shrink-0" /> : <Upload className="w-3.5 h-3.5 flex-shrink-0" />}
            <span>{restorePhase === 'busy' ? 'Meng-restore...' : 'Restore dari JSON'}</span>
          </button>
        </div>
        <input
          ref={fileInputRef}
          type="file"
          accept=".json,application/json"
          className="hidden"
          onChange={handleFileSelect}
          aria-label="Pilih file backup JSON"
        />
        {lastBackup && (
          <p className="cyber-mono text-[9px] text-muted-foreground flex items-center gap-1">
            <CheckCircle2 className="w-3 h-3 text-green-400 flex-shrink-0" />
            Terakhir diunduh: <span className="text-cyan-300 truncate max-w-[180px] sm:max-w-none">{lastBackup.filename}</span> ({lastBackup.size})
          </p>
        )}
        {restorePhase === 'confirm' && (
          <div className="rounded-lg border-2 border-amber-500/60 bg-amber-500/10 p-3 space-y-2" role="alert">
            <div className="flex items-center gap-1.5">
              <AlertTriangle className="w-3.5 h-3.5 text-amber-400 flex-shrink-0" />
              <p className="cyber-mono text-[10px] text-amber-300 font-bold">KONFIRMASI RESTORE</p>
            </div>
            <p className="cyber-mono text-[9px] text-amber-300/90 leading-relaxed">
              {restoreMsg?.text}
            </p>
            <div className="grid grid-cols-2 gap-2">
              <button
                onClick={() => handleRestoreJson()}
                disabled={restorePhase === 'busy'}
                className="min-h-[40px] rounded-lg border border-amber-400/60 bg-amber-400/15 text-amber-200 hover:bg-amber-400/25 px-3 py-2 cyber-mono text-[11px] font-bold flex items-center justify-center gap-1.5 transition-colors disabled:opacity-50"
              >
                <CheckCircle2 className="w-3.5 h-3.5 flex-shrink-0" /> Ya, Restore
              </button>
              <button
                onClick={() => { setRestorePhase('idle'); pendingFileRef.current = null; setRestoreMsg(null); }}
                className="min-h-[40px] rounded-lg border border-[var(--sl-border)] bg-transparent text-muted-foreground hover:bg-[var(--sl-surface)] px-3 py-2 cyber-mono text-[11px] flex items-center justify-center gap-1.5 transition-colors"
              >
                <XCircle className="w-3.5 h-3.5 flex-shrink-0" /> Batal
              </button>
            </div>
          </div>
