            disabled={anyBusy || !ghConfigured}
            className="sl-icon-btn min-h-[40px] border-green-400/40 bg-green-400/5 text-green-300 hover:bg-green-400/15 flex items-center justify-center gap-2 rounded-lg px-3 py-2 text-[11px] cyber-mono transition-colors disabled:opacity-50 w-full"
            aria-label="Pulihkan hanya data yang hilang dari GitHub"
            title="Ambil dari GitHub hanya record yang belum ada di DB (aman)"
          >
            {ghPulling ? <Loader2 className="w-3.5 h-3.5 animate-spin flex-shrink-0" /> : <CloudDownload className="w-3.5 h-3.5 flex-shrink-0" />}
            <span>{ghPulling ? 'Memulihkan...' : 'Pulihkan (Diff)'}</span>
          </button>
          <button
            onClick={() => setConfirmFullRestore(true)}
            disabled={anyBusy || !ghConfigured}
            className="sl-icon-btn min-h-[40px] border-red-400/40 bg-red-400/5 text-red-300 hover:bg-red-400/15 flex items-center justify-center gap-2 rounded-lg px-3 py-2 text-[11px] cyber-mono transition-colors disabled:opacity-50 w-full"
            aria-label="Pulihkan penuh dari GitHub (hapus semua data lalu buat ulang)"
            title="Hapus seluruh data DB lalu buat ulang dari backup GitHub"
          >
            <Trash2 className="w-3.5 h-3.5 flex-shrink-0" />
            <span>Pulihkan Penuh</span>
          </button>
        </div>

        {/* Progress bar while running */}
        {ghProgress && (
          <div className="rounded-lg border border-cyan-400/30 bg-cyan-400/5 p-2.5 space-y-1.5">
            <div className="flex items-center justify-between gap-2">
              <span className="cyber-mono text-[9px] text-cyan-300 truncate flex-1">{ghProgress.label || 'Memproses...'}</span>
              <span className="cyber-mono text-[9px] neon-text-cyan font-bold flex-shrink-0">{ghProgress.percentage}%</span>
            </div>
            <div className="h-1.5 w-full rounded-full bg-black/40 overflow-hidden">
              <div
                className="h-full bg-cyan-400 transition-all duration-300"
                style={{ width: `${ghProgress.percentage}%`, boxShadow: '0 0 8px rgba(34, 211, 238, 0.5)' }}
              />
            </div>
            <p className="cyber-mono text-[8px] text-muted-foreground">Chunk {ghProgress.current} / {ghProgress.total}</p>
          </div>
        )}

        {/* Full restore confirmation */}
        {confirmFullRestore && (
          <div className="rounded-lg border-2 border-red-500/60 bg-red-500/10 p-3 space-y-2" role="alert">
            <div className="flex items-center gap-1.5">
              <AlertTriangle className="w-3.5 h-3.5 text-red-400 flex-shrink-0" />
              <p className="cyber-mono text-[10px] text-red-300 font-bold">KONFIRMASI PEMULIHAN PENUH</p>
            </div>
            <p className="cyber-mono text-[9px] text-red-300/90 leading-relaxed">
              Seluruh data di database akan DIHAPUS lalu dibuat ulang dari backup GitHub. Data yang belum pernah di-sync akan hilang permanen. Pastikan "Sync ke GitHub" sudah dijalankan sebelumnya.
            </p>
            <div className="grid grid-cols-2 gap-2">
              <button
                onClick={() => handleGhPullFull()}
                className="min-h-[40px] rounded-lg border border-red-400/60 bg-red-400/15 text-red-200 hover:bg-red-400/25 px-3 py-2 cyber-mono text-[11px] font-bold flex items-center justify-center gap-1.5 transition-colors"
              >
                <CheckCircle2 className="w-3.5 h-3.5 flex-shrink-0" /> Ya, Pulihkan Penuh
              </button>
              <button
                onClick={() => setConfirmFullRestore(false)}
                className="min-h-[40px] rounded-lg border border-[var(--sl-border)] bg-transparent text-muted-foreground hover:bg-[var(--sl-surface)] px-3 py-2 cyber-mono text-[11px] flex items-center justify-center gap-1.5 transition-colors"
              >
                <XCircle className="w-3.5 h-3.5 flex-shrink-0" /> Batal
              </button>
            </div>
          </div>
        )}

        {/* Last result */}
        {ghLastResult && (
          <div className={`flex items-start gap-1.5 p-2 rounded-lg border ${ghLastResult.success ? 'border-green-400/40 bg-green-400/5' : 'border-red-400/40 bg-red-400/10'}`}>
            {ghLastResult.success ? <CheckCircle2 className="w-3.5 h-3.5 text-green-400 flex-shrink-0 mt-0.5" /> : <XCircle className="w-3.5 h-3.5 text-red-400 flex-shrink-0 mt-0.5" />}
            <div className="min-w-0 flex-1">
              <p className={`cyber-mono text-[9px] leading-relaxed break-words ${ghLastResult.success ? 'text-green-300' : 'text-red-300'}`}>
                Hasil terakhir: {ghLastResult.message}
              </p>
            </div>
            <RefreshCw
              className="w-3 h-3 text-muted-foreground flex-shrink-0 mt-0.5 cursor-pointer hover:text-cyan-300"
              onClick={() => { setGhLastResult(null); }}
              aria-hidden="true"
            />
          </div>
        )}
      </div>

      {/* ===== 3. BACKUP KODE APLIKASI ===== */}
      <div className="rounded-lg border border-[var(--sl-border)] bg-[var(--sl-surface)] p-3 sm:p-4 space-y-3">
        <div className="flex items-center justify-between gap-2 flex-wrap">
          <div className="flex items-center gap-1.5 min-w-0">
            <FileCode2 className="w-3.5 h-3.5 text-emerald-400 flex-shrink-0" />
            <p className="cyber-subheading text-[11px] sm:text-xs text-emerald-300">BACKUP KODE APLIKASI (GITHUB)</p>
          </div>
          {codeInfo && (
            <span className="cyber-mono text-[8px] sm:text-[9px] font-bold px-1.5 py-0.5 rounded flex-shrink-0 text-emerald-300 bg-emerald-400/10">
              ADA BACKUP KODE
            </span>
          )}
        </div>
        <p className="cyber-mono text-[9px] text-muted-foreground leading-relaxed">
          Backup/restore VERSI APLIKASI — seluruh kode versi terakhir (src, prisma, public, konfigurasi) dikirim ke GitHub dengan chunk khusus <span className="text-emerald-300">code-backup/code-chunk-*.json</span>, sehingga saat dipulihkan tidak pernah tertukar dengan chunk absensi siswa (backup/chunk-*).
        </p>

        {codeInfo ? (
          <div className="rounded-lg border border-emerald-400/30 bg-emerald-400/5 p-2.5">
            <p className="cyber-mono text-[9px] text-emerald-200 leading-relaxed">
              Backup terakhir: <span className="font-bold">{codeInfo.appVersion}</span>
              <br />{codeInfo.fileCount} file · {codeInfo.totalChunks} chunk · {(codeInfo.totalBytes / 1024 / 1024).toFixed(2)} MB · {new Date(codeInfo.backedUpAt).toLocaleString('id-ID')}
            </p>
          </div>
        ) : (
          <p className="cyber-mono text-[9px] text-muted-foreground flex items-center gap-1">
            {codeChecking ? <Loader2 className="w-3 h-3 animate-spin" /> : <AlertTriangle className="w-3 h-3 text-amber-400" />}
            {codeChecking ? 'Memeriksa backup kode di GitHub...' : 'Belum ada backup kode di GitHub — jalankan "Backup Kode ke GitHub" terlebih dahulu.'}
          </p>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
          <button
            onClick={() => handleCodeBackup()}
            disabled={anyBusy || !ghConfigured}
            className="sl-icon-btn min-h-[40px] border-emerald-400/40 bg-emerald-400/5 text-emerald-300 hover:bg-emerald-400/15 flex items-center justify-center gap-2 rounded-lg px-3 py-2 text-[11px] cyber-mono transition-colors disabled:opacity-50 w-full"
            aria-label="Backup kode aplikasi ke GitHub"
            title="Kirim seluruh kode versi terakhir ke GitHub (chunk khusus)"
          >
            {codeBusy ? <Loader2 className="w-3.5 h-3.5 animate-spin flex-shrink-0" /> : <CloudUpload className="w-3.5 h-3.5 flex-shrink-0" />}
            <span>{codeBusy ? 'Backup kode berjalan...' : 'Backup Kode ke GitHub'}</span>
          </button>
          <button
            onClick={() => setConfirmCodeRestore(true)}
            disabled={anyBusy || !ghConfigured || !codeInfo}
            className="sl-icon-btn min-h-[40px] border-fuchsia-400/40 bg-fuchsia-400/5 text-fuchsia-300 hover:bg-fuchsia-400/15 flex items-center justify-center gap-2 rounded-lg px-3 py-2 text-[11px] cyber-mono transition-colors disabled:opacity-50 w-full"
            aria-label="Pulihkan kode aplikasi dari GitHub"
            title="Tulis ulang seluruh kode dari chunk khusus code-backup di GitHub"
          >
            <CloudDownload className="w-3.5 h-3.5 flex-shrink-0" />
