          </button>
        </div>

        {/* Progress bar while running */}
        {codeProgress && (
          <div className="rounded-lg border border-emerald-400/30 bg-emerald-400/5 p-2.5 space-y-1.5">
            <div className="flex items-center justify-between gap-2">
              <span className="cyber-mono text-[9px] text-emerald-300 truncate flex-1">{codeProgress.label || 'Memproses...'}</span>
              <span className="cyber-mono text-[9px] neon-text-cyan font-bold flex-shrink-0">{codeProgress.percentage}%</span>
            </div>
            <div className="h-1.5 w-full rounded-full bg-black/40 overflow-hidden">
              <div
                className="h-full bg-emerald-400 transition-all duration-300"
                style={{ width: `${codeProgress.percentage}%`, boxShadow: '0 0 8px rgba(52, 211, 153, 0.5)' }}
              />
            </div>
          </div>
        )}

        {/* Code restore confirmation */}
        {confirmCodeRestore && (
          <div className="rounded-lg border-2 border-fuchsia-500/60 bg-fuchsia-500/10 p-3 space-y-2" role="alert">
            <div className="flex items-center gap-1.5">
              <AlertTriangle className="w-3.5 h-3.5 text-fuchsia-400 flex-shrink-0" />
              <p className="cyber-mono text-[10px] text-fuchsia-300 font-bold">KONFIRMASI PEMULIHAN KODE</p>
