        {/* Last result */}
        {codeLastResult && (
          <div className={`flex items-start gap-1.5 p-2 rounded-lg border ${codeLastResult.success ? 'border-green-400/40 bg-green-400/5' : 'border-red-400/40 bg-red-400/10'}`}>
            {codeLastResult.success ? <CheckCircle2 className="w-3.5 h-3.5 text-green-400 flex-shrink-0 mt-0.5" /> : <XCircle className="w-3.5 h-3.5 text-red-400 flex-shrink-0 mt-0.5" />}
            <div className="min-w-0 flex-1">
              <p className={`cyber-mono text-[9px] leading-relaxed break-words ${codeLastResult.success ? 'text-green-300' : 'text-red-300'}`}>
                Hasil terakhir: {codeLastResult.message}
              </p>
            </div>
            <RefreshCw
              className="w-3 h-3 text-muted-foreground flex-shrink-0 mt-0.5 cursor-pointer hover:text-cyan-300"
              onClick={() => { setCodeLastResult(null); }}
              aria-hidden="true"
            />
          </div>
        )}
      </div>
    </div>
  );
}
"},{"path":"src/components/app/CheckAbsensiView.tsx","content":"'use client';

import { useState, useEffect, useMemo, Fragment, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, Cell } from 'recharts';
import { CheckCircle, XCircle, Calendar as CalendarIcon, BarChart3, AlertTriangle, RefreshCw, Users, Search, Download, Printer, Eye, FileSpreadsheet, X } from 'lucide-react';
import { CheckAbsensiData, AttendanceCompletenessData } from './types';
import { safeFetchJson } from '@/lib/fetch';
import { getJakartaToday, formatDateJakarta } from '@/lib/utils';
import { CyberCalendar } from './CyberCalendar';

interface RekapGuruEntry {
  fullName: string;
  classId: string;
  className: string;
  hours: number[];
}
interface DayTable {
  date: string;
  dayName: string;
  formattedDate: string;
  teachers: RekapGuruEntry[];
}
type RekapGuruEntryWithDate = RekapGuruEntry & { date: string; dayName: string; formattedDate: string };
interface TeacherGroup {
  fullName: string;
  totalMissed: number;
  entries: RekapGuruEntryWithDate[];
}
interface RekapGuruData {
  mode: 'week' | 'month' | 'range';
  groupBy: 'date' | 'teacher';
  date: string;
  windowStart: string;
  windowEnd: string;
  totalSchoolDays: number;
  days?: DayTable[];
  teachers?: TeacherGroup[];
}

interface CariResult {
  date: string;
  dayName: string;
  formattedDate: string;
  className: string;
  hours: number[];
}
interface CariGuruData {
  results: CariResult[];
  query: string;
  teacherName: string;
  teacherNickname: string;
  totalMissed: number;
}

function getBarColor(percentage: number): string {
  if (percentage >= 100) return 'var(--color-hadir)';
  if (percentage >= 75) return 'var(--color-terlambat)';
  if (percentage >= 50) return '#f59e0b';
  if (percentage > 0) return 'var(--color-alfa)';
  return '#374151';
}

// Escape user-provided strings before injecting into the printable HTML window.
// Prevents XSS in the print preview (e.g., a teacher name with HTML characters).
function escapeHtml(s: string): string {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function CompletenessTooltip({ active, payload, label }: { active?: boolean; payload?: Array<{ payload: { percentage: number; totalScheduled: number; totalFilled: number } }>; label?: string }) {
  if (!active || !payload?.length) return null;
  const d = payload[0].payload;
  return (
    <div className="sl-dialog p-0 overflow-hidden" style={{ minWidth: 150 }}>
      <div className="sl-window-title">
        <div className="sl-window-dots"><span /><span /><span /></div>
        <span className="flex-1 text-center text-[10px] cyber-subheading neon-text-cyan">{label}</span>
        <div className="w-[42px]" />
      </div>
      <div className="p-2 space-y-1">
        <div className="flex items-center justify-between gap-3">
          <span className="cyber-mono text-[10px] text-muted-foreground">Kelengkapan</span>
          <span className={`cyber-mono text-[10px] font-bold ${d.percentage >= 100 ? 'text-green-400' : d.percentage >= 50 ? 'text-orange-300' : 'text-red-400'}`}>{d.percentage}%</span>
        </div>
        <div className="flex items-center justify-between gap-3">
          <span className="cyber-mono text-[10px] text-muted-foreground">Terisi</span>
          <span className="cyber-mono text-[10px] font-bold text-cyan-300">{d.totalFilled}/{d.totalScheduled} jam</span>
        </div>
      </div>
    </div>
  );
}

export function CheckAbsensiView() {
  const [activeTab, setActiveTab] = useState<'hari-ini' | 'rekap-guru' | 'cari'>('hari-ini');
  const [selectedDate, setSelectedDate] = useState(() => getJakartaToday());

  const tabItems = [
    { key: 'hari-ini' as const, label: 'Hari Ini', icon: CalendarIcon },
    { key: 'rekap-guru' as const, label: 'Rekap Guru', icon: Users },
    { key: 'cari' as const, label: 'Cari', icon: Search },
  ];

  return (
    <div className="space-y-4 sm:space-y-6">
      {/* Tab selector */}
      <div className="flex gap-1 p-1 rounded-lg bg-[var(--sl-surface)] border border-[var(--sl-border)]">
        {tabItems.map(tab => {
          const Icon = tab.icon;
          const isActive = activeTab === tab.key;
          return (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={`flex-1 flex items-center justify-center gap-1.5 px-3 py-2.5 sm:py-2 rounded-md text-xs font-medium transition-all min-h-[44px] sm:min-h-[40px] ${
                isActive
                  ? 'bg-fuchsia-500/20 text-fuchsia-300 border border-fuchsia-400/30'
                  : 'text-muted-foreground hover:text-foreground hover:bg-[var(--sl-glow-strong)]'
              }`}
            >
              <Icon className="w-3.5 h-3.5" />
              <span className="hidden sm:inline">{tab.label}</span>
              <span className="sm:hidden">{tab.label.split(' ')[0]}</span>
            </button>
          );
        })}
      </div>

      {activeTab === 'hari-ini' ? (
        <HariIniContent selectedDate={selectedDate} setSelectedDate={setSelectedDate} />
      ) : activeTab === 'rekap-guru' ? (
        <RekapGuruContent selectedDate={selectedDate} setSelectedDate={setSelectedDate} />
      ) : (
        <CariGuruContent selectedDate={selectedDate} setSelectedDate={setSelectedDate} />
      )}
    </div>
  );
}

// ======================== HARI INI (existing check-absensi view) ========================
