                    </div>
                  </motion.div>
                </>
              )}
            </AnimatePresence>
          </div>
        </div>
      </div>

      {/* Holiday notice */}
      {data?.isHoliday && (
        <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} className="neon-card rounded-xl p-4 border border-fuchsia-400/30 bg-fuchsia-400/5">
          <div className="flex items-start gap-3">
            <AlertTriangle className="w-5 h-5 text-fuchsia-400 flex-shrink-0 mt-0.5" />
            <div className="flex-1 min-w-0">
              <h3 className="cyber-subheading text-sm neon-text-magenta">HARI LIBUR — {data.holidayName || 'Tidak Diketahui'}</h3>
