      {/* Summary badges */}
      {!loading && data && !data.isHoliday && (
        <div className="flex items-center justify-center sm:justify-start gap-3">
          <div className="flex items-center gap-1.5 px-3 py-2 rounded-lg border border-green-400/30 bg-green-400/10">
            <CheckCircle className="w-4 h-4 text-green-400" />
            <span className="cyber-subheading text-xs neon-text-green">Lengkap: {completeCount}</span>
          </div>
          <div className="flex items-center gap-1.5 px-3 py-2 rounded-lg border border-orange-400/30 bg-orange-400/10">
            <XCircle className="w-4 h-4 text-orange-400" />
            <span className="cyber-subheading text-xs neon-text-orange">Belum: {incompleteCount}</span>
