        <div className="hidden sm:grid sm:grid-cols-[32px_1fr_100px] items-center gap-3 mb-4">
          <span />
          <h3 className="cyber-subheading text-sm neon-text-cyan">DAFTAR GURU</h3>
          <div className="flex justify-center">
            {!loading && data && data.teachers.length > 0 && !data.isHoliday && (
