            {loading && <RefreshCw className="w-4 h-4 animate-spin text-muted-foreground" />}
          </div>
        </div>
        {/* Mobile header */}
        <div className="sm:hidden grid grid-cols-[24px_1fr_36px] items-center gap-2 mb-4">
          <span />
          <h3 className="cyber-subheading text-sm neon-text-cyan">DAFTAR GURU</h3>
          <div className="flex justify-center">
