            {data.isHoliday ? 'Hari libur — tidak ada jadwal' : 'Tidak ada jadwal guru pada hari ini'}
          </div>
        ) : (
          <div className="max-h-96 overflow-y-auto custom-scrollbar">
            {data?.teachers.map((teacher, idx) => (
