// ======================== REKAP GURU (week / month / range, grouped by date or teacher) ========================
const REKAP_MONTHS = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];

const REKAP_MODES: { key: 'week' | 'month' | 'range'; label: string }[] = [
  { key: 'week', label: 'Per Minggu' },
  { key: 'month', label: 'Per Bulan' },
  { key: 'range', label: 'Per Rentang' },
];

// Format a YYYY-MM-DD string as "D MMMM YYYY" (client-side, for preview + print).
function formatIndoDateStr(dateStr: string): string {
  const [y, m, d] = dateStr.split('-').map(Number);
  return `${d} ${REKAP_MONTHS[m - 1]} ${y}`;
}

function RekapGuruContent({ selectedDate, setSelectedDate }: { selectedDate: string; setSelectedDate: (d: string) => void }) {
  const [data, setData] = useState<RekapGuruData | null>(null);
  const [loading, setLoading] = useState(true);
  const [showCalendar, setShowCalendar] = useState(false);
  const [mode, setMode] = useState<'week' | 'month' | 'range'>('week');
  const [groupBy, setGroupBy] = useState<'date' | 'teacher'>('date');
  const [selMonth, setSelMonth] = useState(() => new Date(selectedDate + 'T00:00:00').getMonth() + 1);
  const [selYear, setSelYear] = useState(() => String(new Date(selectedDate + 'T00:00:00').getFullYear()));
  const [rangeStart, setRangeStart] = useState(selectedDate);
  const [rangeEnd, setRangeEnd] = useState(selectedDate);
  const [refreshKey, setRefreshKey] = useState(0);
  const [showPreview, setShowPreview] = useState(false);

  // API query follows the active period mode + grouping
  const apiUrl = useMemo(() => {
    if (mode === 'month') {
      return `/api/check-absensi/rekap-guru?mode=month&month=${selMonth}&year=${selYear}&groupBy=${groupBy}`;
    }
    if (mode === 'range') {
      return `/api/check-absensi/rekap-guru?mode=range&startDate=${rangeStart}&endDate=${rangeEnd}&groupBy=${groupBy}`;
    }
    return `/api/check-absensi/rekap-guru?date=${selectedDate}&groupBy=${groupBy}`;
  }, [mode, selMonth, selYear, rangeStart, rangeEnd, groupBy, selectedDate]);

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      setLoading(true);
      const result = await safeFetchJson(apiUrl);
      if (!cancelled) {
        if (result) setData(result);
        setLoading(false);
      }
    };
    load();
    return () => { cancelled = true; };
  }, [apiUrl, refreshKey]);

  // Derived: does the current window contain any missing-attendance entries?
  const hasRekapData = !!data && (
    groupBy === 'teacher'
      ? !!data.teachers && data.teachers.length > 0
      : !!data.days && data.days.some(d => d.teachers.length > 0)
  );

  // Period label shared by the preview modal + print header.
  const periodText = useMemo(() => {
    if (mode === 'month') return `${REKAP_MONTHS[selMonth - 1]} ${selYear}`;
    if (data) return `${formatIndoDateStr(data.windowStart)} s/d ${formatIndoDateStr(data.windowEnd)}`;
    return '';
  }, [mode, selMonth, selYear, data]);

  // Shared query params for the PDF / Excel export endpoints — groupBy is
  // ALWAYS included so the downloaded filter matches the Kelompok selector:
  // - Per Guru    → dikelompokkan berdasarkan NAMA GURU (tabel: TANGGAL | KELAS | JAM)
  // - Per Tanggal → dikelompokkan berdasarkan TANGGAL (tabel: NAMA GURU | KELAS | JAM)
  const exportQuery = useMemo(() => {
    const pad = (n: number) => String(n).padStart(2, '0');
    if (mode === 'month') return { query: `mode=month&month=${selMonth}&year=${selYear}`, fileBase: `Rekap_Guru_${selYear}-${pad(selMonth)}` };
    if (mode === 'range') return { query: `mode=range&startDate=${rangeStart}&endDate=${rangeEnd}`, fileBase: `Rekap_Guru_${rangeStart}_sd_${rangeEnd}` };
    // week: compute the 7-day window (windowStart = selectedDate - 6 days)
    // so the downloaded filename matches the server's naming convention.
    const endD = new Date(selectedDate + 'T00:00:00');
    const startD = new Date(endD);
    startD.setDate(endD.getDate() - 6);
    const windowStart = `${startD.getFullYear()}-${pad(startD.getMonth() + 1)}-${pad(startD.getDate())}`;
    return { query: `date=${selectedDate}`, fileBase: `Rekap_Guru_${windowStart}_sd_${selectedDate}` };
  }, [mode, selMonth, selYear, rangeStart, rangeEnd, selectedDate]);

  const handleDownloadPdf = useCallback(() => {
    const groupSuffix = groupBy === 'teacher' ? '_Per_Guru' : '';
    const link = document.createElement('a');
    link.href = `/api/recap/rekap-guru-pdf?${exportQuery.query}&groupBy=${groupBy}`;
    link.download = `${exportQuery.fileBase}${groupSuffix}.pdf`;
    link.click();
  }, [exportQuery, groupBy]);

  const handleDownloadExcel = useCallback(() => {
    const groupSuffix = groupBy === 'teacher' ? '_Per_Guru' : '';
