    let sectionsHtml = '';
    if (groupBy === 'teacher' && data.teachers) {
      sectionsHtml = data.teachers.map(group => `
        <div class="section">
          <div class="group-title">Nama Guru: ${escapeHtml(group.fullName)}</div>
          <div class="group-sub">Total ${group.totalMissed} jam belum diisi</div>
          <table>
            <thead><tr><th style="width:40px;">NO</th><th style="width:190px;">TANGGAL</th><th style="width:110px;">KELAS</th><th>JAM KE-</th></tr></thead>
