              ${group.entries.map((e, idx) => `
                <tr>
                  <td style="text-align:center;">${idx + 1}</td>
                  <td>${escapeHtml(e.formattedDate)}</td>
                  <td style="text-align:center;">${escapeHtml(e.className)}</td>
                  <td style="text-align:center;">${e.hours.map(h => hourBadge(h)).join(' ')}</td>
                </tr>`).join('')}
            </tbody>
          </table>
        </div>`).join('');
    } else if (data.days) {
      sectionsHtml = data.days.filter(d => d.teachers.length > 0).map(day => `
        <div class="section">
          <div class="group-title">Rekap Guru Hari ${escapeHtml(day.dayName)}, Tanggal ${escapeHtml(formatIndoDateStr(day.date))}</div>
          <div class="group-sub">${day.teachers.length} entri</div>
          <table>
            <thead><tr><th style="width:40px;">NO</th><th style="width:200px;">NAMA GURU</th><th style="width:110px;">KELAS</th><th>JAM KE-</th></tr></thead>
            <tbody>
              ${day.teachers.map((t, idx) => `
                <tr>
                  <td style="text-align:center;">${idx + 1}</td>
                  <td>${escapeHtml(t.fullName)}</td>
                  <td style="text-align:center;">${escapeHtml(t.className)}</td>
                  <td style="text-align:center;">${t.hours.map(h => hourBadge(h)).join(' ')}</td>
                </tr>`).join('')}
            </tbody>
          </table>
        </div>`).join('');
    }
    if (!sectionsHtml) return;

    const html = `<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Cetak - REKAP GURU ${groupLabel}</title>
  <style>
    * { box-sizing: border-box; }
    body { font-family: 'Times New Roman', serif; margin: 24px; color: #000; }
    h1 { text-align: center; font-size: 16px; margin: 0 0 4px 0; text-transform: uppercase; letter-spacing: 0.5px; }
    h2 { text-align: center; font-size: 13px; margin: 0 0 4px 0; font-weight: bold; }
    h3 { text-align: center; font-size: 12px; margin: 0 0 16px 0; font-weight: normal; }
    .section { margin-bottom: 18px; }
    .group-title { font-size: 13px; font-weight: bold; margin-bottom: 2px; }
    .group-sub { font-size: 11px; color: #555; margin-bottom: 6px; font-style: italic; }
    table { width: 100%; border-collapse: collapse; font-size: 12px; }
    th, td { border: 1px solid #000; padding: 6px 8px; vertical-align: middle; }
    th { background: #e5e5e5; font-weight: 600; text-align: center; }
    .footer { margin-top: 20px; font-size: 11px; color: #444; text-align: right; }
    @media print {
      body { margin: 12mm; }
      .no-print { display: none; }
    }
    .toolbar { text-align: right; margin-bottom: 12px; }
    .toolbar button {
      padding: 6px 14px; font-size: 12px; cursor: pointer;
      background: #0891b2; color: white; border: none; border-radius: 4px;
    }
  </style>
</head>
<body>
  <div class="toolbar no-print">
    <button onclick="window.print()">Cetak Sekarang</button>
  </div>
  <h1>REKAP GURU BELUM MENGISI ABSENSI SISWA</h1>
  <h2>KELOMPOK ${groupLabel}</h2>
  <h3>PERIODE ${escapeHtml(periodText)}</h3>
  ${sectionsHtml}
  <div class="footer">Dicetak: ${new Date().toLocaleString('id-ID', { dateStyle: 'full', timeStyle: 'short' })}</div>
  <script>
    // Auto-trigger print dialog after the document loads
    window.addEventListener('load', function() {
      setTimeout(function() { window.print(); }, 300);
    });
  </script>
</body>
</html>`;

    const printWin = window.open('', '_blank', 'width=900,height=700');
    if (!printWin) {
      alert('Popup diblokir. Mohon izinkan popup untuk mencetak.');
      return;
    }
    printWin.document.open();
    printWin.document.write(html);
    printWin.document.close();
  }, [data, groupBy, hasRekapData, periodText]);

  return (
