// ======================== CARI GURU (search by name, within 1 month) ========================
const CARI_MONTHS = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];

function CariGuruContent({ selectedDate, setSelectedDate }: { selectedDate: string; setSelectedDate: (d: string) => void }) {
  const [searchQuery, setSearchQuery] = useState('');
  const [searchInput, setSearchInput] = useState('');
  const [data, setData] = useState<CariGuruData | null>(null);
  const [loading, setLoading] = useState(false);
  const [searched, setSearched] = useState(false);

  const selDateObj = new Date(selectedDate + 'T00:00:00');
  const [cariMonth, setCariMonth] = useState(String(selDateObj.getMonth() + 1));
  const [cariYear, setCariYear] = useState(String(selDateObj.getFullYear()));

  const handleSearch = useCallback(async () => {
    const q = searchInput.trim();
    if (!q) return;
    setSearchQuery(q);
    setLoading(true);
    setSearched(true);
    const dateForApi = `${cariYear}-${cariMonth.padStart(2, '0')}-01`;
    const result = await safeFetchJson(`/api/check-absensi/cari-guru?query=${encodeURIComponent(q)}&date=${dateForApi}`);
    if (result) setData(result);
    else setData(null);
    setLoading(false);
  }, [searchInput, cariMonth, cariYear]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleSearch();
  };

  // Print the current search results as a printable table view.
  // Opens a new window with a clean print-friendly HTML layout, then triggers
  // window.print() automatically. The header includes the selected month/year
  // in the format "REKAP GURU YANG BELUM MENGISI ABSENSI SISWA PERIODE [BULAN] [YEAR]".
  const handlePrint = useCallback(() => {
    if (!data || data.results.length === 0) return;
    const monthName = CARI_MONTHS[parseInt(cariMonth) - 1] || '';
    const periodLabel = `${monthName} ${cariYear}`;
    const teacherLabel = data.teacherName || data.teacherNickname || searchQuery || '-';

    // Build printable HTML
    const rowsHtml = data.results.map((r, idx) => `
      <tr>
        <td style="text-align:center;font-weight:600;">${idx + 1}</td>
        <td>${escapeHtml(r.formattedDate)}</td>
        <td style="text-align:center;">${escapeHtml(r.className)}</td>
        <td style="text-align:center;">${r.hours.map(h => `<span style="display:inline-block;padding:2px 8px;margin:2px;border:1px solid #b91c1c;background:#fee2e2;color:#b91c1c;border-radius:4px;font-size:11px;">Jam ${h}</span>`).join(' ')}</td>
      </tr>
    `).join('');

    const html = `<!DOCTYPE html>
<html lang="id">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Cetak - REKAP GURU PERIODE ${periodLabel}</title>
  <style>
    * { box-sizing: border-box; }
    body { font-family: 'Times New Roman', serif; margin: 24px; color: #000; }
    h1 { text-align: center; font-size: 16px; margin: 0 0 4px 0; text-transform: uppercase; letter-spacing: 0.5px; }
    h2 { text-align: center; font-size: 13px; margin: 0 0 18px 0; font-weight: normal; }
    .meta { margin: 0 0 14px 0; font-size: 12px; display: flex; justify-content: space-between; }
    .meta strong { font-weight: 600; }
    table { width: 100%; border-collapse: collapse; font-size: 12px; }
    th, td { border: 1px solid #000; padding: 6px 8px; vertical-align: middle; }
    th { background: #e5e5e5; font-weight: 600; text-align: center; }
    td:nth-child(1) { width: 40px; }
    td:nth-child(3) { width: 120px; }
    .footer { margin-top: 20px; font-size: 11px; color: #444; text-align: right; }
    @media print {
      body { margin: 12mm; }
      .no-print { display: none; }
    }
    .toolbar { text-align: right; margin-bottom: 12px; }
    .toolbar button {
      padding: 6px 14px; font-size: 12px; cursor: pointer;
      background: #0891b2; color: white; border: none; border-radius: 4px;
    }
  </style>
</head>
<body>
  <div class="toolbar no-print">
    <button onclick="window.print()">Cetak Sekarang</button>
  </div>
  <h1>REKAP GURU YANG BELUM MENGISI ABSENSI SISWA</h1>
  <h2>PERIODE ${escapeHtml(periodLabel)}</h2>
  <div class="meta">
    <span><strong>Nama Guru:</strong> ${escapeHtml(teacherLabel)}</span>
    <span><strong>Total Entri Belum Diisi:</strong> ${data.totalMissed}</span>
  </div>
  <table>
    <thead>
      <tr>
        <th>NO</th>
        <th>HARI / TANGGAL</th>
        <th>KELAS</th>
        <th>JAM BELUM DIISI</th>
      </tr>
    </thead>
    <tbody>
      ${rowsHtml}
    </tbody>
  </table>
  <div class="footer">Dicetak: ${new Date().toLocaleString('id-ID', { dateStyle: 'full', timeStyle: 'short' })}</div>
  <script>
    // Auto-trigger print dialog after the document loads
    window.addEventListener('load', function() {
      setTimeout(function() { window.print(); }, 300);
    });
  </script>
</body>
</html>`;

    const printWin = window.open('', '_blank', 'width=900,height=700');
    if (!printWin) {
      alert('Popup diblokir. Mohon izinkan popup untuk mencetak.');
      return;
    }
    printWin.document.open();
    printWin.document.write(html);
    printWin.document.close();
  }, [data, cariMonth, cariYear, searchQuery]);

  return (
    <div className="space-y-4 sm:space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 sm:gap-3">
        <div className="flex items-center gap-2 sm:gap-3 min-w-0">
          <div className="min-w-0">
            <h2 className="cyber-heading text-xl sm:text-2xl md:text-3xl neon-text-magenta">CARI GURU</h2>
            <p className="cyber-mono text-[10px] sm:text-xs text-muted-foreground mt-1 truncate">Cari guru yang belum mengisi absensi dalam 1 bulan</p>
          </div>
        </div>
      </div>

      <div className="neon-card rounded-xl p-4 space-y-3">
        <div className="flex flex-wrap items-end gap-2 justify-center sm:justify-start">
          <div>
            <label className="cyber-mono text-[10px] text-muted-foreground uppercase block mb-1">Bulan</label>
            <select value={cariMonth} onChange={(e) => setCariMonth(e.target.value)} className="neon-input px-2.5 py-2 rounded-lg text-xs min-h-[40px]">
              {CARI_MONTHS.map((m, i) => (<option key={i} value={String(i + 1)}>{m}</option>))}
            </select>
          </div>
          <div>
            <label className="cyber-mono text-[10px] text-muted-foreground uppercase block mb-1">Tahun</label>
            <select value={cariYear} onChange={(e) => setCariYear(e.target.value)} className="neon-input px-2.5 py-2 rounded-lg text-xs min-h-[40px]">
              {[2025, 2026, 2027].map(y => (<option key={y} value={String(y)}>{y}</option>))}
            </select>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <input type="text" value={searchInput} onChange={(e) => setSearchInput(e.target.value)} onKeyDown={handleKeyDown} placeholder="Ketik nama guru (panggilan atau lengkap)..." className="neon-input flex-1 px-3 py-2 rounded-lg text-sm" autoFocus />
          <button onClick={handleSearch} disabled={loading || !searchInput.trim()} className="neon-btn-cyan px-4 py-2 rounded-lg text-xs flex items-center justify-center gap-1.5 min-h-[40px] disabled:opacity-40 disabled:cursor-not-allowed">
            {loading ? <RefreshCw className="w-3.5 h-3.5 animate-spin" /> : <Search className="w-3.5 h-3.5" />}
            <span className="hidden sm:inline">Cari</span>
          </button>
        </div>
        <p className="cyber-mono text-[10px] text-muted-foreground mt-2 text-center">Pencarian dalam bulan {CARI_MONTHS[parseInt(cariMonth) - 1]} {cariYear} (hari libur dikecualikan)</p>
      </div>

      {loading ? (
        <div className="neon-card rounded-xl p-12 h-40 flex items-center justify-center">
          <div className="cyber-mono text-sm text-muted-foreground animate-neon-pulse">MENCARI DATA...</div>
        </div>
      ) : searched && data ? (
        data.results.length === 0 ? (
          <div className="neon-card rounded-xl p-8 text-center">
            {data.teacherName ? (
              <><CheckCircle className="w-8 h-8 text-green-400 mx-auto mb-3" /><p className="cyber-body text-sm text-green-400 font-medium">{data.teacherName} sudah mengisi semua absensi minggu ini.</p></>
            ) : (
              <><AlertTriangle className="w-8 h-8 text-orange-400 mx-auto mb-3" /><p className="cyber-body text-sm text-muted-foreground">Guru &ldquo;{searchQuery}&rdquo; tidak ditemukan atau tidak memiliki jadwal mengajar.</p></>
            )}
          </div>
        ) : (
          <div className="neon-card rounded-xl p-4 md:p-6">
            <div className="flex items-center justify-between gap-2 mb-4 flex-wrap">
              <div className="flex items-center gap-2 min-w-0">
                <Search className="w-5 h-5 neon-text-magenta flex-shrink-0" />
                <h3 className="cyber-subheading text-sm sm:text-base neon-text-magenta truncate">{data.teacherName || data.teacherNickname || searchQuery}</h3>
              </div>
              <div className="flex items-center gap-2 flex-shrink-0">
                <span className="cyber-mono text-[10px] sm:text-xs text-muted-foreground">{data.totalMissed} entri belum diisi</span>
                <button
                  onClick={handlePrint}
                  disabled={!data || data.results.length === 0}
                  className="neon-btn-cyan px-3 py-2 sm:px-3 sm:py-1.5 rounded-lg text-[11px] sm:text-xs flex items-center justify-center gap-1.5 min-h-[40px] disabled:opacity-40 disabled:cursor-not-allowed"
                  title={`Cetak rekap guru periode ${CARI_MONTHS[parseInt(cariMonth) - 1]} ${cariYear}`}
                >
                  <Printer className="w-3.5 h-3.5" />
                  <span className="hidden sm:inline">Cetak</span>
                </button>
              </div>
            </div>
            <div className="hidden sm:block overflow-x-auto">
              <table className="neon-table w-full">
                <thead><tr><th className="w-12 text-center">NO</th><th className="min-w-[160px] text-left">HARI/TANGGAL</th><th className="min-w-[100px] text-center">KELAS</th><th className="w-40 text-center">JAM KE-</th></tr></thead>
                <tbody>
                  {data.results.map((r, idx) => (
                    <tr key={`${r.date}-${r.className}-${idx}`}>
                      <td className="text-center cyber-mono">{idx + 1}</td>
                      <td className="cyber-body text-sm">{r.formattedDate}</td>
