                      <td><div className="flex flex-wrap justify-center gap-1">{r.hours.map(h => (<span key={h} className="cyber-mono text-[10px] px-1.5 py-0.5 rounded bg-red-400/15 text-red-400 border border-red-400/30">{h}</span>))}</div></td>
