"},{"path":"src/components/app/ClassView.tsx","content":"'use client';

import { useState, useEffect, useCallback } from 'react';
import { BookOpen, Globe, ScrollText, Users, Calendar, ToggleLeft, ToggleRight, AlertTriangle } from 'lucide-react';
import { ClassData, Student, ActivityStatus } from './types';
import { safeFetchJson } from '@/lib/fetch';
import { getJakartaToday, formatDateJakarta, getDayOfWeekUTC } from '@/lib/utils';
import { CyberCalendar } from './CyberCalendar';
import { DataSiswaTab } from './DataSiswaTab';
import { IsiAbsensiTab } from './IsiAbsensiTab';
import { RekapAbsensiTab } from './RekapAbsensiTab';

interface ClassViewProps {
  classData: ClassData;
  role: 'admin' | 'guru';
  onRefreshClasses: () => void;
  initialTab?: string | null;
}

const CLASS_ICONS: Record<string, React.ReactNode> = {
  '7 Tahfidz': <BookOpen className="w-5 h-5" />,
  '8 Tahfidz': <BookOpen className="w-5 h-5" />,
  '8 Bahasa': <Globe className="w-5 h-5" />,
  '9 Tahfidz': <BookOpen className="w-5 h-5" />,
  '9 Kitab': <ScrollText className="w-5 h-5" />,
  '9 Bahasa': <Globe className="w-5 h-5" />,
};

export function ClassView({ classData, role, onRefreshClasses, initialTab }: ClassViewProps) {
  const [selectedDate, setSelectedDate] = useState(getJakartaToday);
  const [activeTab, setActiveTab] = useState<string>(initialTab || (role === 'admin' ? 'data-siswa' : 'isi-absensi'));
  const [students, setStudents] = useState<Student[]>([]);
  const [loadingStudents, setLoadingStudents] = useState(true);
  const [activityStatus, setActivityStatus] = useState<ActivityStatus>('Masuk');
  const [holidayName, setHolidayName] = useState<string | null>(null);
  const [isAutoHoliday, setIsAutoHoliday] = useState(false);
  const [holidays, setHolidays] = useState<{ dayOfWeek: number; name: string; isActive: boolean }[]>([]);
  const [showMobileCalendar, setShowMobileCalendar] = useState(false); // unused — kept for potential future use

  const tabs = role === 'admin'
    ? [
        { id: 'data-siswa', name: 'Data Siswa', shortName: 'Siswa' },
        { id: 'isi-absensi', name: 'Isi Absensi', shortName: 'Absensi' },
        { id: 'rekap-absensi', name: 'Rekap Absensi', shortName: 'Rekap' },
      ]
    : [
        { id: 'isi-absensi', name: 'Isi Absensi', shortName: 'Absensi' },
        { id: 'rekap-absensi', name: 'Rekap Absensi', shortName: 'Rekap' },
      ];

  useEffect(() => {
    const load = async () => {
      setLoadingStudents(true);
      const data = await safeFetchJson(`/api/students?classId=${classData.id}`);
      if (data) setStudents(data);
      setLoadingStudents(false);
    };
    load();
    const iv = setInterval(load, 20000);
    return () => clearInterval(iv);
  }, [classData.id]);

  const [dateHolidayName, setDateHolidayName] = useState<string | null>(null);

  const checkHolidayForDate = useCallback((dateStr: string) => {
    const dow = getDayOfWeekUTC(dateStr);
    // Check weekly academic holidays
    const holiday = holidays.find(h => h.dayOfWeek === dow && h.isActive);
    if (holiday) {
      setHolidayName(holiday.name);
      setIsAutoHoliday(true);
      return 'Libur' as ActivityStatus;
    }
    // Check per-date holidays
    if (dateHolidayName) {
      setHolidayName(dateHolidayName);
      setIsAutoHoliday(true);
      return 'Libur' as ActivityStatus;
    }
    setHolidayName(null);
    setIsAutoHoliday(false);
    return 'Masuk' as ActivityStatus;
  }, [holidays, dateHolidayName]);

  const fetchActivity = useCallback(async () => {
    const data = await safeFetchJson(`/api/academic-activity?classId=${classData.id}&date=${selectedDate}`);
    if (data && data.status) {
      setActivityStatus(data.status);
      checkHolidayForDate(selectedDate);
    } else {
      const autoStatus = checkHolidayForDate(selectedDate);
      setActivityStatus(autoStatus);
    }
  }, [classData.id, selectedDate, checkHolidayForDate]);

  // Fetch weekly holidays
  useEffect(() => {
    const load = async () => {
      const data = await safeFetchJson('/api/holidays');
      if (data) setHolidays(data);
    };
    load();
  }, []);

  // Fetch per-date holiday
  useEffect(() => {
    const check = async () => {
      const data = await safeFetchJson(`/api/date-holidays?date=${selectedDate}`);
      setDateHolidayName(data && data.date ? data.name : null);
    };
    check();
  }, [selectedDate]);

  useEffect(() => {
    let cancelled = false;
    const run = async () => {
      const data = await safeFetchJson(`/api/academic-activity?classId=${classData.id}&date=${selectedDate}`);
      if (cancelled) return;
      if (data && data.status) {
        setActivityStatus(data.status);
        checkHolidayForDate(selectedDate);
      } else {
        const autoStatus = checkHolidayForDate(selectedDate);
        setActivityStatus(autoStatus);
      }
    };
    run();
    return () => { cancelled = true; };
  }, [classData.id, selectedDate, checkHolidayForDate]);

  const handleActivityToggle = async () => {
    const newStatus = activityStatus === 'Masuk' ? 'Libur' : 'Masuk';
    setActivityStatus(newStatus);
    try {
      await fetch('/api/academic-activity', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ classId: classData.id, date: selectedDate, status: newStatus }),
      });
    } catch (e) { console.error(e); }
  };

  const handleStudentsChanged = () => {
    const load = async () => {
      const data = await safeFetchJson(`/api/students?classId=${classData.id}`);
      if (data) setStudents(data);
    };
    load();
    onRefreshClasses();
  };

  // Mobile: show calendar when on non-IsiAbsensi tabs
  const showMobileDate = activeTab !== 'isi-absensi';

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-3">
        <div className="flex items-center gap-2 sm:gap-3 min-w-0">
          <div className="w-10 h-10 sm:w-12 sm:h-12 rounded-xl flex items-center justify-center border border-cyan-400/40 bg-cyan-400/10 text-cyan-400 flex-shrink-0">
            {CLASS_ICONS[classData.name] || <BookOpen className="w-5 h-5" />}
          </div>
          <div className="min-w-0 flex-1">
            <div className="flex items-center justify-between gap-2">
              <h2 className="cyber-heading text-lg sm:text-xl md:text-2xl neon-text-cyan truncate">{classData.name}</h2>
              {/* Mobile: Activity toggle inline with class name, right-aligned */}
              <div className="sm:hidden flex items-center gap-1.5 px-2 py-1 rounded-lg neon-card flex-shrink-0">
                {role === 'admin' ? (
                  <button onClick={handleActivityToggle} className="flex items-center gap-1 transition-all" title={isAutoHoliday && activityStatus === 'Libur' ? 'Klik untuk override ke Masuk' : 'Toggle aktivitas'}>
                    {activityStatus === 'Masuk' ? (
                      <><ToggleRight className="w-5 h-5 neon-text-green" /><span className="cyber-subheading text-[10px] neon-text-green">MASUK</span></>
                    ) : (
                      <><ToggleLeft className="w-5 h-5 neon-text-magenta" /><span className="cyber-subheading text-[10px] neon-text-magenta">LIBUR</span></>
                    )}
                  </button>
                ) : (
                  <div className="flex items-center gap-1.5">
                    {activityStatus === 'Masuk' ? (
                      <><div className="w-2 h-2 rounded-full bg-green-400 flex-shrink-0" /><span className="cyber-subheading text-[10px] neon-text-green">MASUK</span></>
                    ) : (
                      <><div className="w-2 h-2 rounded-full bg-fuchsia-400 flex-shrink-0" /><span className="cyber-subheading text-[10px] neon-text-magenta">LIBUR</span></>
                    )}
                  </div>
                )}
              </div>
            </div>
            <div className="flex items-center gap-2 sm:gap-3 mt-1">
              <span className="flex items-center gap-1 cyber-mono text-[10px] sm:text-xs text-muted-foreground">
                <Users className="w-3 h-3 sm:w-3.5 sm:h-3.5" /> {students.length} Siswa
              </span>
              {classData.waliKelasName && (
                <span className="cyber-mono text-[10px] sm:text-xs text-fuchsia-400 truncate">WK: {classData.waliKelasName}</span>
              )}
            </div>
          </div>
        </div>

        {/* Desktop: Activity toggle + date pill */}
        <div className="hidden sm:flex items-center gap-2 sm:gap-3 flex-wrap">
          {isAutoHoliday && holidayName && (
            <div className="flex items-center gap-1.5 px-2 py-1.5 sm:py-2 rounded-lg border border-fuchsia-400/30 bg-fuchsia-400/5">
              <AlertTriangle className="w-3.5 h-3.5 text-fuchsia-400" />
              <span className="cyber-mono text-[9px] sm:text-[10px] text-fuchsia-400 truncate">{holidayName}</span>
            </div>
          )}

          <div className="flex items-center gap-1.5 sm:gap-2 px-2 sm:px-3 py-1.5 sm:py-2 rounded-lg neon-card">
            <span className="cyber-mono text-[9px] sm:text-[10px] text-muted-foreground hidden sm:inline">AKTIVITAS:</span>
            {role === 'admin' ? (
              <button onClick={handleActivityToggle} className="flex items-center gap-1 sm:gap-1.5 transition-all" title={isAutoHoliday && activityStatus === 'Libur' ? 'Klik untuk override ke Masuk' : 'Toggle aktivitas'}>
                {activityStatus === 'Masuk' ? (
                  <><ToggleRight className="w-5 h-5 sm:w-6 sm:h-6 neon-text-green" /><span className="cyber-subheading text-[10px] sm:text-xs neon-text-green">MASUK</span></>
                ) : (
                  <><ToggleLeft className="w-5 h-5 sm:w-6 sm:h-6 neon-text-magenta" /><span className="cyber-subheading text-[10px] sm:text-xs neon-text-magenta">LIBUR</span>{isAutoHoliday && <span className="cyber-mono text-[8px] text-fuchsia-400/60 hidden sm:inline">(auto)</span>}</>
                )}
              </button>
            ) : (
              <div className="flex items-center gap-1.5">
                {activityStatus === 'Masuk' ? (
                  <><div className="w-2 h-2 rounded-full bg-green-400 flex-shrink-0" /><span className="cyber-subheading text-[10px] sm:text-xs neon-text-green">MASUK</span></>
                ) : (
                  <><div className="w-2 h-2 rounded-full bg-fuchsia-400 flex-shrink-0" /><span className="cyber-subheading text-[10px] sm:text-xs neon-text-magenta">LIBUR</span>{isAutoHoliday && <span className="cyber-mono text-[8px] text-fuchsia-400/60 hidden sm:inline">(auto)</span>}</>
                )}
              </div>
            )}
          </div>

          {/* Date pill - desktop only */}
          <div className="hidden sm:flex items-center gap-1.5 sm:gap-2 px-2 sm:px-3 py-1.5 sm:py-2 rounded-lg neon-card min-w-0">
            <Calendar className="w-3.5 h-3.5 sm:w-4 sm:h-4 neon-text-magenta flex-shrink-0" />
            <span className="cyber-mono text-[10px] sm:text-xs text-cyan-300 truncate">{formatDateJakarta(selectedDate)}</span>
          </div>
        </div>
      </div>

      {/* Mobile: holiday warning (if any) */}
      {isAutoHoliday && holidayName && (
        <div className="sm:hidden flex items-center gap-1.5 px-2 py-1.5 rounded-lg border border-fuchsia-400/30 bg-fuchsia-400/5">
          <AlertTriangle className="w-3.5 h-3.5 text-fuchsia-400 flex-shrink-0" />
          <span className="cyber-mono text-[9px] text-fuchsia-400 truncate">{holidayName}</span>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* Left: Content */}
        <div className="lg:col-span-3">
          {/* Mobile date bar removed — date is now only in IsiAbsensiTab next to edit button */}

          {/* Tabs */}
          <div className="flex gap-1 border-b border-cyan-400/20 mb-4 overflow-x-auto">
            {tabs.map((tab) => (
              <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`px-3 sm:px-4 py-2.5 text-sm whitespace-nowrap transition-all ${activeTab === tab.id ? 'neon-tab-active' : 'neon-tab-inactive'}`}>
                <span className="sm:hidden">{tab.shortName}</span><span className="hidden sm:inline">{tab.name}</span>
              </button>
            ))}
          </div>

          {/* Tab content */}
          <div className="min-h-[400px]">
            {activeTab === 'data-siswa' && role === 'admin' && (
              <DataSiswaTab classData={classData} students={students} onRefresh={handleStudentsChanged} />
            )}
            {activeTab === 'isi-absensi' && (
              <IsiAbsensiTab classData={classData} students={students} selectedDate={selectedDate} activityStatus={activityStatus} role={role} onRefresh={handleStudentsChanged} onDateChange={setSelectedDate} />
            )}
            {activeTab === 'rekap-absensi' && (
              <RekapAbsensiTab classData={classData} students={students} selectedDate={selectedDate} />
            )}
          </div>
        </div>

        {/* Right: Calendar - desktop only */}
        <div className="hidden lg:block lg:col-span-1">
          <div className="neon-card rounded-xl p-4 sticky top-20">
            <div className="flex items-center gap-2 mb-4">
              <Calendar className="w-5 h-5 neon-text-magenta" />
              <h3 className="cyber-subheading text-xs neon-text-magenta">PILIH TANGGAL</h3>
            </div>
            <CyberCalendar value={selectedDate} onChange={setSelectedDate} />
            <div className="mt-4 p-3 rounded-lg bg-fuchsia-400/5 border border-fuchsia-400/20">
              <p className="cyber-mono text-[10px] text-fuchsia-400 uppercase mb-1">Tanggal</p>
              <p className="cyber-body text-sm text-fuchsia-200">{formatDateJakarta(selectedDate)}</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
"},{"path":"src/components/app/CyberCalendar.tsx","content":"'use client';

import { useState } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';

interface CyberCalendarProps {
  value: string;
  onChange: (date: string) => void;
}

export function CyberCalendar({ value, onChange }: CyberCalendarProps) {
  const [currentMonth, setCurrentMonth] = useState(() => {
    const d = new Date(value);
    return new Date(d.getFullYear(), d.getMonth(), 1);
  });

  const year = currentMonth.getFullYear();
  const month = currentMonth.getMonth();

  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Ags', 'Sep', 'Okt', 'Nov', 'Des'];
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDay = new Date(year, month, 1).getDay();
  const dayNames = ['Min', 'Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab'];

  const prevMonth = () => setCurrentMonth(new Date(year, month - 1, 1));
  const nextMonth = () => setCurrentMonth(new Date(year, month + 1, 1));

  const selectedDate = new Date(value);
  const isSelected = (day: number) => {
    return selectedDate.getFullYear() === year &&
      selectedDate.getMonth() === month &&
      selectedDate.getDate() === day;
  };

  const isToday = (day: number) => {
    const today = new Date();
    return today.getFullYear() === year &&
      today.getMonth() === month &&
      today.getDate() === day;
  };

  const handleSelect = (day: number) => {
    const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    onChange(dateStr);
  };

  const days: (number | null)[] = [];
  for (let i = 0; i < firstDay; i++) days.push(null);
  for (let i = 1; i <= daysInMonth; i++) days.push(i);

  return (
    <div className="neon-card rounded-lg overflow-hidden">
      {/* Month navigation */}
      <div className="flex items-center justify-between px-3 py-2 bg-cyan-400/5 border-b border-cyan-400/20">
        <button onClick={prevMonth} className="p-1.5 rounded-lg hover:bg-cyan-400/10 text-cyan-400 transition-colors">
          <ChevronLeft className="w-4 h-4" />
        </button>
        <span className="cyber-subheading text-xs neon-text-cyan tracking-wider">
          {months[month]} {year}
        </span>
        <button onClick={nextMonth} className="p-1.5 rounded-lg hover:bg-cyan-400/10 text-cyan-400 transition-colors">
          <ChevronRight className="w-4 h-4" />
        </button>
      </div>

      {/* Day names */}
      <div className="grid grid-cols-7 border-b border-cyan-400/10">
        {dayNames.map((d) => (
          <div key={d} className="py-2 text-center cyber-mono text-[10px] text-fuchsia-400 font-semibold">
            {d}
          </div>
        ))}
      </div>

      {/* Days */}
      <div className="grid grid-cols-7">
        {days.map((day, idx) => (
          <button
            key={idx}
            disabled={!day}
            onClick={() => day && handleSelect(day)}
            className={`
              aspect-square flex items-center justify-center cyber-mono text-sm transition-all
              ${!day ? '' : 'hover:bg-cyan-400/10 cursor-pointer'}
              ${day && isSelected(day)
                ? 'bg-cyan-400/20 text-cyan-300 border border-cyan-400/60 rounded-lg font-bold'
                : day && isToday(day)
                  ? 'text-fuchsia-300 font-semibold'
                  : day ? 'text-muted-foreground' : ''
              }
            `}
          >
            {day || ''}
          </button>
        ))}
      </div>
    </div>
  );
}
"},{"path":"src/components/app/DashboardView.tsx","content":"'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, Cell } from 'recharts';
import { Users, TrendingUp, AlertTriangle, CalendarOff, ToggleLeft, ToggleRight, Clock, Lock, Zap, CheckCircle, Timer, XCircle, Heart, Mail, Calendar as CalendarIcon, CalendarX2, Pencil, Check, X as XIcon, ChevronRight, BarChart3, Cloud, RefreshCw } from 'lucide-react';
import { ClassData, DashboardData, AttendanceCompletenessData } from './types';
import { safeFetchJson } from '@/lib/fetch';
import { getJakartaToday, formatDateJakarta, getDayOfWeekUTC } from '@/lib/utils';
import { CyberCalendar } from './CyberCalendar';

const HOURS = [1, 2, 3, 4, 5, 6, 7, 8];

// Same icons/colors as RekapHarianContent STATUS_ICON_MAP
const STATUS_LEGEND: { key: string; label: string; icon: typeof CheckCircle; color: string }[] = [
  { key: 'Hadir', label: 'Hadir', icon: CheckCircle, color: 'var(--color-hadir)' },
  { key: 'Terlambat', label: 'Terlambat', icon: Timer, color: 'var(--color-terlambat)' },
  { key: 'Alfa', label: 'Alfa', icon: XCircle, color: 'var(--color-alfa)' },
  { key: 'Sakit', label: 'Sakit', icon: Heart, color: 'var(--color-sakit)' },
  { key: 'Izin', label: 'Izin', icon: Mail, color: 'var(--color-izin)' },
];

interface DashboardViewProps {
  role: 'admin' | 'guru';
  classes: ClassData[];
  onRefreshClasses: () => void;
  onNavigateToClass?: (className: string) => void;
  // Optional controlled selectedDate so the parent (AppShell) can sync
  // notifications with the date the user is viewing.
  selectedDate?: string;
  onSelectedDateChange?: (date: string) => void;
}

// Custom tooltip for bar chart using the same icons
function CustomChartTooltip({ active, payload, label }: { active?: boolean; payload?: Array<{ dataKey: string; value: number; color: string }>; label?: string }) {
  if (!active || !payload?.length) return null;
  return (
    <div className="sl-dialog p-0 overflow-hidden" style={{ minWidth: 160 }}>
      <div className="sl-window-title">
        <div className="sl-window-dots"><span /><span /><span /></div>
        <span className="flex-1 text-center text-[10px] cyber-subheading neon-text-cyan">{label}</span>
        <div className="w-[42px]" />
      </div>
      <div className="p-2 space-y-1">
        {payload.map((entry) => {
          const legend = STATUS_LEGEND.find(l => l.key === entry.dataKey);
          if (!legend) return null;
          const IconComp = legend.icon;
          return (
            <div key={entry.dataKey} className="flex items-center justify-between gap-3">
              <div className="flex items-center gap-1.5">
                <IconComp className="w-3 h-3" style={{ color: legend.color }} />
                <span className="cyber-mono text-[10px]" style={{ color: legend.color }}>{legend.label}</span>
              </div>
              <span className="cyber-mono text-[10px] font-bold" style={{ color: legend.color }}>{entry.value}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// Tooltip for completeness chart
function CompletenessTooltip({ active, payload, label }: { active?: boolean; payload?: Array<{ payload: { percentage: number; totalScheduled: number; totalFilled: number } }>; label?: string }) {
  if (!active || !payload?.length) return null;
  const d = payload[0].payload;
  return (
    <div className="sl-dialog p-0 overflow-hidden" style={{ minWidth: 150 }}>
      <div className="sl-window-title">
        <div className="sl-window-dots"><span /><span /><span /></div>
        <span className="flex-1 text-center text-[10px] cyber-subheading neon-text-cyan">{label}</span>
        <div className="w-[42px]" />
      </div>
      <div className="p-2 space-y-1">
        <div className="flex items-center justify-between gap-3">
          <span className="cyber-mono text-[10px] text-muted-foreground">Kelengkapan</span>
          <span className={`cyber-mono text-[10px] font-bold ${d.percentage >= 100 ? 'text-green-400' : d.percentage >= 50 ? 'text-orange-300' : 'text-red-400'}`}>{d.percentage}%</span>
        </div>
        <div className="flex items-center justify-between gap-3">
          <span className="cyber-mono text-[10px] text-muted-foreground">Terisi</span>
          <span className="cyber-mono text-[10px] font-bold text-cyan-300">{d.totalFilled}/{d.totalScheduled} jam</span>
        </div>
      </div>
    </div>
  );
}

function getBarColor(percentage: number): string {
  if (percentage >= 100) return 'var(--color-hadir)';
  if (percentage >= 75) return 'var(--color-terlambat)';
  if (percentage >= 50) return '#f59e0b';
  if (percentage > 0) return 'var(--color-alfa)';
  return '#374151';
}

export function DashboardView({ role, classes, onRefreshClasses, onNavigateToClass, selectedDate: controlledDate, onSelectedDateChange }: DashboardViewProps) {
  const [internalDate, setInternalDate] = useState(() => getJakartaToday());
  const selectedDate = controlledDate ?? internalDate;
  const setSelectedDate = (d: string) => {
    if (onSelectedDateChange) onSelectedDateChange(d);
    else setInternalDate(d);
  };
  const [dashboardData, setDashboardData] = useState<DashboardData | null>(null);
  const [loading, setLoading] = useState(true);
  const [holidayInfo, setHolidayInfo] = useState<{ name: string; isAuto: boolean } | null>(null);

  // Activity states
  const [bulkActivityStatus, setBulkActivityStatus] = useState<'Masuk' | 'Libur'>('Masuk');
  const [bulkSaving, setBulkSaving] = useState(false);

  // Per-date max hours
  const [maxHours, setMaxHours] = useState(8);
  const [hoursSaving, setHoursSaving] = useState(false);

  // Mobile calendar
  const [showMobileCalendar, setShowMobileCalendar] = useState(false);

  // Per-date holiday (red day)
  const [dateHolidaySaving, setDateHolidaySaving] = useState(false);
  const [editingDateHolidayName, setEditingDateHolidayName] = useState(false);
  const [dateHolidayNameInput, setDateHolidayNameInput] = useState('');

  // Attendance completeness data
  const [completenessData, setCompletenessData] = useState<AttendanceCompletenessData | null>(null);
  const [completenessLoading, setCompletenessLoading] = useState(true);

  // Online backup sync health (admin only)
  const [syncHealth, setSyncHealth] = useState<{
    configured: boolean;
    status: 'synced' | 'error' | 'stale' | 'disconnected' | 'unconfigured' | 'pulling';
    statusLabel: string;
    statusColor: 'green' | 'red' | 'yellow' | 'gray' | 'cyan';
    minutesAgo: number | null;
    isHealthy: boolean;
    githubInfo?: {
      totalChunks: number;
      attendanceCount: number;
      classes: number;
      students: number;
      exportedAt: string | null;
      fileCount: number;
    } | null;
  } | null>(null);

  // Mobile clock (Jakarta GMT+7)
  const [mobileClock, setMobileClock] = useState('');
  const mobileClockRef = useRef<ReturnType<typeof setInterval> | null>(null);
  useEffect(() => {
    const tick = () => {
      const n = new Date();
      const j = new Date(n.getTime() + n.getTimezoneOffset() * 60000 + 7 * 3600000);
      setMobileClock(`${String(j.getHours()).padStart(2,'0')}:${String(j.getMinutes()).padStart(2,'0')}:${String(j.getSeconds()).padStart(2,'0')}`);
    };
    tick();
    mobileClockRef.current = setInterval(tick, 1000);
    return () => { if (mobileClockRef.current) clearInterval(mobileClockRef.current); };
  }, []);

  // Fetch holidays (weekly + per-date)
  const fetchHolidays = useCallback(async () => {
    const dateHoliday = await safeFetchJson(`/api/date-holidays?date=${selectedDate}`);
    if (dateHoliday && dateHoliday.date) {
      setHolidayInfo({ name: dateHoliday.name, isAuto: false });
      return;
    }
    const data = await safeFetchJson('/api/holidays');
    if (!data) return;
    const dow = getDayOfWeekUTC(selectedDate);
    const holiday = data.find((h: { dayOfWeek: number; name: string; isActive: boolean }) => h.dayOfWeek === dow && h.isActive);
    setHolidayInfo(holiday ? { name: holiday.name, isAuto: true } : null);
  }, [selectedDate]);

  // Toggle per-date holiday (red day / tanggal merah)
  const handleDateHolidayToggle = async () => {
    setDateHolidaySaving(true);
    try {
      if (holidayInfo && !holidayInfo.isAuto) {
        await fetch(`/api/date-holidays?date=${selectedDate}`, { method: 'DELETE' });
      } else {
        const name = dateHolidayNameInput.trim() || 'Hari Libur Nasional';
        await fetch('/api/date-holidays', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ date: selectedDate, name }),
        });
      }
      setEditingDateHolidayName(false);
      setDateHolidayNameInput('');
      fetchHolidays();
      fetchDashboard();
      onRefreshClasses();
    } catch (e) { console.error(e); } finally { setDateHolidaySaving(false); }
  };

  const fetchDashboard = useCallback(async () => {
    setLoading(true);
    const data = await safeFetchJson(`/api/dashboard?date=${selectedDate}`);
    if (data) {
      setDashboardData(data);
      setMaxHours(data.maxHours ?? 8);
      const activities = data.classes.map((c: { classId: string; className: string; activityStatus: string }) => ({
        classId: c.classId, className: c.className,
        status: c.activityStatus === 'Libur' ? 'Libur' : 'Masuk',
      }));
      const allLibur = activities.every(a => a.status === 'Libur');
      setBulkActivityStatus(allLibur ? 'Libur' : 'Masuk');
    }
    setLoading(false);
  }, [selectedDate]);

  const fetchCompleteness = useCallback(async () => {
    setCompletenessLoading(true);
    const data = await safeFetchJson(`/api/attendance-completeness?date=${selectedDate}`);
    if (data) setCompletenessData(data);
    setCompletenessLoading(false);
  }, [selectedDate]);

  useEffect(() => {
    const load = () => { fetchDashboard(); fetchHolidays(); fetchCompleteness(); };
    load();
    const iv = setInterval(load, 30000);
    return () => clearInterval(iv);
  }, [fetchDashboard, fetchHolidays, fetchCompleteness]);

  const formatDateDisplay = (dateStr: string) => formatDateJakarta(dateStr);

  const chartData = dashboardData?.classes.map(c => ({
    name: c.className, Hadir: c.hadir, Terlambat: c.terlambat,
    Alfa: c.alfa, Sakit: c.sakit, Izin: c.izin,
  })) || [];

  const completenessChartData = completenessData?.classes.map(c => ({
    name: c.className,
    percentage: c.percentage,
    totalScheduled: c.totalScheduled,
    totalFilled: c.totalFilled,
  })) || [];

  const totalStudents = classes.reduce((sum, c) => sum + c.studentCount, 0);
  const [totalAttendance, setTotalAttendance] = useState(0);
  const [gsAttCount, setGsAttCount] = useState(0);

  useEffect(() => {
    (async () => {
      try {
        const res = await fetch('/api/attendance/count');
        if (res.ok) {
          const data = await res.json();
          setTotalAttendance(data.count || 0);
        }
      } catch { /* silent */ }
    })();
  }, [selectedDate]);

  // G-Sheet attendance count comes from the dashboard API response (gsAttCount)
  useEffect(() => {
    if (dashboardData && typeof dashboardData.gsAttCount === 'number') {
      setGsAttCount(dashboardData.gsAttCount);
    }
  }, [dashboardData]);

  // Fetch online backup sync health (admin only) — refresh every 5 min to avoid GitHub API rate limits
  useEffect(() => {
    if (role !== 'admin') return;
    let cancelled = false;
    const fetchHealth = async () => {
      try {
        const res = await fetch('/api/online-backup', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'health' }),
          cache: 'no-store',
        });
        if (cancelled) return;
        const data = await res.json();
        if (!cancelled && data) {
          setSyncHealth(data);
        }
      } catch { /* silent */ }
    };
    fetchHealth();
    const interval = setInterval(fetchHealth, 600000); // 10 minutes — no GitHub API calls, just DB read
    return () => { cancelled = true; clearInterval(interval); };
  }, [role]);

  const handleBulkActivityToggle = async () => {
    const newStatus = bulkActivityStatus === 'Masuk' ? 'Libur' : 'Masuk';
    setBulkSaving(true);
    try {
      await fetch('/api/academic-activity/bulk', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ date: selectedDate, status: newStatus }),
      });
      setBulkActivityStatus(newStatus);
      fetchDashboard();
      onRefreshClasses();
    } catch (e) { console.error(e); } finally { setBulkSaving(false); }
  };

  const handleHourClick = async (hour: number) => {
    const newMax = hour;
    setMaxHours(newMax);
    setHoursSaving(true);
    try {
      await fetch('/api/daily-hours', {
        method: 'PUT', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ date: selectedDate, maxHours: newMax }),
      });
      fetchDashboard();
      fetchCompleteness();
    } catch (e) { console.error(e); } finally { setHoursSaving(false); }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 sm:gap-3">
        <div className="flex items-center gap-2 sm:gap-3 min-w-0">
          <div className="min-w-0 flex-1">
            <div className="flex items-center justify-between gap-2">
              <h2 className="cyber-heading text-xl sm:text-2xl md:text-3xl neon-text-cyan">DASHBOARD</h2>
              <span className={`cyber-mono text-[10px] sm:hidden whitespace-nowrap ml-auto ${gsAttCount > 0 && gsAttCount === totalAttendance ? 'neon-text-green' : gsAttCount > totalAttendance ? 'text-yellow-400' : 'neon-text-green'}`}>
                ABSENSI: {totalAttendance.toLocaleString()}{gsAttCount > 0 ? ` | GS: ${gsAttCount.toLocaleString()}` : ''}
              </span>
            </div>
            <p className="cyber-mono text-[10px] sm:text-xs text-muted-foreground mt-1 truncate">{formatDateDisplay(selectedDate)}</p>
          </div>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          {role === 'admin' && syncHealth && (
            <div
              className={`flex items-center gap-1.5 px-2.5 py-1.5 sm:py-2 rounded-lg border ${
                syncHealth.statusColor === 'green' ? 'border-green-400/40 bg-green-400/10' :
                syncHealth.statusColor === 'red' ? 'border-red-400/40 bg-red-400/10' :
                syncHealth.statusColor === 'yellow' ? 'border-yellow-400/40 bg-yellow-400/10' :
                syncHealth.statusColor === 'cyan' ? 'border-cyan-400/40 bg-cyan-400/10' :
                'border-gray-400/40 bg-gray-400/10'
              }`}
              title={syncHealth.githubInfo ? `GitHub: ${syncHealth.githubInfo.fileCount} files, ${syncHealth.githubInfo.attendanceCount} absensi, ${syncHealth.githubInfo.totalChunks} chunks` : syncHealth.statusLabel}
            >
              <Cloud className={`w-3.5 h-3.5 ${
                syncHealth.statusColor === 'green' ? 'text-green-400' :
                syncHealth.statusColor === 'red' ? 'text-red-400' :
                syncHealth.statusColor === 'yellow' ? 'text-yellow-400' :
                syncHealth.statusColor === 'cyan' ? 'text-cyan-400' :
                'text-gray-400'
              }`} />
              <span className={`cyber-mono text-[9px] sm:text-[10px] ${
                syncHealth.statusColor === 'green' ? 'text-green-300' :
                syncHealth.statusColor === 'red' ? 'text-red-300' :
                syncHealth.statusColor === 'yellow' ? 'text-yellow-300' :
                syncHealth.statusColor === 'cyan' ? 'text-cyan-300' :
                'text-gray-400'
              }`}>
                {syncHealth.statusLabel}
              </span>
              {syncHealth.githubInfo && (
                <span className="cyber-mono text-[8px] text-muted-foreground hidden sm:inline">
                  GH: {syncHealth.githubInfo.attendanceCount.toLocaleString()}
                </span>
              )}
              <span className={`w-1.5 h-1.5 rounded-full ${
                syncHealth.statusColor === 'green' ? 'bg-green-400 animate-pulse' :
                syncHealth.statusColor === 'red' ? 'bg-red-400' :
                syncHealth.statusColor === 'yellow' ? 'bg-yellow-400' :
                syncHealth.statusColor === 'cyan' ? 'bg-cyan-400 animate-pulse' :
                'bg-gray-400'
              }`} />
            </div>
          )}
          {holidayInfo && (
            <div className="flex items-center gap-1.5 px-2.5 py-1.5 sm:py-2 rounded-lg border border-fuchsia-400/40 bg-fuchsia-400/10">
              <CalendarOff className="w-4 h-4 text-fuchsia-400" />
              <span className="cyber-subheading text-xs neon-text-magenta">LIBUR</span>
              <span className="cyber-mono text-[9px] text-fuchsia-400/70">{holidayInfo.name}</span>
            </div>
          )}
          <div className="flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-lg neon-card flex-shrink-0">
            <Users className="w-4 h-4 sm:w-5 sm:h-5 neon-text-cyan" />
            <span className="cyber-mono text-xs sm:text-sm text-cyan-300">TOTAL: {totalStudents}</span>
            <span className="hidden sm:inline cyber-mono text-[10px] text-muted-foreground">|</span>
            <span className="hidden sm:inline cyber-mono text-xs neon-text-green">ABSENSI: {totalAttendance.toLocaleString()}</span>
            {gsAttCount > 0 && (
              <>
                <span className="hidden sm:inline cyber-mono text-[10px] text-muted-foreground">|</span>
                <span
                  className={`hidden sm:inline cyber-mono text-xs ${
                    gsAttCount === totalAttendance
                      ? 'neon-text-green'
                      : gsAttCount > totalAttendance
                        ? 'text-yellow-400'
                        : 'text-red-400'
                  }`}
                  title={`Google Sheets attendance count = ${gsAttCount.toLocaleString()} (local: ${totalAttendance.toLocaleString()})`}
                >
                  GS: {gsAttCount.toLocaleString()}
                </span>
              </>
            )}
          </div>
