                <p className="cyber-mono text-[10px] text-muted-foreground">SISWA</p>
                {cls.waliKelasName && <p className="text-xs text-muted-foreground mt-2 truncate cyber-body">WK: {cls.waliKelasName}</p>}
                <ChevronRight className="w-4 h-4 text-cyan-400/0 group-hover:text-cyan-400/60 transition-colors absolute top-4 right-4" />
