import { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Plus, Download, Upload, Trash2, Pencil, Save, X,
  Users, FileSpreadsheet, FileText, ChevronDown
} from 'lucide-react';
import { ClassData, Student } from './types';

interface DataSiswaTabProps {
  classData: ClassData;
  students: Student[];
  onRefresh: () => void;
}

export function DataSiswaTab({ classData, students, onRefresh }: DataSiswaTabProps) {
  const [showAddDialog, setShowAddDialog] = useState(false);
  const [editingStudent, setEditingStudent] = useState<Student | null>(null);
  const [formData, setFormData] = useState({ name: '', nisn: '', gender: '', whatsapp: '' });
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState<string | null>(null);
  const [uploadFile, setUploadFile] = useState<File | null>(null);
  const [uploading, setUploading] = useState(false);
  const [uploadMessage, setUploadMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [showTemplateMenu, setShowTemplateMenu] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const uploadInputRef = useRef<HTMLInputElement>(null);
  const templateMenuRef = useRef<HTMLDivElement>(null);

  const handleAddOpen = () => {
    setFormData({ name: '', nisn: '', gender: '', whatsapp: '' });
    setEditingStudent(null);
    setShowAddDialog(true);
  };

  const handleEditOpen = (student: Student) => {
    setFormData({ name: student.name, nisn: student.nisn, gender: student.gender, whatsapp: student.whatsapp });
    setEditingStudent(student);
    setShowAddDialog(true);
  };

  const handleSave = async () => {
    if (!formData.name.trim()) return;
    setSaving(true);
    try {
      if (editingStudent) {
        await fetch(`/api/students/${editingStudent.id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(formData),
        });
      } else {
        await fetch('/api/students', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ...formData, classId: classData.id }),
        });
      }
      setShowAddDialog(false);
      onRefresh();
    } catch (e) {
      console.error(e);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (studentId: string) => {
    setDeleting(studentId);
    try {
      await fetch(`/api/students/${studentId}`, { method: 'DELETE' });
      onRefresh();
    } catch (e) {
      console.error(e);
    } finally {
      setDeleting(null);
    }
  };

  const handleDownloadCSV = () => {
    const headers = ['Nomor Urut', 'Nama Siswa', 'NISN', 'Jenis Kelamin', 'Nomor WA'];
    const csv = [headers.join(','), '1,Contoh Nama,1234567890,Laki-laki,081234567890'].join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Template_Siswa_${classData.name.replace(/\s+/g, '_')}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    setShowTemplateMenu(false);
  };

  const handleDownloadXLSX = async () => {
    setShowTemplateMenu(false);
    // Dynamically import xlsx to avoid SSR issues
    const XLSX = await import('xlsx');
    const wsData = [
      ['Nomor Urut', 'Nama Siswa', 'NISN', 'Jenis Kelamin', 'Nomor WA'],
      [1, 'Contoh Nama', 1234567890, 'Laki-laki', '081234567890'],
      [2, 'Contoh Nama 2', 9876543210, 'Perempuan', '081234567891'],
    ];
    const ws = XLSX.utils.aoa_to_sheet(wsData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Data Siswa');
    XLSX.writeFile(wb, `Template_Siswa_${classData.name.replace(/\s+/g, '_')}.xlsx`);
  };

  const handleUploadTemplate = async () => {
    if (!uploadFile) return;
    setUploading(true);
    setUploadMessage(null);
    try {
      const formDataUpload = new FormData();
      formDataUpload.append('file', uploadFile);
