import { useState, useEffect, useCallback } from 'react';
import {
  Cloud, Check, AlertTriangle, Loader2, X, Copy, ExternalLink,
  Sheet, Settings as SettingsIcon, RefreshCw, Download, Upload,
} from 'lucide-react';
import { useToast } from '@/hooks/use-toast';

interface GSheetsIntegrationProps {
  isOpen: boolean;
  onClose: () => void;
}

interface GSheetsConfig {
  configured: boolean;
  webhookUrl: string | null;
  webhookUrlMasked: string | null;
  spreadsheetUrl: string | null;
  health: {
    configured: boolean;
    status: string;
    statusLabel: string;
    statusColor: string;
    lastSyncAt: string | null;
    lastPullAt: string | null;
    minutesAgo: number | null;
  } | null;
  appsScriptCode?: string;
}

export function GSheetsIntegration({ isOpen, onClose }: GSheetsIntegrationProps) {
  const { toast } = useToast();
  const [config, setConfig] = useState<GSheetsConfig | null>(null);
  const [loading, setLoading] = useState(true);
  const [webhookUrl, setWebhookUrl] = useState('');
  const [spreadsheetUrl, setSpreadsheetUrl] = useState('');
  const [showCode, setShowCode] = useState(false);
  const [copied, setCopied] = useState(false);
  const [testing, setTesting] = useState(false);
  const [saving, setSaving] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [pulling, setPulling] = useState(false);
  const [replacing, setReplacing] = useState(false);

  useEffect(() => {
    if (!isOpen) return;
    let cancelled = false;
    const load = async () => {
      setLoading(true);
      try {
        const res = await fetch('/api/gsheets', { cache: 'no-store' });
        const data = await res.json();
        if (cancelled) return;
        setConfig(data);
        if (data.webhookUrl) setWebhookUrl(data.webhookUrl);
        if (data.spreadsheetUrl) setSpreadsheetUrl(data.spreadsheetUrl);
      } catch {
        // ignore
      }
      if (!cancelled) setLoading(false);
    };
    load();
    return () => { cancelled = true; };
  }, [isOpen]);

  const refreshConfig = useCallback(async () => {
    try {
      const res = await fetch('/api/gsheets', { cache: 'no-store' });
      const data = await res.json();
      setConfig(data);
    } catch {}
  }, []);

  const handleSave = async () => {
    if (!webhookUrl.trim()) {
      toast({ title: 'Webhook URL wajib diisi', variant: 'destructive' });
      return;
    }
    setSaving(true);
    try {
      const res = await fetch('/api/gsheets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ webhookUrl: webhookUrl.trim(), spreadsheetUrl: spreadsheetUrl.trim() }),
      });
      const data = await res.json();
      if (data.success) {
        toast({ title: 'Konfigurasi disimpan!', description: data.message });
        refreshConfig();
      } else {
        toast({ title: 'Gagal menyimpan', description: data.message, variant: 'destructive' });
      }
    } catch {
      toast({ title: 'Gagal menyimpan', variant: 'destructive' });
    }
    setSaving(false);
  };

  const handleTest = async () => {
    setTesting(true);
    try {
      const res = await fetch('/api/gsheets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'test' }),
      });
      const data = await res.json();
      if (data.ok) {
        toast({ title: 'Koneksi berhasil!', description: data.message });
      } else {
        toast({ title: 'Koneksi gagal', description: data.message, variant: 'destructive' });
      }
    } catch {
      toast({ title: 'Gagal test koneksi', variant: 'destructive' });
    }
    setTesting(false);
  };

  const handleSync = async () => {
    setSyncing(true);
    try {
      const res = await fetch('/api/gsheets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'sync' }),
      });
      const data = await res.json();
      if (data.success) {
        toast({ title: 'Sync berhasil!', description: data.message });
        refreshConfig();
      } else {
        toast({ title: 'Sync gagal', description: data.message, variant: 'destructive' });
      }
    } catch {
      toast({ title: 'Sync gagal', variant: 'destructive' });
    }
    setSyncing(false);
  };

  const handlePull = async () => {
    setPulling(true);
    try {
      const res = await fetch('/api/gsheets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'pull' }),
      });
      const data = await res.json();
      if (data.success) {
        toast({ title: 'Pull berhasil!', description: data.message });
        refreshConfig();
      } else {
        toast({ title: 'Pull gagal', description: data.message, variant: 'destructive' });
      }
    } catch {
      toast({ title: 'Pull gagal', variant: 'destructive' });
    }
    setPulling(false);
  };

  // REPLACE date holidays and max hours on G-Sheet with current DB data.
  // Unlike "SYNC" (which merges), this CLEARS old entries and writes ONLY
  // new data. Requires the deployed Apps Script to support the
  // "replaceDateHolidaysAndMaxHours" action (see APPS_SCRIPT_CODE).
  const handleReplace = async () => {
    if (!confirm('PERINGATAN: Ini akan MENGHAPUS semua data hari libur tanggal dan max hour lama di G-Sheet dan menggantinya dengan data dari server saat ini. Lanjutkan?')) {
      return;
    }
    setReplacing(true);
    try {
      const res = await fetch('/api/gsheets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'replaceDateHolidaysAndMaxHours' }),
      });
      const data = await res.json();
      if (data.success) {
        toast({ title: 'Replace berhasil!', description: data.message });
        refreshConfig();
      } else {
        toast({ title: 'Replace gagal', description: data.message, variant: 'destructive' });
      }
    } catch {
      toast({ title: 'Replace gagal', variant: 'destructive' });
    }
    setReplacing(false);
  };

  const handleCopyCode = () => {
    if (config?.appsScriptCode) {
      navigator.clipboard.writeText(config.appsScriptCode);
      setCopied(true);
      toast({ title: 'Code disalin!', description: 'Paste ke Apps Script editor.' });
      setTimeout(() => setCopied(false), 3000);
    }
  };

  if (!isOpen) return null;

  const health = config?.health;
  const statusColor = health?.statusColor === 'green' ? 'text-green-400' :
                      health?.statusColor === 'yellow' ? 'text-yellow-400' :
                      health?.statusColor === 'red' ? 'text-red-400' :
                      'text-muted-foreground';

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-2 sm:p-4" onClick={onClose}>
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" />
      <div
        className="relative z-10 w-full max-w-2xl max-h-[90vh] overflow-y-auto neon-card rounded-xl"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="sticky top-0 z-10 flex items-center justify-between p-3 sm:p-4 border-b border-green-400/20 bg-[var(--sl-surface)]/95 backdrop-blur-md">
          <div className="flex items-center gap-2">
            <Sheet className="w-5 h-5 text-green-400" />
            <h2 className="cyber-heading text-sm sm:text-base neon-text-green">G-SHEET INTEGRATION</h2>
          </div>
          <button onClick={onClose} className="sl-icon-btn border-[var(--sl-border)] text-[var(--sl-text-accent)] bg-[var(--sl-surface)] hover:bg-[var(--sl-glow-strong)]">
            <X className="w-4 h-4" />
          </button>
        </div>

        <div className="p-3 sm:p-5 space-y-4">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="w-6 h-6 animate-spin neon-text-green" />
            </div>
          ) : (
            <>
              {/* Status */}
              {health && (
                <div className={`p-3 rounded-lg border ${health.status === 'synced' ? 'border-green-400/30 bg-green-400/5' : health.status === 'error' ? 'border-red-400/30 bg-red-400/5' : 'border-yellow-400/30 bg-yellow-400/5'}`}>
                  <div className="flex items-center gap-2">
                    {health.status === 'synced' ? <Check className="w-4 h-4 text-green-400" /> : <AlertTriangle className="w-4 h-4 text-yellow-400" />}
                    <span className={`cyber-mono text-xs ${statusColor}`}>{health.statusLabel}</span>
                  </div>
                </div>
              )}

              {/* Setup Instructions */}
              <div className="p-3 rounded-lg bg-green-400/5 border border-green-400/15">
                <h3 className="cyber-subheading text-xs neon-text-green mb-2">SETUP INSTRUKSI</h3>
                <ol className="cyber-body text-[11px] text-green-300/80 space-y-1.5 list-decimal list-inside">
                  <li>Buka <a href="https://script.google.com" target="_blank" rel="noreferrer" className="text-cyan-400 hover:underline inline-flex items-center gap-0.5">script.google.com <ExternalLink className="w-3 h-3 inline" /></a> → New Project</li>
                  <li>Hapus kode default, paste kode Apps Script di bawah</li>
                  <li>Klik <strong>Deploy → New deployment</strong></li>
                  <li>Pilih <strong>Web app</strong> → Execute as: <strong>Me</strong> → Access: <strong>Anyone</strong></li>
                  <li>Copy <strong>Web app URL</strong> dan paste di bawah</li>
                  <li>Share spreadsheet <a href="https://docs.google.com/spreadsheets/d/10qr4FBMKSuIiZ9esT3EaX50BnsmBME_fYgrzO9-MPSI/edit" target="_blank" rel="noreferrer" className="text-cyan-400 hover:underline inline-flex items-center gap-0.5">ini <ExternalLink className="w-3 h-3 inline" /></a> dengan email Anda (Editor)</li>
                </ol>
              </div>

              {/* Webhook URL Config */}
              <div className="space-y-2">
                <label className="cyber-mono text-[10px] text-green-400 uppercase">APPS SCRIPT WEBHOOK URL</label>
                <input
                  type="url"
                  value={webhookUrl}
                  onChange={(e) => setWebhookUrl(e.target.value)}
                  placeholder="https://script.google.com/macros/s/AKfycbx.../exec"
                  className="neon-input w-full px-3 py-2 rounded-lg text-xs"
                />
              </div>

              {/* Spreadsheet URL (optional) */}
              <div className="space-y-2">
                <label className="cyber-mono text-[10px] text-green-400 uppercase">SPREADSHEET URL (OPSIONAL)</label>
                <input
                  type="url"
                  value={spreadsheetUrl}
                  onChange={(e) => setSpreadsheetUrl(e.target.value)}
                  placeholder="https://docs.google.com/spreadsheets/d/10qr4FBMKSuIiZ9esT3EaX50BnsmBME_fYgrzO9-MPSI/edit"
                  className="neon-input w-full px-3 py-2 rounded-lg text-xs"
                />
              </div>

              {/* Action Buttons */}
              <div className="flex flex-wrap gap-2">
                <button
                  onClick={handleSave}
                  disabled={saving}
                  className="neon-btn-green px-3 py-2 rounded-lg text-xs flex items-center gap-1.5 disabled:opacity-40"
                >
                  {saving ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <SettingsIcon className="w-3.5 h-3.5" />}
                  Simpan Konfigurasi
                </button>
                <button
                  onClick={handleTest}
                  disabled={testing || !webhookUrl}
                  className="neon-btn-cyan px-3 py-2 rounded-lg text-xs flex items-center gap-1.5 disabled:opacity-40"
                >
                  {testing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Cloud className="w-3.5 h-3.5" />}
                  Test Koneksi
                </button>
              </div>

              {/* Sync/Pull buttons — only show when configured */}
              {config?.configured && (
                <div className="flex flex-wrap gap-2 pt-2 border-t border-green-400/15">
                  <button
                    onClick={handleSync}
                    disabled={syncing}
                    className="neon-btn-green px-3 py-2 rounded-lg text-xs flex items-center gap-1.5 disabled:opacity-40"
                  >
                    {syncing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Upload className="w-3.5 h-3.5" />}
                    Sync (Push ke G-Sheet)
                  </button>
                  <button
                    onClick={handlePull}
                    disabled={pulling}
                    className="neon-btn-orange px-3 py-2 rounded-lg text-xs flex items-center gap-1.5 disabled:opacity-40"
                  >
                    {pulling ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Download className="w-3.5 h-3.5" />}
                    Pull (Ambil dari G-Sheet)
                  </button>
                  <button
                    onClick={handleReplace}
                    disabled={replacing || syncing || pulling}
                    className="neon-btn-cyan px-3 py-2 rounded-lg text-xs flex items-center gap-1.5 disabled:opacity-40"
                    title="Hapus semua data lama di G-Sheet (libur tanggal + max hour) dan ganti dengan data dari server"
                  >
                    {replacing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RefreshCw className="w-3.5 h-3.5" />}
                    Replace (Hapus + Ganti Data Lama)
                  </button>
                </div>
              )}

              {/* Apps Script Code */}
              <div className="pt-2 border-t border-green-400/15">
                <button
                  onClick={() => setShowCode(!showCode)}
                  className="cyber-mono text-[10px] text-cyan-400 hover:text-cyan-300 flex items-center gap-1"
                >
                  <Sheet className="w-3.5 h-3.5" />
                  {showCode ? 'SEMBUNYIKAN' : 'TAMPILKAN'} KODE APPS SCRIPT
                </button>
                {showCode && (
                  <div className="mt-2 relative">
                    <button
                      onClick={handleCopyCode}
                      className="absolute top-2 right-2 z-10 sl-icon-btn border-green-400/30 text-green-400 bg-green-400/10 hover:bg-green-400/20 p-1.5 rounded"
                      title="Copy code"
                    >
                      {copied ? <Check className="w-3.5 h-3.5" /> : <Copy className="w-3.5 h-3.5" />}
                    </button>
                    <pre className="bg-black/60 border border-green-400/20 rounded-lg p-3 pt-9 overflow-x-auto max-h-64 text-[9px] sm:text-[10px] text-green-300/90 cyber-mono leading-relaxed">
                      <code>{config?.appsScriptCode || '// Loading...'}</code>
                    </pre>
                  </div>
                )}
              </div>

              {/* Info */}
              <div className="p-2 rounded-lg bg-green-400/5 border border-green-400/15 flex items-start gap-1.5">
                <RefreshCw className="w-3 h-3 text-green-400 flex-shrink-0 mt-0.5" />
                <div className="text-[9px] text-green-300/80 cyber-body space-y-1">
                  <p><strong>Auto-sync:</strong> Setiap perubahan user (save, max hour click) otomatis ter-push ke G-Sheet (production).</p>
                  <p><strong>Auto-fetch:</strong> Saat server reset, data di-fetch otomatis dari G-Sheet.</p>
                  <p><strong>Synced:</strong> Max hour, hari libur, guru, wali kelas, jadwal, siswa. <strong>Absensi tetap di GitHub.</strong></p>
                </div>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
"},{"path":"src/components/app/GoogleSheetsSync.tsx","content":"'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Sheet, RefreshCw, Download, Check, AlertTriangle, Copy,
  ExternalLink, ChevronDown, Loader2, X, Wifi, WifiOff, Zap,
  Settings, ArrowDownToLine, DatabaseBackup
} from 'lucide-react';
import { safeFetchJson } from '@/lib/fetch';
import { useToast } from '@/hooks/use-toast';
import { APPS_SCRIPT_V6 as APPS_SCRIPT_CODE } from '@/lib/apps-script-v6';

const SPREADSHEET_URL = 'https://docs.google.com/spreadsheets/d/10qr4FBMKSuIiZ9esT3EaX50BnsmBME_fYgrzO9-MPSI/edit?usp=sharing';

// Simple URL validation for client-side
function isValidScriptUrl(url: string): boolean {
  if (!url.trim()) return false;
  return /^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(url.trim());
}

interface GoogleSheetsSyncProps {
  isOpen: boolean;
  onClose: () => void;
  className?: string;
}

export function GoogleSheetsSync({ isOpen, onClose, className = '' }: GoogleSheetsSyncProps) {
  const [scriptUrl, setScriptUrl] = useState('');
  const [configured, setConfigured] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [pulling, setPulling] = useState(false);
  const [savingUrl, setSavingUrl] = useState(false);
  const [testingUrl, setTestingUrl] = useState(false);
  const [lastSyncStatus, setLastSyncStatus] = useState<{ success: boolean; message: string } | null>(null);
  const [testResult, setTestResult] = useState<{ success: boolean; message: string } | null>(null);
  const [showSetup, setShowSetup] = useState(false);
  const [copied, setCopied] = useState(false);
  const [showCode, setShowCode] = useState(false);
  const [urlError, setUrlError] = useState<string | null>(null);
  const [showPullConfirm, setShowPullConfirm] = useState(false);
  const { toast } = useToast();

  const handleUrlChange = useCallback((value: string) => {
    setScriptUrl(value);
    setTestResult(null);
    if (!value.trim()) {
      setUrlError(null);
      return;
    }
    if (!value.startsWith('https://script.google.com/macros/s/')) {
      setUrlError('URL harus dimulai dengan https://script.google.com/macros/s/');
    } else if (!value.endsWith('/exec')) {
      setUrlError('URL harus diakhungi dengan /exec');
    } else if (!isValidScriptUrl(value)) {
      setUrlError('Format URL tidak valid');
    } else {
      setUrlError(null);
    }
  }, []);

  useEffect(() => {
    if (!isOpen) return;
    let cancelled = false;
    (async () => {
      const data = await safeFetchJson('/api/google-sheets/config');
      if (cancelled) return;
      if (data) {
        setScriptUrl(data.scriptUrl || '');
        setConfigured(!!data.scriptUrl && isValidScriptUrl(data.scriptUrl || ''));
      }
    })();
    return () => { cancelled = true; };
  }, [isOpen]);

  const handleSaveUrl = useCallback(async () => {
    if (!scriptUrl.trim()) {
      toast({ title: 'URL tidak boleh kosong', variant: 'destructive' });
      return;
    }
    if (urlError) {
      toast({ title: 'Perbaiki format URL terlebih dahulu', variant: 'destructive' });
      return;
    }
    setSavingUrl(true);
    const res = await safeFetchJson('/api/google-sheets/config', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ scriptUrl: scriptUrl.trim() }),
    });
    setSavingUrl(false);
    if (res?.success) {
      setConfigured(true);
      toast({ title: 'URL tersimpan!', description: 'Google Sheets siap untuk disinkronkan' });
    } else {
      toast({ title: res?.error || 'Gagal menyimpan URL', variant: 'destructive' });
    }
  }, [scriptUrl, urlError, toast]);

  const handleTestConnection = useCallback(async () => {
    const urlToTest = scriptUrl.trim();
    if (!urlToTest) {
      toast({ title: 'Masukkan URL terlebih dahulu', variant: 'destructive' });
      return;
    }
    if (urlError) {
      toast({ title: 'Perbaiki format URL terlebih dahulu', variant: 'destructive' });
      return;
    }
    setTestingUrl(true);
    setTestResult(null);
    try {
      const testUrl = '/api/google-sheets/config?test=' + encodeURIComponent(urlToTest);
      const data = await safeFetchJson(testUrl);
      if (data?.testConnection) {
        setTestResult(data.testConnection);
        if (data.testConnection.success) {
          toast({ title: 'Koneksi berhasil!', description: data.testConnection.message });
        } else {
          toast({ title: 'Koneksi gagal', description: data.testConnection.message, variant: 'destructive' });
        }
      } else {
        setTestResult({ success: false, message: 'Tidak dapat menghubungi server' });
      }
    } catch {
      setTestResult({ success: false, message: 'Gagal menghubungi server' });
    }
    setTestingUrl(false);
  }, [scriptUrl, urlError, toast]);

  // Robust fetch for long-running operations (sync/pull/restore) that shows real error messages instead of generic 'Gagal terhubung ke server'
  const robustFetch = useCallback(async (url: string, options: RequestInit & { timeoutMs?: number } = {}): Promise<any> => {
    const { timeoutMs = 300_000, ...fetchOpts } = options;
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const res = await fetch(url, { ...fetchOpts, cache: 'no-store', signal: controller.signal });
      clearTimeout(timeoutId);
      // Try to parse JSON body even for error responses to get the real error message
      let data: any = null;
      const contentType = res.headers.get('content-type') || '';
      if (contentType.includes('application/json')) {
        data = await res.json();
      } else {
        const text = await res.text();
        // Try parsing as JSON anyway (some servers don't set content-type)
        try { data = JSON.parse(text); } catch { data = null; }
      }
      if (data) return data;
      // Non-JSON response — return an error object with status info
      return { success: false, message: `Server error: HTTP ${res.status}` };
    } catch (e) {
      clearTimeout(timeoutId);
      if (e instanceof DOMException && e.name === 'AbortError') {
        return { success: false, message: 'Timeout: Operasi melebihi batas waktu. Data terlalu besar, coba lagi.' };
      }
      return { success: false, message: `Gagal terhubung ke server: ${e instanceof Error ? e.message : 'Network error'}` };
    }
  }, []);

  const [syncProgress, setSyncProgress] = useState<{ current: number; total: number; percentage: number; label: string } | null>(null);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const handleSync = useCallback(async () => {
    setSyncing(true);
    setLastSyncStatus(null);
    setSyncProgress(null);

    // Start background sync
    const res = await robustFetch('/api/google-sheets', { method: 'POST' });
    if (!res || !res.success) {
      setSyncing(false);
      if (res) {
        setLastSyncStatus({ success: res.success, message: res.message });
        toast({ title: 'Sinkronisasi gagal', description: res.message, variant: 'destructive' });
      }
      return;
    }

    // Poll for sync status every 2 seconds
    pollRef.current = setInterval(async () => {
      try {
        const statusRes = await fetch('/api/google-sheets', { cache: 'no-store' });
        const statusData = await statusRes.json();
        const ss = statusData?.syncStatus;
        if (ss?.progress) {
          setSyncProgress(ss.progress);
        }
        if (!ss?.running) {
          // Sync finished
          if (pollRef.current) { clearInterval(pollRef.current); pollRef.current = null; }
          setSyncing(false);
          setSyncProgress(null);
          if (ss?.lastResult) {
            setLastSyncStatus({ success: ss.lastResult.success, message: ss.lastResult.message });
            if (ss.lastResult.success) {
              toast({ title: 'Sinkronisasi berhasil!', description: ss.lastResult.message });
            } else {
              toast({ title: 'Sinkronisasi gagal', description: ss.lastResult.message, variant: 'destructive' });
            }
          }
        }
      } catch {
        // Ignore poll errors
      }
    }, 2000);
  }, [toast, robustFetch]);

  // Cleanup polling on unmount
  useEffect(() => {
    return () => {
      if (pollRef.current) clearInterval(pollRef.current);
    };
  }, []);

  const [pullProgress, setPullProgress] = useState<{ current: number; total: number; percentage: number; label: string } | null>(null);
  const pullPollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const handlePull = useCallback(async () => {
    setPulling(true);
    setLastSyncStatus(null);
    setShowPullConfirm(false);
    setPullProgress(null);

    // Start background pull
    const res = await robustFetch('/api/google-sheets', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'restore' }),
    });

    if (!res || !res.success) {
      setPulling(false);
      if (res) {
        setLastSyncStatus({ success: res.success, message: res.message });
        toast({ title: 'Pull gagal', description: res.message, variant: 'destructive' });
      }
      return;
    }

    // Poll for pull status every 2 seconds
    pullPollRef.current = setInterval(async () => {
      try {
        const statusRes = await fetch('/api/google-sheets', { cache: 'no-store' });
        const statusData = await statusRes.json();
        const ss = statusData?.syncStatus;
        if (ss?.progress) {
          setPullProgress(ss.progress);
        }
        if (!ss?.running) {
          if (pullPollRef.current) { clearInterval(pullPollRef.current); pullPollRef.current = null; }
          setPulling(false);
          setPullProgress(null);
          if (ss?.lastResult) {
            setLastSyncStatus({ success: ss.lastResult.success, message: ss.lastResult.message });
            if (ss.lastResult.success) {
              toast({ title: 'Pull berhasil!', description: ss.lastResult.message });
            } else {
              toast({ title: 'Pull gagal', description: ss.lastResult.message, variant: 'destructive' });
            }
          }
        }
      } catch {
        // Ignore poll errors
      }
    }, 2000);
  }, [toast, robustFetch]);

  // Cleanup pull polling on unmount
  useEffect(() => {
    return () => {
      if (pullPollRef.current) clearInterval(pullPollRef.current);
    };
  }, []);

  const handleExportCSV = useCallback(() => {
    const link = document.createElement('a');
    const today = new Date().toISOString().split('T')[0];
    link.href = '/api/google-sheets/export';
    link.download = 'Absensi_MTsAlIshlah_' + today + '.csv';
    link.click();
    toast({ title: 'CSV berhasil diunduh' });
  }, [toast]);

  const handleCopyCode = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(APPS_SCRIPT_CODE);
      setCopied(true);
      toast({ title: 'Kode v7 berhasil disalin!' });
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast({ title: 'Gagal menyalin kode', variant: 'destructive' });
    }
  }, [toast]);

  if (!isOpen) return null;

  return (
    <>
      <div className={`sl-notification ${className}`}>
        <div className="sl-window-title">
          <div className="sl-window-dots"><span /><span /><span /></div>
          <Sheet className="w-4 h-4" />
          <span className="flex-1 text-center">SPREADSHEET</span>
          {configured ? (
            <span className="sl-badge sl-badge-green">AKTIF</span>
          ) : (
            <span className="sl-badge sl-badge-red">BELUM SIAP</span>
          )}
        </div>

        <div className="p-3 max-h-[60vh] overflow-y-auto space-y-3">
          <div className="p-2.5 rounded-lg border border-green-400/20 bg-green-400/5">
            <p className="cyber-mono text-[9px] text-green-400/60 mb-1">LINK SPREADSHEET</p>
            <a
              href={SPREADSHEET_URL}
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center gap-2 text-xs text-green-300 hover:text-green-400 transition-colors group"
            >
              <span className="truncate flex-1 cyber-body">REKAP ABSENSI 2026-2027</span>
              <ExternalLink className="w-3.5 h-3.5 flex-shrink-0 group-hover:translate-x-0.5 transition-transform" />
            </a>
          </div>

          {/* Action Buttons - SYNC + PULL side by side */}
          <div className="grid grid-cols-2 gap-2">
            <button
              onClick={handleSync}
              disabled={syncing || pulling || !configured}
              className="neon-btn-green px-3 py-2 rounded-lg text-[10px] sm:text-xs flex items-center justify-center gap-1.5 disabled:opacity-40 disabled:cursor-not-allowed"
            >
              {syncing ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <RefreshCw className="w-3.5 h-3.5" />
              )}
              {syncing ? 'SINKRON...' : 'SYNC'}
            </button>
            <button
              onClick={() => setShowPullConfirm(true)}
              disabled={pulling || syncing || !configured}
              className="neon-btn-cyan px-3 py-2 rounded-lg text-[10px] sm:text-xs flex items-center justify-center gap-1.5 disabled:opacity-40 disabled:cursor-not-allowed"
            >
              {pulling ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <ArrowDownToLine className="w-3.5 h-3.5" />
              )}
              {pulling ? 'PULLING...' : 'PULL'}
            </button>
          </div>

          {/* Stop button — shown when sync or pull is running */}
          {(syncing || pulling) && (
            <button
              onClick={async () => {
                try {
                  await fetch('/api/google-sheets', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ action: 'stop' }),
                  });
                } catch {}
                if (pollRef.current) { clearInterval(pollRef.current); pollRef.current = null; }
                if (pullPollRef.current) { clearInterval(pullPollRef.current); pullPollRef.current = null; }
                setSyncing(false);
                setPulling(false);
                setSyncProgress(null);
                setPullProgress(null);
                toast({ title: 'Operasi dihentikan' });
              }}
              className="neon-btn-danger w-full px-3 py-2 rounded-lg text-[10px] sm:text-xs flex items-center justify-center gap-1.5"
            >
              <X className="w-3.5 h-3.5" />
              STOP RESET/RESTORE
            </button>
          )}

          {/* Export CSV button */}
          <button
            onClick={handleExportCSV}
            className="neon-btn-orange w-full px-3 py-2 rounded-lg text-[10px] sm:text-xs flex items-center justify-center gap-1.5"
          >
            <Download className="w-3.5 h-3.5" />
            EXPORT CSV
          </button>

          {/* Sync Progress Bar — shown below Export CSV button while syncing */}
          {syncing && syncProgress && (
            <div className="space-y-1.5">
              <div className="flex items-center justify-between">
                <span className="cyber-mono text-[9px] text-cyan-300 truncate flex-1">{syncProgress.label}</span>
                <span className="cyber-mono text-[9px] neon-text-cyan font-bold ml-2 flex-shrink-0">{syncProgress.percentage}%</span>
              </div>
              <div className="w-full h-2 rounded-full bg-gray-700/50 overflow-hidden">
                <div
                  className="h-full rounded-full bg-cyan-400 transition-all duration-500"
                  style={{ width: `${syncProgress.percentage}%`, boxShadow: '0 0 8px rgba(34, 211, 238, 0.5)' }}
                />
              </div>
              <div className="flex items-center justify-between">
                <span className="cyber-mono text-[8px] text-muted-foreground">
                  Chunk {syncProgress.current} / {syncProgress.total}
                </span>
                <span className="cyber-mono text-[8px] text-muted-foreground">
                  {syncProgress.total > 0 ? `${Math.round((syncProgress.current / syncProgress.total) * 100)}% complete` : ''}
                </span>
              </div>
            </div>
          )}

          {/* Pull Progress Bar — shown below sync progress while pulling */}
          {pulling && pullProgress && (
            <div className="space-y-1.5">
              <div className="flex items-center justify-between">
                <span className="cyber-mono text-[9px] text-green-300 truncate flex-1">{pullProgress.label}</span>
                <span className="cyber-mono text-[9px] neon-text-green font-bold ml-2 flex-shrink-0">{pullProgress.percentage}%</span>
              </div>
              <div className="w-full h-2 rounded-full bg-gray-700/50 overflow-hidden">
                <div
                  className="h-full rounded-full bg-green-400 transition-all duration-500"
                  style={{ width: `${pullProgress.percentage}%`, boxShadow: '0 0 8px rgba(74, 222, 128, 0.5)' }}
                />
              </div>
              <div className="flex items-center justify-between">
                <span className="cyber-mono text-[8px] text-muted-foreground">
                  Chunk {pullProgress.current} / {pullProgress.total}
                </span>
                <span className="cyber-mono text-[8px] text-muted-foreground">
                  {pullProgress.total > 0 ? `${Math.round((pullProgress.current / pullProgress.total) * 100)}% diambil` : ''}
                </span>
              </div>
            </div>
          )}

          {/* Sync Status */}
          {lastSyncStatus && (
            <div className={`p-2.5 rounded-lg border flex items-start gap-2 ${lastSyncStatus.success ? 'border-green-400/30 bg-green-400/5' : 'border-red-400/30 bg-red-400/5'}`}>
              {lastSyncStatus.success ? (
                <Check className="w-3.5 h-3.5 text-green-400 flex-shrink-0 mt-0.5" />
              ) : (
                <AlertTriangle className="w-3.5 h-3.5 text-red-400 flex-shrink-0 mt-0.5" />
              )}
              <p className={`text-[10px] cyber-body ${lastSyncStatus.success ? 'text-green-300' : 'text-red-300'}`}>
                {lastSyncStatus.message}
              </p>
            </div>
          )}

          {/* Pull Confirmation Dialog */}
          <AnimatePresence>
            {showPullConfirm && (
              <motion.div
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                className="p-3 rounded-lg border border-red-400/40 bg-red-400/10 space-y-2"
              >
                <div className="flex items-start gap-2">
                  <AlertTriangle className="w-4 h-4 text-red-400 flex-shrink-0 mt-0.5" />
                  <div className="flex-1">
                    <p className="text-[10px] font-bold text-red-300 mb-1">PULL dari Google Sheets?</p>
                    <p className="text-[9px] text-red-300/70 cyber-body">
                      Semua data lokal akan diganti dengan data terakhir di Google Sheets (termasuk data dari auto-sync).
                    </p>
                  </div>
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={handlePull}
                    disabled={pulling}
                    className="flex-1 px-2 py-1.5 rounded-lg text-[10px] bg-red-500/20 border border-red-400/30 text-red-300 hover:bg-red-500/30 transition-colors flex items-center justify-center gap-1 disabled:opacity-40"
                  >
                    {pulling ? <Loader2 className="w-3 h-3 animate-spin" /> : <DatabaseBackup className="w-3 h-3" />}
                    {pulling ? 'PULLING...' : 'YA, PULL'}
                  </button>
                  <button
                    onClick={() => setShowPullConfirm(false)}
                    className="flex-1 px-2 py-1.5 rounded-lg text-[10px] bg-white/5 border border-white/10 text-muted-foreground hover:bg-white/10 transition-colors"
                  >
                    BATAL
                  </button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Quick Setup toggle */}
          <div className="border border-cyan-400/20 rounded-lg overflow-hidden">
            <button
              onClick={() => setShowSetup(!showSetup)}
              className="w-full flex items-center justify-between p-2.5 bg-cyan-400/5 hover:bg-cyan-400/10 transition-colors"
            >
              <div className="flex items-center gap-2">
                <Settings className="w-3.5 h-3.5 text-cyan-400" />
                <span className="cyber-subheading text-[10px] text-cyan-400">PENGATURAN</span>
                {!configured && (
                  <Zap className="w-3 h-3 text-yellow-400 animate-pulse" />
                )}
              </div>
              <ChevronDown className={`w-3.5 h-3.5 text-cyan-400 transition-transform ${showSetup ? 'rotate-180' : ''}`} />
            </button>

            <AnimatePresence>
              {showSetup && (
                <motion.div
                  initial={{ height: 0, opacity: 0 }}
                  animate={{ height: 'auto', opacity: 1 }}
                  exit={{ height: 0, opacity: 0 }}
                  className="overflow-hidden"
                >
                  <div className="p-3 space-y-3 border-t border-cyan-400/10">
                    {/* v7 Update Notice */}
                    <div className="p-2.5 rounded-lg bg-orange-400/10 border border-orange-400/30 flex items-start gap-2">
                      <AlertTriangle className="w-3.5 h-3.5 text-orange-400 flex-shrink-0 mt-0.5" />
                      <div className="text-[10px] text-orange-300 cyber-body space-y-1">
                        <p><strong>PENTING: Update Apps Script ke v7!</strong></p>
                        <p>Versi lama (v6) melakukan merge pada setiap chunk — lambat &amp; bisa korup untuk data besar.</p>
                        <p>v7 menyimpan setiap chunk terpisah (cepat, anti-korupsi). <strong>Update + SYNC ulang</strong> setelah deploy.</p>
                      </div>
                    </div>

                    {!configured && (
                      <div className="p-2.5 rounded-lg bg-yellow-400/10 border border-yellow-400/20 flex items-start gap-2">
                        <AlertTriangle className="w-3.5 h-3.5 text-yellow-400 flex-shrink-0 mt-0.5" />
                        <p className="text-[10px] text-yellow-300 cyber-body">
                          <strong>Sync belum siap.</strong> Ikuti langkah di bawah untuk menghubungkan.
                        </p>
                      </div>
                    )}

                    <ol className="space-y-1.5 text-[10px] text-muted-foreground cyber-body list-decimal list-inside">
                      <li>Buka <a href={SPREADSHEET_URL} target="_blank" rel="noopener noreferrer" className="text-yellow-400 hover:underline">Spreadsheet</a></li>
                      <li>Extensions &rarr; Apps Script &rarr; tempel kode</li>
                      <li>Deploy &rarr; Web app &rarr; Anyone &rarr; Deploy</li>
                      <li>Salin URL, tempel di bawah</li>
                    </ol>

                    <div className="p-2 rounded-lg bg-green-400/5 border border-green-400/15 flex items-center gap-1.5">
                      <Check className="w-3 h-3 text-green-400 flex-shrink-0" />
                      <p className="text-[9px] text-green-300/80">
                        v7 tidak memerlukan izin Drive tambahan
                      </p>
                    </div>

                    {/* Script Code */}
                    <div className="relative">
                      <button
                        onClick={() => setShowCode(!showCode)}
                        className="flex items-center gap-2 text-[10px] text-cyan-400 hover:text-cyan-300 transition-colors mb-2"
                      >
                        <ChevronDown className={`w-3 h-3 transition-transform ${showCode ? 'rotate-180' : ''}`} />
                        {showCode ? 'Sembunyikan' : 'Lihat kode Script (v7)'}
                      </button>
                      <AnimatePresence>
                        {showCode && (
                          <motion.div
                            initial={{ height: 0, opacity: 0 }}
                            animate={{ height: 'auto', opacity: 1 }}
                            exit={{ height: 0, opacity: 0 }}
                            className="overflow-hidden"
                          >
                            <div className="relative group">
                              <pre className="text-[9px] cyber-mono bg-black/40 rounded-lg p-2.5 overflow-x-auto max-h-48 overflow-y-auto border border-cyan-400/10 leading-relaxed">
                                <code className="text-cyan-300/80">{APPS_SCRIPT_CODE}</code>
                              </pre>
                              <button
                                onClick={handleCopyCode}
                                className="absolute top-1.5 right-1.5 p-1 rounded-md bg-cyan-400/10 border border-cyan-400/20 text-cyan-400 hover:bg-cyan-400/20 opacity-0 group-hover:opacity-100 transition-all"
                                title="Salin kode v7"
                              >
                                {copied ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                              </button>
                            </div>
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </div>

                    {/* Script URL Input */}
                    <div className="space-y-1.5">
                      <label className="cyber-mono text-[9px] text-muted-foreground">APPS SCRIPT WEB APP URL</label>
                      <input
                        type="url"
                        value={scriptUrl}
                        onChange={(e) => handleUrlChange(e.target.value)}
                        placeholder="https://script.google.com/macros/s/XXXXX/exec"
                        className={`neon-input w-full px-2.5 py-1.5 rounded-lg text-[10px] ${urlError ? 'border-red-400/60 focus:border-red-400' : ''}`}
                      />
                      {urlError && (
                        <p className="text-[9px] text-red-400 flex items-center gap-1">
                          <X className="w-2.5 h-2.5" />
                          {urlError}
                        </p>
                      )}
                      <div className="flex gap-1.5">
                        <button
                          onClick={handleTestConnection}
                          disabled={testingUrl || !!urlError || !scriptUrl.trim()}
                          className="neon-btn-cyan px-2.5 py-1.5 rounded-lg text-[10px] flex items-center gap-1 disabled:opacity-40 disabled:cursor-not-allowed flex-1"
                        >
                          {testingUrl ? (
                            <Loader2 className="w-3 h-3 animate-spin" />
                          ) : (
                            <Wifi className="w-3 h-3" />
                          )}
                          {testingUrl ? 'TEST...' : 'TEST'}
                        </button>
                        <button
                          onClick={handleSaveUrl}
                          disabled={savingUrl || !!urlError || !scriptUrl.trim()}
                          className="neon-btn-green px-2.5 py-1.5 rounded-lg text-[10px] flex items-center gap-1 disabled:opacity-40 disabled:cursor-not-allowed flex-1"
                        >
                          {savingUrl ? <Loader2 className="w-3 h-3 animate-spin" /> : <Check className="w-3 h-3" />}
                          SIMPAN
                        </button>
                      </div>

                      {testResult && (
                        <div className={`p-2 rounded-lg border flex items-start gap-1.5 ${testResult.success ? 'border-green-400/30 bg-green-400/5' : 'border-red-400/30 bg-red-400/5'}`}>
                          {testResult.success ? (
                            <Wifi className="w-3 h-3 text-green-400 flex-shrink-0 mt-0.5" />
                          ) : (
                            <WifiOff className="w-3 h-3 text-red-400 flex-shrink-0 mt-0.5" />
                          )}
                          <p className={`text-[9px] cyber-body ${testResult.success ? 'text-green-300' : 'text-red-300'}`}>
                            {testResult.message}
                          </p>
                        </div>
                      )}
                    </div>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </div>

        <div className="sl-window-status">
          <span>{configured ? 'CONNECTED' : 'NOT CONFIGURED'}</span>
          <span>SYSTEM ACTIVE</span>
        </div>
      </div>
    </>
  );
}
"},{"path":"src/components/app/GuruView.tsx","content":"'use client';

import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Save, Trash2, AlertTriangle, X, Check, Loader2, RefreshCw, UserCog,
} from 'lucide-react';
import { TeacherData } from './types';
import { safeFetchJson } from '@/lib/fetch';
import { useToast } from '@/hooks/use-toast';

export function GuruView() {
  const { toast } = useToast();
  const [teachers, setTeachers] = useState<TeacherData[]>([]);
  const [original, setOriginal] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [error, setError] = useState('');
  const [deletingNickname, setDeletingNickname] = useState<string | null>(null);

  const fetchTeachers = useCallback(async () => {
    setLoading(true);
    const data = await safeFetchJson('/api/teachers');
    if (data?.teachers) {
      setTeachers(data.teachers);
      const map: Record<string, string> = {};
      for (const t of data.teachers) map[t.nickname] = t.fullName;
      setOriginal(map);
    } else {
      setError('Gagal memuat data guru');
    }
    setLoading(false);
    setSaved(false);
  }, []);

  useEffect(() => { fetchTeachers(); }, [fetchTeachers]);

  const handleFullNameChange = (nickname: string, value: string) => {
    setTeachers(prev => prev.map(t => t.nickname === nickname ? { ...t, fullName: value } : t));
    setSaved(false);
  };

  const isDirty = teachers.some(t => (t.fullName || '') !== (original[t.nickname] || ''));

  const handleSave = async () => {
    setSaving(true);
    setError('');
    try {
      const res = await fetch('/api/teachers', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          teachers: teachers.map(t => ({ nickname: t.nickname, fullName: t.fullName })),
        }),
      });
      const data = await res.json();
      if (data.success) {
        setSaved(true);
        // Refresh from server to get sorted/normalized state
        await fetchTeachers();
        setSaved(true);
        toast({ title: 'Data guru tersimpan!', description: data.message });
      } else {
        setError(data.error || 'Gagal menyimpan');
        toast({ title: 'Gagal menyimpan', description: data.error, variant: 'destructive' });
      }
    } catch {
      setError('Terjadi kesalahan saat menyimpan');
      toast({ title: 'Gagal menyimpan', variant: 'destructive' });
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (nickname: string) => {
    setDeletingNickname(null);
    setSaving(true);
    setError('');
    try {
      const encoded = encodeURIComponent(nickname);
      const res = await fetch(`/api/teachers/${encoded}`, { method: 'DELETE' });
      const data = await res.json();
      if (data.success) {
        toast({
          title: 'Guru dihapus',
          description: `"${nickname}" dan ${data.deletedSchedules} jadwal terkait dihapus`,
        });
        await fetchTeachers();
      } else {
        setError(data.error || 'Gagal menghapus');
        toast({ title: 'Gagal menghapus', description: data.error, variant: 'destructive' });
      }
    } catch {
      setError('Terjadi kesalahan saat menghapus');
      toast({ title: 'Gagal menghapus', variant: 'destructive' });
    } finally {
      setSaving(false);
    }
  };

  const filledCount = teachers.filter(t => t.fullName.trim()).length;
  const emptyCount = teachers.length - filledCount;

  return (
    <div className="space-y-4 sm:space-y-6">
      {/* Header with Save button on top */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div>
          <h2 className="cyber-heading text-xl sm:text-2xl md:text-3xl neon-text-magenta">GURU</h2>
          <p className="cyber-mono text-[10px] sm:text-xs text-muted-foreground mt-1">
            NAMA PANGGILAN &amp; NAMA LENGKAP GURU
          </p>
        </div>
        <div className="flex items-center gap-2">
          <span className="cyber-mono text-[10px] text-muted-foreground">{teachers.length} guru</span>
          <button
            onClick={fetchTeachers}
            disabled={loading}
            className="sl-icon-btn border-[var(--sl-border)] bg-[var(--sl-surface)] hover:bg-[var(--sl-glow-strong)] p-1.5 rounded-lg"
            title="Refresh data guru"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
          </button>
          <button
            onClick={handleSave}
            disabled={!isDirty || saving || loading}
            className={`neon-btn-green px-3 py-1.5 sm:px-4 sm:py-2 rounded-lg text-xs flex items-center gap-1.5 disabled:opacity-40 ${saved ? 'ring-1 ring-green-400/50' : ''}`}
          >
            {saving ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : saved ? <Check className="w-3.5 h-3.5" /> : <Save className="w-3.5 h-3.5" />}
            {saving ? 'Menyimpan...' : saved ? 'Tersimpan' : 'Simpan'}
          </button>
        </div>
      </div>

      {/* Error */}
      <AnimatePresence>
        {error && (
          <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="flex items-center gap-2 p-3 rounded-lg border border-red-400/40 bg-red-400/10">
            <AlertTriangle className="w-4 h-4 text-red-400 flex-shrink-0" />
            <span className="cyber-body text-xs text-red-400 flex-1">{error}</span>
            <button onClick={() => setError('')} className="text-red-400 hover:text-red-300"><X className="w-4 h-4" /></button>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Summary badges */}
      {!loading && teachers.length > 0 && (
        <div className="flex items-center gap-3 flex-wrap">
          <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-green-400/30 bg-green-400/10">
            <Check className="w-4 h-4 text-green-400" />
            <span className="cyber-subheading text-xs neon-text-green">Lengkap: {filledCount}</span>
          </div>
          {emptyCount > 0 && (
            <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-orange-400/30 bg-orange-400/10">
              <AlertTriangle className="w-4 h-4 text-orange-400" />
              <span className="cyber-subheading text-xs neon-text-orange">Belum: {emptyCount}</span>
            </div>
          )}
        </div>
      )}

      {/* Delete confirmation */}
      <AnimatePresence>
        {deletingNickname && (
          <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="neon-card rounded-xl p-4 border border-red-400/40">
            <div className="flex items-start gap-3">
              <AlertTriangle className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
              <div className="flex-1">
                <p className="cyber-body text-sm text-red-400 font-medium">Hapus guru &ldquo;{deletingNickname}&rdquo;?</p>
                <p className="cyber-mono text-[10px] text-muted-foreground mt-1">
                  Semua jadwal mingguan yang menggunakan nama panggilan ini akan ikut terhapus. Aksi ini tidak dapat dibatalkan.
                </p>
                <div className="flex gap-2 mt-3">
                  <button onClick={() => handleDelete(deletingNickname)} className="neon-btn-red px-3 py-1.5 rounded-lg text-xs flex items-center gap-1.5">
                    <Trash2 className="w-3.5 h-3.5" /> <span className="hidden sm:inline">Ya, Hapus</span><span className="sm:hidden">Hapus</span>
                  </button>
                  <button onClick={() => setDeletingNickname(null)} className="px-3 py-1.5 rounded-lg text-xs border border-[var(--sl-border)] cyber-body hover:bg-[var(--sl-glow-strong)] transition-colors">
                    Batal
                  </button>
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Loading state */}
      {loading ? (
        <div className="neon-card rounded-xl p-8 flex items-center justify-center">
          <Loader2 className="w-6 h-6 animate-spin neon-text-cyan" />
        </div>
      ) : teachers.length === 0 ? (
        <div className="neon-card rounded-xl p-8 text-center">
          <UserCog className="w-8 h-8 text-muted-foreground mx-auto mb-2" />
          <p className="cyber-mono text-sm text-muted-foreground">Belum ada data guru</p>
          <p className="cyber-mono text-[10px] text-muted-foreground mt-1">
            Data guru otomatis muncul dari Tab Jadwal Mingguan
          </p>
        </div>
      ) : (
        <>
          {/* Mobile: Card layout */}
          <div className="sm:hidden space-y-2">
            {teachers.map((t, idx) => (
              <motion.div
                key={t.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: idx * 0.03 }}
                className="neon-card rounded-lg p-3 space-y-2"
              >
                <div className="flex items-center justify-between gap-2">
                  <div className="flex items-center gap-2 min-w-0">
                    <span className="cyber-mono text-[10px] text-muted-foreground w-5 text-right flex-shrink-0">{idx + 1}</span>
                    <span className="cyber-heading text-xs neon-text-cyan truncate">{t.nickname}</span>
                  </div>
                  <button
                    onClick={() => setDeletingNickname(t.nickname)}
                    disabled={saving}
                    className="sl-icon-btn border-red-400/40 bg-red-400/5 text-red-400 hover:bg-red-400/15 p-1 flex-shrink-0"
                    title={`Hapus ${t.nickname}`}
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
                <div className="pl-7">
                  <input
                    type="text"
                    value={t.fullName}
                    onChange={e => handleFullNameChange(t.nickname, e.target.value)}
                    className="neon-input w-full px-2.5 py-1.5 rounded-lg text-xs"
                    placeholder="Nama lengkap & gelar..."
                  />
                </div>
              </motion.div>
            ))}
          </div>

          {/* Desktop: Table layout */}
          <div className="hidden sm:block neon-card rounded-xl overflow-hidden">
            <div className="p-3 sm:p-4 border-b border-fuchsia-400/20 bg-fuchsia-400/5">
              <div className="flex items-center gap-2">
                <UserCog className="w-4 h-4 sm:w-5 sm:h-5 neon-text-magenta" />
                <h3 className="cyber-subheading text-[10px] sm:text-sm neon-text-magenta">DATA GURU</h3>
              </div>
            </div>
            <div className="overflow-x-auto">
              <table className="neon-table">
                <thead>
                  <tr>
                    <th className="w-12">NO</th>
                    <th className="w-56">NAMA PANGGILAN</th>
                    <th>NAMA LENGKAP &amp; GELAR</th>
                    <th className="w-20">AKSI</th>
                  </tr>
                </thead>
                <tbody>
                  {teachers.map((t, idx) => {
                    const dirty = (t.fullName || '') !== (original[t.nickname] || '');
                    return (
                      <motion.tr
                        key={t.id}
                        initial={{ opacity: 0, x: -10 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: idx * 0.03 }}
                      >
                        <td className="text-center cyber-mono">{idx + 1}</td>
                        <td>
                          <div className="flex items-center gap-2">
                            <span className="neon-text-cyan font-semibold cyber-body truncate">{t.nickname}</span>
                            {dirty && <span className="w-1.5 h-1.5 rounded-full bg-orange-400 flex-shrink-0" title="Belum disimpan" />}
                          </div>
                        </td>
                        <td>
                          <input
                            type="text"
                            value={t.fullName}
                            onChange={e => handleFullNameChange(t.nickname, e.target.value)}
                            className="neon-input w-full px-3 py-2 rounded-lg"
                            placeholder="Masukkan nama lengkap & gelar..."
                          />
                        </td>
                        <td>
                          <button
                            onClick={() => setDeletingNickname(t.nickname)}
                            disabled={saving}
                            className="sl-icon-btn border-red-400/40 bg-red-400/5 text-red-400 hover:bg-red-400/15"
                            title={`Hapus ${t.nickname}`}
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        </td>
                      </motion.tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </div>
  );
}
"},{"path":"src/components/app/HolidayManager.tsx","content":"'use client';

import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { CalendarOff, Save, X, Plus } from 'lucide-react';
import { safeFetchJson } from '@/lib/fetch';

const DAY_NAMES = ['Ahad', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];

interface Holiday {
  id: string;
  dayOfWeek: number;
  name: string;
  isActive: boolean;
}

export function HolidayManager({ isOpen, onClose }: { isOpen: boolean; onClose: () => void }) {
  const [holidays, setHolidays] = useState<Holiday[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [editDay, setEditDay] = useState<number | null>(null);
  const [editName, setEditName] = useState('');

  const fetchHolidays = useCallback(async () => {
    setLoading(true);
    const data = await safeFetchJson('/api/holidays');
    if (data) setHolidays(data);
    else setHolidays([]);
    setLoading(false);
  }, []);

  useEffect(() => {
    if (isOpen) fetchHolidays();
  }, [isOpen, fetchHolidays]);

  const isHoliday = (day: number) => holidays.some(h => h.dayOfWeek === day);
  const getHolidayName = (day: number) => holidays.find(h => h.dayOfWeek === day)?.name || '';
  const getHolidayId = (day: number) => holidays.find(h => h.dayOfWeek === day)?.id || '';

  const handleToggle = async (day: number) => {
    setSaving(true);
    try {
      if (isHoliday(day)) {
        const id = getHolidayId(day);
        await fetch(`/api/holidays/${id}`, { method: 'DELETE' });
      } else {
        await fetch('/api/holidays', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ dayOfWeek: day, name: `Hari ${DAY_NAMES[day]}` }) });
      }
      fetchHolidays();
      // Notify other components (e.g. JadwalMingguanView) to re-fetch holidays
      window.dispatchEvent(new CustomEvent('holidays-changed'));
    } catch (e) { console.error(e); } finally { setSaving(false); }
  };

  const handleSaveName = async () => {
    if (editDay === null || !editName.trim()) return;
    setSaving(true);
    try {
      await fetch('/api/holidays', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ dayOfWeek: editDay, name: editName.trim() }) });
      setEditDay(null);
      setEditName('');
      fetchHolidays();
      // Notify other components (e.g. JadwalMingguanView) to re-fetch holidays
      window.dispatchEvent(new CustomEvent('holidays-changed'));
    } catch (e) { console.error(e); } finally { setSaving(false); }
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4" onClick={onClose}>
        <motion.div initial={{ opacity: 0, scale: 0.9, y: 20 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={{ opacity: 0, scale: 0.9, y: 20 }} className="sl-dialog p-0 w-full max-w-lg max-h-[85vh] overflow-hidden" onClick={(e) => e.stopPropagation()}>
          <div className="sl-window-title">
            <div className="sl-window-dots"><span /><span /><span /></div>
            <CalendarOff className="w-4 h-4" />
            <span className="flex-1 text-center">HARI LIBUR AKADEMIK</span>
            <div className="w-[42px]" />
          </div>
          <div className="p-5 space-y-4 max-h-[calc(85vh-100px)] overflow-y-auto">
          {loading ? (
            <div className="py-8 text-center"><div className="cyber-mono text-sm text-muted-foreground animate-neon-pulse">LOADING...</div></div>
          ) : (
            <div className="space-y-2">
              {DAY_NAMES.map((dayName, idx) => {
                const checked = isHoliday(idx);
                const isEditing = editDay === idx;
                return (
                  <div key={idx} className={`flex items-center gap-3 p-3 rounded-lg border transition-all ${checked ? 'border-fuchsia-400/40 bg-fuchsia-400/10' : 'border-cyan-400/20 bg-cyan-400/5'}`}>
                    <input type="checkbox" checked={checked} onChange={() => handleToggle(idx)} disabled={saving} className="w-4 h-4 rounded accent-fuchsia-500 cursor-pointer" />
                    <span className={`cyber-body text-sm flex-1 ${checked ? 'text-fuchsia-300' : 'text-foreground'}`}>{dayName}</span>
                    {checked && !isEditing && (
                      <span className="cyber-mono text-xs text-fuchsia-400 truncate max-w-[180px]">{getHolidayName(idx)}</span>
                    )}
                    {checked && !isEditing && (
                      <button onClick={() => { setEditDay(idx); setEditName(getHolidayName(idx)); }} className="p-1 rounded border border-cyan-400/30 text-cyan-400 hover:bg-cyan-400/10" title="Edit nama"><Plus className="w-3 h-3" /></button>
                    )}
                    {isEditing && (
                      <div className="flex items-center gap-1.5">
                        <input type="text" value={editName} onChange={(e) => setEditName(e.target.value)} className="neon-input px-2 py-1 rounded-lg text-xs w-36" placeholder="Nama libur" autoFocus onKeyDown={(e) => { if (e.key === 'Enter') handleSaveName(); if (e.key === 'Escape') { setEditDay(null); setEditName(''); } }} />
                        <button onClick={handleSaveName} disabled={saving || !editName.trim()} className="p-1 rounded border border-green-400/30 text-green-400 hover:bg-green-400/10 disabled:opacity-30" title="Simpan"><Save className="w-3 h-3" /></button>
                        <button onClick={() => { setEditDay(null); setEditName(''); }} className="p-1 rounded border border-red-400/30 text-red-400 hover:bg-red-400/10" title="Batal"><X className="w-3 h-3" /></button>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
          <div className="mt-4 p-3 rounded-lg bg-cyan-400/5 border border-cyan-400/20">
            <p className="cyber-mono text-[10px] text-cyan-400">ℹ️ Tandai hari libur sesuai kebutuhan. Hari yang ditandai akan otomatis menyetel status aktivitas menjadi &quot;Libur&quot;.</p>
          </div>
          </div>
          <div className="sl-window-status">
            <span>SYSTEM</span>
            <span>ACTIVE</span>
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
}
"},{"path":"src/components/app/IsiAbsensiTab.tsx","content":"'use client';

import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Save, Lock, Unlock, AlertTriangle, Check, X,
  Clock, Calendar, Download, Upload, FileSpreadsheet, FileText, ChevronDown, Loader2, Zap
} from 'lucide-react';
import { ClassData, Student, AttendanceRecord, AttendanceStatus, ActivityStatus, HOURS, ATTENDANCE_COLORS } from './types';
import { safeFetchJson } from '@/lib/fetch';
import { useToast } from '@/hooks/use-toast';
import { getDayOfWeekUTC } from '@/lib/utils';
import { CyberCalendar } from './CyberCalendar';

interface IsiAbsensiTabProps {
  classData: ClassData;
  students: Student[];
  selectedDate: string;
  activityStatus: ActivityStatus;
  role: 'admin' | 'guru';
  onRefresh: () => void;
  onDateChange: (date: string) => void;
}

const STATUS_OPTIONS: AttendanceStatus[] = ['Hadir', 'Terlambat', 'Alfa', 'Sakit', 'Izin'];

// ISI CEPAT quick-fill statuses — Terlambat intentionally excluded (set via the main table)
const QUICK_FILL_STATUSES: AttendanceStatus[] = ['Hadir', 'Sakit', 'Izin', 'Alfa'];

// Server reset state — fetched from /api/sync-status when the confirmation
// popup opens. If serverReset is true (local count < GitHub count), the
// "Sudah" button is disabled until pull-diff completes.
interface ServerResetState {
  serverReset: boolean;
  localCount: number;
  ghCount: number;
  pullDiffRunning: boolean;
  progress: { current: number; total: number; percentage: number; label: string } | null;
}

export function IsiAbsensiTab({ classData, students, selectedDate, activityStatus, role, onRefresh, onDateChange }: IsiAbsensiTabProps) {
  const { toast } = useToast();
  const [selectedHours, setSelectedHours] = useState<number[]>([]);
  const [attendanceData, setAttendanceData] = useState<Record<string, AttendanceStatus>>({});
  const [existingAttendance, setExistingAttendance] = useState<AttendanceRecord[]>([]);
  const [lockedHours, setLockedHours] = useState<Set<number>>(new Set());
  const [editMode, setEditMode] = useState(false);
  const [saving, setSaving] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  // Server reset state — polled when the confirmation popup is open.
  // If serverReset is true (local count < GitHub count) OR pull-diff is
  // running, the "Sudah" button is disabled until pull-diff completes.
  const [resetState, setResetState] = useState<ServerResetState | null>(null);
  const [countdownSec, setCountdownSec] = useState<number>(0);
  const showConfirmRef = useRef(false);
  showConfirmRef.current = showConfirm;
  // Track whether the countdown has been started for this popup session.
  // Prevents the polling from resetting the countdown to 30 every time it
  // reaches 0 (which would block the user indefinitely).
  const countdownStartedRef = useRef(false);
  // Track the last pull-diff progress to estimate countdown
  const lastProgressRef = useRef<{ current: number; total: number } | null>(null);
  const [showDownloadMenu, setShowDownloadMenu] = useState(false);
  const [showUploadMenu, setShowUploadMenu] = useState(false);
  const [holidayName, setHolidayName] = useState<string | null>(null);
  const [maxHoursForDay, setMaxHoursForDay] = useState(8);
  const [showCalendar, setShowCalendar] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadMsg, setUploadMsg] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const csvInputRef = useRef<HTMLInputElement>(null);
  const excelInputRef = useRef<HTMLInputElement>(null);

  // ===== ISI CEPAT (quick-fill) state =====
  // quickAttendance maps studentId -> status applied to ALL selected hours.
  // It is intentionally NOT cleared when the modal closes — cleared after a
  // successful save so the user can reopen and continue where they left off.
  const [showQuickFill, setShowQuickFill] = useState(false);
  const [showQuickCalendar, setShowQuickCalendar] = useState(false);
  const [quickAttendance, setQuickAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [selectedQuickStudent, setSelectedQuickStudent] = useState<string | null>(null);
  const quickDateLabel = useMemo(() => {
    try {
      return new Date(`${selectedDate}T00:00:00`).toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
    } catch { return selectedDate; }
  }, [selectedDate]);

  // Reset quick-fill popup calendar + tapped student when the modal closes
  useEffect(() => {
    if (!showQuickFill) {
      setShowQuickCalendar(false);
      setSelectedQuickStudent(null);
    }
  }, [showQuickFill]);

  // Fetch holiday info (weekly academic holidays + per-date holidays)
  useEffect(() => {
    const checkHoliday = async () => {
      const dow = getDayOfWeekUTC(selectedDate);
      // Check weekly academic holidays
      const holidays = await safeFetchJson('/api/holidays');
      if (holidays) {
        const weeklyMatch = holidays.find((h: { dayOfWeek: number; name: string; isActive: boolean }) => h.dayOfWeek === dow && h.isActive);
        if (weeklyMatch) { setHolidayName(weeklyMatch.name); return; }
      }
      // Check per-date holidays (e.g., national holidays)
      const dateHoliday = await safeFetchJson(`/api/date-holidays?date=${selectedDate}`);
      if (dateHoliday && dateHoliday.date) {
        setHolidayName(dateHoliday.name);
        return;
      }
      setHolidayName(null);
    };
    checkHoliday();
  }, [selectedDate]);

  // Fetch per-date max hours
  useEffect(() => {
    const fetchMaxHours = async () => {
      const data = await safeFetchJson(`/api/daily-hours?date=${selectedDate}`);
      if (data) setMaxHoursForDay(data.maxHours ?? 8);
    };
    fetchMaxHours();
  }, [selectedDate]);

  const availableHours = useMemo(() => HOURS.filter(h => h <= maxHoursForDay), [maxHoursForDay]);
  const isHolidayDisabled = holidayName !== null || activityStatus === 'Libur';

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, expectedExt: string) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    setUploadMsg(null);
    try {
      const fd = new FormData();
      fd.append('file', file);
      fd.append('classId', classData.id);
      fd.append('date', selectedDate);
      const res = await fetch('/api/attendance/template', { method: 'POST', body: fd });
      const data = await res.json();
      if (res.ok) {
        const parts = [data.message || `Berhasil: ${data.savedCount} data`];
        if (data.warnings && data.warnings.length > 0) {
          parts.push(data.warnings.join(' | '));
        }
        setUploadMsg(parts.join('\n'));
        fetchAttendance();
        onRefresh();
      } else {
        const parts = [data.error || 'Gagal mengimpor'];
        if (data.detail) parts.push(data.detail);
        setUploadMsg(parts.join('\n'));
      }
    } catch {
      setUploadMsg('Gagal mengimpor file: koneksi terputus atau server tidak merespon.');
    }
    setUploading(false);
    // Reset the correct input
    if (expectedExt === '.csv' && csvInputRef.current) csvInputRef.current.value = '';
    if (expectedExt === '.xlsx' && excelInputRef.current) excelInputRef.current.value = '';
  };

  const fetchAttendance = useCallback(async () => {
    const data = await safeFetchJson(`/api/attendance?classId=${classData.id}&date=${selectedDate}`);
    setExistingAttendance(data || []);
    const locked = new Set<number>();
    (data || []).forEach((r: AttendanceRecord) => locked.add(r.hour));
    setLockedHours(locked);
  }, [classData.id, selectedDate]);

  useEffect(() => { fetchAttendance(); }, [fetchAttendance]);
  useEffect(() => { setSelectedHours([]); setAttendanceData({}); setEditMode(false); }, [selectedDate]);

  // ===== SERVER RESET DETECTION (countdown timer on confirmation popup) =====
  // When the confirmation popup is open, poll /api/sync-status every 2s to
  // detect server reset condition (local count < GitHub count). If detected,
  // show a countdown timer + progress bar and DISABLE the "Sudah" button
  // until pull-diff completes (serverReset becomes false AND no pull-diff running).
  useEffect(() => {
    if (!showConfirm) {
      setResetState(null);
      setCountdownSec(0);
      // Reset the "countdown started" flag when popup closes
      countdownStartedRef.current = false;
      lastProgressRef.current = null;
      return;
    }
    let cancelled = false;
    let intervalId: ReturnType<typeof setTimeout> | null = null;

    const poll = async () => {
      if (cancelled || !showConfirmRef.current) return;
      try {
        const res = await fetch('/api/sync-status', { cache: 'no-store' });
        const data = await res.json();
        if (cancelled) return;
        const newState: ServerResetState = {
          serverReset: !!data.serverReset,
          localCount: data.localCount || 0,
          ghCount: data.ghCount || 0,
          pullDiffRunning: !!data.pullDiffRunning,
          progress: data.progress || null,
        };
        setResetState(newState);

        // Start countdown ONCE when server reset is first detected.
        // Don't reset it again — once the countdown starts, let it run to 0.
        if (newState.pullDiffRunning && newState.progress && newState.progress.total > 0) {
          // Pull-diff is running with progress — estimate remaining time
          const remaining = newState.progress.total - newState.progress.current;
          // Estimate: ~0.5s per chunk (generous; actual is ~200-500ms)
          const estSec = Math.max(1, Math.ceil(remaining * 0.5));
          lastProgressRef.current = { current: newState.progress.current, total: newState.progress.total };
          if (!countdownStartedRef.current) {
            // First time detecting pull-diff — set countdown to the estimate
            countdownStartedRef.current = true;
            setCountdownSec(estSec);
          }
          // If countdown is already started, let it count down — don't increase
          // (the estimate may fluctuate, but we want a smooth countdown)
        } else if (newState.serverReset && !newState.pullDiffRunning) {
          // Server reset detected but pull-diff not yet running — start a 30s
          // safety countdown. After it reaches 0, the button enables (we assume
          // pull-diff won't start, or it's safe to proceed).
          if (!countdownStartedRef.current) {
            countdownStartedRef.current = true;
            setCountdownSec(30);
          }
          // If countdown already started, don't reset — let it run to 0
        } else if (!newState.serverReset && !newState.pullDiffRunning) {
          // No server reset and no pull-diff — clear countdown, button enabled
          setCountdownSec(0);
        }
      } catch {
        // Non-fatal: don't block saves if status check fails
      }
    };

    // Initial poll immediately
    poll();
    // Then poll every 2 seconds
    intervalId = setInterval(poll, 2000);

    return () => {
      cancelled = true;
      if (intervalId) clearInterval(intervalId);
    };
  }, [showConfirm]);

  // Countdown timer — decrement every second until 0
  const isCounting = countdownSec > 0;
  useEffect(() => {
    if (!isCounting) return;
    const timer = setInterval(() => {
      setCountdownSec(prev => (prev > 0 ? prev - 1 : 0));
    }, 1000);
    return () => clearInterval(timer);
  }, [isCounting]);

  // Block save when server reset is detected AND we're still waiting for
  // pull-diff to complete. The "Sudah" button enables when EITHER:
  //   - countdown timer reaches 0 (estimated wait time elapsed), OR
  //   - pull-diff finishes running (currentOperation no longer 'pull-diff')
  // Per user's request: "tombol Sudah non aktif hingga count down timer
  // mencapai 0 atau pull diff selesai berjalan" (disabled until countdown
  // reaches 0 OR pull-diff finishes).
  //
  // Logic:
  //   - No server reset AND no pull-diff running → don't block
  //   - Server reset detected, pull-diff NOT running, countdown > 0 → BLOCK
  //     (waiting for pull-diff to start, countdown is a safety timer)
  //   - Server reset detected, pull-diff running, countdown > 0 → BLOCK
  //     (pull-diff in progress, countdown estimates remaining time)
  //   - Countdown reaches 0 → ENABLE (safety timer expired)
  //   - Pull-diff finished (not running) AND countdown == 0 → ENABLE
  const isBlockedByReset = (() => {
    if (!resetState) return false;
    // No server reset condition at all → never block
    if (!resetState.serverReset && !resetState.pullDiffRunning) return false;
    // Countdown reached 0 → enable (safety timer expired, one OR condition met)
    if (countdownSec <= 0) return false;
    // Pull-diff finished AND countdown == 0 → already handled above
    // If we get here: countdown > 0 AND (serverReset OR pullDiffRunning) → BLOCK
    return true;
  })();

  const toggleHour = (hour: number) => {
    if (isHolidayDisabled) return;
    if (lockedHours.has(hour) && !editMode) return;
    setSelectedHours(prev => {
      if (prev.includes(hour)) return prev.filter(h => h !== hour);
      return [...prev, hour].sort();
    });
    setAttendanceData(prev => {
      const newData = { ...prev };
      students.forEach(s => { const key = `${s.id}-${hour}`; if (!newData[key]) newData[key] = 'Hadir'; });
      return newData;
    });
  };

  const handleStatusChange = (studentId: string, hour: number, status: AttendanceStatus) => {
    setAttendanceData(prev => ({ ...prev, [`${studentId}-${hour}`]: status }));
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      // Save all selected hours IN PARALLEL (Promise.all) — much faster than sequential awaits.
      // For 8 hours: sequential = 8 × ~75ms = 600ms+ on dev (and 8 × ~1-3s on prod → timeout).
      // Parallel = max(~75ms) on dev, max(~1-3s) on prod → single round-trip-equivalent latency.
      // Each request has its own AbortController with 30s timeout to prevent infinite hangs.
      const saveOneHour = async (hour: number): Promise<{ hour: number; ok: boolean; error?: string }> => {
        const records = students.map(s => ({ studentId: s.id, status: attendanceData[`${s.id}-${hour}`] || 'Hadir' }));
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 30000);
        try {
          const res = await fetch('/api/attendance', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ classId: classData.id, date: selectedDate, hour, records }),
            signal: controller.signal,
          });
          if (res.ok) return { hour, ok: true };
          const err = await res.json().catch(() => ({}));
          // Map HTTP 507 (disk full) to a user-friendly message
          if (res.status === 507 || (err.error && err.error.includes('penuh'))) {
            return { hour, ok: false, error: 'Disk server penuh — sistem sedang membersihkan, coba lagi 10 detik.' };
          }
          return { hour, ok: false, error: err.error || `HTTP ${res.status}` };
        } catch (e) {
          const msg = (e instanceof DOMException && e.name === 'AbortError')
            ? 'Timeout — server terlalu lambat merespon (30detik)'
            : (e instanceof Error ? e.message : 'Network error');
          return { hour, ok: false, error: msg };
        } finally {
          clearTimeout(timeoutId);
        }
      };

      const results = await Promise.all(selectedHours.map(saveOneHour));
      const savedCount = results.filter(r => r.ok).length;
      const failedCount = results.filter(r => !r.ok).length;
      const firstError = results.find(r => !r.ok)?.error || '';

      if (failedCount === 0) {
        // All succeeded — show green success toast (was silent before, user didn't know if it worked)
        setShowConfirm(false); setEditMode(false); setQuickAttendance({}); setSelectedQuickStudent(null); fetchAttendance(); onRefresh();
        toast({ title: 'Tersimpan!', description: `${savedCount} jam absensi berhasil disimpan.` });
      } else if (savedCount === 0) {
        // All failed
        console.error('Save error (all failed):', firstError);
        toast({ title: 'Gagal menyimpan', description: firstError, variant: 'destructive' });
      } else {
        // Partial success
        setShowConfirm(false); setEditMode(false); setQuickAttendance({}); setSelectedQuickStudent(null); fetchAttendance(); onRefresh();
        toast({ title: 'Sebagian tersimpan', description: `${savedCount} jam tersimpan, ${failedCount} gagal: ${firstError}`, variant: 'destructive' });
      }
    } catch (e) {
      console.error('Save error:', e);
      toast({ title: 'Gagal menyimpan', description: e instanceof Error ? e.message : 'Unknown error', variant: 'destructive' });
    } finally { setSaving(false); }
  };

  // ===== ISI CEPAT (quick-fill) =====
  // Applies quickAttendance status to every selected hour for every student,
  // then opens the shared confirmation dialog — handleSave does the actual
  // POSTs (with server-reset protection) once the user confirms.
  // The modal is closed here so the confirm dialog (earlier in the DOM, same
  // z-50 stacking) is not covered by the still-open quick-fill modal.
  const handleQuickSave = () => {
    if (selectedHours.length === 0 || students.length === 0 || isHolidayDisabled) return;
    setAttendanceData(prev => {
      const next = { ...prev };
      students.forEach(s => {
        const st = quickAttendance[s.id] || 'Hadir';
        selectedHours.forEach(h => { next[`${s.id}-${h}`] = st; });
      });
      return next;
    });
    setShowQuickFill(false);
    setShowConfirm(true);
  };

  // Students without a quick-fill status yet — shown in the tap pool
  const unassignedStudents = students.filter(s => !quickAttendance[s.id]);

  useEffect(() => {
    if (selectedHours.length > 0) {
      const newData: Record<string, AttendanceStatus> = {};
      existingAttendance.forEach(record => {
        if (selectedHours.includes(record.hour)) newData[`${record.studentId}-${record.hour}`] = record.status as AttendanceStatus;
      });
      setAttendanceData(prev => ({ ...prev, ...newData }));
    }
  }, [existingAttendance, selectedHours]);

  return (
    <div className="space-y-4">
      {/* Holiday notices */}
      {holidayName && (
        <motion.div initial={{ opacity: 0, y: -10, scale: 0.98 }} animate={{ opacity: 1, y: 0, scale: 1 }} className="rounded-xl p-5 border-2 border-fuchsia-500/60 bg-fuchsia-500/10 backdrop-blur-sm" style={{ boxShadow: '0 0 20px rgba(217,70,239,0.15), inset 0 0 20px rgba(217,70,239,0.05)' }}>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-fuchsia-500/20 border border-fuchsia-500/40 flex items-center justify-center flex-shrink-0"><AlertTriangle className="w-5 h-5 text-fuchsia-400" /></div>
            <div>
              <p className="cyber-heading text-sm sm:text-base text-fuchsia-300">📌 HARI LIBUR AKADEMIK — {holidayName}</p>
              <p className="cyber-mono text-xs text-muted-foreground mt-1">Absensi dinonaktifkan untuk hari ini.</p>
            </div>
          </div>
        </motion.div>
      )}
      {activityStatus === 'Libur' && (
        <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} className="neon-card rounded-xl p-4 border-l-4 border-fuchsia-500">
          <div className="flex items-center gap-3">
            <AlertTriangle className="w-5 h-5 text-fuchsia-400" />
            <div><p className="cyber-subheading text-sm neon-text-magenta">HARI INI LIBUR</p><p className="cyber-mono text-xs text-muted-foreground">Tidak perlu mengisi absensi pada tanggal ini</p></div>
          </div>
        </motion.div>
      )}

      {/* Action buttons + Mobile mini calendar */}
      <div className="flex flex-wrap items-center justify-center sm:justify-start gap-1.5 sm:gap-2">
        {/* Mobile mini calendar trigger */}
        <div className="relative sm:hidden">
          <button onClick={() => setShowCalendar(!showCalendar)} className="neon-btn px-3 py-2 rounded-lg text-[11px] flex items-center justify-center gap-1.5 min-h-[40px]">
            <Calendar className="w-3 h-3" />
            <span className="truncate max-w-[100px]">{selectedDate}</span>
          </button>
          <AnimatePresence>
            {showCalendar && (
              <>
                <div className="fixed inset-0 z-20" onClick={() => setShowCalendar(false)} />
                <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }} className="absolute top-full left-0 mt-1 z-30 neon-card rounded-lg border border-cyan-400/30 shadow-lg p-2" style={{ minWidth: 260 }}>
                  <CyberCalendar value={selectedDate} onChange={(d) => { onDateChange(d); setShowCalendar(false); }} />
                </motion.div>
              </>
            )}
          </AnimatePresence>
        </div>

        <button onClick={() => setEditMode(!editMode)} className={editMode ? 'neon-btn-magenta px-3 sm:px-3.5 py-2 rounded-lg text-[11px] sm:text-xs flex items-center justify-center gap-1.5 min-h-[40px]' : 'neon-btn-orange px-3 sm:px-3.5 py-2 rounded-lg text-[11px] sm:text-xs flex items-center justify-center gap-1.5 min-h-[40px]'}>
          {editMode ? <><Unlock className="w-3 h-3 sm:w-3.5 sm:h-3.5" /><span className="hidden sm:inline">Batal Edit</span><span className="sm:hidden">Edit</span></> : <><Unlock className="w-3 h-3 sm:w-3.5 sm:h-3.5" /><span className="hidden sm:inline">Edit Absensi</span><span className="sm:hidden">Edit</span></>}
        </button>

        {/* ISI CEPAT — quick-fill modal trigger */}
        <button disabled={isHolidayDisabled} onClick={() => setShowQuickFill(true)} className="neon-btn px-3 sm:px-3.5 py-2 rounded-lg text-[11px] sm:text-xs flex items-center justify-center gap-1.5 min-h-[40px]">
          <Zap className="w-3.5 h-3.5" /> <span className="hidden sm:inline">ISI CEPAT</span><span className="sm:hidden">CEPAT</span>
        </button>

        {/* Download & Upload template (admin only) */}
        {role === 'admin' && (
          <>
            {/* Download dropdown */}
            <div className="relative">
              <button onClick={() => { setShowDownloadMenu(!showDownloadMenu); setShowUploadMenu(false); }} className="neon-btn px-3 sm:px-3.5 py-2 rounded-lg text-[11px] sm:text-xs flex items-center justify-center gap-1.5 min-h-[40px]">
                <Download className="w-3 h-3 sm:w-3.5 sm:h-3.5" /> <span className="hidden sm:inline">Download</span><ChevronDown className="w-2.5 h-2.5 sm:w-3 sm:h-3" />
              </button>
              <AnimatePresence>
                {showDownloadMenu && (
                  <>
                    <div className="fixed inset-0 z-20" onClick={() => setShowDownloadMenu(false)} />
                    <motion.div initial={{ opacity: 0, y: -4, scale: 0.97 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: -4, scale: 0.97 }} className="absolute top-full left-0 mt-1 z-30 neon-card rounded-lg border border-cyan-400/30 shadow-lg overflow-hidden min-w-[160px]">
                      <button onClick={() => { window.open(`/api/attendance/template?classId=${classData.id}&date=${selectedDate}&format=csv`, '_blank'); setShowDownloadMenu(false); }} className="w-full flex items-center gap-2 px-3 py-2.5 text-xs hover:bg-cyan-400/10 transition-colors text-left">
