                        <div><p className="cyber-body font-medium">CSV</p><p className="cyber-mono text-[10px] text-muted-foreground">.csv file</p></div>
                      </button>
                      <div className="border-t border-cyan-400/15" />
                      <button onClick={() => { window.open(`/api/attendance/template?classId=${classData.id}&date=${selectedDate}&format=excel`, '_blank'); setShowDownloadMenu(false); }} className="w-full flex items-center gap-2 px-3 py-2.5 text-xs hover:bg-cyan-400/10 transition-colors text-left">
                        <FileSpreadsheet className="w-4 h-4 text-green-400" />
                        <div><p className="cyber-body font-medium">Excel</p><p className="cyber-mono text-[10px] text-muted-foreground">.xlsx file</p></div>
                      </button>
                    </motion.div>
                  </>
                )}
              </AnimatePresence>
            </div>

            {/* Upload dropdown */}
            <div className="relative">
              <button onClick={() => { setShowUploadMenu(!showUploadMenu); setShowDownloadMenu(false); }} disabled={uploading} className="neon-btn px-3 sm:px-3.5 py-2 rounded-lg text-[11px] sm:text-xs flex items-center justify-center gap-1.5 min-h-[40px]">
