                      <button onClick={() => { setShowUploadMenu(false); csvInputRef.current?.click(); }} className="w-full flex items-center gap-2 px-3 py-2.5 text-xs hover:bg-cyan-400/10 transition-colors text-left">
                        <FileText className="w-4 h-4 text-cyan-400" />
