                      </button>
                      <div className="border-t border-cyan-400/15" />
                      <button onClick={() => { setShowUploadMenu(false); excelInputRef.current?.click(); }} className="w-full flex items-center gap-2 px-3 py-2.5 text-xs hover:bg-cyan-400/10 transition-colors text-left">
                        <FileSpreadsheet className="w-4 h-4 text-green-400" />
                        <div><p className="cyber-body font-medium">Excel</p><p className="cyber-mono text-[10px] text-muted-foreground">.xlsx file</p></div>
                      </button>
                    </motion.div>
                  </>
                )}
              </AnimatePresence>
            </div>

            {/* Hidden file inputs */}
            <input ref={csvInputRef} type="file" accept=".csv" className="hidden" onChange={async (e) => { await handleFileUpload(e, '.csv'); }} />
            <input ref={excelInputRef} type="file" accept=".xlsx,.xls" className="hidden" onChange={async (e) => { await handleFileUpload(e, '.xlsx'); }} />
          </>
        )}
        <div className="flex-1" />
        {uploadMsg && (
