import { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Download, Upload, Save, Loader2, Check, AlertTriangle, CalendarDays, RefreshCw, X,
} from 'lucide-react';
import { ClassData } from './types';
import { safeFetchJson } from '@/lib/fetch';
import { useToast } from '@/hooks/use-toast';

interface JadwalMingguanViewProps {
  classes: ClassData[];
}

const ALL_DAYS = ['Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu', 'Ahad'];
const DAY_NUMS = [1, 2, 3, 4, 5, 6, 0]; // dayOfWeek values
const HOURS = [1, 2, 3, 4, 5, 6, 7, 8];

type ScheduleMap = Record<string, string>; // "dayOfWeek-hour" -> teacher name

export function JadwalMingguanView({ classes }: JadwalMingguanViewProps) {
  const { toast } = useToast();
  const [activeClassId, setActiveClassId] = useState<string>('');
  const [activeDays, setActiveDays] = useState<number[]>(DAY_NUMS);
  const [scheduleMap, setScheduleMap] = useState<ScheduleMap>({});
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [saved, setSaved] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Set initial class
  useEffect(() => {
    if (classes.length > 0 && !activeClassId) {
      setActiveClassId(classes[0].id);
    }
  }, [classes, activeClassId]);

  // Fetch academic holidays to determine active days
  const fetchHolidays = useCallback(async () => {
    const data = await safeFetchJson('/api/holidays');
    if (Array.isArray(data)) {
      const holidayDays = new Set(
        (data as { dayOfWeek: number; isActive: boolean }[])
          .filter(h => h.isActive)
          .map(h => h.dayOfWeek)
      );
      setActiveDays(DAY_NUMS.filter(d => !holidayDays.has(d)));
    }
  }, []);

  // Fetch schedules for active class
  const fetchSchedules = useCallback(async (classId: string) => {
    if (!classId) return;
    setLoading(true);
    const data = await safeFetchJson(`/api/schedules?classId=${classId}`);
    if (data?.schedules) {
      const map: ScheduleMap = {};
      for (const s of data.schedules) {
        map[`${s.dayOfWeek}-${s.hour}`] = s.teacher;
      }
      setScheduleMap(map);
    }
    setLoading(false);
  }, []);

  // Fetch holidays on mount
  useEffect(() => { fetchHolidays(); }, [fetchHolidays]);

  // Re-fetch holidays when document becomes visible (user returns from settings)
  // or when holidays are changed via HolidayManager
  useEffect(() => {
    const onVisibility = () => {
      if (document.visibilityState === 'visible') fetchHolidays();
    };
    const onHolidaysChanged = () => fetchHolidays();
    document.addEventListener('visibilitychange', onVisibility);
    window.addEventListener('holidays-changed', onHolidaysChanged);
    return () => {
      document.removeEventListener('visibilitychange', onVisibility);
      window.removeEventListener('holidays-changed', onHolidaysChanged);
    };
  }, [fetchHolidays]);

  useEffect(() => {
    if (activeClassId) {
      fetchSchedules(activeClassId);
    }
  }, [activeClassId, fetchSchedules]);

  const handleCellChange = (dayOfWeek: number, hour: number, value: string) => {
    const key = `${dayOfWeek}-${hour}`;
    setScheduleMap(prev => ({ ...prev, [key]: value }));
    setSaved(false);
  };

  const handleSave = useCallback(async () => {
    if (!activeClassId) return;
    setSaving(true);
    setError('');
    try {
      const schedules = Object.entries(scheduleMap)
        .filter(([, v]) => v.trim())
        .map(([key, teacher]) => {
          const [dayOfWeek, hour] = key.split('-').map(Number);
          return { dayOfWeek, hour, teacher: teacher.trim() };
        });

      const res = await fetch('/api/schedules', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ classId: activeClassId, schedules }),
      });
      const data = await res.json();
      if (data.success) {
        setSaved(true);
        toast({ title: 'Jadwal tersimpan!', description: data.message });
      } else {
        setError(data.error || 'Gagal menyimpan');
        toast({ title: 'Gagal menyimpan', description: data.error, variant: 'destructive' });
      }
    } catch {
      setError('Terjadi kesalahan');
      toast({ title: 'Gagal menyimpan', variant: 'destructive' });
    } finally {
      setSaving(false);
    }
  }, [activeClassId, scheduleMap, toast]);

  const handleDownload = useCallback(() => {
    if (!activeClassId) return;
    window.open(`/api/schedules/download?classId=${activeClassId}`, '_blank');
  }, [activeClassId]);

  const handleUpload = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !activeClassId) return;
    setUploading(true);
    setError('');
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('classId', activeClassId);
      const res = await fetch('/api/schedules/upload', {
        method: 'POST',
        body: formData,
      });
      const data = await res.json();
      if (data.success) {
        toast({ title: 'Upload berhasil!', description: data.message });
        fetchSchedules(activeClassId);
      } else {
        setError(data.error || 'Gagal mengupload');
        toast({ title: 'Upload gagal', description: data.error, variant: 'destructive' });
      }
    } catch {
      setError('Terjadi kesalahan saat upload');
      toast({ title: 'Upload gagal', variant: 'destructive' });
    } finally {
      setUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  }, [activeClassId, fetchSchedules, toast]);

  const getDayName = (dayOfWeek: number) => {
    return ALL_DAYS[DAY_NUMS.indexOf(dayOfWeek)] || '???';
  };

  return (
    <div className="space-y-4 sm:space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
        <div>
          <h2 className="cyber-heading text-xl sm:text-2xl md:text-3xl neon-text-magenta">JADWAL MINGGUAN</h2>
          <p className="cyber-mono text-[10px] sm:text-xs text-muted-foreground mt-1">MANAJEMEN JADWAL MINGGUAN PER KELAS</p>
        </div>
      </div>

      {/* Error */}
      <AnimatePresence>
        {error && (
          <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="flex items-center gap-2 p-3 rounded-lg border border-red-400/40 bg-red-400/10">
            <AlertTriangle className="w-4 h-4 text-red-400 flex-shrink-0" />
            <span className="cyber-body text-xs text-red-400 flex-1">{error}</span>
            <button onClick={() => setError('')} className="text-red-400 hover:text-red-300"><X className="w-4 h-4" /></button>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Class sub-tabs */}
      <div className="flex gap-1.5 overflow-x-auto pb-1 scrollbar-thin">
        {classes.map(cls => (
          <button
            key={cls.id}
            onClick={() => { setActiveClassId(cls.id); setSaved(false); setError(''); }}
            className={`px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap transition-all ${
              activeClassId === cls.id
                ? 'bg-fuchsia-500/20 text-fuchsia-300 border border-fuchsia-400/40'
                : 'bg-[var(--sl-surface)] text-muted-foreground border border-[var(--sl-border)] hover:bg-[var(--sl-glow-strong)]'
            }`}
          >
            {cls.name}
          </button>
        ))}
      </div>

      {/* Action Buttons */}
      <div className="flex flex-wrap items-center gap-2">
        <button
          onClick={handleDownload}
          disabled={!activeClassId}
          className="neon-btn-cyan px-3 py-1.5 sm:px-4 sm:py-2 rounded-lg text-xs flex items-center gap-1.5 disabled:opacity-40"
        >
          <Download className="w-3.5 h-3.5" /> Download
        </button>

        <button
          onClick={() => fileInputRef.current?.click()}
          disabled={!activeClassId || uploading}
          className="neon-btn-green px-3 py-1.5 sm:px-4 sm:py-2 rounded-lg text-xs flex items-center gap-1.5 disabled:opacity-40"
        >
          {uploading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Upload className="w-3.5 h-3.5" />}
          {uploading ? 'Uploading...' : 'Upload'}
        </button>
        <input
          ref={fileInputRef}
          type="file"
          accept=".xlsx,.xls"
          onChange={handleUpload}
          className="hidden"
        />

        <button
          onClick={handleSave}
          disabled={!activeClassId || saving}
          className={`neon-btn-orange px-3 py-1.5 sm:px-4 sm:py-2 rounded-lg text-xs flex items-center gap-1.5 disabled:opacity-40 ${saved ? 'ring-1 ring-green-400/50' : ''}`}
        >
          {saving ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : saved ? <Check className="w-3.5 h-3.5 text-green-400" /> : <Save className="w-3.5 h-3.5" />}
          {saving ? 'Menyimpan...' : saved ? 'Tersimpan' : 'Simpan'}
        </button>

        <button
          onClick={() => fetchSchedules(activeClassId)}
          disabled={loading || !activeClassId}
          className="sl-icon-btn border-[var(--sl-border)] bg-[var(--sl-surface)] hover:bg-[var(--sl-glow-strong)] p-1.5 rounded-lg"
          title="Refresh jadwal"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
        </button>
      </div>

      {/* Schedule Grid */}
      <div className="neon-card rounded-xl overflow-hidden">
        <div className="p-3 sm:p-4 border-b border-fuchsia-400/20 bg-fuchsia-400/5">
          <div className="flex items-center gap-2">
            <CalendarDays className="w-4 h-4 sm:w-5 sm:h-5 neon-text-magenta" />
            <h3 className="cyber-subheading text-[10px] sm:text-sm neon-text-magenta">
              JADWAL MINGGUAN — {classes.find(c => c.id === activeClassId)?.name || '...'}
            </h3>
          </div>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="w-6 h-6 animate-spin neon-text-cyan" />
          </div>
        ) : (
          <>
            {activeDays.length < DAY_NUMS.length && (
              <div className="px-3 sm:px-4 py-1.5 bg-fuchsia-400/5 border-b border-fuchsia-400/10">
                <p className="cyber-mono text-[9px] sm:text-[10px] text-fuchsia-400">
                  ⚠ Kolom {DAY_NUMS.filter(d => !activeDays.includes(d)).map(d => getDayName(d)).join(', ')} disembunyikan (Hari Libur Akademik)
                </p>
              </div>
            )}
            <div className="overflow-x-auto">
              <table className="neon-table w-full min-w-[500px]">
                <thead>
                  <tr>
                    <th className="w-16 text-center">Jam</th>
                    {activeDays.map(d => (
                      <th key={d} className="text-center">{getDayName(d)}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {HOURS.map(hour => (
                    <tr key={hour}>
                      <td className="text-center cyber-mono font-bold neon-text-cyan">{hour}</td>
                      {activeDays.map(day => {
                        const key = `${day}-${hour}`;
                        return (
                          <td key={key} className="p-0.5">
                            <input
                              type="text"
                              value={scheduleMap[key] || ''}
                              onChange={e => handleCellChange(day, hour, e.target.value)}
                              className="neon-input w-full px-2 py-1.5 rounded text-xs text-center"
                              placeholder="-"
                            />
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
"},{"path":"src/components/app/OnlineBackupSync.tsx","content":"'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import {
  Cloud, RefreshCw, Download, Check, AlertTriangle, Loader2, X,
  Settings, ArrowDownToLine, Github, CloudUpload, Wrench, CopyCheck
} from 'lucide-react';
import { safeFetchJson } from '@/lib/fetch';
import { useToast } from '@/hooks/use-toast';

interface OnlineBackupSyncProps {
  isOpen: boolean;
  onClose: () => void;
  className?: string;
}

export function OnlineBackupSync({ isOpen, onClose, className = '' }: OnlineBackupSyncProps) {
  const [token, setToken] = useState('');
  const [owner, setOwner] = useState('');
  const [repo, setRepo] = useState('');
  const [branch, setBranch] = useState('main');
  const [configured, setConfigured] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [pulling, setPulling] = useState(false);
  const [savingConfig, setSavingConfig] = useState(false);
  const [lastSyncStatus, setLastSyncStatus] = useState<{ success: boolean; message: string } | null>(null);
  const [showSetup, setShowSetup] = useState(false);
  const [showPullConfirm, setShowPullConfirm] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<{ ok: boolean; message: string; files?: string[] } | null>(null);
  const [repairing, setRepairing] = useState(false);
  const [deduplicating, setDeduplicating] = useState(false);
  const { toast } = useToast();

  // Progress states
  const [syncProgress, setSyncProgress] = useState<{ current: number; total: number; percentage: number; label: string } | null>(null);
  const [pullProgress, setPullProgress] = useState<{ current: number; total: number; percentage: number; label: string } | null>(null);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const pullPollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (!isOpen) return;
    let cancelled = false;
    (async () => {
      const data = await safeFetchJson('/api/online-backup');
      if (cancelled) return;
      if (data?.configured) {
        setConfigured(true);
        setOwner(data.owner || '');
        setRepo(data.repo || '');
        setBranch(data.branch || 'main');
        if (data.connectionStatus) {
          setConnectionStatus(data.connectionStatus);
        }
      } else {
        setShowSetup(true);
      }

      // Check if there's an ongoing sync/pull — if so, resume polling and show progress bar
      const ss = data?.syncStatus;
      if (ss?.running && ss?.progress) {
        // Determine if it's a sync or pull based on progress label
        const label = ss.progress.label || '';
        if (label.toLowerCase().includes('ambil') || label.toLowerCase().includes('pull') || label.toLowerCase().includes('mengambil')) {
          setPulling(true);
          setPullProgress(ss.progress);
        } else {
          setSyncing(true);
          setSyncProgress(ss.progress);
        }

        // Resume polling for sync progress
        let resumePoll: ReturnType<typeof setInterval> | null = setInterval(async () => {
          try {
            const statusRes = await fetch('/api/online-backup', { cache: 'no-store' });
            const statusData = await statusRes.json();
            const s = statusData?.syncStatus;
            if (s?.progress) {
              if (label.toLowerCase().includes('ambil') || label.toLowerCase().includes('pull')) {
                setPullProgress(s.progress);
              } else {
                setSyncProgress(s.progress);
              }
            }
            if (!s?.running) {
              if (resumePoll) { clearInterval(resumePoll); resumePoll = null; }
              setSyncing(false);
              setPulling(false);
              setSyncProgress(null);
              setPullProgress(null);
              if (s?.lastResult) {
                setLastSyncStatus({ success: s.lastResult.success, message: s.lastResult.message });
                if (s.lastResult.success) {
                  toast({ title: 'Operasi selesai!', description: s.lastResult.message });
                } else {
                  toast({ title: 'Operasi gagal', description: s.lastResult.message, variant: 'destructive' });
                }
              }
              // Refresh connection status
              if (statusData?.connectionStatus) {
                setConnectionStatus(statusData.connectionStatus);
              }
            }
          } catch {}
        }, 2000);
        // Store in pollRef for cleanup
        pollRef.current = resumePoll;
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [isOpen, toast]);

  const handleSaveConfig = useCallback(async () => {
    if (!token.trim() || !owner.trim() || !repo.trim()) {
      toast({ title: 'Token, owner, dan repo wajib diisi', variant: 'destructive' });
      return;
    }
    setSavingConfig(true);
    const res = await safeFetchJson('/api/online-backup/config', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ token: token.trim(), owner: owner.trim(), repo: repo.trim(), branch: branch.trim() || 'main' }),
    });
    setSavingConfig(false);
    if (res?.success) {
      setConfigured(true);
      toast({ title: 'Konfigurasi tersimpan!', description: 'GitHub backup siap digunakan' });
    } else {
      toast({ title: res?.error || 'Gagal menyimpan konfigurasi', variant: 'destructive' });
    }
  }, [token, owner, repo, branch, toast]);

  const robustFetch = useCallback(async (url: string, options: RequestInit & { timeoutMs?: number } = {}): Promise<any> => {
    const { timeoutMs = 300_000, ...fetchOpts } = options;
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const res = await fetch(url, { ...fetchOpts, cache: 'no-store', signal: controller.signal });
      clearTimeout(timeoutId);
      let data: any = null;
      const contentType = res.headers.get('content-type') || '';
      if (contentType.includes('application/json')) {
        data = await res.json();
      } else {
        const text = await res.text();
        try { data = JSON.parse(text); } catch { data = null; }
      }
      if (data) return data;
      return { success: false, message: `Server error: HTTP ${res.status}` };
    } catch (e) {
      clearTimeout(timeoutId);
      if (e instanceof DOMException && e.name === 'AbortError') {
        return { success: false, message: 'Timeout: Operasi melebihi batas waktu.' };
      }
      return { success: false, message: `Gagal terhubung: ${e instanceof Error ? e.message : 'Network error'}` };
    }
  }, []);

  const handleSync = useCallback(async () => {
    setSyncing(true);
    setLastSyncStatus(null);
    setSyncProgress(null);

    const res = await robustFetch('/api/online-backup', { method: 'POST' });
    if (!res || !res.success) {
      setSyncing(false);
      if (res) {
        setLastSyncStatus({ success: res.success, message: res.message });
        toast({ title: 'Sync gagal', description: res.message, variant: 'destructive' });
      }
      return;
    }

    pollRef.current = setInterval(async () => {
      try {
        const statusRes = await fetch('/api/online-backup', { cache: 'no-store' });
        const statusData = await statusRes.json();
        const ss = statusData?.syncStatus;
        if (ss?.progress) setSyncProgress(ss.progress);
        if (!ss?.running) {
          if (pollRef.current) { clearInterval(pollRef.current); pollRef.current = null; }
          setSyncing(false);
          setSyncProgress(null);
          if (ss?.lastResult) {
            setLastSyncStatus({ success: ss.lastResult.success, message: ss.lastResult.message });
            if (ss.lastResult.success) {
              toast({ title: 'Sync berhasil!', description: ss.lastResult.message });
            } else {
              toast({ title: 'Sync gagal', description: ss.lastResult.message, variant: 'destructive' });
            }
          }
          // Refresh connection status after sync completes
          if (statusData?.connectionStatus) {
            setConnectionStatus(statusData.connectionStatus);
          }
        }
      } catch {}
    }, 2000);
  }, [toast, robustFetch]);

  useEffect(() => {
    return () => { if (pollRef.current) clearInterval(pollRef.current); };
  }, []);

  const handlePull = useCallback(async (mode: 'diff' | 'full' = 'diff') => {
    setPulling(true);
    setLastSyncStatus(null);
    setShowPullConfirm(false);
    setPullProgress(null);

    const action = mode === 'full' ? 'restore' : 'restore-diff';
    const res = await robustFetch('/api/online-backup', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action }),
    });

    if (!res || !res.success) {
      setPulling(false);
      if (res) {
        setLastSyncStatus({ success: res.success, message: res.message });
        toast({ title: 'Pull gagal', description: res.message, variant: 'destructive' });
      }
      return;
    }

    pullPollRef.current = setInterval(async () => {
      try {
        const statusRes = await fetch('/api/online-backup', { cache: 'no-store' });
        const statusData = await statusRes.json();
        const ss = statusData?.syncStatus;
        if (ss?.progress) setPullProgress(ss.progress);
        if (!ss?.running) {
          if (pullPollRef.current) { clearInterval(pullPollRef.current); pullPollRef.current = null; }
          setPulling(false);
          setPullProgress(null);
          if (ss?.lastResult) {
            setLastSyncStatus({ success: ss.lastResult.success, message: ss.lastResult.message });
            if (ss.lastResult.success) {
              toast({ title: 'Pull berhasil!', description: ss.lastResult.message });
            } else {
              toast({ title: 'Pull gagal', description: ss.lastResult.message, variant: 'destructive' });
            }
          }
        }
      } catch {}
    }, 2000);
  }, [toast, robustFetch]);

  useEffect(() => {
    return () => { if (pullPollRef.current) clearInterval(pullPollRef.current); };
  }, []);

  const handleRepair = useCallback(async () => {
    setRepairing(true);
    try {
      const res = await robustFetch('/api/online-backup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'repair' }),
      });
      if (res?.success) {
        toast({ title: 'Meta.json diperbaiki!', description: res.message });
        setLastSyncStatus({ success: true, message: res.message });
        // Refresh connection status
        const statusRes = await fetch('/api/online-backup', { cache: 'no-store' });
        const statusData = await statusRes.json();
        if (statusData?.connectionStatus) {
          setConnectionStatus(statusData.connectionStatus);
        }
      } else {
        toast({ title: 'Repair gagal', description: res?.message || 'Unknown error', variant: 'destructive' });
        setLastSyncStatus({ success: false, message: res?.message || 'Unknown error' });
      }
    } catch (e) {
      toast({ title: 'Repair gagal', description: e instanceof Error ? e.message : 'Network error', variant: 'destructive' });
    }
    setRepairing(false);
  }, [toast, robustFetch]);

  const handleDeduplicate = useCallback(async () => {
    setDeduplicating(true);
    try {
      const res = await robustFetch('/api/online-backup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'deduplicate' }),
      });
      if (res?.success && res?.background) {
        toast({ title: 'Deduplication dimulai!', description: res.message || 'Proses berjalan di background.' });
        setLastSyncStatus({ success: true, message: res.message || 'Deduplication berjalan di background.' });
      } else if (res?.success) {
        toast({ title: 'Deduplication berhasil!', description: res.message });
        setLastSyncStatus({ success: true, message: res.message });
      } else {
        toast({ title: 'Deduplication gagal', description: res?.message || 'Unknown error', variant: 'destructive' });
        setLastSyncStatus({ success: false, message: res?.message || 'Unknown error' });
      }
    } catch (e) {
      toast({ title: 'Deduplication gagal', description: e instanceof Error ? e.message : 'Network error', variant: 'destructive' });
    }
    setDeduplicating(false);
  }, [toast, robustFetch]);

  if (!isOpen) return null;

  return (
    <>
      <div className={`sl-notification ${className}`}>
        <div className="sl-window-title">
          <div className="sl-window-dots"><span /><span /><span /></div>
          <Cloud className="w-4 h-4" />
          <span className="flex-1 text-center">JSON BACKUP</span>
          {configured ? (
            <span className="sl-badge sl-badge-green">AKTIF</span>
          ) : (
            <span className="sl-badge sl-badge-red">BELUM SIAP</span>
          )}
        </div>

        <div className="p-3 max-h-[60vh] overflow-y-auto space-y-3">
          {/* Config info */}
          {configured && (
            <div className="p-2.5 rounded-lg border border-purple-400/20 bg-purple-400/5">
              <p className="cyber-mono text-[9px] text-purple-400/60 mb-1">REPO GITHUB</p>
              <a
                href={`https://github.com/${owner}/${repo}`}
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center gap-2 text-xs text-purple-300 hover:text-purple-400 transition-colors group"
              >
                <Github className="w-3.5 h-3.5 flex-shrink-0" />
                <span className="truncate flex-1 cyber-body">{owner}/{repo}</span>
              </a>
              <p className="cyber-mono text-[8px] text-muted-foreground mt-1">Branch: {branch}</p>
              {connectionStatus && (
                <div className={`mt-2 p-1.5 rounded text-[9px] cyber-body ${connectionStatus.ok ? 'bg-green-400/10 text-green-300' : 'bg-red-400/10 text-red-300'}`}>
                  <div className="flex items-start gap-1">
                    {connectionStatus.ok ? <Check className="w-3 h-3 flex-shrink-0 mt-0.5" /> : <AlertTriangle className="w-3 h-3 flex-shrink-0 mt-0.5" />}
                    <span>{connectionStatus.message}</span>
                  </div>
                  {connectionStatus.files && connectionStatus.files.length > 0 && (
                    <div className="mt-1 cyber-mono text-[8px] text-muted-foreground">
                      Files: {connectionStatus.files.slice(0, 5).join(', ')}{connectionStatus.files.length > 5 ? ` +${connectionStatus.files.length - 5} lainnya` : ''}
                    </div>
                  )}
                </div>
              )}
            </div>
          )}

          {/* Action Buttons */}
          <div className="grid grid-cols-2 gap-2">
            <button
              onClick={handleSync}
              disabled={syncing || pulling || !configured}
              className="neon-btn-green px-3 py-2 rounded-lg text-[10px] sm:text-xs flex items-center justify-center gap-1.5 disabled:opacity-40 disabled:cursor-not-allowed"
            >
              {syncing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RefreshCw className="w-3.5 h-3.5" />}
              {syncing ? 'SINKRON...' : 'SYNC'}
            </button>
            <button
              onClick={() => setShowPullConfirm(true)}
              disabled={pulling || syncing || !configured}
              className="neon-btn-cyan px-3 py-2 rounded-lg text-[10px] sm:text-xs flex items-center justify-center gap-1.5 disabled:opacity-40 disabled:cursor-not-allowed"
            >
              {pulling ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <ArrowDownToLine className="w-3.5 h-3.5" />}
              {pulling ? 'PULLING...' : 'PULL'}
            </button>
          </div>

          {/* Data types included in backup */}
          <div className="p-2 rounded-lg bg-purple-400/5 border border-purple-400/15">
            <p className="cyber-mono text-[9px] text-purple-400/60 mb-1">DATA YANG DISYNC:</p>
            <div className="grid grid-cols-2 gap-x-2 gap-y-0.5 text-[9px] cyber-body text-purple-300">
              <span>✓ Kelas & Siswa</span>
              <span>✓ Absensi</span>
              <span>✓ Hari Libur</span>
              <span>✓ Nama Guru</span>
              <span>✓ Wali Kelas</span>
              <span>✓ Jadwal Mingguan</span>
              <span>✓ Max Hour (per tanggal)</span>
              <span>✓ Pengaturan</span>
            </div>
          </div>

          {/* Stop button */}
          {(syncing || pulling) && (
            <button
              onClick={async () => {
                try {
                  await fetch('/api/online-backup', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ action: 'stop' }),
                  });
                } catch {}
                if (pollRef.current) { clearInterval(pollRef.current); pollRef.current = null; }
                if (pullPollRef.current) { clearInterval(pullPollRef.current); pullPollRef.current = null; }
                setSyncing(false);
                setPulling(false);
                setSyncProgress(null);
                setPullProgress(null);
                toast({ title: 'Operasi dihentikan' });
              }}
              className="neon-btn-danger w-full px-3 py-2 rounded-lg text-[10px] sm:text-xs flex items-center justify-center gap-1.5"
            >
              <X className="w-3.5 h-3.5" />
              STOP RESET/RESTORE
            </button>
          )}

          {/* Sync Progress Bar */}
          {syncing && syncProgress && (
            <div className="space-y-1.5">
              <div className="flex items-center justify-between">
                <span className="cyber-mono text-[9px] text-cyan-300 truncate flex-1">{syncProgress.label}</span>
                <span className="cyber-mono text-[9px] neon-text-cyan font-bold ml-2 flex-shrink-0">{syncProgress.percentage}%</span>
              </div>
              <div className="w-full h-2 rounded-full bg-gray-700/50 overflow-hidden">
                <div
                  className="h-full rounded-full bg-cyan-400 transition-all duration-500"
                  style={{ width: `${syncProgress.percentage}%`, boxShadow: '0 0 8px rgba(34, 211, 238, 0.5)' }}
                />
              </div>
              <div className="flex items-center justify-between">
                <span className="cyber-mono text-[8px] text-muted-foreground">
                  Chunk {syncProgress.current} / {syncProgress.total}
                </span>
                <span className="cyber-mono text-[8px] text-muted-foreground">
                  {syncProgress.total > 0 ? `${Math.round((syncProgress.current / syncProgress.total) * 100)}% complete` : ''}
                </span>
              </div>
            </div>
          )}

          {/* Pull Progress Bar */}
          {pulling && pullProgress && (
            <div className="space-y-1.5">
              <div className="flex items-center justify-between">
                <span className="cyber-mono text-[9px] text-green-300 truncate flex-1">{pullProgress.label}</span>
                <span className="cyber-mono text-[9px] neon-text-green font-bold ml-2 flex-shrink-0">{pullProgress.percentage}%</span>
              </div>
              <div className="w-full h-2 rounded-full bg-gray-700/50 overflow-hidden">
                <div
                  className="h-full rounded-full bg-green-400 transition-all duration-500"
                  style={{ width: `${pullProgress.percentage}%`, boxShadow: '0 0 8px rgba(74, 222, 128, 0.5)' }}
                />
              </div>
              <div className="flex items-center justify-between">
                <span className="cyber-mono text-[8px] text-muted-foreground">
                  Chunk {pullProgress.current} / {pullProgress.total}
                </span>
                <span className="cyber-mono text-[8px] text-muted-foreground">
                  {pullProgress.total > 0 ? `${Math.round((pullProgress.current / pullProgress.total) * 100)}% diambil` : ''}
                </span>
              </div>
            </div>
          )}

          {/* Sync Status */}
          {lastSyncStatus && (
            <div className={`p-2.5 rounded-lg border flex items-start gap-2 ${lastSyncStatus.success ? 'border-green-400/30 bg-green-400/5' : 'border-red-400/30 bg-red-400/5'}`}>
              {lastSyncStatus.success ? <Check className="w-3.5 h-3.5 text-green-400 flex-shrink-0 mt-0.5" /> : <AlertTriangle className="w-3.5 h-3.5 text-red-400 flex-shrink-0 mt-0.5" />}
              <p className={`text-[10px] cyber-body ${lastSyncStatus.success ? 'text-green-300' : 'text-red-300'}`}>
                {lastSyncStatus.message}
              </p>
            </div>
          )}

          {/* Pull confirmation */}
          {showPullConfirm && (
            <div className="p-2.5 rounded-lg border border-red-400/30 bg-red-400/5">
              <div className="flex items-start gap-2 mb-2">
                <AlertTriangle className="w-4 h-4 text-red-400 flex-shrink-0 mt-0.5" />
                <div className="space-y-1">
                  <p className="text-[10px] font-bold text-red-300 mb-1">Pull dari GitHub?</p>
                  <p className="text-[9px] text-red-300/70 cyber-body">
                    Pilih mode pull:
                  </p>
                  <div className="space-y-1.5 mt-1">
                    <button
                      onClick={() => handlePull('diff')}
                      className="w-full px-2 py-1.5 rounded-lg text-[10px] bg-green-500/20 border border-green-400/30 text-green-300 hover:bg-green-500/30 transition-colors flex items-center justify-center gap-1"
                    >
                      <Check className="w-3 h-3" /> PULL DIFF (cepat — hanya data hilang)
                    </button>
                    <button
                      onClick={() => handlePull('full')}
                      className="w-full px-2 py-1.5 rounded-lg text-[10px] bg-red-500/20 border border-red-400/30 text-red-300 hover:bg-red-500/30 transition-colors flex items-center justify-center gap-1"
                    >
                      <AlertTriangle className="w-3 h-3" /> PULL FULL (hapus semua + restore)
                    </button>
                  </div>
                </div>
              </div>
              <button
                onClick={() => setShowPullConfirm(false)}
                className="w-full px-2 py-1.5 rounded-lg text-[10px] bg-muted border text-muted-foreground hover:bg-muted/80 transition-colors mt-2"
              >
                BATAL
              </button>
            </div>
          )}

          {/* Setup/Config toggle */}
          <button
            onClick={() => setShowSetup(!showSetup)}
            className="w-full flex items-center gap-2 px-3 py-2 rounded-lg text-[10px] sm:text-xs neon-text-cyan hover:bg-cyan-400/5 transition-colors"
          >
            <Settings className="w-3.5 h-3.5 text-cyan-400" />
            <span className="cyber-subheading text-cyan-400">PENGATURAN</span>
            <CloudUpload className="w-3 h-3 text-yellow-400 animate-pulse ml-auto" />
            <span className="cyber-mono text-[9px] text-muted-foreground">{configured ? 'AKTIF' : 'SETUP'}</span>
          </button>

          {showSetup && (
            <div className="p-3 space-y-2 border-t border-cyan-400/10">
              {!configured && (
                <div className="p-2.5 rounded-lg bg-yellow-400/10 border border-yellow-400/20 flex items-start gap-2">
                  <AlertTriangle className="w-3.5 h-3.5 text-yellow-400 flex-shrink-0 mt-0.5" />
                  <p className="text-[10px] text-yellow-300 cyber-body">
                    <strong>Setup belum selesai.</strong> Buat GitHub repo + Personal Access Token (PAT).
                  </p>
                </div>
              )}

              <ol className="space-y-1.5 text-[10px] text-muted-foreground cyber-body list-decimal list-inside">
                <li>Buat repo baru di GitHub (bisa private)</li>
                <li>Buat token di GitHub Settings → Developer settings → Personal access tokens → Fine-grained tokens</li>
                <li>Beri izin <strong>Contents: Read and write</strong> untuk repo tersebut</li>
                <li>Isi form di bawah</li>
              </ol>

              <div className="space-y-2">
                <div>
                  <label className="cyber-mono text-[9px] text-cyan-400/60 block mb-1">GITHUB TOKEN (PAT)</label>
                  <input
                    type="password"
                    value={token}
                    onChange={(e) => setToken(e.target.value)}
                    placeholder="github_pat_xxxx..."
                    className="w-full px-2 py-1.5 rounded-md text-[10px] sl-input"
                  />
                </div>
                <div className="grid grid-cols-2 gap-2">
                  <div>
                    <label className="cyber-mono text-[9px] text-cyan-400/60 block mb-1">OWNER</label>
                    <input
                      type="text"
                      value={owner}
                      onChange={(e) => setOwner(e.target.value)}
                      placeholder="username"
                      className="w-full px-2 py-1.5 rounded-md text-[10px] sl-input"
                    />
                  </div>
                  <div>
                    <label className="cyber-mono text-[9px] text-cyan-400/60 block mb-1">REPO</label>
                    <input
                      type="text"
                      value={repo}
                      onChange={(e) => setRepo(e.target.value)}
                      placeholder="backup-absensi"
                      className="w-full px-2 py-1.5 rounded-md text-[10px] sl-input"
                    />
                  </div>
                </div>
                <div>
                  <label className="cyber-mono text-[9px] text-cyan-400/60 block mb-1">BRANCH (default: main)</label>
                  <input
                    type="text"
                    value={branch}
                    onChange={(e) => setBranch(e.target.value)}
                    placeholder="main"
                    className="w-full px-2 py-1.5 rounded-md text-[10px] sl-input"
                  />
                </div>
                <button
                  onClick={handleSaveConfig}
                  disabled={savingConfig}
                  className="neon-btn w-full px-3 py-2 rounded-lg text-[10px] sm:text-xs flex items-center justify-center gap-1.5 disabled:opacity-40"
                >
                  {savingConfig ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <CloudUpload className="w-3.5 h-3.5" />}
                  SIMPAN KONFIGURASI
                </button>
              </div>
            </div>
          )}

          {/* Repair Meta + Deduplicate buttons — shown when configured */}
          {configured && (
            <div className="flex gap-1.5">
              <button
                onClick={handleRepair}
                disabled={repairing || deduplicating || syncing || pulling}
                className="neon-btn-orange flex-1 px-2 py-2 rounded-lg text-[10px] sm:text-xs flex items-center justify-center gap-1.5 disabled:opacity-40 disabled:cursor-not-allowed"
              >
                {repairing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Wrench className="w-3.5 h-3.5" />}
                {repairing ? '...' : 'REPAIR META'}
              </button>
              <button
                onClick={handleDeduplicate}
                disabled={repairing || deduplicating || syncing || pulling}
                className="neon-btn-cyan flex-1 px-2 py-2 rounded-lg text-[10px] sm:text-xs flex items-center justify-center gap-1.5 disabled:opacity-40 disabled:cursor-not-allowed"
                title="Hapus chunk duplikat dan record yang sama, perbaiki meta.json"
              >
                {deduplicating ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <CopyCheck className="w-3.5 h-3.5" />}
                {deduplicating ? '...' : 'DEDUP CHUNK'}
              </button>
            </div>
          )}

          {/* Info */}
          <div className="p-2 rounded-lg bg-cyan-400/5 border border-cyan-400/15 flex items-start gap-1.5">
            <Cloud className="w-3 h-3 text-cyan-400 flex-shrink-0 mt-0.5" />
            <div className="text-[9px] text-cyan-300/80 cyber-body space-y-1">
              <p><strong>Auto-sync:</strong> Data baru otomatis ter-push ke GitHub (incremental).</p>
              <p><strong>Auto-restore:</strong> Jika completeness 0% (bukan hari libur), data otomatis di-pull dari GitHub.</p>
              <p><strong>Pause sync:</strong> Sync otomatis di-pause saat restore berjalan.</p>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
"},{"path":"src/components/app/PopupShell.tsx","content":"'use client';

import { type ReactNode } from 'react';

interface PopupShellProps {
  children: ReactNode;
  onClose?: () => void;
  maxWidth?: string;
}

/**
 * Mobile (below lg): full-screen fixed overlay, perfectly centered.
 * Desktop (lg+): fixed positioned at top-right (below header), no backdrop.
 */
export function PopupShell({ children, onClose, maxWidth = 'max-w-[300px]' }: PopupShellProps) {
  return (
    <>
      {/* MOBILE: full-screen overlay, perfectly centered */}
      <div className="fixed top-0 left-0 right-0 bottom-0 z-[9999] flex items-center justify-center p-2 lg:hidden">
        {onClose && (
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />
        )}
        <div
          className={`relative z-10 w-full ${maxWidth} max-h-[75vh] overflow-y-auto overscroll-contain rounded-lg my-auto`}
          style={{ maxHeight: 'calc(100vh - 3rem)' }}
        >
          {children}
        </div>
      </div>

      {/* DESKTOP: fixed at top-right, below header */}
      <div className="hidden lg:block fixed top-12 right-2 xl:right-4 z-[9999]">
        <div className={`w-full ${maxWidth}`}>{children}</div>
      </div>
    </>
  );
}
"},{"path":"src/components/app/RekapAbsensiGuruView.tsx","content":"'use client';

import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  CalendarDays, FileSpreadsheet, Loader2, RefreshCw, AlertTriangle, X,
} from 'lucide-react';
import { ClassData } from './types';
import { safeFetchJson } from '@/lib/fetch';
import { getJakartaToday } from '@/lib/utils';
import { useToast } from '@/hooks/use-toast';

interface RekapAbsensiGuruViewProps {
  classes: ClassData[];
}

interface RecapRow {
  no: number;
  name: string;
  nisn: string;
  gender: string;
  masuk: number;
  terlambat: number;
  alfa: number;
  sakit: number;
  izin: number;
}

const STATUS_LABELS: Record<string, string> = {
  Hadir: 'Masuk',
  Terlambat: 'Terlambat',
  Alfa: 'Alfa',
  Sakit: 'Sakit',
  Izin: 'Izin',
};

export function RekapAbsensiGuruView({ classes }: RekapAbsensiGuruViewProps) {
  const { toast } = useToast();
  // Set default class
  const defaultClassId = classes.length > 0 ? classes[0].id : '';
  // Default: start date = 30 days ago, end date = today
  const defaultStartDate = (() => {
    const d = new Date();
    d.setDate(d.getDate() - 30);
    return d.toISOString().split('T')[0];
  })();
  const [selectedClass, setSelectedClass] = useState<string>(defaultClassId);
  const [startDate, setStartDate] = useState<string>(defaultStartDate);
  const [endDate, setEndDate] = useState<string>(() => getJakartaToday());
  const [data, setData] = useState<RecapRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [exporting, setExporting] = useState(false);
  const [error, setError] = useState('');

  const fetchData = useCallback(async () => {
    if (!selectedClass || !startDate || !endDate) return;
    let cancelled = false;
    setLoading(true);
    setError('');
    try {
      const data = await fetch(
        `/api/recap/student-bulk?classId=${selectedClass}&startDate=${startDate}&endDate=${endDate}`
      ).then(r => r.json()).catch(() => ({ students: [] }));
      if (cancelled) return;
      if (data.students) {
        setData(data.students.map((s: any, i: number) => ({
          no: i + 1,
          name: s.name,
          nisn: s.nisn || '-',
          gender: s.gender || '-',
          masuk: s.masuk || 0,
          terlambat: s.terlambat || 0,
          alfa: s.alfa || 0,
          sakit: s.sakit || 0,
          izin: s.izin || 0,
        })));
      }
    } catch {
      if (!cancelled) setError('Gagal memuat data rekap');
    }
    if (!cancelled) setLoading(false);
  }, [selectedClass, startDate, endDate]);

  useEffect(() => {
    if (!selectedClass || !startDate || !endDate) return;
    let cancelled = false;
    const load = async () => {
      setLoading(true);
      setError('');
      try {
        const data = await fetch(
          `/api/recap/student-bulk?classId=${selectedClass}&startDate=${startDate}&endDate=${endDate}`
        ).then(r => r.json()).catch(() => ({ students: [] }));
        if (cancelled) return;
        if (data.students) {
          setData(data.students.map((s: any, i: number) => ({
            no: i + 1,
            name: s.name,
            nisn: s.nisn || '-',
            gender: s.gender || '-',
            masuk: s.masuk || 0,
            terlambat: s.terlambat || 0,
            alfa: s.alfa || 0,
            sakit: s.sakit || 0,
            izin: s.izin || 0,
          })));
        }
      } catch {
        if (!cancelled) setError('Gagal memuat data rekap');
      }
      if (!cancelled) setLoading(false);
    };
    load();
    return () => { cancelled = true; };
  }, [selectedClass, startDate, endDate]);

  const handleExport = useCallback(() => {
    if (!selectedClass || !startDate || !endDate) return;
    setExporting(true);
    const cls = classes.find(c => c.id === selectedClass);
    const className = cls ? cls.name.replace(/\s+/g, '_') : 'kelas';
    window.open(
      `/api/recap/excel?type=mingguan&classId=${selectedClass}&startDate=${startDate}&endDate=${endDate}`,
      '_blank'
    );
    toast({ title: 'Export dimulai', description: 'File Excel akan diunduh.' });
    setExporting(false);
  }, [selectedClass, startDate, endDate, classes, toast]);

  const totals = data.reduce((acc, r) => ({
    masuk: acc.masuk + r.masuk,
    terlambat: acc.terlambat + r.terlambat,
    alfa: acc.alfa + r.alfa,
    sakit: acc.sakit + r.sakit,
    izin: acc.izin + r.izin,
  }), { masuk: 0, terlambat: 0, alfa: 0, sakit: 0, izin: 0 });

  return (
    <div className="space-y-4 sm:space-y-6">
      {/* Header */}
      <div>
        <h2 className="cyber-heading text-xl sm:text-2xl md:text-3xl neon-text-magenta">REKAP ABSENSI</h2>
        <p className="cyber-mono text-[10px] sm:text-xs text-muted-foreground mt-1">REKAPITULASI KEHADIRAN SISWA PER KELAS</p>
      </div>

      {/* Error */}
      <AnimatePresence>
        {error && (
          <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="flex items-center gap-2 p-3 rounded-lg border border-red-400/40 bg-red-400/10">
            <AlertTriangle className="w-4 h-4 text-red-400 flex-shrink-0" />
            <span className="cyber-body text-xs text-red-400 flex-1">{error}</span>
            <button onClick={() => setError('')} className="text-red-400 hover:text-red-300"><X className="w-4 h-4" /></button>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Filters */}
      <div className="neon-card rounded-xl p-3 sm:p-4 space-y-3">
        <div className="flex flex-col sm:flex-row gap-3 sm:gap-4">
          {/* Class selector */}
          <div className="flex-1">
            <label className="cyber-mono text-[10px] text-cyan-400 uppercase block mb-1">KELAS</label>
            <select
              value={selectedClass}
              onChange={(e) => setSelectedClass(e.target.value)}
              className="neon-input w-full px-3 py-2 rounded-lg text-xs sm:text-sm"
            >
              {classes.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
            </select>
          </div>

          {/* Start date */}
          <div className="flex-1">
            <label className="cyber-mono text-[10px] text-cyan-400 uppercase block mb-1">TANGGAL MULAI</label>
            <input
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              className="neon-input w-full px-3 py-2 rounded-lg text-xs sm:text-sm"
            />
          </div>

          {/* End date */}
          <div className="flex-1">
            <label className="cyber-mono text-[10px] text-cyan-400 uppercase block mb-1">TANGGAL AKHIR</label>
            <input
              type="date"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              className="neon-input w-full px-3 py-2 rounded-lg text-xs sm:text-sm"
            />
          </div>

          {/* Actions */}
          <div className="flex items-end gap-2">
            <button
              onClick={fetchData}
              disabled={loading || !selectedClass || !startDate || !endDate}
              className="neon-btn-cyan px-3 py-2 rounded-lg text-xs flex items-center gap-1.5 disabled:opacity-40"
            >
              {loading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RefreshCw className="w-3.5 h-3.5" />}
              <span className="hidden sm:inline">Refresh</span>
            </button>
            <button
              onClick={handleExport}
              disabled={exporting || data.length === 0}
              className="neon-btn-green px-3 py-2 rounded-lg text-xs flex items-center gap-1.5 disabled:opacity-40"
            >
              {exporting ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <FileSpreadsheet className="w-3.5 h-3.5" />}
              <span className="hidden sm:inline">Excel</span>
            </button>
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="neon-card rounded-xl overflow-hidden">
        <div className="p-3 sm:p-4 border-b border-cyan-400/20 bg-cyan-400/5">
          <div className="flex items-center gap-2">
            <CalendarDays className="w-4 h-4 sm:w-5 sm:h-5 neon-text-cyan" />
            <h3 className="cyber-subheading text-[10px] sm:text-sm neon-text-cyan">
              REKAP KEHADIRAN — {classes.find(c => c.id === selectedClass)?.name || '...'}
            </h3>
            {startDate && endDate && (
              <span className="cyber-mono text-[9px] sm:text-[10px] text-muted-foreground ml-auto">
                {startDate} s/d {endDate}
              </span>
            )}
          </div>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="w-6 h-6 animate-spin neon-text-cyan" />
          </div>
        ) : data.length === 0 ? (
          <div className="flex items-center justify-center py-12">
            <p className="cyber-body text-sm text-muted-foreground">Pilih kelas dan tanggal untuk menampilkan rekap</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="neon-table w-full min-w-[700px]">
              <thead>
                <tr>
                  <th className="text-center w-10">NO</th>
                  <th className="text-left">NAMA SISWA</th>
                  <th className="text-center">NISN</th>
                  <th className="text-center w-12">JK</th>
                  <th className="text-center">MASUK</th>
                  <th className="text-center">TERLAMBAT</th>
                  <th className="text-center">ALFA</th>
                  <th className="text-center">SAKIT</th>
                  <th className="text-center">IZIN</th>
                </tr>
              </thead>
              <tbody>
                {data.map((row) => (
                  <tr key={row.no}>
                    <td className="text-center cyber-mono font-bold neon-text-cyan">{row.no}</td>
                    <td className="text-left">{row.name}</td>
                    <td className="text-center cyber-mono text-xs">{row.nisn}</td>
                    <td className="text-center text-xs">{row.gender === 'Laki-laki' ? 'L' : row.gender === 'Perempuan' ? 'P' : '-'}</td>
                    <td className="text-center">
                      <span className={row.masuk > 0 ? 'neon-text-green font-bold' : 'text-muted-foreground'}>{row.masuk}</span>
                    </td>
                    <td className="text-center">
                      <span className={row.terlambat > 0 ? 'text-yellow-400 font-bold' : 'text-muted-foreground'}>{row.terlambat}</span>
                    </td>
                    <td className="text-center">
                      <span className={row.alfa > 0 ? 'text-red-400 font-bold' : 'text-muted-foreground'}>{row.alfa}</span>
                    </td>
                    <td className="text-center">
                      <span className={row.sakit > 0 ? 'text-blue-400 font-bold' : 'text-muted-foreground'}>{row.sakit}</span>
                    </td>
                    <td className="text-center">
                      <span className={row.izin > 0 ? 'text-purple-400 font-bold' : 'text-muted-foreground'}>{row.izin}</span>
                    </td>
                  </tr>
                ))}
                {/* Totals row */}
                <tr className="border-t-2 border-cyan-400/30">
                  <td colSpan={4} className="text-right cyber-subheading text-xs neon-text-cyan pr-3">TOTAL</td>
                  <td className="text-center cyber-mono font-bold neon-text-green">{totals.masuk}</td>
                  <td className="text-center cyber-mono font-bold text-yellow-400">{totals.terlambat}</td>
                  <td className="text-center cyber-mono font-bold text-red-400">{totals.alfa}</td>
                  <td className="text-center cyber-mono font-bold text-blue-400">{totals.sakit}</td>
                  <td className="text-center cyber-mono font-bold text-purple-400">{totals.izin}</td>
                </tr>
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}
"},{"path":"src/components/app/RekapAbsensiTab.tsx","content":"'use client';

import { useState } from 'react';
import { Eye } from 'lucide-react';
import { ClassData, Student } from './types';
import { RekapHarianContent } from './RekapHarianContent';
import { RekapMingguanTab } from './RekapMingguanTab';
import { RekapBulananTab } from './RekapBulananTab';
import { RekapPerSiswaTab } from './RekapPerSiswaTab';

const SUB_TABS = [
  { id: 'harian', name: 'Harian' },
  { id: 'mingguan', name: 'Mingguan' },
  { id: 'bulanan', name: 'Bulanan' },
  { id: 'per-siswa', name: 'Per Siswa' },
];

export function RekapAbsensiTab({ classData, students, selectedDate }: { classData: ClassData; students: Student[]; selectedDate: string }) {
  const [subTab, setSubTab] = useState('harian');

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row sm:items-center sm:gap-2 gap-1">
        <div className="flex items-center gap-2 min-w-0">
          <Eye className="w-3.5 h-3.5 sm:w-4 sm:h-4 neon-text-magenta flex-shrink-0" />
          <span className="cyber-subheading text-[10px] sm:text-xs neon-text-magenta truncate">REKAP ABSENSI</span>
        </div>
        <span className="cyber-mono text-[9px] sm:text-[10px] text-muted-foreground">{classData.name.toUpperCase()}</span>
      </div>

      {/* Sub-tabs */}
      <div className="flex gap-1 border-b border-cyan-400/20 overflow-x-auto">
        {SUB_TABS.map(tab => (
          <button key={tab.id} onClick={() => setSubTab(tab.id)} className={`px-4 py-2 text-sm whitespace-nowrap transition-all ${subTab === tab.id ? 'neon-tab-active' : 'neon-tab-inactive'}`}>
            {tab.name}
          </button>
        ))}
      </div>

      {subTab === 'harian' && <RekapHarianContent classData={classData} students={students} selectedDate={selectedDate} />}
      {subTab === 'mingguan' && <RekapMingguanTab classData={classData} />}
      {subTab === 'bulanan' && <RekapBulananTab classData={classData} />}
      {subTab === 'per-siswa' && <RekapPerSiswaTab classData={classData} students={students} />}
    </div>
  );
}
"},{"path":"src/components/app/RekapBulananTab.tsx","content":"'use client';

import { useState, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import { Calendar, Save, FileSpreadsheet, Loader2 } from 'lucide-react';
import { ClassData } from './types';
import { safeFetchJson } from '@/lib/fetch';

const MONTHS = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];

interface RecapStudent { studentId: string; name: string; nisn: string; hMasuk: number; hSakit: number; hIzin: number; hAlfa: number; terlambat: number; totalHari: number; }
interface RecapData { students: RecapStudent[]; totals: { hMasuk: number; hSakit: number; hIzin: number; hAlfa: number; terlambat: number }; effectiveDays: number; }

export function RekapBulananTab({ classData }: { classData: ClassData }) {
  const now = new Date();
  const [month, setMonth] = useState(String(now.getMonth() + 1));
  const [year, setYear] = useState(String(now.getFullYear()));
  const [startDateStr, setStartDateStr] = useState('');
  const [data, setData] = useState<RecapData | null>(null);
  const [loading, setLoading] = useState(false);
  const [savingStart, setSavingStart] = useState(false);
  const [exportingExcel, setExportingExcel] = useState(false);

  useEffect(() => {
    const load = async () => { const r = await safeFetchJson('/api/settings/attendance-start'); if (r?.value) setStartDateStr(r.value); };
    load();
  }, []);

  const fetchRecap = useCallback(async () => {
    setLoading(true);
    const r = await safeFetchJson(`/api/recap?type=monthly&classId=${classData.id}&month=${month}&year=${year}`);
    if (r) setData(r); else setData(null);
    setLoading(false);
  }, [classData.id, month, year]);

  useEffect(() => { fetchRecap(); }, [fetchRecap]);

  const handleSaveStartDate = async () => {
    if (!startDateStr) return;
    setSavingStart(true);
    try { await fetch('/api/settings/attendance-start', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ value: startDateStr }) }); fetchRecap(); } catch (e) { console.error(e); } finally { setSavingStart(false); }
  };

  const pct = (m: number, t: number) => t === 0 ? '0.0' : ((m / t) * 100).toFixed(1);

  const handleExportExcel = useCallback(async () => {
    setExportingExcel(true);
    try {
      const url = `/api/recap/excel?type=bulanan&classId=${classData.id}&month=${month}&year=${year}`;
      const res = await fetch(url);
      if (!res.ok) {
        console.error('Export failed:', res.status);
        setExportingExcel(false);
        return;
      }
      const blob = await res.blob();
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      const safeName = classData.name.replace(/[^a-zA-Z0-9 ]/g, '').replace(/\s+/g, '_');
      link.download = `Rekap_Bulanan_${safeName}_${MONTHS[parseInt(month) - 1]}_${year}.xlsx`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(link.href);
    } catch (e) {
      console.error('Export error:', e);
    }
    setExportingExcel(false);
  }, [classData.id, classData.name, month, year]);

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2"><Calendar className="w-3.5 h-3.5 sm:w-4 sm:h-4 neon-text-cyan" /><span className="cyber-subheading text-[10px] sm:text-xs neon-text-cyan">REKAP BULANAN</span></div>
      <div className="neon-card rounded-xl p-3 sm:p-4">
        <div className="flex flex-wrap items-end gap-3">
          <div><label className="cyber-mono text-[10px] text-muted-foreground uppercase">Bulan</label><select value={month} onChange={e => setMonth(e.target.value)} className="neon-select px-3 py-2 rounded-lg mt-1 text-xs">{MONTHS.map((m, i) => <option key={i} value={String(i + 1)}>{m}</option>)}</select></div>
          <div><label className="cyber-mono text-[10px] text-muted-foreground uppercase">Tahun</label><select value={year} onChange={e => setYear(e.target.value)} className="neon-select px-3 py-2 rounded-lg mt-1 text-xs">{[2024,2025,2026,2027].map(y => <option key={y} value={String(y)}>{y}</option>)}</select></div>
          <button
            onClick={handleExportExcel}
            disabled={exportingExcel || !data || data.students.length === 0}
            className="neon-btn-green px-3 py-2 rounded-lg text-[10px] sm:text-xs flex items-center gap-1 disabled:opacity-40 disabled:cursor-not-allowed"
            title="Export ke Excel"
          >
            {exportingExcel ? <Loader2 className="w-3 h-3 animate-spin" /> : <FileSpreadsheet className="w-3 h-3" />}
            {exportingExcel ? 'Exporting...' : <span className="hidden sm:inline">Export Excel</span>}
            {!exportingExcel && <span className="sm:hidden">Excel</span>}
          </button>
        </div>
        <div className="mt-4 pt-3 border-t border-cyan-400/10">
          <label className="cyber-mono text-[10px] text-muted-foreground uppercase"><span className="hidden sm:inline">Tanggal Mulai Perekaman</span><span className="sm:hidden">Tgl Mulai</span></label>
          <div className="flex items-center gap-2 mt-1">
            <input type="date" value={startDateStr} onChange={e => setStartDateStr(e.target.value)} className="neon-input px-3 py-2 rounded-lg text-xs" />
            <button onClick={handleSaveStartDate} disabled={savingStart || !startDateStr} className="neon-btn-green px-3 py-2 rounded-lg text-[10px] sm:text-xs flex items-center gap-1.5 disabled:opacity-30"><Save className="w-3 h-3" /> Simpan</button>
          </div>
        </div>
      </div>
      {loading ? (<div className="neon-card rounded-xl p-12 text-center"><div className="cyber-mono text-sm text-muted-foreground animate-neon-pulse">LOADING...</div></div>) : data && data.students.length > 0 ? (
        <div className="neon-card rounded-xl overflow-hidden max-h-[60vh] overflow-y-auto">
          <div className="p-2 sm:p-3 border-b border-cyan-400/20 bg-cyan-400/5 flex items-center justify-between">
            <span className="cyber-subheading text-[10px] sm:text-xs neon-text-cyan truncate">{classData.name.toUpperCase()} - {MONTHS[parseInt(month) - 1]} {year}</span>
            <span className="cyber-mono text-[9px] sm:text-[10px] text-muted-foreground flex-shrink-0">{data.effectiveDays} hari efektif</span>
          </div>
          <div className="overflow-x-auto">
            <table className="neon-table"><thead><tr><th className="w-8 sm:w-12">NO</th><th className="min-w-[60px] sm:min-w-[130px]">NAMA</th><th className="hidden md:table-cell w-24">NISN</th><th className="w-12 sm:w-14 text-center">MASUK</th><th className="w-12 sm:w-14 text-center">SAKIT</th><th className="w-12 sm:w-14 text-center">IZIN</th><th className="w-12 sm:w-14 text-center">ALFA</th><th className="w-14 sm:w-16 text-center">TERLAMBAT</th><th className="w-12 sm:w-16 text-center">TOTAL</th><th className="w-12 sm:w-16 text-center">%</th></tr></thead>
            <tbody>{data.students.map((s, idx) => { const p = parseFloat(pct(s.hMasuk, s.totalHari)); return (<motion.tr key={s.studentId} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: idx * 0.02 }}><td className="text-center cyber-mono">{idx + 1}</td><td className="font-semibold cyber-body whitespace-nowrap">{s.name}</td><td className="hidden md:table-cell cyber-mono text-sm">{s.nisn}</td><td className="text-center cyber-mono text-green-400">{s.hMasuk}</td><td className="text-center cyber-mono text-cyan-400">{s.hSakit}</td><td className="text-center cyber-mono text-yellow-400">{s.hIzin}</td><td className="text-center cyber-mono text-red-400">{s.hAlfa}</td><td className="text-center cyber-mono text-orange-400">{s.terlambat}</td><td className="text-center cyber-mono">{s.totalHari}</td><td className="text-center cyber-mono" style={{ color: p >= 80 ? '#39ff14' : p >= 60 ? '#ff6600' : '#ff0044' }}>{pct(s.hMasuk, s.totalHari)}%</td></motion.tr>); })}</tbody>
            <tfoot><tr className="border-t-2 border-cyan-400/30"><td colSpan={2} className="cyber-subheading text-xs text-cyan-400 uppercase py-2">Total</td><td className="hidden md:table-cell" /><td className="text-center cyber-mono text-green-400 py-2">{data.totals.hMasuk}</td><td className="text-center cyber-mono text-cyan-400 py-2">{data.totals.hSakit}</td><td className="text-center cyber-mono text-yellow-400 py-2">{data.totals.hIzin}</td><td className="text-center cyber-mono text-red-400 py-2">{data.totals.hAlfa}</td><td className="text-center cyber-mono text-orange-400 py-2">{data.totals.terlambat}</td><td className="text-center cyber-mono py-2">{data.effectiveDays * data.students.length}</td><td className="text-center cyber-mono py-2">{pct(data.totals.hMasuk, data.effectiveDays * data.students.length)}%</td></tr></tfoot></table>
          </div>
        </div>
      ) : !loading && data && data.students.length === 0 ? (<div className="neon-card rounded-xl p-12 text-center"><p className="text-muted-foreground cyber-body">Belum ada data siswa</p></div>) : null}
    </div>
  );
}
"},{"path":"src/components/app/RekapHarianContent.tsx","content":"'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { motion } from 'framer-motion';
import { CalendarDays, Clock, CheckCircle, Timer, XCircle, Heart, Mail, FileSpreadsheet, Loader2 } from 'lucide-react';
import { ClassData, Student, AttendanceRecord, AttendanceStatus, HOURS, ATTENDANCE_COLORS } from './types';
import { safeFetchJson } from '@/lib/fetch';

const STATUS_ICON_MAP: Record<AttendanceStatus, { icon: typeof CheckCircle; color: string }> = {
  Hadir: { icon: CheckCircle, color: '#39ff14' },
  Terlambat: { icon: Timer, color: '#ff6600' },
  Alfa: { icon: XCircle, color: '#ff0044' },
  Sakit: { icon: Heart, color: '#00f0ff' },
  Izin: { icon: Mail, color: '#ffe600' },
};

// Tooltip component for mobile tap & desktop hover
function StatusTooltip({ status, children }: { status: AttendanceStatus; children: React.ReactNode }) {
  const [show, setShow] = useState(false);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  const handleEnter = useCallback(() => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setShow(true);
  }, []);

  const handleLeave = useCallback(() => {
    timeoutRef.current = setTimeout(() => setShow(false), 300);
  }, []);

  const handleClick = useCallback(() => {
    setShow(prev => !prev);
  }, []);

  return (
    <div className="relative inline-flex" onMouseEnter={handleEnter} onMouseLeave={handleLeave} onClick={handleClick}>
      {children}
      {show && (
        <div
          className="status-tooltip"
          style={{ color: STATUS_ICON_MAP[status].color }}
        >
          {status}
        </div>
      )}
    </div>
  );
}

interface RekapHarianContentProps {
  classData: ClassData;
  students: Student[];
  selectedDate: string;
}

export function RekapHarianContent({ classData, students, selectedDate }: RekapHarianContentProps) {
  const [date, setDate] = useState(selectedDate);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [exporting, setExporting] = useState(false);

  useEffect(() => {
    setDate(selectedDate);
  }, [selectedDate]);

  useEffect(() => {
    const fetchAttendance = async () => {
      setLoading(true);
      const data = await safeFetchJson(`/api/attendance?classId=${classData.id}&date=${date}`);
      setAttendance(data || []);
      setLoading(false);
    };
    fetchAttendance();
  }, [classData.id, date]);

  const getStatusForCell = (studentId: string, hour: number): AttendanceStatus | null => {
    const record = attendance.find(r => r.studentId === studentId && r.hour === hour);
    return record ? (record.status as AttendanceStatus) : null;
  };

  const formatDateDisplay = (d: string) => {
    const dateObj = new Date(d + 'T00:00:00');
    const dayNames = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
    return `${dayNames[dateObj.getDay()]}, ${dateObj.getDate().toString().padStart(2, '0')}/${(dateObj.getMonth() + 1).toString().padStart(2, '0')}/${dateObj.getFullYear()}`;
  };

  const handleExportExcel = useCallback(async () => {
    setExporting(true);
    try {
      const url = `/api/recap/excel?type=harian&classId=${classData.id}&startDate=${date}&endDate=${date}`;
      const res = await fetch(url);
      if (!res.ok) {
        console.error('Export failed:', res.status);
        setExporting(false);
        return;
      }
      const blob = await res.blob();
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      const safeName = classData.name.replace(/[^a-zA-Z0-9 ]/g, '').replace(/\s+/g, '_');
      link.download = `Rekap_Harian_${safeName}_${date}.xlsx`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(link.href);
    } catch (e) {
      console.error('Export error:', e);
    }
    setExporting(false);
  }, [classData.id, classData.name, date]);

  return (
    <div className="space-y-4">
      {/* Date picker */}
      <div className="neon-card rounded-xl p-3 sm:p-4">
        <div className="flex flex-col sm:flex-row sm:items-center gap-3">
          <div className="flex items-center gap-2 flex-shrink-0">
            <CalendarDays className="w-4 h-4 neon-text-cyan" />
            <span className="cyber-subheading text-[10px] sm:text-xs neon-text-cyan">PILIH TANGGAL</span>
          </div>
          <input
            type="date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            className="neon-input px-3 py-1.5 rounded-lg text-sm w-full sm:w-auto"
          />
          <span className="cyber-mono text-[10px] sm:text-xs text-muted-foreground">
            {formatDateDisplay(date)}
          </span>
        </div>
      </div>

      {/* Summary bar - icon legend */}
      <div className="flex flex-wrap items-center gap-2">
        <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-cyan-400/5 border border-cyan-400/20">
          <Clock className="w-3 h-3 neon-text-cyan" />
          <span className="cyber-mono text-[10px] text-muted-foreground">Jam terisi:</span>
          {HOURS.map(h => {
            const hasAny = attendance.some(r => r.hour === h);
            return (
              <span
                key={h}
                className={`cyber-mono text-[10px] px-1.5 py-0.5 rounded ${hasAny ? 'bg-cyan-400/20 text-cyan-300' : 'text-muted-foreground/40'}`}
              >
                {h}
              </span>
            );
          })}
        </div>
        <div className="ml-auto cyber-mono text-[10px] text-muted-foreground">
          {students.length} siswa
        </div>
        <button
          onClick={handleExportExcel}
          disabled={exporting || students.length === 0}
          className="neon-btn-green px-3 py-1.5 rounded-lg text-[10px] sm:text-xs flex items-center gap-1.5 disabled:opacity-40 disabled:cursor-not-allowed"
          title="Export ke Excel"
        >
          {exporting ? <Loader2 className="w-3 h-3 animate-spin" /> : <FileSpreadsheet className="w-3 h-3" />}
          {exporting ? 'Exporting...' : <span className="hidden sm:inline">Export Excel</span>}
          {!exporting && <span className="sm:hidden">Excel</span>}
        </button>
      </div>

      {/* Attendance table */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        className="neon-card rounded-xl overflow-hidden"
      >
        {loading ? (
          <div className="py-12 text-center">
            <div className="cyber-mono text-sm text-muted-foreground animate-neon-pulse">LOADING DATA...</div>
          </div>
        ) : students.length === 0 ? (
          <div className="py-12 text-center">
            <p className="text-muted-foreground cyber-body">Belum ada siswa di kelas ini</p>
          </div>
        ) : (
          <div className="overflow-x-auto" style={{ maxHeight: 'calc(100vh - 340px)' }}>
            <table className="neon-table">
              <thead className="sticky top-0 z-10">
                <tr>
                  <th className="w-10 sm:w-14 text-center">NO</th>
                  <th className="min-w-[80px] sm:min-w-[120px]">NAMA</th>
                  <th className="hidden sm:table-cell min-w-[80px]">NISN</th>
                  {HOURS.map(hour => (
                    <th key={hour} className="w-10 sm:w-12 text-center px-0.5">
                      <div className="text-[8px] sm:text-[9px]">JAM</div>
                      <div className="text-[10px] sm:text-xs">{hour}</div>
                    </th>
                  ))}
                  <th className="w-14 sm:w-16 text-center">%</th>
                </tr>
              </thead>
              <tbody>
                {students.map((student, idx) => {
                  const filledCount = attendance.filter(r => r.studentId === student.id).length;
                  const hadirCount = attendance.filter(r => r.studentId === student.id && r.status === 'Hadir').length;
                  const pct = filledCount > 0 ? Math.round((hadirCount / filledCount) * 100) : 0;
                  return (
                    <tr key={student.id}>
                      <td className="text-center cyber-mono text-xs">{idx + 1}</td>
                      <td className="font-semibold cyber-body text-sm whitespace-nowrap">{student.name}</td>
                      <td className="hidden sm:table-cell cyber-mono text-xs">{student.nisn}</td>
                      {HOURS.map(hour => {
                        const status = getStatusForCell(student.id, hour);
                        if (!status) {
                          return (
                            <td key={hour} className="text-center p-1">
                              <span className="text-muted-foreground/30 text-xs">-</span>
                            </td>
                          );
                        }
                        const IconComp = STATUS_ICON_MAP[status].icon;
                        const iconColor = STATUS_ICON_MAP[status].color;
                        return (
                          <td key={hour} className="text-center p-1">
                            <StatusTooltip status={status}>
                              <div
                                className="inline-flex items-center justify-center w-6 h-6 sm:w-7 sm:h-7 rounded cursor-pointer transition-transform hover:scale-110"
                                style={{
                                  backgroundColor: `${iconColor}15`,
                                  border: `1px solid ${iconColor}30`,
                                }}
                              >
                                <IconComp className="w-3.5 h-3.5 sm:w-4 sm:h-4" style={{ color: iconColor }} />
                              </div>
                            </StatusTooltip>
                          </td>
                        );
                      })}
                      <td className="text-center">
                        <span
                          className="cyber-mono text-xs font-bold"
                          style={{ color: pct >= 80 ? '#39ff14' : pct >= 50 ? '#ffe600' : '#ff0044' }}
                        >
                          {pct}%
                        </span>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </motion.div>

      {/* Legend */}
      <div className="flex flex-wrap items-center gap-3 px-1">
        {(Object.entries(STATUS_ICON_MAP) as [AttendanceStatus, { icon: typeof CheckCircle; color: string }][]).map(([status, { icon: IconComp, color }]) => (
          <div key={status} className="flex items-center gap-1.5">
            <IconComp className="w-3.5 h-3.5" style={{ color }} />
            <span className="cyber-mono text-[10px] text-muted-foreground">{status}</span>
          </div>
        ))}
      </div>
    </div>
  );
}
